import { useState, useEffect } from 'react';
import { 
  auth, 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword, 
  signInWithPopup, 
  signOut, 
  updateProfile,
  updateUserStatus,
  getUserById,
  makeUserAdmin
} from '../firebase';
import { User } from '../types';

export const useAuth = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let mounted = true;

    // Safety timeout: If Firebase auth hangs for more than 4 seconds, 
    // force the loading to stop so the user can see the Login screen.
    const timeoutTimer = setTimeout(() => {
        if (mounted && loading) {
            console.warn("Auth listener timed out. Defaulting to logged out state.");
            setLoading(false);
        }
    }, 4000);

    // Listen to auth state changes
    const unsubscribe = auth.onAuthStateChanged(
        async (firebaseUser: any) => {
            clearTimeout(timeoutTimer); 
            if (!mounted) return;

            if (firebaseUser) {
                try {
                  // Fetch the full user profile from Firestore to get 'isAdmin' and other fields
                  let dbUser = await getUserById(firebaseUser.uid);

                  // Force Admin Status for specific email
                  const isHardcodedAdmin = firebaseUser.email?.toLowerCase() === 'betterrroxx@gmail.com';
                  if (isHardcodedAdmin) {
                     if (dbUser && !dbUser.isAdmin) {
                        await makeUserAdmin(firebaseUser.uid);
                        dbUser.isAdmin = true;
                     }
                  }

                  // Default Fallback if DB fetch fails but Auth works (prevents lockout)
                  const finalUser: User = {
                    uid: firebaseUser.uid,
                    name: dbUser?.name || firebaseUser.displayName || 'Anonymous',
                    email: firebaseUser.email || '',
                    photoURL: dbUser?.photoURL || firebaseUser.photoURL || `https://picsum.photos/seed/${firebaseUser.uid}/200`,
                    status: dbUser?.status || 'online',
                    lastSeen: dbUser?.lastSeen || Date.now(),
                    bio: dbUser?.bio,
                    blockedUsers: dbUser?.blockedUsers || [],
                    chatLockPassword: dbUser?.chatLockPassword,
                    isAdmin: dbUser ? !!dbUser.isAdmin : isHardcodedAdmin, // Use DB status or hardcode fallback
                    isGloballyBlocked: !!dbUser?.isGloballyBlocked
                  };

                  setUser(finalUser);

                  // Update status
                  try {
                      updateUserStatus(firebaseUser.uid, 'online').catch(e => console.warn("Status update failed:", e));
                  } catch(e) {}

                  const handleVisibilityChange = () => {
                    if (document.hidden) {
                        updateUserStatus(firebaseUser.uid, 'offline');
                    } else {
                        updateUserStatus(firebaseUser.uid, 'online');
                    }
                  };

                  const handleBeforeUnload = () => {
                      updateUserStatus(firebaseUser.uid, 'offline');
                  };

                  document.addEventListener('visibilitychange', handleVisibilityChange);
                  window.addEventListener('beforeunload', handleBeforeUnload);
                } catch (err) {
                  console.error("Error fetching user details:", err);
                  // Even if DB fails, allow basic auth so user can at least see something
                  setUser({
                    uid: firebaseUser.uid,
                    name: firebaseUser.displayName || 'User',
                    email: firebaseUser.email || '',
                    photoURL: firebaseUser.photoURL || '',
                    status: 'online',
                    lastSeen: Date.now(),
                    isAdmin: false
                  } as User);
                }
            } else {
                setUser(null);
            }
            setLoading(false);
        }, 
        (error: any) => {
            console.error("Auth Error:", error);
            if(mounted) setLoading(false);
        }
    );

    return () => {
      mounted = false;
      clearTimeout(timeoutTimer);
      unsubscribe();
    };
  }, []);

  const signup = async (email: string, pass: string, name: string) => {
    const res = await createUserWithEmailAndPassword(auth, email, pass);
    const updated = await updateProfile(res.user, { 
      displayName: name,
      name: name,
      photoURL: `https://picsum.photos/seed/${res.user.uid}/200`
    });
    return updated;
  };

  const login = async (email: string, pass: string) => {
    const res = await signInWithEmailAndPassword(auth, email, pass);
    return res.user;
  };

  const googleSignIn = async () => {
    const res = await signInWithPopup();
    return res.user;
  };

  const logout = async () => {
    await signOut();
  };

  return { user, loading, signup, login, googleSignIn, logout };
};

import { useState, useEffect } from 'react';
import { 
  auth, 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword, 
  signInWithPopup, 
  signOut, 
  updateProfile,
  updateUserStatus,
  getUserById,
  makeUserAdmin
} from '../firebase';
import { User } from '../types';

export const useAuth = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  // Auth Listener
  useEffect(() => {
    let mounted = true;

    const timeoutTimer = setTimeout(() => {
        if (mounted && loading) {
            console.warn("Auth listener timed out. Defaulting to logged out state.");
            setLoading(false);
        }
    }, 4000);

    const unsubscribe = auth.onAuthStateChanged(
        async (firebaseUser: any) => {
            clearTimeout(timeoutTimer); 
            if (!mounted) return;

            if (firebaseUser) {
                try {
                  let dbUser = await getUserById(firebaseUser.uid);

                  const isHardcodedAdmin = firebaseUser.email?.toLowerCase() === 'betterrroxx@gmail.com';
                  if (isHardcodedAdmin) {
                     if (dbUser && !dbUser.isAdmin) {
                        await makeUserAdmin(firebaseUser.uid);
                        dbUser.isAdmin = true;
                     }
                  }

                  const finalUser: User = {
                    uid: firebaseUser.uid,
                    name: dbUser?.name || firebaseUser.displayName || 'Anonymous',
                    email: firebaseUser.email || '',
                    photoURL: dbUser?.photoURL || firebaseUser.photoURL || `https://picsum.photos/seed/${firebaseUser.uid}/200`,
                    status: dbUser?.status || 'online',
                    lastSeen: dbUser?.lastSeen || Date.now(),
                    bio: dbUser?.bio,
                    blockedUsers: dbUser?.blockedUsers || [],
                    chatLockPassword: dbUser?.chatLockPassword,
                    isAdmin: dbUser ? !!dbUser.isAdmin : isHardcodedAdmin,
                    isGloballyBlocked: !!dbUser?.isGloballyBlocked
                  };

                  setUser(finalUser);
                } catch (err) {
                  console.error("Error fetching user details:", err);
                  setUser({
                    uid: firebaseUser.uid,
                    name: firebaseUser.displayName || 'User',
                    email: firebaseUser.email || '',
                    photoURL: firebaseUser.photoURL || '',
                    status: 'online',
                    lastSeen: Date.now(),
                    isAdmin: false
                  } as User);
                }
            } else {
                setUser(null);
            }
            setLoading(false);
        }, 
        (error: any) => {
            console.error("Auth Error:", error);
            if(mounted) setLoading(false);
        }
    );

    return () => {
      mounted = false;
      clearTimeout(timeoutTimer);
      unsubscribe();
    };
  }, []);

  // Presence System
  useEffect(() => {
    if (!user?.uid) return;

    const uid = user.uid;

    // Set online immediately on mount
    updateUserStatus(uid, 'online');

    // Heartbeat to keep status online/update lastSeen
    const heartbeat = setInterval(() => {
        if (document.visibilityState === 'visible') {
            updateUserStatus(uid, 'online');
        }
    }, 60000);

    const handleVisibilityChange = () => {
        if (document.visibilityState === 'hidden') {
            updateUserStatus(uid, 'offline');
        } else {
            updateUserStatus(uid, 'online');
        }
    };

    // Before unload is the last chance to set offline on close
    const handleBeforeUnload = () => {
        updateUserStatus(uid, 'offline');
    };

    document.addEventListener('visibilitychange', handleVisibilityChange);
    window.addEventListener('beforeunload', handleBeforeUnload);

    return () => {
        clearInterval(heartbeat);
        document.removeEventListener('visibilitychange', handleVisibilityChange);
        window.removeEventListener('beforeunload', handleBeforeUnload);
        // Attempt to set offline on component unmount (logout)
        updateUserStatus(uid, 'offline');
    };
  }, [user?.uid]);

  const signup = async (email: string, pass: string, name: string) => {
    const res = await createUserWithEmailAndPassword(auth, email, pass);
    const updated = await updateProfile(res.user, { 
      displayName: name,
      name: name,
      photoURL: `https://picsum.photos/seed/${res.user.uid}/200`
    });
    return updated;
  };

  const login = async (email: string, pass: string) => {
    const res = await signInWithEmailAndPassword(auth, email, pass);
    return res.user;
  };

  const googleSignIn = async () => {
    const res = await signInWithPopup();
    return res.user;
  };

  const logout = async () => {
    if (user?.uid) await updateUserStatus(user.uid, 'offline');
    await signOut();
  };

  return { user, loading, signup, login, googleSignIn, logout };
};

import React, { useState, useMemo, useEffect } from 'react';
import { User, Chat } from '../../types';
import { getAllUsers, getMyChats } from '../../firebase';
import { CreateGroupModal } from './CreateGroupModal';

interface SidebarProps {
  currentUser: User;
  onChatSelect: (chat: Chat) => void;
  activeChatId?: string;
}

export const Sidebar: React.FC<SidebarProps> = ({ 
  currentUser, onChatSelect, activeChatId
}) => {
  const [search, setSearch] = useState('');
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [chats, setChats] = useState<Chat[]>([]);
  const [showGroupModal, setShowGroupModal] = useState(false);

  useEffect(() => {
    const sync = async () => {
      const users = await getAllUsers();
      const myBlocked = currentUser.blockedUsers || [];
      setAllUsers(users.filter(u => u.uid !== currentUser.uid && !myBlocked.includes(u.uid)));
      const myChats = await getMyChats(currentUser.uid);
      setChats(myChats);
    };
    sync();
    // Sync faster to find new users quickly
    const itv = setInterval(sync, 2000);
    return () => clearInterval(itv);
  }, [currentUser]);

  const isRevealingLocked = currentUser.chatLockPassword && search === currentUser.chatLockPassword;

  // Helper to check if user is truly online (status online + heartbeat within last 3 mins)
  const isUserOnline = (u: User | undefined) => {
    if (!u) return false;
    if (u.status !== 'online') return false;
    const timeDiff = Date.now() - (u.lastSeen || 0);
    return timeDiff < 3 * 60 * 1000; // 3 minutes timeout
  };

  const searchResults = useMemo(() => {
    const term = search.toLowerCase().trim();

    const visibleChats = chats.filter(c => {
      const isLocked = c.lockedBy?.includes(currentUser.uid);
      if (isRevealingLocked) return isLocked; 
      return !isLocked;
    });

    if (!term || isRevealingLocked) return { chats: visibleChats, users: [] };

    const matchedUsers = allUsers.filter(u => u.name.toLowerCase().includes(term));
    const matchedChats = visibleChats.filter(c => {
      if (c.type === 'group') return c.name?.toLowerCase().includes(term);
      const otherId = c.participants.find(p => p !== currentUser.uid);
      const user = allUsers.find(u => u.uid === otherId);
      return user?.name.toLowerCase().includes(term);
    });

    return { chats: matchedChats, users: matchedUsers.filter(u => !chats.some(c => c.type === 'private' && c.participants.includes(u.uid))) };
  }, [search, allUsers, chats, currentUser.uid, isRevealingLocked]);

  const handleStartNewChat = (user: User) => {
    const existing = chats.find(c => c.type === 'private' && c.participants.includes(user.uid));
    if (existing) onChatSelect(existing);
    else onChatSelect({
      id: [currentUser.uid, user.uid].sort().join('_'),
      type: 'private', participants: [currentUser.uid, user.uid],
      updatedAt: Date.now(), lockedBy: []
    });
    setSearch('');
  };

  const getChatInfo = (chat: Chat) => {
    if (chat.type === 'group') return { name: chat.name || 'Group', photo: chat.groupIcon || `https://picsum.photos/seed/${chat.id}/200` };
    const otherId = chat.participants.find(p => p !== currentUser.uid);
    const user = allUsers.find(u => u.uid === otherId);
    return { name: user?.name || 'Contact', photo: user?.photoURL || `https://picsum.photos/seed/${otherId}/200`, status: user?.status, userObj: user };
  };

  return (
    <div className="w-full h-full flex flex-col bg-white dark:bg-slate-900 animate-in slide-in-from-left duration-300">
      <div className="p-6 flex items-center justify-between border-b border-slate-100 dark:border-slate-800">
        <h2 className="text-2xl font-black tracking-tight">Chats</h2>
        <button onClick={() => setShowGroupModal(true)} className="p-3 bg-indigo-50 text-indigo-500 dark:bg-indigo-500/10 rounded-2xl hover:bg-indigo-100 transition-all shadow-sm active:scale-95">
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 4v16m8-8H4" /></svg>
        </button>
      </div>

      <div className="p-4">
        <div className="relative group">
          <span className="absolute inset-y-0 left-3.5 flex items-center text-slate-400 group-focus-within:text-indigo-500 transition-colors">
            {isRevealingLocked ? (
              <svg className="w-4 h-4 text-indigo-500 animate-pulse" fill="currentColor" viewBox="0 0 24 24"><path d="M12 17c1.1 0 2-.9 2-2s-.9-2-2-2-2 .9-2 2 .9 2 2 2zm6-9h-1V6c0-2.76-2.24-5-5-5S7 3.24 7 6v2H6c-1.1 0-2 .9-2 2v10c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V10c0-1.1-.9-2-2-2zm-6-5c1.66 0 3 1.34 3 3v2H9V6c0-1.66 1.34-3 3-3z"/></svg>
            ) : (
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
            )}
          </span>
          <input 
            type="text" placeholder={isRevealingLocked ? "Secret Vault Unlocked" : "Search conversations..."}
            value={search} onChange={(e) => setSearch(e.target.value)}
            className={`w-full border-none rounded-2xl py-3.5 pl-11 pr-4 text-sm outline-none transition-all shadow-sm ${isRevealingLocked ? 'bg-indigo-50 dark:bg-indigo-900/30 ring-2 ring-indigo-500' : 'bg-slate-100/80 dark:bg-slate-800/80 focus:ring-2 focus:ring-indigo-500/40 focus:bg-white dark:focus:bg-slate-800'}`}
          />
        </div>
      </div>

      <div className="flex-1 overflow-y-auto space-y-0.5 px-3 pb-20 no-scrollbar">
        {isRevealingLocked && (
          <div className="px-4 py-3 bg-indigo-500/10 rounded-2xl mb-4 border border-indigo-500/20 text-center animate-in fade-in slide-in-from-top-2">
             <span className="text-[10px] font-black text-indigo-500 dark:text-indigo-400 uppercase tracking-[0.25em]">Private Vault Unlocked</span>
          </div>
        )}

        {searchResults.chats.length === 0 && searchResults.users.length === 0 && (
          <div className="py-20 text-center px-6">
            <p className="text-slate-400 dark:text-slate-500 text-sm font-medium">No conversations found.</p>
            <button onClick={() => setShowGroupModal(true)} className="mt-4 text-indigo-500 font-bold text-xs hover:underline">Start a new chat</button>
          </div>
        )}

        {searchResults.chats.map(chat => {
          const info = getChatInfo(chat);
          const isActive = activeChatId === chat.id;
          const isOnline = chat.type === 'private' && isUserOnline(info.userObj);

          return (
            <div 
              key={chat.id} onClick={() => { onChatSelect(chat); if(isRevealingLocked) setSearch(''); }}
              className={`flex items-center gap-3.5 p-4 rounded-[2rem] cursor-pointer transition-all active:scale-[0.97] mb-1.5 ${isActive ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-600/20' : 'hover:bg-slate-50 dark:hover:bg-slate-800/60'}`}
            >
              <div className="relative flex-shrink-0">
                <img src={info.photo} className="w-14 h-14 rounded-2xl object-cover shadow-sm" alt="" />
                {isOnline && !isActive && <div className="absolute -bottom-0.5 -right-0.5 w-4 h-4 bg-green-500 rounded-full border-2 border-white dark:border-slate-900 shadow-sm"></div>}
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex justify-between items-center">
                  <h4 className="font-bold text-[15px] truncate">{info.name}</h4>
                  <span className={`text-[9px] font-bold uppercase tracking-tight ${isActive ? 'text-white/70' : 'text-slate-400 dark:text-slate-500'}`}>
                    {chat.lastMessage ? new Date(chat.lastMessage.timestamp).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'}) : ''}
                  </span>
                </div>
                <div className="flex items-center justify-between gap-2 mt-0.5">
                  <p className={`text-[13px] truncate font-medium ${isActive ? 'text-white/80' : 'text-slate-500 dark:text-slate-400'}`}>
                    {chat.lastMessage?.text || 'Start chatting...'}
                  </p>
                  {chat.lockedBy?.includes(currentUser.uid) && !isActive && (
                    <svg className="w-3.5 h-3.5 text-indigo-500 shrink-0" fill="currentColor" viewBox="0 0 24 24"><path d="M12 17c1.1 0 2-.9 2-2s-.9-2-2-2-2 .9-2 2 .9 2 2 2zm6-9h-1V6c0-2.76-2.24-5-5-5S7 3.24 7 6v2H6c-1.1 0-2 .9-2 2v10c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V10c0-1.1-.9-2-2-2zm-6-5c1.66 0 3 1.34 3 3v2H9V6c0-1.66 1.34-3 3-3z"/></svg>
                  )}
                </div>
              </div>
            </div>
          );
        })}

        {searchResults.users.map(u => {
          const isOnline = isUserOnline(u);
          return (
            <div key={u.uid} onClick={() => handleStartNewChat(u)} className="flex items-center gap-3.5 p-4 rounded-[2rem] cursor-pointer hover:bg-indigo-50 dark:hover:bg-indigo-900/10 transition-all group">
              <img src={u.photoURL} className="w-14 h-14 rounded-2xl object-cover shadow-sm group-hover:scale-105 transition-transform" alt="" />
              <div className="flex-1 min-w-0">
                <h4 className="font-bold text-[15px] truncate">{u.name}</h4>
                <p className={`text-[10px] font-bold uppercase tracking-wider ${isOnline ? 'text-green-500' : 'text-slate-500'}`}>
                    {isOnline ? 'Online Now' : 'Offline'}
                </p>
              </div>
              <div className="p-2 opacity-0 group-hover:opacity-100 transition-all translate-x-2 group-hover:translate-x-0">
                 <svg className="w-5 h-5 text-indigo-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 5l7 7-7 7" /></svg>
              </div>
            </div>
          );
        })}
      </div>

      {showGroupModal && <CreateGroupModal currentUser={currentUser} onClose={() => setShowGroupModal(false)} onCreated={onChatSelect} />}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { User, Chat, Message } from '../../types';
import { MessageBubble } from './MessageBubble';
import { getAIResponse } from '../../gemini';
import { getUserById, addMessage, getMessages, toggleChatLock, markMessagesAsSeen, markMessagesAsDelivered, getMyChats, getAllUsers, setTypingStatus, subscribeToChat, deleteMessage, subscribeToUser } from '../../firebase';

interface ChatWindowProps {
  chat: Chat;
  currentUser: User;
  onClose: () => void;
  onUserClick: (user: User) => void;
  onCallStart?: (user: User, type: 'voice' | 'video') => void;
}

const WALLPAPER_CLASSES: Record<string, string> = {
  default: 'bg-slate-100 dark:bg-slate-950',
  indigo: 'bg-indigo-600',
  emerald: 'bg-emerald-700',
  rose: 'bg-rose-500',
  amber: 'bg-amber-500',
  dark: 'bg-black',
  gradient: 'bg-gradient-to-br from-purple-900 via-indigo-900 to-black',
};

const FONT_SIZE_CLASSES: Record<string, string> = {
  small: 'text-[12px]',
  medium: 'text-[14px]',
  large: 'text-[16px]',
};

export const ChatWindow: React.FC<ChatWindowProps> = ({ chat, currentUser, onClose, onUserClick, onCallStart }) => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [otherUser, setOtherUser] = useState<User | null>(null);
  const [isLocked, setIsLocked] = useState(chat.lockedBy?.includes(currentUser.uid) || false);
  const [inputText, setInputText] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [typingUsers, setTypingUsers] = useState<string[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [recordingDuration, setRecordingDuration] = useState(0);
  const [mediaRecorder, setMediaRecorder] = useState<MediaRecorder | null>(null);

  const [wallpaper, setWallpaper] = useState('default');
  const [customUrl, setCustomUrl] = useState<string | null>(null);
  const [fontSize, setFontSize] = useState('medium');
  const [replyingTo, setReplyingTo] = useState<Message | null>(null);
  const [forwardingMessage, setForwardingMessage] = useState<Message | null>(null);
  const [availableChats, setAvailableChats] = useState<Chat[]>([]);
  const [allUsers, setAllUsers] = useState<User[]>([]);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const typingTimeoutRef = useRef<any>(null);
  const timerRef = useRef<any>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  const isGroup = chat.type === 'group';
  const otherId = !isGroup 
    ? (chat.participants.find(p => p !== currentUser.uid) || (chat.participants.includes(currentUser.uid) ? currentUser.uid : '')) 
    : chat.id;

  const loadSettings = () => {
    const saved = localStorage.getItem('roxx_settings');
    if (saved) {
      const parsed = JSON.parse(saved);
      setWallpaper(parsed.wallpaper || 'default');
      setCustomUrl(parsed.customWallpaperUrl || null);
      setFontSize(parsed.fontSize || 'medium');
    }
  };

  useEffect(() => {
    loadSettings();
    window.addEventListener('roxx_settings_updated', loadSettings);
    return () => window.removeEventListener('roxx_settings_updated', loadSettings);
  }, []);

  // Subscribe to Chat (Typing indicators & Metadata)
  useEffect(() => {
    const unsubscribe = subscribeToChat(chat.id, (data) => {
      if (data.typing) {
        const activeTypers = Object.entries(data.typing)
          .filter(([uid, isTyping]) => uid !== currentUser.uid && isTyping)
          .map(([uid]) => uid);
        setTypingUsers(activeTypers);
      } else {
        setTypingUsers([]);
      }
    });
    return () => unsubscribe();
  }, [chat.id, currentUser.uid]);

  // Subscribe to Other User (Online Status)
  useEffect(() => {
    if (isGroup || !otherId) return;

    // Initial fetch
    getUserById(otherId).then(u => { if(u) setOtherUser(u); });

    // Real-time listener
    const unsubscribe = subscribeToUser(otherId, (userData) => {
        setOtherUser(userData);
    });
    return () => unsubscribe();
  }, [otherId, isGroup]);

  // Messages Polling (Could be optimized to onSnapshot for message list too)
  useEffect(() => {
    const sync = async () => {
      const msgs = await getMessages(chat.id);
      setMessages(prev => {
        if (prev.length !== msgs.length) return msgs;
        const hasChanged = prev.some((p, i) => {
          const m = msgs[i];
          return p.id !== m.id || p.status !== m.status || p.timestamp !== m.timestamp;
        });
        return hasChanged ? msgs : prev;
      });
    };
    sync();
    const itv = setInterval(sync, 2000);
    return () => clearInterval(itv);
  }, [chat.id]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [messages, isTyping, isUploading, replyingTo, typingUsers, isRecording]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setInputText(e.target.value);
    if (!isTyping) {
      setIsTyping(true);
      setTypingStatus(chat.id, currentUser.uid, true);
    }
    if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
    typingTimeoutRef.current = setTimeout(() => {
      setIsTyping(false);
      setTypingStatus(chat.id, currentUser.uid, false);
    }, 2000);
  };

  // --- Voice Recording Logic (Fixed for proper playback) ---
  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

      // Determine supported mimeType (Safari prefers mp4, Chrome/FF webm)
      let mimeType = 'audio/webm';
      if (MediaRecorder.isTypeSupported('audio/webm;codecs=opus')) {
          mimeType = 'audio/webm;codecs=opus';
      } else if (MediaRecorder.isTypeSupported('audio/mp4')) {
          mimeType = 'audio/mp4';
      }

      const recorder = new MediaRecorder(stream, { mimeType });
      setMediaRecorder(recorder);
      audioChunksRef.current = [];

      recorder.ondataavailable = (e) => {
        if (e.data.size > 0) audioChunksRef.current.push(e.data);
      };

      recorder.start();
      setIsRecording(true);
      setRecordingDuration(0);
      timerRef.current = setInterval(() => setRecordingDuration(p => p + 1), 1000);
    } catch (err) {
      alert("Microphone access denied. Please enable permissions.");
    }
  };

  const stopRecording = async (shouldSend: boolean) => {
    if (mediaRecorder && isRecording) {
      const mimeType = mediaRecorder.mimeType; // Capture before stopping

      // Define what happens when recording stops
      mediaRecorder.onstop = async () => {
        if (shouldSend && audioChunksRef.current.length > 0) {
            const blob = new Blob(audioChunksRef.current, { type: mimeType });
            const reader = new FileReader();
            reader.readAsDataURL(blob);
            reader.onloadend = async () => {
                const base64Audio = reader.result as string;
                const msg: Message = {
                    id: 'v_' + Math.random().toString(36).substr(2, 9),
                    senderId: currentUser.uid,
                    recipientId: isGroup ? chat.id : otherId!,
                    text: 'Voice Message',
                    type: 'voice',
                    timestamp: Date.now(),
                    status: 'sent',
                    audioUrl: base64Audio,
                    duration: recordingDuration
                };
                setMessages(prev => [...prev, msg]);
                await addMessage(msg);
            };
        }
        // Cleanup
        mediaRecorder.stream.getTracks().forEach(track => track.stop());
        setMediaRecorder(null);
        audioChunksRef.current = [];
      };

      mediaRecorder.stop();
      clearInterval(timerRef.current);
      setIsRecording(false);
    }
  };

  const formatDuration = (sec: number) => {
    const m = Math.floor(sec / 60);
    const s = sec % 60;
    return `${m}:${s.toString().padStart(2, '0')}`;
  };

  const handleDeleteMessage = async (msgId: string) => {
    if (window.confirm("Delete this message?")) {
      setMessages(prev => prev.filter(m => m.id !== msgId));
      await deleteMessage(msgId, chat.id);
    }
  };

  const handleSend = async (e?: React.FormEvent) => {
    e?.preventDefault();
    const text = inputText.trim();
    if (!text) return;

    const recipient = isGroup ? chat.id : otherId;
    if (!recipient) return;

    // Immediately stop typing indicator
    if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
    setIsTyping(false);
    setTypingStatus(chat.id, currentUser.uid, false);

    let replyContext = undefined;
    if (replyingTo) {
      const sender = await getUserById(replyingTo.senderId);
      replyContext = {
        messageId: replyingTo.id,
        text: replyingTo.text || 'Media',
        senderName: sender?.name || 'User'
      };
    }

    const msg: Message = {
      id: 'm_' + Math.random().toString(36).substr(2, 9),
      senderId: currentUser.uid, 
      recipientId: recipient,
      text, 
      type: 'text', 
      timestamp: Date.now(), 
      status: 'sent',
      replyContext
    };

    setMessages(prev => [...prev, msg]);
    setInputText('');
    setReplyingTo(null);

    await addMessage(msg);

    if (text.toLowerCase().startsWith('/ai')) {
      setTypingUsers(prev => [...prev, 'gemini_ai']);
      try {
        const res = await getAIResponse(text.replace('/ai', '').trim());
        const aiMsg: Message = {
          id: 'ai_' + Date.now(), 
          senderId: 'gemini_ai', 
          recipientId: isGroup ? chat.id : currentUser.uid,
          text: res || "I'm thinking...", 
          type: 'text', 
          timestamp: Date.now(), 
          status: 'seen'
        };
        await addMessage(aiMsg);
      } catch (err) { }
      finally { setTypingUsers(prev => prev.filter(id => id !== 'gemini_ai')); }
    }
  };

  const handleForward = async (targetChat: Chat) => {
    if (!forwardingMessage) return;
    const targetId = targetChat.type === 'group' ? targetChat.id : targetChat.participants.find(p => p !== currentUser.uid)!;
    const { replyContext, ...msgContent } = forwardingMessage;
    const forwardMsg: Message = {
      ...msgContent,
      id: 'fwd_' + Math.random().toString(36).substr(2, 9),
      senderId: currentUser.uid,
      recipientId: targetId,
      timestamp: Date.now(),
      status: 'sent',
      isForwarded: true
    };
    await addMessage(forwardMsg);
    setForwardingMessage(null);
    alert(`Forwarded to ${targetChat.name || 'Contact'}`);
  };

  const openForwardModal = async (msg: Message) => {
    setForwardingMessage(msg);
    const chats = await getMyChats(currentUser.uid);
    const users = await getAllUsers();
    setAvailableChats(chats);
    setAllUsers(users);
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const recipient = isGroup ? chat.id : otherId;
    if (!recipient) return;

    setIsUploading(true);
    const reader = new FileReader();
    reader.onload = async (event) => {
      const fileUrl = event.target?.result as string;
      let messageType: any = 'file';
      if (file.type.startsWith('image/')) messageType = 'image';
      else if (file.type.startsWith('video/')) messageType = 'video';
      const msg: Message = {
        id: 'f_' + Math.random().toString(36).substr(2, 9), 
        senderId: currentUser.uid,
        recipientId: recipient, 
        text: file.name, 
        type: messageType,
        timestamp: Date.now(), 
        status: 'sent', 
        fileUrl, 
        fileName: file.name
      };
      setMessages(prev => [...prev, msg]);
      await addMessage(msg);
      setIsUploading(false);
    };
    reader.readAsDataURL(file);
    e.target.value = '';
  };

  const renderDateSeparator = (timestamp: number, prevTimestamp?: number) => {
    const date = new Date(timestamp).toDateString();
    const prevDate = prevTimestamp ? new Date(prevTimestamp).toDateString() : null;
    if (date !== prevDate) {
      return (
        <div className="flex justify-center my-6 sticky top-2 z-10">
          <div className="px-4 py-1.5 bg-slate-900/10 dark:bg-white/10 backdrop-blur-xl border border-white/20 rounded-full">
            <span className="text-[10px] font-black uppercase tracking-widest text-slate-500 dark:text-slate-300">
              {new Date(timestamp).toLocaleDateString(undefined, { weekday: 'long', month: 'short', day: 'numeric' })}
            </span>
          </div>
        </div>
      );
    }
    return null;
  };

  // Helper logic to ensure offline status is displayed if lastSeen is old
  const isOnline = otherUser?.status === 'online' && (Date.now() - (otherUser.lastSeen || 0) < 3 * 60 * 1000);
  const statusColor = !isGroup && isOnline ? 'text-green-500' : 'text-slate-500 dark:text-slate-400';
  const statusText = !isGroup && isOnline ? 'Online Now' : 'Offline';

  return (
    <div className={`flex-1 flex flex-col h-full bg-white dark:bg-slate-900 animate-in fade-in duration-300 relative overflow-hidden ${FONT_SIZE_CLASSES[fontSize]}`}>
      <div className={`absolute inset-0 z-0 transition-all duration-700 ${wallpaper !== 'custom' ? WALLPAPER_CLASSES[wallpaper] : ''}`}>
        {wallpaper === 'custom' && customUrl && <img src={customUrl} className="absolute inset-0 w-full h-full object-cover" alt="" /> }
        <div className="absolute inset-0 opacity-[0.08] pointer-events-none" style={{ backgroundImage: `url('https://www.transparenttextures.com/patterns/asfalt-dark.png')` }}></div>
      </div>

      {/* Header */}
      <div className="p-3 md:p-4 flex items-center justify-between glass z-10 border-b border-slate-200 dark:border-slate-800 shadow-sm">
        <div className="flex items-center gap-3">
          <button onClick={onClose} className="lg:hidden p-2 rounded-xl hover:bg-slate-200 dark:hover:bg-slate-800"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 19l-7-7 7-7" /></svg></button>
          <div className="relative cursor-pointer group" onClick={() => onUserClick(isGroup ? ({} as User) : (otherUser || {} as User))}>
            <img src={isGroup ? (chat.groupIcon || `https://picsum.photos/seed/${chat.id}/200`) : otherUser?.photoURL} className="w-10 h-10 rounded-2xl object-cover border border-slate-200 dark:border-slate-700 group-hover:scale-105 transition-transform" alt="" />
            {!isGroup && isOnline && <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-green-500 rounded-full border-2 border-white dark:border-slate-900 animate-pulse"></div>}
          </div>
          <div className="min-w-0 cursor-pointer" onClick={() => onUserClick(isGroup ? ({} as User) : (otherUser || {} as User))}>
            <h3 className="font-bold text-sm leading-none flex items-center gap-1.5 truncate">
              {isGroup ? chat.name : (otherUser?.name || 'Loading...')}
              {isLocked && <svg className="w-3.5 h-3.5 text-indigo-500" fill="currentColor" viewBox="0 0 24 24"><path d="M12 17c1.1 0 2-.9 2-2s-.9-2-2-2-2 .9-2 2 .9 2 2 2zm6-9h-1V6c0-2.76-2.24-5-5-5S7 3.24 7 6v2H6c-1.1 0-2 .9-2 2v10c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V10c0-1.1-.9-2-2-2zm-6-5c1.66 0 3 1.34 3 3v2H9V6c0-1.66 1.34-3 3-3z"/></svg>}
            </h3>
            {typingUsers.length > 0 ? (
               <span className="text-[10px] text-indigo-500 font-bold uppercase tracking-widest mt-0.5 animate-pulse flex items-center gap-1">
                  <div className="flex gap-0.5">
                    <span className="w-1 h-1 bg-indigo-500 rounded-full animate-bounce"></span>
                    <span className="w-1 h-1 bg-indigo-500 rounded-full animate-bounce [animation-delay:0.1s]"></span>
                    <span className="w-1 h-1 bg-indigo-500 rounded-full animate-bounce [animation-delay:0.2s]"></span>
                  </div>
                  {isGroup ? `${typingUsers.length} typing...` : typingUsers.includes('gemini_ai') ? 'AI thinking...' : 'Typing...'}
               </span>
            ) : (
               <span className={`text-[10px] font-bold uppercase tracking-widest mt-0.5 ${statusColor}`}>
                  {isGroup ? `${chat.participants.length} members` : statusText}
               </span>
            )}
          </div>
        </div>
        <div className="flex items-center gap-2">
          {!isGroup && otherUser && (
            <>
