export const updateUserStatus = async (uid: string, status: 'online' | 'offline') => {
  if (!db || !db.type) return; 
  try {
    const userRef = doc(db, "users", uid);
    await updateDoc(userRef, {
      status: status,
      lastSeen: Date.now()
    });
  } catch (e) {
    // console.error("Error updating status:", e);
  }
};

