                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
             </div>
        )}
        {replyingTo && (
          <div className="px-4 py-2 bg-slate-50 dark:bg-slate-800/80 border-l-4 border-indigo-500 flex items-center justify-between">
             <div className="min-w-0">
                <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest mb-0.5">Replying to {replyingTo.senderId === currentUser.uid ? 'Yourself' : 'Contact'}</p>
                <p className="text-xs text-slate-500 truncate">{replyingTo.text || 'Media Message'}</p>
             </div>
             <button onClick={() => setReplyingTo(null)} className="p-1.5 text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-full">
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
             </button>
          </div>
        )}

        <div className="p-3 md:p-4 flex gap-2.5 items-center">
          {isRecording ? (
             <div className="flex-1 flex items-center justify-between bg-red-500 text-white rounded-[1.5rem] px-6 py-4 animate-pulse">
                <div className="flex items-center gap-3">
                   <div className="w-3 h-3 bg-white rounded-full animate-bounce"></div>
                   <span className="font-bold text-sm tracking-widest">{formatDuration(recordingDuration)}</span>
                </div>
                <div className="flex items-center gap-3">
                    <button onClick={() => stopRecording(false)} className="text-white/80 hover:text-white text-xs font-bold uppercase">Cancel</button>
                    <button onClick={() => stopRecording(true)} className="p-2 bg-white text-red-500 rounded-full shadow-lg">
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M5 13l4 4L19 7" /></svg>
                    </button>
                </div>
             </div>
          ) : (
            <>
              <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" />
              <button type="button" onClick={() => fileInputRef.current?.click()} className="p-3.5 text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-2xl shrink-0 transition-colors active:scale-90"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 4v16m8-8H4" /></svg></button>

              <form onSubmit={handleSend} className="flex-1 flex gap-2">
                 <input 
                    ref={inputRef}
                    type="text" 
                    value={inputText} 
                    onChange={handleInputChange} 
                    placeholder="Type a message..." 
                    className="flex-1 bg-white/60 dark:bg-slate-800/80 rounded-[1.5rem] px-6 py-4 text-sm font-medium outline-none border border-slate-200 dark:border-slate-700 focus:ring-2 focus:ring-indigo-500/20 transition-all shadow-inner" 
                />
                {inputText.trim() ? (
                    <button type="submit" className="p-4 bg-indigo-500 text-white rounded-2xl shadow-xl shadow-indigo-500/20 transition-all shrink-0 active:scale-95">
                        {editingMessage ? (
                             <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M5 13l4 4L19 7" /></svg>
                        ) : (
                             <svg className="w-6 h-6 rotate-90" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
                        )}
                    </button>
                ) : (
                    <button type="button" onClick={startRecording} className="p-4 bg-slate-100 dark:bg-slate-800 text-slate-500 hover:bg-red-500 hover:text-white rounded-2xl transition-all shrink-0 active:scale-95 group">
                        <svg className="w-6 h-6 group-hover:scale-110 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
                    </button>
                )}
              </form>
            </>
          )}
        </div>
      </div>

      {/* Group Info Modal */}
      {showGroupInfo && (
        <GroupInfoModal 
          chat={chat}
          currentUser={currentUser}
          onClose={() => setShowGroupInfo(false)}
        />
      )}

      {/* Delete Options Bottom Sheet / Modal */}
      {showDeleteOptions && messageToDelete && (
        <div className="fixed inset-0 z-[200] flex items-end justify-center sm:items-center">
            <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setShowDeleteOptions(false)}></div>
            <div className="relative w-full max-w-sm bg-white dark:bg-slate-900 rounded-t-[2rem] sm:rounded-[2rem] p-6 shadow-2xl animate-in slide-in-from-bottom duration-300">
                <div className="w-12 h-1.5 bg-slate-200 dark:bg-slate-700 rounded-full mx-auto mb-6"></div>
                <h3 className="text-lg font-bold mb-4 text-center">Delete Message?</h3>

                <div className="flex flex-col gap-3">
                    {messageToDelete.senderId === currentUser.uid && (
                        <button 
                            onClick={() => confirmDelete('everyone')}
                            className="w-full p-4 rounded-2xl bg-slate-100 dark:bg-slate-800 text-red-500 font-bold hover:bg-red-50 dark:hover:bg-red-900/10 transition-colors flex items-center justify-between group"
                        >
                            <span>Delete for everyone</span>
                            <svg className="w-5 h-5 opacity-0 group-hover:opacity-100 transition-opacity" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                        </button>
                    )}
                    <button 
                        onClick={() => confirmDelete('me')}
                        className="w-full p-4 rounded-2xl bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-200 font-bold hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors flex items-center justify-between"
                    >
                        <span>Delete for me</span>
                        <svg className="w-5 h-5 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" /></svg>
                    </button>
                    <button 
                        onClick={() => setShowDeleteOptions(false)}
                        className="w-full p-4 rounded-2xl border-2 border-slate-100 dark:border-slate-800 text-slate-500 font-bold hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors mt-2"
                    >
                        Cancel
                    </button>
                </div>
            </div>
        </div>
      )}

      {forwardingMessage && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-950/60 backdrop-blur-md" onClick={() => setForwardingMessage(null)}></div>
          <div className="relative w-full max-w-sm bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl flex flex-col max-h-[70vh] animate-in zoom-in-95">
             <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between">
                <h3 className="text-xl font-bold">Forward Message</h3>
                <button onClick={() => setForwardingMessage(null)} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full">
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
             </div>
             <div className="flex-1 overflow-y-auto p-4 space-y-2 no-scrollbar">
                {availableChats.map(c => {
                   const isGrp = c.type === 'group';
                   const target = isGrp ? null : allUsers.find(u => u.uid === c.participants.find(p => p !== currentUser.uid));
                   return (
                     <button key={c.id} onClick={() => handleForward(c)} className="w-full flex items-center gap-3 p-3 hover:bg-slate-50 dark:hover:bg-slate-800 rounded-2xl transition-colors text-left">
                        <img src={isGrp ? c.groupIcon : target?.photoURL || `https://picsum.photos/seed/${c.id}/100`} className="w-10 h-10 rounded-xl object-cover" alt="" />
                        <span className="font-bold text-sm flex-1 truncate">{isGrp ? c.name : target?.name || 'Contact'}</span>
                     </button>
                   );
                })}
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { CallSession, CallStatus } from '../../types';
import { updateCallStatus, getCallById, updateCallSignal, addIceCandidate, subscribeToCall } from '../../firebase';

interface CallModalProps {
  session: CallSession;
  onHangUp: () => void;
}

const SERVERS = {
  iceServers: [
    { urls: ['stun:stun1.l.google.com:19302', 'stun:stun2.l.google.com:19302'] }
  ]
};

export const CallModal: React.FC<CallModalProps> = ({ session, onHangUp }) => {
  const [status, setStatus] = useState<CallStatus | 'calling' | 'denied'>(session.isIncoming ? 'ringing' : 'calling');
  const [isMuted, setIsMuted] = useState(false);
  const [isVideoOff, setIsVideoOff] = useState(session.type === 'voice');
  const [duration, setDuration] = useState(0);

  const localVideoRef = useRef<HTMLVideoElement>(null);
  const remoteVideoRef = useRef<HTMLVideoElement>(null);
  const remoteAudioRef = useRef<HTMLAudioElement>(null);
  const ringtoneRef = useRef<HTMLAudioElement | null>(null);

  const pc = useRef<RTCPeerConnection | null>(null);
  const localStream = useRef<MediaStream | null>(null);

  // Initialize Ringtone for incoming calls
  useEffect(() => {
    if (session.isIncoming && status === 'ringing') {
      try {
        const audio = new Audio("https://cdn.pixabay.com/download/audio/2022/03/24/audio_c8c8a73467.mp3?filename=smartphone-ringtone-6260.mp3");
        audio.loop = true;
        audio.play().catch(e => console.warn("Autoplay blocked for ringtone", e));
        ringtoneRef.current = audio;
      } catch (e) {}
    } else {
      if (ringtoneRef.current) {
        ringtoneRef.current.pause();
        ringtoneRef.current = null;
      }
    }
    return () => {
      if (ringtoneRef.current) {
        ringtoneRef.current.pause();
      }
    };
  }, [session.isIncoming, status]);

  // 1. Initialize Peer Connection & Local Stream
  useEffect(() => {
    const init = async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
            audio: true, 
            video: session.type === 'video' ? { facingMode: 'user' } : false 
        });
        localStream.current = stream;

        // IMPORTANT: Local video must be muted to prevent feedback loop
        if (localVideoRef.current) {
            localVideoRef.current.srcObject = stream;
            localVideoRef.current.muted = true;
        }

        pc.current = new RTCPeerConnection(SERVERS);

        // Add tracks
        stream.getTracks().forEach(track => {
            if (pc.current) pc.current.addTrack(track, stream);
        });

        // Handle remote stream
        pc.current.ontrack = (event) => {
            const track = event.track;
            const remoteStream = new MediaStream([track]);

            if (track.kind === 'video') {
                if (remoteVideoRef.current) remoteVideoRef.current.srcObject = remoteStream;
            } else if (track.kind === 'audio') {
                // IMPORTANT: Audio goes to a separate audio element that is always active
                if (remoteAudioRef.current) {
                    remoteAudioRef.current.srcObject = remoteStream;
                    remoteAudioRef.current.play().catch(e => console.error("Remote audio play error", e));
                }
            }
        };

        // Handle ICE candidates
        pc.current.onicecandidate = (event) => {
            if (event.candidate) {
                addIceCandidate(session.id, event.candidate, session.isIncoming ? 'callee' : 'caller');
            }
        };

        // If caller, create offer
        if (!session.isIncoming) {
            const offer = await pc.current.createOffer();
            await pc.current.setLocalDescription(offer);
            await updateCallSignal(session.id, { offer });
        }

      } catch (err) {
        console.error("Media/WebRTC Error:", err);
        setStatus('denied');
      }
    };

    // Only init WebRTC immediately if we are the Caller. 
    // If Incoming, wait until Accept.
    if (!session.isIncoming) {
        init();
    }

    return () => {
       if(localStream.current) localStream.current.getTracks().forEach(t => t.stop());
       if(pc.current) pc.current.close();
    };
  }, []);

  // 2. Listen for Signaling Changes
  useEffect(() => {
    const unsubscribe = subscribeToCall(session.id, async (data) => {
        if (!data) return;

        // Handle Status Updates
        if (data.status === 'ended' || data.status === 'rejected') {
            onHangUp();
        } else if (data.status === 'accepted') {
            setStatus('accepted');
        }

        if (!pc.current) return;

        // Handle Signaling
        if (!session.isIncoming && data.answer && !pc.current.currentRemoteDescription) {
            // Caller receives Answer
            const answer = new RTCSessionDescription(data.answer);
            await pc.current.setRemoteDescription(answer);
        }

        // Handle Candidates
        const newCandidates = session.isIncoming ? data.callerCandidates : data.calleeCandidates;
        if (newCandidates && newCandidates.length > 0) {
           newCandidates.forEach(async (c: any) => {
               try { await pc.current?.addIceCandidate(new RTCIceCandidate(c)); } catch(e) {}
           });
        }
    });
    return () => unsubscribe();
  }, [session.id, session.isIncoming]);

  const handleAccept = async () => {
    // Initialize WebRTC for the Callee now
    try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
            audio: true, 
            video: session.type === 'video' 
        });
        localStream.current = stream;
        if (localVideoRef.current) {
            localVideoRef.current.srcObject = stream;
            localVideoRef.current.muted = true;
        }

        pc.current = new RTCPeerConnection(SERVERS);

        stream.getTracks().forEach(track => pc.current?.addTrack(track, stream));

        pc.current.ontrack = (event) => {
            const track = event.track;
            const remoteStream = new MediaStream([track]);
            if (track.kind === 'video' && remoteVideoRef.current) {
                remoteVideoRef.current.srcObject = remoteStream;
            } else if (track.kind === 'audio' && remoteAudioRef.current) {
                remoteAudioRef.current.srcObject = remoteStream;
                remoteAudioRef.current.play().catch(console.error);
            }
        };

        pc.current.onicecandidate = (event) => {
            if (event.candidate) addIceCandidate(session.id, event.candidate, 'callee');
        };

        // Fetch Offer
        const callData = await getCallById(session.id);
        if (callData?.offer) {
            await pc.current.setRemoteDescription(new RTCSessionDescription(callData.offer));
            const answer = await pc.current.createAnswer();
            await pc.current.setLocalDescription(answer);

            await updateCallSignal(session.id, { answer });
            await updateCallStatus(session.id, 'accepted');
            setStatus('accepted');
        }
    } catch(err) {
        console.error("Accept Error", err);
        setStatus('denied');
    }
  };

  const handleDecline = async () => {
    await updateCallStatus(session.id, 'rejected');
    onHangUp();
  };

  const toggleMute = () => {
    if (localStream.current) {
        const track = localStream.current.getAudioTracks()[0];
        track.enabled = !track.enabled;
        setIsMuted(!track.enabled);
    }
  };

  const toggleVideo = () => {
    if (localStream.current) {
        const track = localStream.current.getVideoTracks()[0];
        if (track) {
            track.enabled = !track.enabled;
            setIsVideoOff(!track.enabled);
        }
    }
  };

  // Timer
  useEffect(() => {
    let t: any;
    if (status === 'accepted') t = setInterval(() => setDuration(s => s + 1), 1000);
    return () => clearInterval(t);
  }, [status]);

  const formatDuration = (s: number) => {
    const mins = Math.floor(s / 60);
    const secs = s % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="fixed inset-0 z-[1000] bg-slate-950 flex flex-col items-center justify-center text-white overflow-hidden animate-in fade-in duration-500">

      {/* Remote Video (Full Screen) */}
      <video 
        ref={remoteVideoRef} 
        autoPlay 
        playsInline 
        className={`absolute inset-0 w-full h-full object-cover z-0 ${session.type === 'voice' ? 'hidden' : ''}`}
      />

      {/* Dedicated Audio Element for Voice */}
      <audio ref={remoteAudioRef} autoPlay />

      {/* Background Partner Blur (if voice or waiting) */}
      <div className={`absolute inset-0 opacity-40 blur-[50px] pointer-events-none bg-slate-900 z-0 ${status === 'accepted' && session.type === 'video' ? 'opacity-0' : 'opacity-100'}`}>
        <img src={session.partner.photoURL} className="w-full h-full object-cover" alt="" />
      </div>

      {/* Main UI Overlay */}
      <div className="relative z-10 flex flex-col items-center w-full max-w-lg px-6 h-full py-12 justify-between">

        {/* Header / Info */}
        <div className="text-center mt-10">
            {status !== 'accepted' && (
                <div className="w-32 h-32 rounded-full overflow-hidden border-4 border-white/10 shadow-2xl mx-auto mb-6">
                    <img src={session.partner.photoURL} className="w-full h-full object-cover" alt="" />
                </div>
            )}
            <h2 className="text-3xl font-black tracking-tight drop-shadow-md">{session.partner.name}</h2>
            <p className="text-white/80 font-bold tracking-[0.2em] uppercase text-xs mt-2 bg-black/20 inline-block px-4 py-1 rounded-full backdrop-blur-md">
                {status === 'accepted' ? formatDuration(duration) : status === 'calling' ? 'Calling...' : 'Incoming Call...'}
            </p>
        </div>

        {/* Local Video Preview - Show only if accepted & video type */}
        {status === 'accepted' && session.type === 'video' && (
             <div className="w-32 h-48 bg-black rounded-2xl overflow-hidden shadow-2xl border border-white/20 absolute top-6 right-6 z-20">
                <video ref={localVideoRef} autoPlay muted playsInline className={`w-full h-full object-cover mirror ${isVideoOff ? 'hidden' : ''}`} />
                {isVideoOff && <div className="w-full h-full flex items-center justify-center text-xs text-white/50 uppercase font-bold">Cam Off</div>}
             </div>
        )}

        {/* Controls */}
        <div className="flex items-center gap-6 mb-8">
            {/* INCOMING CALL UI */}
            {status === 'ringing' && session.isIncoming ? (
                <>
                    <button onClick={handleDecline} className="flex flex-col items-center gap-2 group">
                        <div className="p-6 bg-red-600 rounded-full shadow-lg group-hover:scale-110 transition-transform">
                            <svg className="w-8 h-8 rotate-[135deg]" fill="currentColor" viewBox="0 0 24 24"><path d="M6.62 10.79c1.44 2.83 3.76 5.14 6.59 6.59l2.2-2.2c.27-.27.67-.36 1.02-.24 1.12.37 2.33.57 3.57.57.55 0 1 .45 1 1V20c0 .55-.45 1-1 1-9.39 0-17-7.61-17-17 0-.55.45-1 1-1h3.5c.55 0 1 .45 1 1 0 1.25.2 2.45.57 3.57.11.35.03.74-.25 1.02l-2.2 2.2z" /></svg>
                        </div>
                        <span className="text-xs font-bold uppercase tracking-widest">Decline</span>
                    </button>
                    <button onClick={handleAccept} className="flex flex-col items-center gap-2 group">
                        <div className="p-6 bg-green-500 rounded-full shadow-lg group-hover:scale-110 transition-transform animate-pulse">
                            <svg className="w-8 h-8" fill="currentColor" viewBox="0 0 24 24"><path d="M6.62 10.79c1.44 2.83 3.76 5.14 6.59 6.59l2.2-2.2c.27-.27.67-.36 1.02-.24 1.12.37 2.33.57 3.57.57.55 0 1 .45 1 1V20c0 .55-.45 1-1 1-9.39 0-17-7.61-17-17 0-.55.45-1 1-1h3.5c.55 0 1 .45 1 1 0 1.25.2 2.45.57 3.57.11.35.03.74-.25 1.02l-2.2 2.2z" /></svg>
                        </div>
                        <span className="text-xs font-bold uppercase tracking-widest">Accept</span>
                    </button>
                </>
            ) : (
                /* ONGOING / OUTGOING UI */
                <>
                    <button onClick={toggleMute} className={`p-4 rounded-full ${isMuted ? 'bg-white text-slate-900' : 'bg-white/20 hover:bg-white/30 backdrop-blur-md'}`}><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d={isMuted ? "M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3zM5.5 5.5l13 13" : "M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z"} /></svg></button>
                    <button onClick={handleDecline} className="p-6 bg-red-600 rounded-full shadow-lg hover:scale-110 transition-transform"><svg className="w-8 h-8 rotate-[135deg]" fill="currentColor" viewBox="0 0 24 24"><path d="M6.62 10.79c1.44 2.83 3.76 5.14 6.59 6.59l2.2-2.2c.27-.27.67-.36 1.02-.24 1.12.37 2.33.57 3.57.57.55 0 1 .45 1 1V20c0 .55-.45 1-1 1-9.39 0-17-7.61-17-17 0-.55.45-1 1-1h3.5c.55 0 1 .45 1 1 0 1.25.2 2.45.57 3.57.11.35.03.74-.25 1.02l-2.2 2.2z" /></svg></button>
                    {session.type === 'video' && (
