            className="absolute top-[4.5rem] left-4 right-4 z-20 bg-white/95 dark:bg-slate-800/95 backdrop-blur-md rounded-xl p-3 border-l-4 border-indigo-500 shadow-lg flex items-center justify-between cursor-pointer animate-in slide-in-from-top-2"
        >
            <div className="min-w-0">
                <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest mb-0.5">Pinned Message</p>
                <p className="text-xs text-slate-600 dark:text-slate-300 truncate font-medium">{pinnedMessage.text || 'Media File'}</p>
            </div>
            <button 
                onClick={(e) => { e.stopPropagation(); togglePinMessage(chat.id, pinnedMessage.id); }}
                className="p-2 text-slate-400 hover:text-indigo-500 transition-colors"
            >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
            </button>
        </div>
      )}

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-1 scroll-smooth z-[5] no-scrollbar">
        {messages.map((msg, index) => (
          <React.Fragment key={msg.id || index}>
            {renderDateSeparator(msg.timestamp, messages[index-1]?.timestamp)}
            <MessageBubble 
              message={msg} 
              isOwn={msg.senderId === currentUser.uid} 
              isAI={msg.senderId === 'gemini_ai'} 
              onReply={setReplyingTo} 
              onForward={openForwardModal}
              onDelete={triggerDeleteFlow}
              onEdit={handleEditMessage}
              onPin={handlePinMessage}
              isPinned={pinnedMessageIds.includes(msg.id)}
              onMediaClick={handleMediaClick}
            />
          </React.Fragment>
        ))}
        {/* Visible Typing Bubble */}
        {typingUsers.length > 0 && (
          <div className="flex items-end gap-2 px-2 py-2 animate-in slide-in-from-left-4 fade-in duration-300">
             {!isGroup && <img src={otherUser?.photoURL || `https://picsum.photos/seed/${chat.id}/50`} className="w-8 h-8 rounded-full border border-white dark:border-slate-800" alt="" />}
             <div className="bg-white dark:bg-slate-800 rounded-2xl rounded-bl-none px-4 py-3 flex items-center gap-1.5 shadow-sm border border-slate-100 dark:border-slate-700">
                <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce"></div>
             </div>
          </div>
        )}
      </div>

      <div className="glass border-t border-slate-200 dark:border-slate-800 z-10 flex flex-col">
        {editingMessage && (
             <div className="px-4 py-2 bg-indigo-50 dark:bg-indigo-900/20 border-l-4 border-indigo-500 flex items-center justify-between">
                <div>
                    <span className="text-xs font-bold text-indigo-500 uppercase tracking-widest">Editing Message</span>
                    <p className="text-xs text-slate-500 dark:text-slate-400 line-clamp-1">{editingMessage.text}</p>
                </div>
                <button onClick={() => { setEditingMessage(null); setInputText(''); }} className="p-1 text-indigo-500 hover:bg-indigo-100 rounded-full">
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
             </div>
        )}
        {replyingTo && (
          <div className="px-4 py-2 bg-slate-50 dark:bg-slate-800/80 border-l-4 border-indigo-500 flex items-center justify-between">
             <div className="min-w-0">
                <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest mb-0.5">Replying to {replyingTo.senderId === currentUser.uid ? 'Yourself' : 'Contact'}</p>
                <p className="text-xs text-slate-500 truncate">{replyingTo.text || 'Media Message'}</p>
             </div>
             <button onClick={() => setReplyingTo(null)} className="p-1.5 text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-full">
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
             </button>
          </div>
        )}

        <div className="p-3 md:p-4 flex gap-2.5 items-center">
          {isRecording ? (
             <div className="flex-1 flex items-center justify-between bg-red-500 text-white rounded-[1.5rem] px-6 py-4 animate-pulse">
                <div className="flex items-center gap-3">
                   <div className="w-3 h-3 bg-white rounded-full animate-bounce"></div>
                   <span className="font-bold text-sm tracking-widest">{formatDuration(recordingDuration)}</span>
                </div>
                <div className="flex items-center gap-3">
                    <button onClick={() => stopRecording(false)} className="text-white/80 hover:text-white text-xs font-bold uppercase">Cancel</button>
                    <button onClick={() => stopRecording(true)} className="p-2 bg-white text-red-500 rounded-full shadow-lg">
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M5 13l4 4L19 7" /></svg>
                    </button>
                </div>
             </div>
          ) : (
            <>
              <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" />
              <button type="button" onClick={() => fileInputRef.current?.click()} className="p-3.5 text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-2xl shrink-0 transition-colors active:scale-90"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 4v16m8-8H4" /></svg></button>

              <form onSubmit={handleSend} className="flex-1 flex gap-2">
                 <input 
                    ref={inputRef}
                    type="text" 
                    value={inputText} 
                    onChange={handleInputChange} 
                    placeholder="Type a message..." 
                    className="flex-1 bg-white/60 dark:bg-slate-800/80 rounded-[1.5rem] px-6 py-4 text-sm font-medium outline-none border border-slate-200 dark:border-slate-700 focus:ring-2 focus:ring-indigo-500/20 transition-all shadow-inner" 
                />
                {inputText.trim() ? (
                    <button type="submit" className="p-4 bg-indigo-500 text-white rounded-2xl shadow-xl shadow-indigo-500/20 transition-all shrink-0 active:scale-95">
                        {editingMessage ? (
                             <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M5 13l4 4L19 7" /></svg>
                        ) : (
                             <svg className="w-6 h-6 rotate-90" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
                        )}
                    </button>
                ) : (
                    <button type="button" onClick={startRecording} className="p-4 bg-slate-100 dark:bg-slate-800 text-slate-500 hover:bg-red-500 hover:text-white rounded-2xl transition-all shrink-0 active:scale-95 group">
                        <svg className="w-6 h-6 group-hover:scale-110 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
                    </button>
                )}
              </form>
            </>
          )}
        </div>
      </div>

      {/* Group Info Modal */}
      {showGroupInfo && (
        <GroupInfoModal 
          chat={chat}
          currentUser={currentUser}
          onClose={() => setShowGroupInfo(false)}
        />
      )}

      {/* Media Viewer Modal */}
      {viewingMedia && (
        <MediaViewer 
           message={viewingMedia}
           onClose={() => setViewingMedia(null)}
           onForward={openForwardModal}
           onReply={(msg) => setReplyingTo(msg)}
        />
      )}

      {/* Delete Options Bottom Sheet / Modal */}
      {showDeleteOptions && messageToDelete && (
        <div className="fixed inset-0 z-[200] flex items-end justify-center sm:items-center">
            <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setShowDeleteOptions(false)}></div>
            <div className="relative w-full max-w-sm bg-white dark:bg-slate-900 rounded-t-[2rem] sm:rounded-[2rem] p-6 shadow-2xl animate-in slide-in-from-bottom duration-300">
                <div className="w-12 h-1.5 bg-slate-200 dark:bg-slate-700 rounded-full mx-auto mb-6"></div>
                <h3 className="text-lg font-bold mb-4 text-center">Delete Message?</h3>

                <div className="flex flex-col gap-3">
                    {messageToDelete.senderId === currentUser.uid && (
                        <button 
                            onClick={() => confirmDelete('everyone')}
                            className="w-full p-4 rounded-2xl bg-slate-100 dark:bg-slate-800 text-red-500 font-bold hover:bg-red-50 dark:hover:bg-red-900/10 transition-colors flex items-center justify-between group"
                        >
                            <span>Delete for everyone</span>
                            <svg className="w-5 h-5 opacity-0 group-hover:opacity-100 transition-opacity" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                        </button>
                    )}
                    <button 
                        onClick={() => confirmDelete('me')}
                        className="w-full p-4 rounded-2xl bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-200 font-bold hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors flex items-center justify-between"
                    >
                        <span>Delete for me</span>
                        <svg className="w-5 h-5 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" /></svg>
                    </button>
                    <button 
                        onClick={() => setShowDeleteOptions(false)}
                        className="w-full p-4 rounded-2xl border-2 border-slate-100 dark:border-slate-800 text-slate-500 font-bold hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors mt-2"
                    >
                        Cancel
                    </button>
                </div>
            </div>
        </div>
      )}

      {forwardingMessage && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-950/60 backdrop-blur-md" onClick={() => setForwardingMessage(null)}></div>
          <div className="relative w-full max-w-sm bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl flex flex-col max-h-[70vh] animate-in zoom-in-95">
             <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between">
                <h3 className="text-xl font-bold">Forward Message</h3>
                <button onClick={() => setForwardingMessage(null)} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full">
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
             </div>
             <div className="flex-1 overflow-y-auto p-4 space-y-2 no-scrollbar">
                {availableChats.map(c => {
                   const isGrp = c.type === 'group';
                   const target = isGrp ? null : allUsers.find(u => u.uid === c.participants.find(p => p !== currentUser.uid));
                   return (
                     <button key={c.id} onClick={() => handleForward(c)} className="w-full flex items-center gap-3 p-3 hover:bg-slate-50 dark:hover:bg-slate-800 rounded-2xl transition-colors text-left">
                        <img src={isGrp ? c.groupIcon : target?.photoURL || `https://picsum.photos/seed/${c.id}/100`} className="w-10 h-10 rounded-xl object-cover" alt="" />
                        <span className="font-bold text-sm flex-1 truncate">{isGrp ? c.name : target?.name || 'Contact'}</span>
                     </button>
                   );
                })}
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Message } from '../../types';

interface MessageBubbleProps {
  message: Message;
  isOwn: boolean;
  isAI?: boolean;
  onReply: (msg: Message) => void;
  onForward: (msg: Message) => void;
  onDelete?: (msg: Message) => void;
  onEdit?: (msg: Message) => void;
  onPin?: (msg: Message) => void;
  isPinned?: boolean;
  onMediaClick?: (msg: Message) => void;
}

export const MessageBubble: React.FC<MessageBubbleProps> = ({ message, isOwn, isAI, onReply, onForward, onDelete, onEdit, onPin, isPinned, onMediaClick }) => {
  const [showMenu, setShowMenu] = useState(false);
  const [swipeOffset, setSwipeOffset] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [progress, setProgress] = useState(0);
  const [currentTime, setCurrentTime] = useState(0);

  const menuRef = useRef<HTMLDivElement>(null);
  const audioRef = useRef<HTMLAudioElement>(null);
  const touchStartX = useRef<number | null>(null);

  useEffect(() => {
    const handleClick = (e: MouseEvent) => { if (menuRef.current && !menuRef.current.contains(e.target as Node)) setShowMenu(false); };
    if (showMenu) document.addEventListener('mousedown', handleClick);
    return () => document.removeEventListener('mousedown', handleClick);
  }, [showMenu]);

  const formatTime = (ts: number) => new Date(ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

  const handleTouchStart = (e: React.TouchEvent) => { touchStartX.current = e.touches[0].clientX; };
  const handleTouchMove = (e: React.TouchEvent) => {
    if (touchStartX.current === null) return;
    const deltaX = e.touches[0].clientX - touchStartX.current;
    if (deltaX > 0) setSwipeOffset(Math.min(deltaX, 80));
  };
  const handleTouchEnd = () => {
    if (swipeOffset > 50) onReply(message);
    setSwipeOffset(0);
    touchStartX.current = null;
  };

  const toggleAudio = () => {
    const audio = audioRef.current;
    if (audio) {
      if (isPlaying) {
        audio.pause();
      } else {
        // Reset all other audios if needed, or just play this one
        document.querySelectorAll('audio').forEach(a => { if(a !== audio) a.pause() });
        const playPromise = audio.play();
        if (playPromise !== undefined) {
          playPromise.catch(e => {
            console.error("Audio play error:", e);
            setIsPlaying(false);
          });
        }
      }
    }
  };

  const handleTimeUpdate = () => {
    const audio = audioRef.current;
    if (audio) {
        setCurrentTime(audio.currentTime);
        if (audio.duration) {
            setProgress((audio.currentTime / audio.duration) * 100);
        }
    }
  };

  const renderStatus = () => {
    if (!isOwn) return null;
    const isSeen = message.status === 'seen';
    const isDelivered = message.status === 'delivered' || isSeen;
    return (
      <div className={`flex -space-x-2 ${isSeen ? 'text-sky-400' : 'text-white/50'} ml-1`}>
        <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3.5" d="M5 13l4 4L19 7" /></svg>
        {isDelivered && <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3.5" d="M5 13l4 4L19 7" /></svg>}
      </div>
    );
  };

  const isDeleted = message.type === 'deleted';

  return (
    <div className={`relative flex w-full ${isOwn ? 'justify-end' : 'justify-start'} mb-2 px-2 group animate-in slide-in-from-${isOwn ? 'right' : 'left'}-4 duration-500`} id={`msg-${message.id}`}>
      {/* Swipe Indicator */}
      <div className="absolute left-4 top-1/2 -translate-y-1/2 transition-all duration-200 pointer-events-none" style={{ opacity: swipeOffset / 50, transform: `translateY(-50%) scale(${Math.min(swipeOffset / 50, 1.2)})` }}>
        <div className="bg-indigo-500 p-2 rounded-full text-white shadow-lg"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M3 10h10a8 8 0 018 8v2M3 10l6 6m-6-6l6-6" /></svg></div>
      </div>

      <div className={`relative flex flex-col max-w-[82%] ${isOwn ? 'items-end' : 'items-start'} transition-transform duration-200`} style={{ transform: `translateX(${swipeOffset}px)` }} onTouchStart={handleTouchStart} onTouchMove={handleTouchMove} onTouchEnd={handleTouchEnd}>

        {/* Context Menu */}
        {showMenu && !isDeleted && (
          <div ref={menuRef} className={`absolute z-50 bottom-full mb-3 bg-white/90 dark:bg-slate-800/95 backdrop-blur-xl rounded-2xl shadow-2xl border border-white/20 p-1.5 flex flex-col min-w-[150px] animate-in zoom-in-95 origin-bottom-${isOwn ? 'right' : 'left'}`}>
            <button onClick={() => { onReply(message); setShowMenu(false); }} className="px-4 py-2.5 hover:bg-indigo-500 hover:text-white rounded-xl text-left font-bold text-xs uppercase tracking-wider flex items-center gap-2 text-slate-700 dark:text-slate-200">
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 10h10a8 8 0 018 8v2M3 10l6 6m-6-6l6-6" /></svg> Reply
            </button>
            <button onClick={() => { onForward(message); setShowMenu(false); }} className="px-4 py-2.5 hover:bg-indigo-500 hover:text-white rounded-xl text-left font-bold text-xs uppercase tracking-wider flex items-center gap-2 text-slate-700 dark:text-slate-200">
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg> Forward
            </button>
            {onPin && (
               <button onClick={() => { onPin(message); setShowMenu(false); }} className="px-4 py-2.5 hover:bg-indigo-500 hover:text-white rounded-xl text-left font-bold text-xs uppercase tracking-wider flex items-center gap-2 text-slate-700 dark:text-slate-200">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" /></svg> {isPinned ? 'Unpin' : 'Pin'}
               </button>
            )}
            {isOwn && message.type === 'text' && onEdit && (
                <button onClick={() => { onEdit(message); setShowMenu(false); }} className="px-4 py-2.5 hover:bg-indigo-500 hover:text-white rounded-xl text-left font-bold text-xs uppercase tracking-wider flex items-center gap-2 text-slate-700 dark:text-slate-200">
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg> Edit
                </button>
            )}
            {onDelete && (
                <button onClick={() => { onDelete(message); setShowMenu(false); }} className="px-4 py-2.5 text-red-500 hover:bg-red-500 hover:text-white rounded-xl text-left font-bold text-xs uppercase tracking-wider flex items-center gap-2">
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg> Delete
                </button>
            )}
          </div>
        )}

        {/* Message Bubble */}
        <div 
          onClick={() => !isDeleted && setShowMenu(!showMenu)} 
          className={`relative px-4 py-3 rounded-[1.75rem] transition-all active:scale-[0.97] cursor-pointer shadow-lg group-hover:shadow-xl overflow-hidden 
            ${isDeleted 
                ? 'bg-slate-200 dark:bg-slate-800 text-slate-500 italic border border-slate-300 dark:border-slate-700' 
                : isOwn 
                    ? 'bg-gradient-to-br from-indigo-600 via-indigo-500 to-indigo-600 text-white rounded-tr-none' 
                    : isAI 
                        ? 'bg-slate-900 text-white border-2 border-indigo-500/40 rounded-tl-none' 
                        : 'bg-white/90 dark:bg-slate-800/90 backdrop-blur-md text-slate-900 dark:text-slate-100 rounded-tl-none border border-white/20 dark:border-slate-700/50'
            }`}
        >
          {isPinned && !isDeleted && (
             <div className="absolute top-0 right-0 p-1 bg-black/20 rounded-bl-xl text-white">
                <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 24 24"><path d="M16 12V4H17V2H7V4H8V12L6 14V16H11V22H13V16H18V14L16 12Z"/></svg>
             </div>
          )}

          {message.replyContext && !isDeleted && (
            <div className={`mb-2 p-2 rounded-xl border-l-4 text-[11px] flex flex-col gap-0.5 ${isOwn ? 'bg-white/10 border-white/40' : 'bg-indigo-500/10 border-indigo-500 dark:bg-indigo-900/30'}`}>
              <span className={`font-black uppercase tracking-tighter ${isOwn ? 'text-white' : 'text-indigo-500 dark:text-indigo-400'}`}>{message.replyContext.senderName}</span>
              <p className="truncate opacity-80 font-medium italic">{message.replyContext.text}</p>
            </div>
          )}

          {isDeleted ? (
              <div className="flex items-center gap-2">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M18.364 18.364A9 9 0 005.636 5.636m12.728 12.728L5.636 5.636" /></svg>
                  <span className="text-sm font-medium">{message.text}</span>
              </div>
          ) : message.type === 'voice' && message.audioUrl ? (
             <div className="flex items-center gap-3 min-w-[180px]">
                <button onClick={(e) => { e.stopPropagation(); toggleAudio(); }} className={`w-10 h-10 rounded-full flex items-center justify-center shrink-0 transition-transform active:scale-90 ${isOwn ? 'bg-white/20 text-white hover:bg-white/30' : 'bg-indigo-500 text-white hover:bg-indigo-600'}`}>
                   {isPlaying ? <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/></svg> : <svg className="w-4 h-4 ml-0.5" fill="currentColor" viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>}
                </button>
                <div className="flex flex-col gap-1 w-full">
                    {/* Progress Bar */}
                    <div className={`h-1.5 rounded-full w-32 relative overflow-hidden ${isOwn ? 'bg-white/30' : 'bg-slate-300 dark:bg-slate-600'}`}>
                        <div 
                            className={`h-full rounded-full transition-all duration-100 ease-linear ${isOwn ? 'bg-white' : 'bg-indigo-500'}`}
                            style={{ width: `${progress}%` }}
                        ></div>
                    </div>
                    <div className="flex justify-between w-32">
                        <span className={`text-[10px] font-bold uppercase tracking-wider ${isOwn ? 'text-white/70' : 'text-slate-500'}`}>
                            {isPlaying ? `${Math.floor(currentTime / 60)}:${Math.floor(currentTime % 60).toString().padStart(2, '0')}` : (message.duration ? `${Math.floor(message.duration / 60)}:${(message.duration % 60).toString().padStart(2, '0')}` : 'Voice')}
                        </span>
                    </div>
                </div>
                {message.audioUrl && (
                  <audio 
                    ref={audioRef} 
                    src={message.audioUrl} 
                    onPlay={() => setIsPlaying(true)}
                    onPause={() => setIsPlaying(false)}
                    onEnded={() => { setIsPlaying(false); setProgress(0); setCurrentTime(0); }}
                    onTimeUpdate={handleTimeUpdate}
                    onError={(e) => {
                      console.error("Audio load failed", e);
                      setIsPlaying(false);
                    }}
                    className="hidden" 
                    preload="metadata"
                  />
                )}
             </div>
          ) : message.type === 'image' && message.fileUrl ? (
            <div 
                className="relative mb-2 -mx-1 -mt-1 overflow-hidden rounded-2xl cursor-zoom-in"
                onClick={(e) => { 
                    e.stopPropagation(); // Prevent menu toggle
                    if(onMediaClick) onMediaClick(message); 
                }}
            >
                <img src={message.fileUrl} className="max-h-80 w-full object-cover" alt="" />
            </div>
          ) : message.type === 'video' && message.fileUrl ? (
            <div 
                className="relative mb-2 -mx-1 -mt-1 overflow-hidden rounded-2xl bg-black cursor-pointer"
                onClick={(e) => { 
                    e.stopPropagation(); 
                    if(onMediaClick) onMediaClick(message); 
                }}
            >
                <video src={message.fileUrl} className="max-h-80 w-full object-contain pointer-events-none" onError={(e) => console.error("Video load failed", e)} />
                <div className="absolute inset-0 flex items-center justify-center bg-black/20 group-hover:bg-black/10 transition-colors">
                     <div className="p-3 bg-white/20 backdrop-blur-md rounded-full text-white border border-white/30 shadow-xl">
                        <svg className="w-6 h-6 ml-1" fill="currentColor" viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>
                     </div>
                </div>
            </div>
          ) : (
            <p className="text-[14.5px] leading-[1.45] font-medium whitespace-pre-wrap">{message.text}</p>
          )}

          <div className={`flex items-center gap-1.5 justify-end mt-1.5 ${isOwn ? 'text-white/60' : 'text-slate-400 dark:text-slate-500'}`}>
            {message.isEdited && !isDeleted && <span className="text-[9px] italic mr-1">(edited)</span>}
            <span className="text-[9.5px] font-black uppercase tracking-tighter">{formatTime(message.timestamp)}</span>
            {renderStatus()}
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Message } from '../../types';

interface MediaViewerProps {
  message: Message;
  onClose: () => void;
  onForward: (msg: Message) => void;
  onReply: (msg: Message) => void;
  onSave?: (msg: Message) => void;
}

export const MediaViewer: React.FC<MediaViewerProps> = ({ message, onClose, onForward, onReply, onSave }) => {
  const [showMenu, setShowMenu] = useState(false);
  const [isSaved, setIsSaved] = useState(false);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [onClose]);

  const handleDownload = async () => {
    if (!message.fileUrl) return;
    try {
      const response = await fetch(message.fileUrl);
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = message.fileName || `roxx_media_${Date.now()}.${message.type === 'video' ? 'mp4' : 'jpg'}`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      window.URL.revokeObjectURL(url);
      setShowMenu(false);
    } catch (e) {
      console.error("Download failed", e);
      // Fallback for cross-origin issues
      window.open(message.fileUrl, '_blank');
    }
  };

  const handleSaveToApp = () => {
    setIsSaved(true);
    if (onSave) onSave(message);
    setTimeout(() => {
        setIsSaved(false);
        setShowMenu(false);
    }, 2000);
  };

  const handleReplyClick = () => {
    onReply(message);
    onClose();
  };

  const handleForwardClick = () => {
    onForward(message);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-[250] bg-black flex flex-col items-center justify-center animate-in fade-in duration-200">

      {/* Top Bar */}
      <div className="absolute top-0 inset-x-0 z-[260] p-4 flex items-center justify-between bg-gradient-to-b from-black/80 to-transparent">
        <div className="flex items-center gap-4">
          <button onClick={onClose} className="p-2 text-white hover:bg-white/10 rounded-full transition-all">
             <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
          </button>
          <div className="flex flex-col">
            <span className="text-white font-bold text-sm">{message.senderId === 'me' ? 'You' : 'Media View'}</span>
            <span className="text-white/60 text-xs">{new Date(message.timestamp).toLocaleString()}</span>
          </div>
        </div>

        <div className="relative">
          <button onClick={() => setShowMenu(!showMenu)} className="p-2 text-white hover:bg-white/10 rounded-full transition-all">
             <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 5v.01M12 12v.01M12 19v.01M12 6a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2z" /></svg>
          </button>

          {showMenu && (
            <div className="absolute right-0 top-full mt-2 w-48 bg-white dark:bg-slate-800 rounded-xl shadow-2xl py-2 overflow-hidden animate-in zoom-in-95 origin-top-right">
               <button onClick={handleSaveToApp} className="w-full px-4 py-3 text-left text-sm font-bold text-slate-700 dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-700 flex items-center gap-3">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" /></svg>
                  Save to App
               </button>
               <button onClick={handleDownload} className="w-full px-4 py-3 text-left text-sm font-bold text-slate-700 dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-700 flex items-center gap-3">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                  Download
               </button>
               <button onClick={handleForwardClick} className="w-full px-4 py-3 text-left text-sm font-bold text-slate-700 dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-700 flex items-center gap-3">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
                  Forward
               </button>
               <button onClick={handleReplyClick} className="w-full px-4 py-3 text-left text-sm font-bold text-slate-700 dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-700 flex items-center gap-3">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 10h10a8 8 0 018 8v2M3 10l6 6m-6-6l6-6" /></svg>
                  Reply
               </button>
            </div>
          )}
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 w-full h-full flex items-center justify-center p-4">
        {message.type === 'video' ? (
           <video 
             src={message.fileUrl} 
             controls 
             autoPlay 
             className="max-w-full max-h-full object-contain shadow-2xl"
           />
        ) : (
           <img 
             src={message.fileUrl} 
             alt="Full View" 
             className="max-w-full max-h-full object-contain shadow-2xl"
           />
        )}
      </div>

      {/* Toast Notification for Save */}
      {isSaved && (
          <div className="absolute bottom-10 left-1/2 -translate-x-1/2 bg-white text-black px-6 py-3 rounded-full font-bold shadow-2xl animate-in slide-in-from-bottom-5">
              Media Saved to App Gallery
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { User, Chat, Message } from '../../types';
import { MessageBubble } from './MessageBubble';
import { GroupInfoModal } from './GroupInfoModal';
import { MediaViewer } from './MediaViewer';
import { getAIResponse } from '../../gemini';
import { getUserById, addMessage, getMessages, toggleChatLock, markMessagesAsSeen, markMessagesAsDelivered, getMyChats, getAllUsers, setTypingStatus, subscribeToChat, deleteMessage, deleteMessageForEveryone, deleteMessageForMe, editMessage, subscribeToUser, togglePinMessage } from '../../firebase';

interface ChatWindowProps {
  chat: Chat;
  currentUser: User;
  onClose: () => void;
  onUserClick: (user: User) => void;
  onCallStart?: (user: User, type: 'voice' | 'video') => void;
}

const WALLPAPER_CLASSES: Record<string, string> = {
  default: 'bg-slate-100 dark:bg-slate-950',
  indigo: 'bg-indigo-600',
  emerald: 'bg-emerald-700',
  rose: 'bg-rose-500',
  amber: 'bg-amber-500',
  dark: 'bg-black',
  gradient: 'bg-gradient-to-br from-purple-900 via-indigo-900 to-black',
};

const FONT_SIZE_CLASSES: Record<string, string> = {
  small: 'text-[12px]',
  medium: 'text-[14px]',
  large: 'text-[16px]',
};

export const ChatWindow: React.FC<ChatWindowProps> = ({ chat, currentUser, onClose, onUserClick, onCallStart }) => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [otherUser, setOtherUser] = useState<User | null>(null);
  const [isLocked, setIsLocked] = useState(chat.lockedBy?.includes(currentUser.uid) || false);
  const [inputText, setInputText] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [typingUsers, setTypingUsers] = useState<string[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [recordingDuration, setRecordingDuration] = useState(0);
  const [mediaRecorder, setMediaRecorder] = useState<MediaRecorder | null>(null);
  const [editingMessage, setEditingMessage] = useState<Message | null>(null);
  const [pinnedMessageIds, setPinnedMessageIds] = useState<string[]>([]);
  const [showGroupInfo, setShowGroupInfo] = useState(false);

  // UI State for Deletion
  const [messageToDelete, setMessageToDelete] = useState<Message | null>(null);
  const [showDeleteOptions, setShowDeleteOptions] = useState(false);

  // UI State for Media Viewing
  const [viewingMedia, setViewingMedia] = useState<Message | null>(null);

  const [wallpaper, setWallpaper] = useState('default');
  const [customUrl, setCustomUrl] = useState<string | null>(null);
  const [fontSize, setFontSize] = useState('medium');
  const [replyingTo, setReplyingTo] = useState<Message | null>(null);
  const [forwardingMessage, setForwardingMessage] = useState<Message | null>(null);
  const [availableChats, setAvailableChats] = useState<Chat[]>([]);
  const [allUsers, setAllUsers] = useState<User[]>([]);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const typingTimeoutRef = useRef<any>(null);
  const timerRef = useRef<any>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const inputRef = useRef<HTMLInputElement>(null);

  const isGroup = chat.type === 'group';
  // Safe access to participants
  const otherId = !isGroup && chat.participants 
    ? (chat.participants.find(p => p !== currentUser.uid) || (chat.participants.includes(currentUser.uid) ? currentUser.uid : '')) 
    : chat.id;

  const loadSettings = () => {
    try {
      const saved = localStorage.getItem('roxx_settings');
      if (saved) {
        const parsed = JSON.parse(saved);
        setWallpaper(parsed.wallpaper || 'default');
        setCustomUrl(parsed.customWallpaperUrl || null);
        setFontSize(parsed.fontSize || 'medium');
      }
    } catch (e) {
      console.warn("Settings corrupted, resetting");
      localStorage.removeItem('roxx_settings');
      setWallpaper('default');
    }
  };

  useEffect(() => {
    loadSettings();
    window.addEventListener('roxx_settings_updated', loadSettings);
    return () => window.removeEventListener('roxx_settings_updated', loadSettings);
  }, []);

  // Subscribe to Chat (Typing indicators, Pinned Messages)
  useEffect(() => {
    const unsubscribe = subscribeToChat(chat.id, (data) => {
      // Typing
      if (data.typing) {
        const activeTypers = Object.entries(data.typing)
          .filter(([uid, isTyping]) => uid !== currentUser.uid && isTyping)
          .map(([uid]) => uid);
        setTypingUsers(activeTypers);
      } else {
        setTypingUsers([]);
      }
      // Pinned Messages
      if (data.pinnedMessages) {
        setPinnedMessageIds(data.pinnedMessages);
      } else {
        setPinnedMessageIds([]);
      }
    });
    return () => unsubscribe();
  }, [chat.id, currentUser.uid]);

  // Subscribe to Other User (Online Status)
  useEffect(() => {
    if (isGroup || !otherId) return;

    getUserById(otherId).then(u => { if(u) setOtherUser(u); });

    const unsubscribe = subscribeToUser(otherId, (userData) => {
        setOtherUser(userData);
    });
    return () => unsubscribe();
  }, [otherId, isGroup]);

  // Messages Polling
  useEffect(() => {
    const sync = async () => {
      const msgs = await getMessages(chat.id);
      setMessages(prev => {
        if (msgs.length !== prev.length) return msgs;
        const changed = msgs.some((m, i) => {
            const p = prev[i];
            return p.id !== m.id || p.status !== m.status || p.text !== m.text || p.type !== m.type;
        });
        return changed ? msgs : prev;
      });
    };
    sync();
    const itv = setInterval(sync, 2000);
    return () => clearInterval(itv);
  }, [chat.id]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [messages, isTyping, isUploading, replyingTo, typingUsers, isRecording, editingMessage, pinnedMessageIds]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setInputText(e.target.value);
    if (!isTyping) {
      setIsTyping(true);
      setTypingStatus(chat.id, currentUser.uid, true);
    }
    if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
    typingTimeoutRef.current = setTimeout(() => {
      setIsTyping(false);
      setTypingStatus(chat.id, currentUser.uid, false);
    }, 2000);
  };

  // --- Voice Recording Logic (Fixed) ---
  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

      let mimeType = 'audio/webm';
      if (MediaRecorder.isTypeSupported('audio/webm;codecs=opus')) {
          mimeType = 'audio/webm;codecs=opus';
      } else if (MediaRecorder.isTypeSupported('audio/mp4')) {
          mimeType = 'audio/mp4';
      }

      const recorder = new MediaRecorder(stream, { mimeType });
      setMediaRecorder(recorder);
      audioChunksRef.current = [];

      recorder.ondataavailable = (e) => {
        if (e.data.size > 0) audioChunksRef.current.push(e.data);
      };

      recorder.start();
      setIsRecording(true);
      setRecordingDuration(0);
      timerRef.current = setInterval(() => setRecordingDuration(p => p + 1), 1000);
    } catch (err) {
      alert("Microphone access denied. Please enable permissions.");
    }
  };

  const stopRecording = async (shouldSend: boolean) => {
    if (mediaRecorder && isRecording) {
      const mimeType = mediaRecorder.mimeType || 'audio/webm';

      mediaRecorder.onstop = async () => {
        if (shouldSend && audioChunksRef.current.length > 0) {
            const blob = new Blob(audioChunksRef.current, { type: mimeType });
            const reader = new FileReader();
            reader.readAsDataURL(blob);
            reader.onloadend = async () => {
                const base64Audio = reader.result as string;
                const msg: Message = {
                    id: 'v_' + Math.random().toString(36).substr(2, 9),
                    senderId: currentUser.uid,
                    recipientId: isGroup ? chat.id : otherId!,
                    text: 'Voice Message',
                    type: 'voice',
                    timestamp: Date.now(),
                    status: 'sent',
                    audioUrl: base64Audio,
                    duration: recordingDuration
                };
                setMessages(prev => [...prev, msg]);
                await addMessage(msg);
            };
        }
        mediaRecorder.stream.getTracks().forEach(track => track.stop());
        setMediaRecorder(null);
        audioChunksRef.current = [];
      };

      mediaRecorder.stop();
      clearInterval(timerRef.current);
      setIsRecording(false);
    }
  };

  const formatDuration = (sec: number) => {
    const m = Math.floor(sec / 60);
    const s = sec % 60;
    return `${m}:${s.toString().padStart(2, '0')}`;
  };

  // --- Deletion UX Logic ---
  const triggerDeleteFlow = (msg: Message) => {
      setMessageToDelete(msg);
      setShowDeleteOptions(true);
  };

  const confirmDelete = async (type: 'me' | 'everyone') => {
      if (!messageToDelete) return;

      const confirmText = type === 'everyone' 
        ? "Are you sure you want to delete this message for EVERYONE?" 
        : "Delete this message from your chat history?";

      if (window.confirm(confirmText)) {
          if (type === 'everyone') {
              setMessages(prev => prev.map(m => m.id === messageToDelete.id ? { ...m, type: 'deleted', text: '🚫 This message was deleted' } : m));
              await deleteMessageForEveryone(messageToDelete.id);
          } else {
              setMessages(prev => prev.filter(m => m.id !== messageToDelete.id));
              await deleteMessageForMe(messageToDelete.id, currentUser.uid);
          }
      }
      setShowDeleteOptions(false);
      setMessageToDelete(null);
  };

  const handlePinMessage = async (msg: Message) => {
      await togglePinMessage(chat.id, msg.id);
  };

  const handleEditMessage = (msg: Message) => {
      setEditingMessage(msg);
      setInputText(msg.text);
      inputRef.current?.focus();
  };

  const handleMediaClick = (msg: Message) => {
      setViewingMedia(msg);
  };

  const handleSend = async (e?: React.FormEvent) => {
    e?.preventDefault();
    const text = inputText.trim();
    if (!text) return;

    if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
    setIsTyping(false);
    setTypingStatus(chat.id, currentUser.uid, false);

    if (editingMessage) {
        setMessages(prev => prev.map(m => m.id === editingMessage.id ? { ...m, text: text, isEdited: true } : m));
        await editMessage(editingMessage.id, text);
        setEditingMessage(null);
        setInputText('');
        return;
    }

    const recipient = isGroup ? chat.id : otherId;
    if (!recipient) return;

    let replyContext = undefined;
    if (replyingTo) {
      const sender = await getUserById(replyingTo.senderId);
      replyContext = {
        messageId: replyingTo.id,
        text: replyingTo.text || 'Media',
        senderName: sender?.name || 'User'
      };
    }

    const msg: Message = {
      id: 'm_' + Math.random().toString(36).substr(2, 9),
      senderId: currentUser.uid, 
      recipientId: recipient,
      text, 
      type: 'text', 
      timestamp: Date.now(), 
      status: 'sent',
      replyContext
    };

    setMessages(prev => [...prev, msg]);
    setInputText('');
    setReplyingTo(null);

    await addMessage(msg);

    if (text.toLowerCase().startsWith('/ai')) {
      setTypingUsers(prev => [...prev, 'gemini_ai']);
      try {
        const res = await getAIResponse(text.replace('/ai', '').trim());
        const aiMsg: Message = {
          id: 'ai_' + Date.now(), 
          senderId: 'gemini_ai', 
          recipientId: isGroup ? chat.id : currentUser.uid,
          text: res || "I'm thinking...", 
          type: 'text', 
          timestamp: Date.now(), 
          status: 'seen'
        };
        await addMessage(aiMsg);
      } catch (err) { }
      finally { setTypingUsers(prev => prev.filter(id => id !== 'gemini_ai')); }
    }
  };

  const handleForward = async (targetChat: Chat) => {
    if (!forwardingMessage) return;
    const targetId = targetChat.type === 'group' ? targetChat.id : targetChat.participants.find(p => p !== currentUser.uid)!;
    const { replyContext, ...msgContent } = forwardingMessage;
    const forwardMsg: Message = {
      ...msgContent,
      id: 'fwd_' + Math.random().toString(36).substr(2, 9),
      senderId: currentUser.uid,
      recipientId: targetId,
      timestamp: Date.now(),
      status: 'sent',
      isForwarded: true
    };
    await addMessage(forwardMsg);
    setForwardingMessage(null);
    alert(`Forwarded to ${targetChat.name || 'Contact'}`);
  };

  const openForwardModal = async (msg: Message) => {
    setForwardingMessage(msg);
    const chats = await getMyChats(currentUser.uid);
    const users = await getAllUsers();
    setAvailableChats(chats);
    setAllUsers(users);
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const recipient = isGroup ? chat.id : otherId;
    if (!recipient) return;

    setIsUploading(true);
    const reader = new FileReader();
    reader.onload = async (event) => {
      const fileUrl = event.target?.result as string;
      let messageType: any = 'file';
      if (file.type.startsWith('image/')) messageType = 'image';
      else if (file.type.startsWith('video/')) messageType = 'video';
      const msg: Message = {
        id: 'f_' + Math.random().toString(36).substr(2, 9), 
        senderId: currentUser.uid,
        recipientId: recipient, 
        text: file.name, 
        type: messageType,
        timestamp: Date.now(), 
        status: 'sent', 
        fileUrl, 
        fileName: file.name
      };
      setMessages(prev => [...prev, msg]);
      await addMessage(msg);
      setIsUploading(false);
    };
    reader.readAsDataURL(file);
    e.target.value = '';
  };

  const handleHeaderClick = () => {
    if (isGroup) {
      setShowGroupInfo(true);
    } else {
      onUserClick(otherUser || {} as User);
    }
  };

  const renderDateSeparator = (timestamp: number, prevTimestamp?: number) => {
    if (!timestamp) return null;
    const date = new Date(timestamp);
    if (isNaN(date.getTime())) return null;

    const dateStr = date.toDateString();
    const prevDateStr = prevTimestamp ? new Date(prevTimestamp).toDateString() : null;

    if (dateStr !== prevDateStr) {
      return (
        <div className="flex justify-center my-6 sticky top-2 z-10">
          <div className="px-4 py-1.5 bg-slate-900/10 dark:bg-white/10 backdrop-blur-xl border border-white/20 rounded-full">
            <span className="text-[10px] font-black uppercase tracking-widest text-slate-500 dark:text-slate-300">
              {date.toLocaleDateString(undefined, { weekday: 'long', month: 'short', day: 'numeric' })}
            </span>
          </div>
        </div>
      );
    }
    return null;
  };

  const isOnline = otherUser?.status === 'online' && (Date.now() - (otherUser.lastSeen || 0) < 3 * 60 * 1000);
  const statusColor = !isGroup && isOnline ? 'text-green-500' : 'text-slate-500 dark:text-slate-400';
  const statusText = !isGroup && isOnline ? 'Online Now' : 'Offline';

  const latestPinnedId = pinnedMessageIds[pinnedMessageIds.length - 1];
  const pinnedMessage = messages.find(m => m.id === latestPinnedId);

  return (
    <div className={`flex-1 flex flex-col h-full bg-white dark:bg-slate-900 animate-in fade-in duration-300 relative overflow-hidden ${FONT_SIZE_CLASSES[fontSize]}`}>
      <div className={`absolute inset-0 z-0 transition-all duration-700 ${wallpaper !== 'custom' ? WALLPAPER_CLASSES[wallpaper] || '' : ''}`}>
        {wallpaper === 'custom' && customUrl && <img src={customUrl} className="absolute inset-0 w-full h-full object-cover" alt="" /> }
        <div className="absolute inset-0 opacity-[0.08] pointer-events-none" style={{ backgroundImage: `url('https://www.transparenttextures.com/patterns/asfalt-dark.png')` }}></div>
      </div>

      <div className="p-3 md:p-4 flex items-center justify-between glass z-10 border-b border-slate-200 dark:border-slate-800 shadow-sm relative">
        <div className="flex items-center gap-3">
          <button onClick={onClose} className="lg:hidden p-2 rounded-xl hover:bg-slate-200 dark:hover:bg-slate-800"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 19l-7-7 7-7" /></svg></button>
          <div className="relative cursor-pointer group" onClick={handleHeaderClick}>
            <img src={isGroup ? (chat.groupIcon || `https://picsum.photos/seed/${chat.id}/200`) : otherUser?.photoURL} className="w-10 h-10 rounded-2xl object-cover border border-slate-200 dark:border-slate-700 group-hover:scale-105 transition-transform" alt="" />
            {!isGroup && isOnline && <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-green-500 rounded-full border-2 border-white dark:border-slate-900 animate-pulse"></div>}
          </div>
          <div className="min-w-0 cursor-pointer" onClick={handleHeaderClick}>
            <h3 className="font-bold text-sm leading-none flex items-center gap-1.5 truncate">
              {isGroup ? chat.name : (otherUser?.name || 'Loading...')}
              {isLocked && <svg className="w-3.5 h-3.5 text-indigo-500" fill="currentColor" viewBox="0 0 24 24"><path d="M12 17c1.1 0 2-.9 2-2s-.9-2-2-2-2 .9-2 2 .9 2 2 2zm6-9h-1V6c0-2.76-2.24-5-5-5S7 3.24 7 6v2H6c-1.1 0-2 .9-2 2v10c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V10c0-1.1-.9-2-2-2zm-6-5c1.66 0 3 1.34 3 3v2H9V6c0-1.66 1.34-3 3-3z"/></svg>}
            </h3>
            {typingUsers.length > 0 ? (
               <span className="text-[10px] text-indigo-500 font-bold uppercase tracking-widest mt-0.5 animate-pulse flex items-center gap-1">
                  <div className="flex gap-0.5">
                    <span className="w-1 h-1 bg-indigo-500 rounded-full animate-bounce"></span>
                    <span className="w-1 h-1 bg-indigo-500 rounded-full animate-bounce [animation-delay:0.1s]"></span>
                    <span className="w-1 h-1 bg-indigo-500 rounded-full animate-bounce [animation-delay:0.2s]"></span>
                  </div>
                  {isGroup ? `${typingUsers.length} typing...` : typingUsers.includes('gemini_ai') ? 'AI thinking...' : 'Typing...'}
               </span>
            ) : (
               <span className={`text-[10px] font-bold uppercase tracking-widest mt-0.5 ${statusColor}`}>
                  {isGroup ? `${chat.participants?.length || 0} members` : statusText}
               </span>
            )}
          </div>
        </div>
        <div className="flex items-center gap-2">
          {!isGroup && otherUser && (
            <>
              <button onClick={() => onCallStart?.(otherUser, 'voice')} className="p-2.5 hover:bg-slate-200 dark:hover:bg-slate-800 text-slate-600 dark:text-slate-300 rounded-xl transition-colors"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z" /></svg></button>
              <button onClick={() => onCallStart?.(otherUser, 'video')} className="p-2.5 hover:bg-slate-200 dark:hover:bg-slate-800 text-slate-600 dark:text-slate-300 rounded-xl transition-colors"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg></button>
            </>
          )}
          <button onClick={async () => { await toggleChatLock(chat.id, currentUser.uid); setIsLocked(!isLocked); }} className={`p-2.5 rounded-xl transition-all ${isLocked ? 'bg-indigo-500 text-white shadow-lg' : 'hover:bg-slate-200 dark:hover:bg-slate-800 text-slate-400'}`}><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg></button>
        </div>
      </div>

      {pinnedMessage && (
        <div 
            onClick={() => {
                const el = document.getElementById(`msg-${pinnedMessage.id}`);
                el?.scrollIntoView({ behavior: 'smooth', block: 'center' });
                el?.classList.add('bg-indigo-100', 'dark:bg-indigo-900');
                setTimeout(() => el?.classList.remove('bg-indigo-100', 'dark:bg-indigo-900'), 1000);
            }}
            className="absolute top-[4.5rem] left-4 right-4 z-20 bg-white/95 dark:bg-slate-800/95 backdrop-blur-md rounded-xl p-3 border-l-4 border-indigo-500 shadow-lg flex items-center justify-between cursor-pointer animate-in slide-in-from-top-2"
        >
            <div className="min-w-0">
                <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest mb-0.5">Pinned Message</p>
                <p className="text-xs text-slate-600 dark:text-slate-300 truncate font-medium">{pinnedMessage.text || 'Media File'}</p>
            </div>
            <button 
                onClick={(e) => { e.stopPropagation(); togglePinMessage(chat.id, pinnedMessage.id); }}
                className="p-2 text-slate-400 hover:text-indigo-500 transition-colors"
            >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
            </button>
        </div>
      )}

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-1 scroll-smooth z-[5] no-scrollbar">
        {messages.map((msg, index) => (
          <React.Fragment key={msg.id || index}>
            {renderDateSeparator(msg.timestamp, messages[index-1]?.timestamp)}
            <MessageBubble 
              message={msg} 
              isOwn={msg.senderId === currentUser.uid} 
              isAI={msg.senderId === 'gemini_ai'} 
              onReply={setReplyingTo} 
              onForward={openForwardModal}
              onDelete={triggerDeleteFlow}
              onEdit={handleEditMessage}
              onPin={handlePinMessage}
              isPinned={pinnedMessageIds.includes(msg.id)}
              onMediaClick={handleMediaClick}
            />
          </React.Fragment>
        ))}
        {typingUsers.length > 0 && (
          <div className="flex items-end gap-2 px-2 py-2 animate-in slide-in-from-left-4 fade-in duration-300">
             {!isGroup && <img src={otherUser?.photoURL || `https://picsum.photos/seed/${chat.id}/50`} className="w-8 h-8 rounded-full border border-white dark:border-slate-800" alt="" />}
             <div className="bg-white dark:bg-slate-800 rounded-2xl rounded-bl-none px-4 py-3 flex items-center gap-1.5 shadow-sm border border-slate-100 dark:border-slate-700">
                <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce"></div>
             </div>
          </div>
        )}
      </div>

      <div className="glass border-t border-slate-200 dark:border-slate-800 z-10 flex flex-col">
        {editingMessage && (
             <div className="px-4 py-2 bg-indigo-50 dark:bg-indigo-900/20 border-l-4 border-indigo-500 flex items-center justify-between">
                <div>
                    <span className="text-xs font-bold text-indigo-500 uppercase tracking-widest">Editing Message</span>
                    <p className="text-xs text-slate-500 dark:text-slate-400 line-clamp-1">{editingMessage.text}</p>
                </div>
                <button onClick={() => { setEditingMessage(null); setInputText(''); }} className="p-1 text-indigo-500 hover:bg-indigo-100 rounded-full">
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
             </div>
        )}
        {replyingTo && (
          <div className="px-4 py-2 bg-slate-50 dark:bg-slate-800/80 border-l-4 border-indigo-500 flex items-center justify-between">
             <div className="min-w-0">
                <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest mb-0.5">Replying to {replyingTo.senderId === currentUser.uid ? 'Yourself' : 'Contact'}</p>
                <p className="text-xs text-slate-500 truncate">{replyingTo.text || 'Media Message'}</p>
             </div>
             <button onClick={() => setReplyingTo(null)} className="p-1.5 text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-full">
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
             </button>
          </div>
        )}

        <div className="p-3 md:p-4 flex gap-2.5 items-center">
          {isRecording ? (
             <div className="flex-1 flex items-center justify-between bg-red-500 text-white rounded-[1.5rem] px-6 py-4 animate-pulse">
                <div className="flex items-center gap-3">
                   <div className="w-3 h-3 bg-white rounded-full animate-bounce"></div>
                   <span className="font-bold text-sm tracking-widest">{formatDuration(recordingDuration)}</span>
                </div>
                <div className="flex items-center gap-3">
                    <button onClick={() => stopRecording(false)} className="text-white/80 hover:text-white text-xs font-bold uppercase">Cancel</button>
                    <button onClick={() => stopRecording(true)} className="p-2 bg-white text-red-500 rounded-full shadow-lg">
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M5 13l4 4L19 7" /></svg>
                    </button>
                </div>
             </div>
          ) : (
            <>
              <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" />
              <button type="button" onClick={() => fileInputRef.current?.click()} className="p-3.5 text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-2xl shrink-0 transition-colors active:scale-90"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 4v16m8-8H4" /></svg></button>

              <form onSubmit={handleSend} className="flex-1 flex gap-2">
                 <input 
                    ref={inputRef}
                    type="text" 
                    value={inputText} 
                    onChange={handleInputChange} 
                    placeholder="Type a message..." 
                    className="flex-1 bg-white/60 dark:bg-slate-800/80 rounded-[1.5rem] px-6 py-4 text-sm font-medium outline-none border border-slate-200 dark:border-slate-700 focus:ring-2 focus:ring-indigo-500/20 transition-all shadow-inner" 
                />
                {inputText.trim() ? (
                    <button type="submit" className="p-4 bg-indigo-500 text-white rounded-2xl shadow-xl shadow-indigo-500/20 transition-all shrink-0 active:scale-95">
                        {editingMessage ? (
                             <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M5 13l4 4L19 7" /></svg>
                        ) : (
                             <svg className="w-6 h-6 rotate-90" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
                        )}
                    </button>
                ) : (
                    <button type="button" onClick={startRecording} className="p-4 bg-slate-100 dark:bg-slate-800 text-slate-500 hover:bg-red-500 hover:text-white rounded-2xl transition-all shrink-0 active:scale-95 group">
                        <svg className="w-6 h-6 group-hover:scale-110 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
                    </button>
                )}
              </form>
            </>
          )}
        </div>
      </div>

      {showGroupInfo && (
        <GroupInfoModal 
          chat={chat}
          currentUser={currentUser}
          onClose={() => setShowGroupInfo(false)}
        />
      )}

      {/* Media Viewer Modal */}
      {viewingMedia && (
        <MediaViewer 
           message={viewingMedia}
           onClose={() => setViewingMedia(null)}
           onForward={openForwardModal}
           onReply={(msg) => setReplyingTo(msg)}
        />
      )}

      {showDeleteOptions && messageToDelete && (
        <div className="fixed inset-0 z-[200] flex items-end justify-center sm:items-center">
            <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setShowDeleteOptions(false)}></div>
            <div className="relative w-full max-w-sm bg-white dark:bg-slate-900 rounded-t-[2rem] sm:rounded-[2rem] p-6 shadow-2xl animate-in slide-in-from-bottom duration-300">
                <div className="w-12 h-1.5 bg-slate-200 dark:bg-slate-700 rounded-full mx-auto mb-6"></div>
                <h3 className="text-lg font-bold mb-4 text-center">Delete Message?</h3>

                <div className="flex flex-col gap-3">
                    {messageToDelete.senderId === currentUser.uid && (
                        <button 
                            onClick={() => confirmDelete('everyone')}
                            className="w-full p-4 rounded-2xl bg-slate-100 dark:bg-slate-800 text-red-500 font-bold hover:bg-red-50 dark:hover:bg-red-900/10 transition-colors flex items-center justify-between group"
                        >
                            <span>Delete for everyone</span>
                            <svg className="w-5 h-5 opacity-0 group-hover:opacity-100 transition-opacity" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                        </button>
                    )}
                    <button 
                        onClick={() => confirmDelete('me')}
                        className="w-full p-4 rounded-2xl bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-200 font-bold hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors flex items-center justify-between"
                    >
                        <span>Delete for me</span>
                        <svg className="w-5 h-5 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" /></svg>
                    </button>
                    <button 
                        onClick={() => setShowDeleteOptions(false)}
                        className="w-full p-4 rounded-2xl border-2 border-slate-100 dark:border-slate-800 text-slate-500 font-bold hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors mt-2"
                    >
                        Cancel
                    </button>
                </div>
            </div>
        </div>
      )}

      {forwardingMessage && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-950/60 backdrop-blur-md" onClick={() => setForwardingMessage(null)}></div>
          <div className="relative w-full max-w-sm bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl flex flex-col max-h-[70vh] animate-in zoom-in-95">
             <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between">
                <h3 className="text-xl font-bold">Forward Message</h3>
                <button onClick={() => setForwardingMessage(null)} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full">
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
             </div>
             <div className="flex-1 overflow-y-auto p-4 space-y-2 no-scrollbar">
                {availableChats.map(c => {
                   const isGrp = c.type === 'group';
                   const target = isGrp ? null : allUsers.find(u => u.uid === c.participants.find(p => p !== currentUser.uid));
                   return (
                     <button key={c.id} onClick={() => handleForward(c)} className="w-full flex items-center gap-3 p-3 hover:bg-slate-50 dark:hover:bg-slate-800 rounded-2xl transition-colors text-left">
                        <img src={isGrp ? c.groupIcon : target?.photoURL || `https://picsum.photos/seed/${c.id}/100`} className="w-10 h-10 rounded-xl object-cover" alt="" />
                        <span className="font-bold text-sm flex-1 truncate">{isGrp ? c.name : target?.name || 'Contact'}</span>
                     </button>
                   );
                })}
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Message } from '../../types';

interface MessageBubbleProps {
  message: Message;
  isOwn: boolean;
  isAI?: boolean;
  onReply: (msg: Message) => void;
  onForward: (msg: Message) => void;
  onDelete?: (msg: Message) => void;
  onEdit?: (msg: Message) => void;
  onPin?: (msg: Message) => void;
  isPinned?: boolean;
  onMediaClick?: (msg: Message) => void;
}

export const MessageBubble: React.FC<MessageBubbleProps> = ({ message, isOwn, isAI, onReply, onForward, onDelete, onEdit, onPin, isPinned, onMediaClick }) => {
  const [showMenu, setShowMenu] = useState(false);
  const [swipeOffset, setSwipeOffset] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [progress, setProgress] = useState(0);
  const [currentTime, setCurrentTime] = useState(0);

  const menuRef = useRef<HTMLDivElement>(null);
  const audioRef = useRef<HTMLAudioElement>(null);
  const touchStartX = useRef<number | null>(null);

  useEffect(() => {
    const handleClick = (e: MouseEvent) => { if (menuRef.current && !menuRef.current.contains(e.target as Node)) setShowMenu(false); };
    if (showMenu) document.addEventListener('mousedown', handleClick);
    return () => document.removeEventListener('mousedown', handleClick);
  }, [showMenu]);

  const formatTime = (ts: number) => new Date(ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

  const handleTouchStart = (e: React.TouchEvent) => { touchStartX.current = e.touches[0].clientX; };
  const handleTouchMove = (e: React.TouchEvent) => {
    if (touchStartX.current === null) return;
    const deltaX = e.touches[0].clientX - touchStartX.current;
    if (deltaX > 0) setSwipeOffset(Math.min(deltaX, 80));
  };
  const handleTouchEnd = () => {
    if (swipeOffset > 50) onReply(message);
    setSwipeOffset(0);
    touchStartX.current = null;
  };

  const toggleAudio = () => {
    const audio = audioRef.current;
    if (audio) {
      if (isPlaying) {
        audio.pause();
      } else {
        document.querySelectorAll('audio').forEach(a => { if(a !== audio) a.pause() });
        const playPromise = audio.play();
        if (playPromise !== undefined) {
          playPromise.catch(e => {
            console.error("Audio play error:", e);
            setIsPlaying(false);
          });
        }
      }
    }
  };

  const handleTimeUpdate = () => {
    const audio = audioRef.current;
    if (audio) {
        setCurrentTime(audio.currentTime);
        if (audio.duration) {
            setProgress((audio.currentTime / audio.duration) * 100);
        }
    }
  };

  const renderStatus = () => {
    if (!isOwn) return null;
    const isSeen = message.status === 'seen';
    const isDelivered = message.status === 'delivered' || isSeen;
    return (
      <div className={`flex -space-x-2 ${isSeen ? 'text-sky-400' : 'text-white/50'} ml-1`}>
        <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3.5" d="M5 13l4 4L19 7" /></svg>
        {isDelivered && <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3.5" d="M5 13l4 4L19 7" /></svg>}
      </div>
    );
  };

  const isDeleted = message.type === 'deleted';

  return (
    <div className={`relative flex w-full ${isOwn ? 'justify-end' : 'justify-start'} mb-2 px-2 group animate-in slide-in-from-${isOwn ? 'right' : 'left'}-4 duration-500`} id={`msg-${message.id}`}>
      {/* Swipe Indicator */}
      <div className="absolute left-4 top-1/2 -translate-y-1/2 transition-all duration-200 pointer-events-none" style={{ opacity: swipeOffset / 50, transform: `translateY(-50%) scale(${Math.min(swipeOffset / 50, 1.2)})` }}>
        <div className="bg-indigo-500 p-2 rounded-full text-white shadow-lg"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M3 10h10a8 8 0 018 8v2M3 10l6 6m-6-6l6-6" /></svg></div>
      </div>

      <div className={`relative flex flex-col max-w-[82%] ${isOwn ? 'items-end' : 'items-start'} transition-transform duration-200`} style={{ transform: `translateX(${swipeOffset}px)` }} onTouchStart={handleTouchStart} onTouchMove={handleTouchMove} onTouchEnd={handleTouchEnd}>

        {/* Context Menu */}
        {showMenu && !isDeleted && (
          <div ref={menuRef} className={`absolute z-50 bottom-full mb-3 bg-white/90 dark:bg-slate-800/95 backdrop-blur-xl rounded-2xl shadow-2xl border border-white/20 p-1.5 flex flex-col min-w-[150px] animate-in zoom-in-95 origin-bottom-${isOwn ? 'right' : 'left'}`}>
            <button onClick={() => { onReply(message); setShowMenu(false); }} className="px-4 py-2.5 hover:bg-indigo-500 hover:text-white rounded-xl text-left font-bold text-xs uppercase tracking-wider flex items-center gap-2 text-slate-700 dark:text-slate-200">
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 10h10a8 8 0 018 8v2M3 10l6 6m-6-6l6-6" /></svg> Reply
            </button>
            <button onClick={() => { onForward(message); setShowMenu(false); }} className="px-4 py-2.5 hover:bg-indigo-500 hover:text-white rounded-xl text-left font-bold text-xs uppercase tracking-wider flex items-center gap-2 text-slate-700 dark:text-slate-200">
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg> Forward
            </button>
            {onPin && (
               <button onClick={() => { onPin(message); setShowMenu(false); }} className="px-4 py-2.5 hover:bg-indigo-500 hover:text-white rounded-xl text-left font-bold text-xs uppercase tracking-wider flex items-center gap-2 text-slate-700 dark:text-slate-200">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" /></svg> {isPinned ? 'Unpin' : 'Pin'}
               </button>
            )}
            {isOwn && message.type === 'text' && onEdit && (
                <button onClick={() => { onEdit(message); setShowMenu(false); }} className="px-4 py-2.5 hover:bg-indigo-500 hover:text-white rounded-xl text-left font-bold text-xs uppercase tracking-wider flex items-center gap-2 text-slate-700 dark:text-slate-200">
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg> Edit
                </button>
            )}
            {onDelete && (
                <button onClick={() => { onDelete(message); setShowMenu(false); }} className="px-4 py-2.5 text-red-500 hover:bg-red-500 hover:text-white rounded-xl text-left font-bold text-xs uppercase tracking-wider flex items-center gap-2">
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg> Delete
                </button>
            )}
          </div>
        )}

        {/* Message Bubble */}
        <div 
          onClick={() => !isDeleted && setShowMenu(!showMenu)} 
          className={`relative px-4 py-3 rounded-[1.75rem] transition-all active:scale-[0.97] cursor-pointer shadow-lg group-hover:shadow-xl overflow-hidden 
            ${isDeleted 
                ? 'bg-slate-200 dark:bg-slate-800 text-slate-500 italic border border-slate-300 dark:border-slate-700' 
                : isOwn 
                    ? 'bg-gradient-to-br from-indigo-600 via-indigo-500 to-indigo-600 text-white rounded-tr-none' 
                    : isAI 
                        ? 'bg-slate-900 text-white border-2 border-indigo-500/40 rounded-tl-none' 
                        : 'bg-white/90 dark:bg-slate-800/90 backdrop-blur-md text-slate-900 dark:text-slate-100 rounded-tl-none border border-white/20 dark:border-slate-700/50'
            }`}
        >
          {isPinned && !isDeleted && (
             <div className="absolute top-0 right-0 p-1 bg-black/20 rounded-bl-xl text-white">
                <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 24 24"><path d="M16 12V4H17V2H7V4H8V12L6 14V16H11V22H13V16H18V14L16 12Z"/></svg>
             </div>
          )}

          {message.replyContext && !isDeleted && (
            <div className={`mb-2 p-2 rounded-xl border-l-4 text-[11px] flex flex-col gap-0.5 ${isOwn ? 'bg-white/10 border-white/40' : 'bg-indigo-500/10 border-indigo-500 dark:bg-indigo-900/30'}`}>
              <span className={`font-black uppercase tracking-tighter ${isOwn ? 'text-white' : 'text-indigo-500 dark:text-indigo-400'}`}>{message.replyContext.senderName}</span>
              <p className="truncate opacity-80 font-medium italic">{message.replyContext.text}</p>
            </div>
          )}

          {isDeleted ? (
              <div className="flex items-center gap-2">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M18.364 18.364A9 9 0 005.636 5.636m12.728 12.728L5.636 5.636" /></svg>
                  <span className="text-sm font-medium">{message.text}</span>
              </div>
          ) : message.type === 'voice' && message.audioUrl ? (
             <div className="flex items-center gap-3 min-w-[180px]">
                <button onClick={(e) => { e.stopPropagation(); toggleAudio(); }} className={`w-10 h-10 rounded-full flex items-center justify-center shrink-0 transition-transform active:scale-90 ${isOwn ? 'bg-white/20 text-white hover:bg-white/30' : 'bg-indigo-500 text-white hover:bg-indigo-600'}`}>
                   {isPlaying ? <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/></svg> : <svg className="w-4 h-4 ml-0.5" fill="currentColor" viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>}
                </button>
                <div className="flex flex-col gap-1 w-full">
                    {/* Progress Bar */}
                    <div className={`h-1.5 rounded-full w-32 relative overflow-hidden ${isOwn ? 'bg-white/30' : 'bg-slate-300 dark:bg-slate-600'}`}>
                        <div 
                            className={`h-full rounded-full transition-all duration-100 ease-linear ${isOwn ? 'bg-white' : 'bg-indigo-500'}`}
                            style={{ width: `${progress}%` }}
                        ></div>
                    </div>
                    <div className="flex justify-between w-32">
                        <span className={`text-[10px] font-bold uppercase tracking-wider ${isOwn ? 'text-white/70' : 'text-slate-500'}`}>
                            {isPlaying ? `${Math.floor(currentTime / 60)}:${Math.floor(currentTime % 60).toString().padStart(2, '0')}` : (message.duration ? `${Math.floor(message.duration / 60)}:${(message.duration % 60).toString().padStart(2, '0')}` : 'Voice')}
                        </span>
                    </div>
                </div>
                {message.audioUrl && (
                  <audio 
                    ref={audioRef} 
                    src={message.audioUrl} 
                    onPlay={() => setIsPlaying(true)}
                    onPause={() => setIsPlaying(false)}
                    onEnded={() => { setIsPlaying(false); setProgress(0); setCurrentTime(0); }}
                    onTimeUpdate={handleTimeUpdate}
                    onError={(e) => {
                      console.error("Audio load failed", e);
                      setIsPlaying(false);
                    }}
                    className="hidden" 
                    preload="metadata"
                  />
                )}
             </div>
          ) : message.type === 'image' && message.fileUrl ? (
            <div 
                className="relative mb-2 -mx-1 -mt-1 overflow-hidden rounded-2xl cursor-zoom-in"
                onClick={(e) => { 
                    e.stopPropagation(); // Prevent menu toggle
                    if(onMediaClick) onMediaClick(message); 
                }}
            >
                <img src={message.fileUrl} className="max-h-80 w-full object-cover" alt="" />
            </div>
          ) : message.type === 'video' && message.fileUrl ? (
            <div 
                className="relative mb-2 -mx-1 -mt-1 overflow-hidden rounded-2xl bg-black cursor-pointer"
                onClick={(e) => { 
                    e.stopPropagation(); 
                    if(onMediaClick) onMediaClick(message); 
                }}
            >
                <video src={message.fileUrl} className="max-h-80 w-full object-contain pointer-events-none" onError={(e) => console.error("Video load failed", e)} />
                <div className="absolute inset-0 flex items-center justify-center bg-black/20 group-hover:bg-black/10 transition-colors">
                     <div className="p-3 bg-white/20 backdrop-blur-md rounded-full text-white border border-white/30 shadow-xl">
                        <svg className="w-6 h-6 ml-1" fill="currentColor" viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>
                     </div>
                </div>
            </div>
          ) : (
            <p className="text-[14.5px] leading-[1.45] font-medium whitespace-pre-wrap">{message.text}</p>
          )}

          <div className={`flex items-center gap-1.5 justify-end mt-1.5 ${isOwn ? 'text-white/60' : 'text-slate-400 dark:text-slate-500'}`}>
            {message.isEdited && !isDeleted && <span className="text-[9px] italic mr-1">(edited)</span>}
            <span className="text-[9.5px] font-black uppercase tracking-tighter">{formatTime(message.timestamp)}</span>
            {renderStatus()}
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, ReactNode, Component } from 'react';
import { AuthView } from './components/Auth/AuthView';
import { ChatDashboard } from './components/Chat/ChatDashboard';
import { AdminDashboard } from './components/Admin/AdminDashboard';
import { useAuth } from './hooks/useAuth';

type AppView = 'auth' | 'role_select' | 'user' | 'admin';

interface ErrorBoundaryProps {
  children?: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
}

// Error Boundary to catch crashes and prevent white screen
class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  // Explicitly initialized state property to fix TS error
  public state: ErrorBoundaryState = { hasError: false };

  constructor(props: ErrorBoundaryProps) {
    super(props);
  }

  static getDerivedStateFromError(error: any) {
    return { hasError: true };
  }

  componentDidCatch(error: any, errorInfo: any) {
    console.error("App Crash:", error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="h-screen w-full flex items-center justify-center bg-slate-50 dark:bg-slate-900 text-slate-900 dark:text-white p-4 text-center">
           <div className="max-w-md">
             <div className="w-20 h-20 bg-red-100 dark:bg-red-900/20 text-red-500 rounded-full flex items-center justify-center mx-auto mb-6">
                <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
             </div>
             <h1 className="text-2xl font-bold mb-2">Something went wrong</h1>
             <p className="opacity-70 mb-8 leading-relaxed">The application encountered an unexpected error. This can happen due to connection issues or corrupted local data.</p>
             <button 
                onClick={() => { 
                    localStorage.removeItem('roxx_settings'); 
                    window.location.reload(); 
                }} 
                className="px-8 py-4 bg-indigo-500 hover:bg-indigo-600 text-white rounded-2xl font-bold shadow-xl shadow-indigo-500/20 transition-all active:scale-95"
             >
                Reset & Reload App
             </button>
           </div>
        </div>
      );
    }

    return this.props.children;
  }
}

const App: React.FC = () => {
  const { user, loading } = useAuth();
  const [view, setView] = useState<AppView>('auth');
  const [darkMode, setDarkMode] = useState(() => {
    return localStorage.getItem('theme') === 'dark' || 
           (!localStorage.getItem('theme') && window.matchMedia('(prefers-color-scheme: dark)').matches);
  });

  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [darkMode]);

  // Handle initial view routing and transitions
  useEffect(() => {
    if (!user) {
      setView('auth');
    } else if (user.isAdmin) {
      // For admins, default to role selection unless they've already chosen a path
      if (view === 'auth') {
        setView('role_select');
      }
    } else {
      setView('user');
    }
  }, [user, view]);

  if (loading) {
    return (
      <div className="h-[100dvh] w-screen flex items-center justify-center bg-slate-50 dark:bg-slate-950">
        <div className="flex flex-col items-center gap-4">
          <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
          <p className="text-slate-500 animate-pulse font-medium text-sm">Initializing Secure Session...</p>
        </div>
      </div>
    );
  }

  // Guard: If no user, always show Auth
  if (!user) {
    return <AuthView />;
  }

  // Role Selection Screen for Admins
  if (view === 'role_select') {
    return (
