                <button onClick={handlePostNote} className="w-full py-3 bg-indigo-500 text-white rounded-xl font-bold hover:bg-indigo-600 transition-all">Share Note</button>
            </div>
        </div>
      )}

      {/* Viewers List Modal */}
      {selectedViewersStory && (
        <div className="fixed inset-0 z-[150] flex flex-col items-center justify-end animate-in slide-in-from-bottom duration-300">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={() => setSelectedViewersStory(null)}></div>
          <div className="relative w-full max-w-xl bg-white dark:bg-slate-900 rounded-t-[3rem] h-[65%] flex flex-col overflow-hidden shadow-2xl">
            <div className="p-8 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between sticky top-0 bg-white/95 dark:bg-slate-900/95 backdrop-blur-md z-10">
              <div>
                <h3 className="text-2xl font-black">Story Viewers</h3>
                <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-1">
                  {selectedViewersStory.views?.length || 0} People have seen this
                </p>
              </div>
              <button onClick={() => setSelectedViewersStory(null)} className="p-3 bg-slate-100 dark:bg-slate-800 rounded-full hover:bg-slate-200 transition-all">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg>
              </button>
            </div>
            <div className="flex-1 overflow-y-auto p-6 space-y-3 no-scrollbar">
              {(!selectedViewersStory.views || selectedViewersStory.views.length === 0) ? (
                <div className="flex flex-col items-center justify-center h-full text-slate-400 gap-6 opacity-60">
                  <div className="w-20 h-20 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center">
                    <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg>
                  </div>
                  <p className="text-sm font-black uppercase tracking-[0.2em]">No views yet</p>
                </div>
              ) : (
                selectedViewersStory.views.slice().sort((a, b) => b.timestamp - a.timestamp).map(v => (
                  <div key={v.userId} className="flex items-center gap-4 p-5 rounded-3xl bg-slate-50 dark:bg-slate-800/40 hover:bg-indigo-50 dark:hover:bg-indigo-900/10 transition-all border border-transparent hover:border-indigo-100 dark:hover:border-indigo-900/20 group">
                    <img src={`https://picsum.photos/seed/${v.userId}/200`} className="w-14 h-14 rounded-2xl object-cover shadow-sm group-hover:scale-105 transition-transform" alt="" />
                    <div className="flex-1 min-w-0">
                      <p className="font-bold text-base truncate">{v.userName}</p>
                      <p className="text-[11px] text-slate-500 font-bold uppercase tracking-widest mt-0.5">{new Date(v.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</p>
                    </div>
                    <div className="text-[10px] font-black text-indigo-500 bg-indigo-500/10 px-4 py-1.5 rounded-xl uppercase tracking-widest border border-indigo-500/20">Seen</div>
                  </div>
                ))
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useAuth } from '../../hooks/useAuth';

export const AuthView: React.FC = () => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [showSavePrompt, setShowSavePrompt] = useState(false);

  const { login, signup, googleSignIn } = useAuth();

  // Clear error when user starts typing again or switches modes
  useEffect(() => {
    if (error) setError(null);
  }, [email, password, name, isLogin]);

  const getFriendlyErrorMessage = (errCode: string) => {
    if (!errCode) return "An unexpected error occurred.";
    const code = errCode.toLowerCase();
    if (code.includes('wrong-password') || code.includes('incorrect-password')) return "Incorrect password. Please double-check your credentials.";
    if (code.includes('user-not-found')) return "No account found with this email. Please sign up or check for typos.";
    if (code.includes('email-already-in-use')) return "This email is already registered. Try signing in instead.";
    if (code.includes('invalid-email')) return "Please enter a valid email address.";
    if (code.includes('weak-password')) return "Password should be at least 6 characters.";
    if (code.includes('suspended') || code.includes('blocked')) return "This account has been suspended by an administrator.";
    return errCode.replace('Firebase: ', '').replace('auth/', '').split('-').join(' ');
  };

  const handleSaveAccount = (user: any) => {
    if (!password) return; // Google sign in doesn't have password, so we can't save plain credentials securely easily here
    try {
        const stored = localStorage.getItem('roxx_accounts');
        let accounts = stored ? JSON.parse(stored) : [];
        // Check if exists
        if (!accounts.find((a: any) => a.uid === user.uid)) {
            accounts.push({
                uid: user.uid,
                email: user.email,
                name: user.displayName || name || user.email.split('@')[0],
                photoURL: user.photoURL,
                pass: password // Storing password locally as requested for fast switching simulation
            });
            localStorage.setItem('roxx_accounts', JSON.stringify(accounts));
        }
    } catch(e) { console.error(e); }
    setShowSavePrompt(false);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setIsLoading(true);

    try {
      let userRes;
      if (isLogin) {
        userRes = await login(email, password);
      } else {
        if (name.trim().length < 2) throw new Error("Please enter your full name.");
        // Try signup
        try {
            const res = await signup(email, password, name);
            userRes = res.user;
        } catch (err: any) {
            if (err.message.includes('email-already-in-use')) {
                setIsLogin(true);
                const res = await login(email, password);
                userRes = res;
            } else throw err;
        }
      }

      if (userRes) {
          // Check if saved
          const stored = localStorage.getItem('roxx_accounts');
          const accounts = stored ? JSON.parse(stored) : [];
          if (!accounts.find((a: any) => a.uid === userRes.uid)) {
              // Ask to save
              // Note: Since App component listens to auth state, it might unmount this view immediately.
              // We need to save BEFORE auth state listener fully redirects, or rely on a global modal.
              // Given the architecture, we'll try a window.confirm or auto-save if this was a "Switch" action.
              // For better UX as requested:
              if (window.confirm("Save your information for fast account switching?")) {
                  handleSaveAccount({ ...userRes, displayName: name || userRes.displayName });
              }
          }
      }

    } catch (err: any) {
      const message = getFriendlyErrorMessage(err.message);
      setError(message.charAt(0).toUpperCase() + message.slice(1));
    } finally {
      setIsLoading(false);
    }
  };

  const handleGoogleSignIn = async () => {
    setError(null);
    setIsLoading(true);
    try {
      await googleSignIn();
    } catch (err: any) {
      setError(getFriendlyErrorMessage(err.message));
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="h-screen w-full flex items-center justify-center bg-gradient-to-br from-indigo-600 via-purple-600 to-pink-500 p-4">
      <div className="glass w-full max-w-md p-8 rounded-3xl shadow-2xl transition-all duration-500 hover:shadow-indigo-500/20">
        <div className="text-center mb-8">
          <div className="w-16 h-16 bg-white/20 rounded-2xl flex items-center justify-center mx-auto mb-4 border border-white/30">
            <svg className="w-10 h-10 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" />
            </svg>
          </div>
          <h1 className="text-3xl font-bold text-white mb-2 tracking-tight">ROXX CHATS</h1>
          <p className="text-white/70">Secure, Real-time messaging</p>
        </div>

        {error && (
          <div className="mb-6 p-4 bg-red-500/10 border border-red-500/30 rounded-2xl text-red-100 text-[13px] leading-relaxed flex items-start gap-3 animate-in slide-in-from-top-2">
            <svg className="w-5 h-5 shrink-0 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
            <span className="flex-1">{error}</span>
          </div>
        )}

        <form id="auth-form" onSubmit={handleSubmit} className="space-y-4">
          {!isLogin && (
            <div className="animate-in fade-in slide-in-from-top-2 duration-300">
              <label className="block text-white/80 text-[11px] font-black uppercase tracking-widest mb-1.5 ml-1">Full Name</label>
              <input 
                type="text" 
                required
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="John Doe"
                disabled={isLoading}
                className="w-full bg-white/10 border border-white/20 rounded-xl px-4 py-3 text-white placeholder-white/40 focus:outline-none focus:ring-2 focus:ring-white/30 transition-all disabled:opacity-50"
              />
            </div>
          )}
          <div>
            <label className="block text-white/80 text-[11px] font-black uppercase tracking-widest mb-1.5 ml-1">Email Address</label>
            <input 
              type="email" 
              required
              value={email}
