            )}
            <ChatDashboard 
              currentUser={user} 
              toggleDarkMode={() => setDarkMode(!darkMode)} 
              isDarkMode={darkMode}
            />
          </div>
        )}
      </div>
    </ErrorBoundary>
  );
};

