      {/* Viewers List Modal */}
      {selectedViewersStory && (
        <div className="fixed inset-0 z-[150] flex flex-col items-center justify-end animate-in slide-in-from-bottom duration-300">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={() => setSelectedViewersStory(null)}></div>
          <div className="relative w-full max-w-xl bg-white dark:bg-slate-900 rounded-t-[3rem] h-[65%] flex flex-col overflow-hidden shadow-2xl">
            <div className="p-8 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between sticky top-0 bg-white/95 dark:bg-slate-900/95 backdrop-blur-md z-10">
              <div>
                <h3 className="text-2xl font-black text-slate-900 dark:text-white">Story Viewers</h3>
                <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-1">
                  {selectedViewersStory.views?.length || 0} People have seen this
                </p>
              </div>
              <button onClick={() => setSelectedViewersStory(null)} className="p-3 bg-slate-100 dark:bg-slate-800 rounded-full hover:bg-slate-200 transition-all">
                <svg className="w-6 h-6 text-slate-600 dark:text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg>
              </button>
            </div>
            <div className="flex-1 overflow-y-auto p-6 space-y-3 no-scrollbar">
              {(!selectedViewersStory.views || selectedViewersStory.views.length === 0) ? (
                <div className="flex flex-col items-center justify-center h-full text-slate-400 gap-6 opacity-60">
                  <div className="w-20 h-20 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center">
                    <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg>
                  </div>
                  <p className="text-sm font-black uppercase tracking-[0.2em]">No views yet</p>
                </div>
              ) : (
                selectedViewersStory.views.slice().sort((a, b) => b.timestamp - a.timestamp).map(v => (
                  <div key={v.userId} className="flex items-center gap-4 p-4 rounded-3xl bg-slate-50 dark:bg-slate-800/40 border border-transparent hover:border-indigo-200 dark:hover:border-indigo-900 transition-all">
                    <img src={`https://picsum.photos/seed/${v.userId}/200`} className="w-12 h-12 rounded-full object-cover shadow-sm" alt="" />
                    <div className="flex-1 min-w-0">
                      <p className="font-bold text-sm truncate text-slate-900 dark:text-white">{v.userName}</p>
                      <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-0.5">{new Date(v.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</p>
                    </div>
                    <div className="text-[9px] font-black text-indigo-600 bg-indigo-50 dark:bg-indigo-900/30 px-3 py-1 rounded-lg uppercase tracking-widest">Seen</div>
                  </div>
                ))
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { User, Chat } from '../../types';
import { getUserById, leaveGroup, makeGroupAdmin, removeGroupMember, updateGroupInfo } from '../../firebase';

interface GroupInfoModalProps {
  chat: Chat;
  currentUser: User;
  onClose: () => void;
}

export const GroupInfoModal: React.FC<GroupInfoModalProps> = ({ chat, currentUser, onClose }) => {
  const [participants, setParticipants] = useState<User[]>([]);
  const [isEditing, setIsEditing] = useState(false);
  const [groupName, setGroupName] = useState(chat.name || '');
  const [groupDescription, setGroupDescription] = useState(chat.description || '');
  const [groupPhoto, setGroupPhoto] = useState(chat.groupIcon || '');
  const [isAdmin, setIsAdmin] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const loadParticipants = async () => {
      const users = await Promise.all(chat.participants.map(uid => getUserById(uid)));
      setParticipants(users.filter(u => u !== null) as User[]);
    };
    loadParticipants();
    setIsAdmin(chat.adminIds?.includes(currentUser.uid) || false);
  }, [chat, currentUser.uid]);

  const handlePhotoSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        setGroupPhoto(ev.target?.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSave = async () => {
    if (!groupName.trim()) return;
    await updateGroupInfo(chat.id, groupName, groupPhoto, groupDescription);
    setIsEditing(false);
  };

  const handleLeaveGroup = async () => {
    if (window.confirm("Are you sure you want to leave this group?")) {
      await leaveGroup(chat.id, currentUser.uid);
      onClose();
    }
  };

  const handleRemoveMember = async (uid: string) => {
    if (window.confirm("Remove this user from the group?")) {
      await removeGroupMember(chat.id, uid);
      setParticipants(prev => prev.filter(p => p.uid !== uid));
    }
  };

  const handleMakeAdmin = async (uid: string) => {
    if (window.confirm("Promote this user to Admin?")) {
      await makeGroupAdmin(chat.id, uid);
    }
  };

  return (
    <div className="fixed inset-0 z-[150] flex justify-end">
      <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={onClose}></div>
      <div className="relative w-full max-w-md bg-white dark:bg-slate-950 h-full shadow-2xl flex flex-col animate-in slide-in-from-right duration-300">

        {/* Header */}
        <div className="h-16 flex items-center px-4 bg-white dark:bg-slate-900 border-b border-slate-100 dark:border-slate-800 shrink-0 gap-4">
          <button onClick={onClose} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-all">
            <svg className="w-6 h-6 text-slate-600 dark:text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
          <h2 className="text-lg font-bold text-slate-900 dark:text-white">Group Info</h2>
        </div>

        <div className="flex-1 overflow-y-auto no-scrollbar">
          {/* Group Profile */}
          <div className="flex flex-col items-center p-8 border-b border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900">
            <div className="relative group mb-6">
              <img src={groupPhoto || `https://picsum.photos/seed/${chat.id}/200`} className="w-32 h-32 rounded-[2.5rem] object-cover shadow-2xl ring-4 ring-slate-50 dark:ring-slate-800" alt="" />
              {isEditing && (
                <div 
                  onClick={() => fileInputRef.current?.click()}
                  className="absolute inset-0 bg-black/50 rounded-[2.5rem] flex items-center justify-center cursor-pointer opacity-0 group-hover:opacity-100 transition-opacity"
                >
                  <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                </div>
              )}
              <input type="file" ref={fileInputRef} onChange={handlePhotoSelect} className="hidden" accept="image/*" />
            </div>

            {isEditing ? (
              <div className="flex flex-col gap-4 w-full">
                <input 
                  value={groupName} 
                  onChange={e => setGroupName(e.target.value)} 
                  className="w-full bg-slate-100 dark:bg-slate-800 px-4 py-3 rounded-xl outline-none font-bold text-center text-lg"
                  placeholder="Group Name"
                />
                <textarea 
                  value={groupDescription} 
                  onChange={e => setGroupDescription(e.target.value)} 
                  className="w-full bg-slate-100 dark:bg-slate-800 px-4 py-3 rounded-xl outline-none text-sm font-medium resize-none min-h-[80px]"
                  placeholder="Group Description"
                />
                <div className="flex gap-2">
                    <button onClick={() => setIsEditing(false)} className="flex-1 py-3 bg-slate-200 dark:bg-slate-800 rounded-xl font-bold text-xs text-slate-500">Cancel</button>
                    <button onClick={handleSave} className="flex-1 py-3 bg-indigo-500 text-white rounded-xl font-bold text-xs shadow-lg shadow-indigo-500/20">Save Changes</button>
                </div>
              </div>
            ) : (
              <div className="text-center w-full">
                <h3 className="text-2xl font-black text-slate-900 dark:text-white">{chat.name}</h3>
                <p className="text-slate-500 text-sm font-medium mt-1 mb-4">{participants.length} participants</p>
                <div className="bg-slate-50 dark:bg-slate-800/50 p-4 rounded-2xl text-left border border-slate-100 dark:border-slate-800">
                    <p className="text-[10px] font-black uppercase text-indigo-500 tracking-widest mb-1">Description</p>
                    <p className="text-sm text-slate-700 dark:text-slate-300 leading-relaxed whitespace-pre-wrap">{chat.description || "No description provided."}</p>
                </div>
              </div>
            )}

            {isAdmin && !isEditing && (
               <button onClick={() => setIsEditing(true)} className="mt-6 px-6 py-3 bg-indigo-50 dark:bg-indigo-900/10 text-indigo-600 dark:text-indigo-400 rounded-xl text-xs font-bold uppercase tracking-widest hover:bg-indigo-100 dark:hover:bg-indigo-900/30 transition-all border border-indigo-100 dark:border-indigo-900/20">
                 Edit Settings
               </button>
            )}
          </div>

          {/* Participants */}
          <div className="p-6">
            <div className="flex items-center justify-between px-2 mb-4">
                <h4 className="text-xs font-black text-slate-400 uppercase tracking-[0.2em]">Members</h4>
                <div className="px-2 py-1 bg-slate-100 dark:bg-slate-800 rounded-lg text-[10px] font-bold text-slate-500">{participants.length}</div>
            </div>

            <div className="space-y-2">
              {participants.map(user => {
                const isUserAdmin = chat.adminIds?.includes(user.uid);
                const isMe = user.uid === currentUser.uid;

                return (
                  <div key={user.uid} className="flex items-center justify-between p-3 rounded-2xl hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors group">
                    <div className="flex items-center gap-3">
                      <img src={user.photoURL} className="w-10 h-10 rounded-full object-cover border border-slate-100 dark:border-slate-800" alt="" />
                      <div>
                        <p className="text-sm font-bold flex items-center gap-2 text-slate-900 dark:text-white">
                          {isMe ? 'You' : user.name}
                          {isUserAdmin && <span className="text-[9px] bg-green-100 text-green-600 px-1.5 py-0.5 rounded border border-green-200 font-bold uppercase">Admin</span>}
                        </p>
                        <p className="text-[11px] text-slate-500">{user.email}</p>
                      </div>
                    </div>

                    {isAdmin && !isMe && (
                      <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                        {!isUserAdmin && (
                          <button onClick={() => handleMakeAdmin(user.uid)} title="Make Admin" className="p-2 bg-indigo-50 text-indigo-500 rounded-xl hover:bg-indigo-100 transition-colors">
                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" /></svg>
                          </button>
                        )}
                        <button onClick={() => handleRemoveMember(user.uid)} title="Remove" className="p-2 bg-red-50 text-red-500 rounded-xl hover:bg-red-100 transition-colors">
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
                        </button>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>

          <div className="p-6 pt-0">
            <button 
              onClick={handleLeaveGroup}
              className="w-full py-4 flex items-center justify-center gap-2 text-red-500 bg-red-50 dark:bg-red-900/10 rounded-2xl font-bold hover:bg-red-100 dark:hover:bg-red-900/20 transition-all border border-red-100 dark:border-red-900/20"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
              Exit Group
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Message, PollOption } from '../../types';
import { toggleMessageReaction, voteOnPoll, auth } from '../../firebase';

interface MessageBubbleProps {
  message: Message;
  isOwn: boolean;
  isAI?: boolean;
  onReply: (msg: Message) => void;
  onForward: (msg: Message) => void;
  onDelete?: (msg: Message) => void;
  onEdit?: (msg: Message) => void;
  onPin?: (msg: Message) => void;
  isPinned?: boolean;
  onMediaClick?: (msg: Message) => void;
}

const COMMON_REACTIONS = ['❤️', '😂', '😮', '😢', '🔥', '👍'];

export const MessageBubble: React.FC<MessageBubbleProps> = ({ message, isOwn, isAI, onReply, onForward, onDelete, onEdit, onPin, isPinned, onMediaClick }) => {
  const [showMenu, setShowMenu] = useState(false);
  const [showReactions, setShowReactions] = useState(false);
  const [swipeOffset, setSwipeOffset] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [progress, setProgress] = useState(0);
  const [currentTime, setCurrentTime] = useState(0);

  const menuRef = useRef<HTMLDivElement>(null);
  const audioRef = useRef<HTMLAudioElement>(null);
  const touchStartX = useRef<number | null>(null);
  const currentUid = auth.currentUser?.uid || '';

  useEffect(() => {
    const handleClick = (e: MouseEvent) => { 
        if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
            setShowMenu(false);
            setShowReactions(false);
        }
    };
    if (showMenu || showReactions) document.addEventListener('mousedown', handleClick);
    return () => document.removeEventListener('mousedown', handleClick);
  }, [showMenu, showReactions]);

  const formatTime = (ts: number) => new Date(ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

  const handleTouchStart = (e: React.TouchEvent) => { touchStartX.current = e.touches[0].clientX; };
  const handleTouchMove = (e: React.TouchEvent) => {
    if (touchStartX.current === null) return;
    const deltaX = e.touches[0].clientX - touchStartX.current;
    if (deltaX > 0) setSwipeOffset(Math.min(deltaX, 80));
  };
  const handleTouchEnd = () => {
    if (swipeOffset > 50) onReply(message);
    setSwipeOffset(0);
    touchStartX.current = null;
  };

  const toggleAudio = () => {
    const audio = audioRef.current;
    if (audio) {
      if (isPlaying) {
        audio.pause();
      } else {
        document.querySelectorAll('audio').forEach(a => { if(a !== audio) a.pause() });
        const playPromise = audio.play();
        if (playPromise !== undefined) {
          playPromise.catch(e => {
            console.error("Audio play error:", e);
            setIsPlaying(false);
          });
        }
      }
    }
  };

  const handleTimeUpdate = () => {
    const audio = audioRef.current;
    if (audio) {
        setCurrentTime(audio.currentTime);
        if (audio.duration) {
            setProgress((audio.currentTime / audio.duration) * 100);
        }
    }
  };

  const handleReaction = async (emoji: string) => {
    await toggleMessageReaction(message.id, emoji, currentUid);
    setShowReactions(false);
    setShowMenu(false);
  };

  const handleVote = async (optionId: string) => {
    await voteOnPoll(message.id, optionId, currentUid);
  };

  const renderStatus = () => {
    if (!isOwn) return null;
    const isSeen = message.status === 'seen';
    // If not seen, logic for delivered (usually implied if not error in firebase)

    if (isSeen) {
       // Requirement: "Seen just now" text
       // Simple logic: If seen, show text. 
       // Note: We might not want to show "Just now" for old messages, but the prompt says "jab seen hojayega to seen just now likha ayegs".
       // I'll place this *below* the message in the main render, here I return the double ticks for "Delivered/Sent" phase before seen or standard ticks.
       return null; // Handled outside to put text below
    }

    // Default to 2 black ticks for Sent/Delivered as requested ("jab sent ho jaye to 2 tick ayenge black colour me")
    return (
      <div className="flex -space-x-1 text-black/60 dark:text-white/60 ml-1">
        <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7" /></svg>
        <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7" /></svg>
      </div>
    );
  };

  const isDeleted = message.type === 'deleted';
  const hasReactions = message.reactions && Object.keys(message.reactions).length > 0;

  return (
    <div className={`relative flex flex-col w-full ${isOwn ? 'items-end' : 'items-start'} ${hasReactions ? 'mb-6' : 'mb-2'} px-2 group animate-in slide-in-from-${isOwn ? 'right' : 'left'}-4 duration-300`} id={`msg-${message.id}`}>

      {/* Swipe Indicator (Hidden but functional) */}
      <div className="absolute left-4 top-1/2 -translate-y-1/2 transition-all duration-200 pointer-events-none opacity-0"></div>

      <div className={`relative flex flex-col max-w-[85%] sm:max-w-[70%] ${isOwn ? 'items-end' : 'items-start'} transition-transform duration-200`} style={{ transform: `translateX(${swipeOffset}px)` }} onTouchStart={handleTouchStart} onTouchMove={handleTouchMove} onTouchEnd={handleTouchEnd}>

        {/* Context Menu */}
        <div ref={menuRef}>
            {showReactions && !isDeleted && (
                <div className={`absolute z-[60] bottom-full mb-2 bg-white dark:bg-slate-800 rounded-full shadow-xl border border-slate-200 dark:border-slate-700 p-2 flex gap-2 animate-in zoom-in-95 ${isOwn ? 'right-0' : 'left-0'}`}>
                    {COMMON_REACTIONS.map(emoji => (
                        <button key={emoji} onClick={() => handleReaction(emoji)} className="text-2xl hover:scale-125 transition-transform active:scale-90 p-1">
                            {emoji}
                        </button>
                    ))}
                </div>
            )}
            {showMenu && !isDeleted && (
            <div className={`absolute z-50 bottom-full mb-12 bg-white/90 dark:bg-slate-800/95 backdrop-blur-xl rounded-2xl shadow-2xl border border-white/20 p-1.5 flex flex-col min-w-[150px] animate-in zoom-in-95 origin-bottom-${isOwn ? 'right' : 'left'}`}>
                <button onClick={() => setShowReactions(!showReactions)} className="px-4 py-2.5 hover:bg-indigo-500 hover:text-white rounded-xl text-left font-bold text-xs uppercase tracking-wider flex items-center gap-2 text-slate-700 dark:text-slate-200">
                    <span className="text-lg leading-none">😊</span> React
                </button>
                <button onClick={() => { onReply(message); setShowMenu(false); }} className="px-4 py-2.5 hover:bg-indigo-500 hover:text-white rounded-xl text-left font-bold text-xs uppercase tracking-wider flex items-center gap-2 text-slate-700 dark:text-slate-200">
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 10h10a8 8 0 018 8v2M3 10l6 6m-6-6l6-6" /></svg> Reply
                </button>
                <button onClick={() => { onForward(message); setShowMenu(false); }} className="px-4 py-2.5 hover:bg-indigo-500 hover:text-white rounded-xl text-left font-bold text-xs uppercase tracking-wider flex items-center gap-2 text-slate-700 dark:text-slate-200">
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg> Forward
                </button>
                {onPin && (
                <button onClick={() => { onPin(message); setShowMenu(false); }} className="px-4 py-2.5 hover:bg-indigo-500 hover:text-white rounded-xl text-left font-bold text-xs uppercase tracking-wider flex items-center gap-2 text-slate-700 dark:text-slate-200">
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" /></svg> {isPinned ? 'Unpin' : 'Pin'}
                </button>
                )}
                {isOwn && message.type === 'text' && onEdit && (
                    <button onClick={() => { onEdit(message); setShowMenu(false); }} className="px-4 py-2.5 hover:bg-indigo-500 hover:text-white rounded-xl text-left font-bold text-xs uppercase tracking-wider flex items-center gap-2 text-slate-700 dark:text-slate-200">
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg> Edit
                    </button>
                )}
                {onDelete && (
                    <button onClick={() => { onDelete(message); setShowMenu(false); }} className="px-4 py-2.5 text-red-500 hover:bg-red-500 hover:text-white rounded-xl text-left font-bold text-xs uppercase tracking-wider flex items-center gap-2">
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg> Delete
                    </button>
                )}
            </div>
            )}
        </div>

        {/* Message Bubble Content */}
        <div 
          onClick={() => !isDeleted && setShowMenu(!showMenu)} 
          className={`relative px-4 py-3 rounded-[1.2rem] transition-all active:scale-[0.99] cursor-pointer shadow-sm group-hover:shadow-md overflow-hidden 
            ${message.type === 'sticker' 
                ? 'bg-transparent shadow-none p-0' 
                : isDeleted 
                    ? 'bg-slate-100 dark:bg-slate-800 text-slate-500 italic border border-slate-200 dark:border-slate-700' 
                    : isOwn 
                        ? 'bg-indigo-600 text-white rounded-tr-none' 
                        : isAI 
                            ? 'bg-slate-800 text-white border border-indigo-500/30 rounded-tl-none' 
                            : 'bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100 rounded-tl-none border border-slate-100 dark:border-slate-700'
            }`}
        >
          {isPinned && !isDeleted && (
             <div className="absolute top-0 right-0 p-1 bg-black/20 rounded-bl-lg text-white">
                <svg className="w-2.5 h-2.5" fill="currentColor" viewBox="0 0 24 24"><path d="M16 12V4H17V2H7V4H8V12L6 14V16H11V22H13V16H18V14L16 12Z"/></svg>
             </div>
          )}

          {message.replyContext && !isDeleted && (
            <div className={`mb-2 p-2 rounded-lg border-l-2 text-[11px] flex flex-col gap-0.5 ${isOwn ? 'bg-white/10 border-white/50' : 'bg-indigo-50 dark:bg-indigo-900/30 border-indigo-500'}`}>
              <span className={`font-black uppercase tracking-tight ${isOwn ? 'text-white' : 'text-indigo-600 dark:text-indigo-400'}`}>{message.replyContext.senderName}</span>
              <p className="truncate opacity-80 font-medium italic">{message.replyContext.text}</p>
            </div>
          )}

          {isDeleted ? (
              <div className="flex items-center gap-2">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M18.364 18.364A9 9 0 005.636 5.636m12.728 12.728L5.636 5.636" /></svg>
                  <span className="text-sm font-medium">{message.text}</span>
              </div>
          ) : message.type === 'voice' && message.audioUrl ? (
             <div className="flex items-center gap-3 min-w-[180px]">
                <button onClick={(e) => { e.stopPropagation(); toggleAudio(); }} className={`w-10 h-10 rounded-full flex items-center justify-center shrink-0 transition-transform active:scale-90 ${isOwn ? 'bg-white/20 text-white hover:bg-white/30' : 'bg-indigo-500 text-white hover:bg-indigo-600'}`}>
                   {isPlaying ? <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/></svg> : <svg className="w-4 h-4 ml-0.5" fill="currentColor" viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>}
                </button>
                <div className="flex flex-col gap-1 w-full">
                    <div className={`h-1.5 rounded-full w-32 relative overflow-hidden ${isOwn ? 'bg-white/30' : 'bg-slate-300 dark:bg-slate-600'}`}>
                        <div 
                            className={`h-full rounded-full transition-all duration-100 ease-linear ${isOwn ? 'bg-white' : 'bg-indigo-500'}`}
                            style={{ width: `${progress}%` }}
                        ></div>
                    </div>
                    <div className="flex justify-between w-32">
                        <span className={`text-[10px] font-bold uppercase tracking-wider ${isOwn ? 'text-white/70' : 'text-slate-500'}`}>
                            {isPlaying ? `${Math.floor(currentTime / 60)}:${Math.floor(currentTime % 60).toString().padStart(2, '0')}` : (message.duration ? `${Math.floor(message.duration / 60)}:${(message.duration % 60).toString().padStart(2, '0')}` : 'Voice')}
                        </span>
                    </div>
                </div>
                {message.audioUrl && (
                  <audio 
                    ref={audioRef} 
                    src={message.audioUrl} 
                    onPlay={() => setIsPlaying(true)}
                    onPause={() => setIsPlaying(false)}
                    onEnded={() => { setIsPlaying(false); setProgress(0); setCurrentTime(0); }}
                    onTimeUpdate={handleTimeUpdate}
                    onError={(e) => {
                      console.error("Audio load failed", e);
                      setIsPlaying(false);
                    }}
                    className="hidden" 
                    preload="metadata"
                  />
                )}
             </div>
          ) : message.type === 'image' && message.fileUrl ? (
            <div 
                className="relative mb-2 -mx-1 -mt-1 overflow-hidden rounded-xl cursor-zoom-in"
                onClick={(e) => { 
                    e.stopPropagation(); 
                    if(onMediaClick) onMediaClick(message); 
                }}
            >
                <img src={message.fileUrl} className="max-h-80 w-full object-cover" alt="" />
            </div>
          ) : message.type === 'video' && message.fileUrl ? (
            <div 
                className="relative mb-2 -mx-1 -mt-1 overflow-hidden rounded-xl bg-black cursor-pointer"
                onClick={(e) => { 
                    e.stopPropagation(); 
                    if(onMediaClick) onMediaClick(message); 
                }}
            >
                <video src={message.fileUrl} className="max-h-80 w-full object-contain pointer-events-none" onError={(e) => console.error("Video load failed", e)} />
                <div className="absolute inset-0 flex items-center justify-center bg-black/20 group-hover:bg-black/10 transition-colors">
                     <div className="p-3 bg-white/20 backdrop-blur-md rounded-full text-white border border-white/30 shadow-xl">
                        <svg className="w-6 h-6 ml-1" fill="currentColor" viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>
                     </div>
                </div>
            </div>
          ) : message.type === 'sticker' && message.stickerUrl ? (
             <div className="w-32 h-32 hover:scale-105 transition-transform">
                <img src={message.stickerUrl} alt="Sticker" className="w-full h-full object-contain" />
             </div>
          ) : message.type === 'poll' && message.poll ? (
             <div className="min-w-[220px]">
                <h4 className="font-bold text-sm mb-3">{message.poll.question}</h4>
                <div className="space-y-2">
                    {message.poll.options.map((opt: PollOption) => {
                        const totalVotes = message.poll!.options.reduce((acc: number, o: PollOption) => {
                           const votes = o.votes as unknown as string[];
                           return acc + (votes?.length || 0);
                        }, 0);
                        const votes = opt.votes as unknown as string[];
                        const voteCount = votes?.length || 0;
                        const percentage = totalVotes > 0 ? Math.round((voteCount / totalVotes) * 100) : 0;
                        const hasVoted = votes?.includes(currentUid);

                        return (
                            <button 
                                key={opt.id}
                                onClick={(e) => { e.stopPropagation(); handleVote(opt.id); }}
                                className={`w-full relative h-10 rounded-lg overflow-hidden border transition-all ${hasVoted ? 'border-indigo-500' : 'border-slate-200 dark:border-slate-600'}`}
                            >
                                <div className={`absolute inset-y-0 left-0 bg-indigo-100 dark:bg-indigo-900/30 transition-all duration-500`} style={{ width: `${percentage}%` }}></div>
                                <div className="absolute inset-0 flex items-center justify-between px-3">
                                    <span className={`text-xs font-bold z-10 ${isOwn ? 'text-white' : 'text-slate-700 dark:text-slate-200'}`}>{opt.text} {hasVoted && '✓'}</span>
                                    <span className={`text-[10px] font-bold z-10 ${isOwn ? 'text-white/80' : 'text-slate-500'}`}>{percentage}%</span>
                                </div>
                            </button>
                        );
                    })}
                </div>
                <div className="mt-2 text-[10px] opacity-70 font-bold uppercase tracking-wider text-center">
                    {message.poll.options.reduce((acc: number, o: PollOption) => {
                        const votes = o.votes as unknown as string[];
                        return acc + (votes?.length || 0);
                    }, 0)} votes
                </div>
             </div>
          ) : (
            <p className="text-[14px] leading-[1.5] font-medium whitespace-pre-wrap">{message.text}</p>
          )}

          {message.type !== 'sticker' && (
            <div className={`flex items-center gap-1 justify-end mt-1 ${isOwn ? 'text-white/70' : 'text-slate-400 dark:text-slate-500'}`}>
                {message.isEdited && !isDeleted && <span className="text-[9px] italic mr-1">(edited)</span>}
                <span className="text-[9px] font-bold uppercase tracking-tight">{formatTime(message.timestamp)}</span>
                {renderStatus()}
            </div>
          )}
        </div>

        {/* Seen Just Now Text */}
        {isOwn && message.status === 'seen' && (
            <span className="text-[9px] font-bold text-slate-400 mt-1 self-end mr-1 animate-in fade-in">
                Seen just now
            </span>
        )}

        {/* Reaction Pill Display */}
        {hasReactions && !isDeleted && (
            <div className={`absolute -bottom-5 ${isOwn ? 'right-2' : 'left-2'} flex gap-1 z-10`}>
                <div className="flex items-center gap-1 bg-white dark:bg-slate-800 rounded-full px-1.5 py-0.5 shadow-md border border-slate-100 dark:border-slate-700">
                    {Object.entries(message.reactions || {}).slice(0, 3).map(([emoji, users]) => (
                        <span key={emoji} className="text-[10px] leading-none" title={`${users.length} reaction(s)`}>{emoji}</span>
                    ))}
                    <span className="text-[9px] font-bold text-slate-500 px-1">
                        {Object.values(message.reactions || {}).reduce((acc, u) => acc + u.length, 0)}
                    </span>
                </div>
            </div>
        )}

      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
