          <AdminDashboard 
            currentUser={user} 
            onExit={() => setView('user')}
          />
        ) : (
          <div className="relative h-full w-full">
            {user.isAdmin && (
              <button 
                onClick={() => setView('role_select')}
                className="fixed bottom-24 right-4 z-[200] bg-indigo-600 text-white px-4 py-2 rounded-full shadow-2xl font-bold text-[10px] uppercase tracking-widest hover:bg-indigo-700 transition-all flex items-center gap-2 border border-white/20"
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7h12m0 0l-4-4m4 4l-4 4m0 6H4m0 0l4 4m-4-4l4-4" /></svg>
                Switch Workspace
              </button>
            )}
            <ChatDashboard 
              currentUser={user} 
              toggleDarkMode={() => setDarkMode(!darkMode)} 
              isDarkMode={darkMode}
            />
          </div>
        )}
      </div>
    </ErrorBoundary>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { User, Chat, Message, PollData } from '../../types';
import { MessageBubble } from './MessageBubble';
import { GroupInfoModal } from './GroupInfoModal';
import { MediaViewer } from './MediaViewer';
import { getAIResponse } from '../../gemini';
import { 
  getUserById, 
  addMessage, 
  getMessages, 
  toggleChatLock, 
  editMessage, 
  subscribeToChat, 
  deleteMessageForEveryone, 
  deleteMessageForMe, 
  subscribeToUser, 
  togglePinMessage, 
  setTypingStatus,
  getMyChats,
  getAllUsers
} from '../../firebase';

interface ChatWindowProps {
  chat: Chat;
  currentUser: User;
  onClose: () => void;
  onUserClick: (user: User) => void;
  onCallStart?: (user: User, type: 'voice' | 'video') => void;
}

const STICKERS = [
    'https://cdn-icons-png.flaticon.com/512/742/742751.png',
    'https://cdn-icons-png.flaticon.com/512/742/742752.png',
    'https://cdn-icons-png.flaticon.com/512/742/742923.png',
    'https://cdn-icons-png.flaticon.com/512/742/742823.png',
    'https://cdn-icons-png.flaticon.com/512/742/742760.png',
    'https://cdn-icons-png.flaticon.com/512/742/742940.png',
    'https://cdn-icons-png.flaticon.com/512/4712/4712109.png',
    'https://cdn-icons-png.flaticon.com/512/4712/4712139.png',
];

const WALLPAPER_CLASSES: Record<string, string> = {
  default: 'bg-slate-50 dark:bg-slate-950',
  indigo: 'bg-indigo-600',
  emerald: 'bg-emerald-700',
  rose: 'bg-rose-500',
  amber: 'bg-amber-500',
  dark: 'bg-black',
  gradient: 'bg-gradient-to-br from-purple-900 via-indigo-900 to-black',
};

const FONT_SIZE_CLASSES: Record<string, string> = {
  small: 'text-[12px]',
  medium: 'text-[14px]',
  large: 'text-[16px]',
};

// SAFE CONSTANTS TO PREVENT BUILD ERRORS (REGEX/SLASH ISSUES)
const ACCEPTED_MEDIA_TYPES = "image/png,image/jpeg,image/gif,video/mp4,video/webm";
const CHAT_BG_PATTERN = "https://www.transparenttextures.com/patterns/asfalt-dark.png";

export const ChatWindow: React.FC<ChatWindowProps> = ({ chat, currentUser, onClose, onUserClick, onCallStart }) => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [otherUser, setOtherUser] = useState<User | null>(null);
  const [isLocked, setIsLocked] = useState(chat.lockedBy?.includes(currentUser.uid) || false);
  const [inputText, setInputText] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [typingUsers, setTypingUsers] = useState<string[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [recordingDuration, setRecordingDuration] = useState(0);
  const [mediaRecorder, setMediaRecorder] = useState<MediaRecorder | null>(null);
  const [editingMessage, setEditingMessage] = useState<Message | null>(null);
  const [pinnedMessageIds, setPinnedMessageIds] = useState<string[]>([]);
  const [showGroupInfo, setShowGroupInfo] = useState(false);

  // Block State
  const [isBlockedByMe, setIsBlockedByMe] = useState(false);
  const [isBlockedByThem, setIsBlockedByThem] = useState(false);

  // UI State for Deletion
  const [messageToDelete, setMessageToDelete] = useState<Message | null>(null);
  const [showDeleteOptions, setShowDeleteOptions] = useState(false);

  // UI State for Media Viewing
  const [viewingMedia, setViewingMedia] = useState<Message | null>(null);

  // UI State for Attachments
  const [showAttachMenu, setShowAttachMenu] = useState(false);
  const [showPollModal, setShowPollModal] = useState(false);
  const [showStickerPicker, setShowStickerPicker] = useState(false);

  // Poll State
  const [pollQuestion, setPollQuestion] = useState('');
  const [pollOptions, setPollOptions] = useState(['', '']);

  const [wallpaper, setWallpaper] = useState('default');
  const [customUrl, setCustomUrl] = useState<string | null>(null);
  const [fontSize, setFontSize] = useState('medium');
  const [replyingTo, setReplyingTo] = useState<Message | null>(null);
  const [forwardingMessage, setForwardingMessage] = useState<Message | null>(null);
  const [availableChats, setAvailableChats] = useState<Chat[]>([]);
  const [allUsers, setAllUsers] = useState<User[]>([]);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const typingTimeoutRef = useRef<any>(null);
  const timerRef = useRef<any>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const inputRef = useRef<HTMLInputElement>(null);
  const attachMenuRef = useRef<HTMLDivElement>(null);

  const isGroup = chat.type === 'group';
  const otherId = !isGroup && chat.participants 
    ? (chat.participants.find(p => p !== currentUser.uid) || (chat.participants.includes(currentUser.uid) ? currentUser.uid : '')) 
    : chat.id;

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (attachMenuRef.current && !attachMenuRef.current.contains(event.target as Node)) {
        setShowAttachMenu(false);
      }
    };
    if (showAttachMenu) document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [showAttachMenu]);

  const loadSettings = () => {
    try {
      const saved = localStorage.getItem('roxx_settings');
      if (saved) {
        const parsed = JSON.parse(saved);
        setWallpaper(parsed.wallpaper || 'default');
        setCustomUrl(parsed.customWallpaperUrl || null);
        setFontSize(parsed.fontSize || 'medium');
      }
    } catch (e) {
      console.warn("Settings corrupted, resetting");
      localStorage.removeItem('roxx_settings');
      setWallpaper('default');
    }
  };

  useEffect(() => {
    loadSettings();
    window.addEventListener('roxx_settings_updated', loadSettings);
    return () => window.removeEventListener('roxx_settings_updated', loadSettings);
  }, []);

  // Subscribe to Chat (Typing indicators, Pinned Messages)
  useEffect(() => {
    const unsubscribe = subscribeToChat(chat.id, (data) => {
      if (data.typing) {
        const activeTypers = Object.entries(data.typing)
          .filter(([uid, isTyping]) => uid !== currentUser.uid && isTyping)
          .map(([uid]) => uid);
        setTypingUsers(activeTypers);
      } else {
        setTypingUsers([]);
      }
      if (data.pinnedMessages) {
        setPinnedMessageIds(data.pinnedMessages);
      } else {
        setPinnedMessageIds([]);
      }
    });
    return () => unsubscribe();
  }, [chat.id, currentUser.uid]);

  // Subscribe to Other User (Online Status & Blocking)
  useEffect(() => {
    if (isGroup || !otherId) return;

    getUserById(otherId).then(u => { 
        if(u) {
            setOtherUser(u); 
            // Check blocking status on load
            setIsBlockedByThem(u.blockedUsers?.includes(currentUser.uid) || false);
        }
    });

    // Also check if I blocked them
    setIsBlockedByMe(currentUser.blockedUsers?.includes(otherId) || false);

    const unsubscribe = subscribeToUser(otherId, (userData) => {
        setOtherUser(userData);
        setIsBlockedByThem(userData.blockedUsers?.includes(currentUser.uid) || false);
    });
    return () => unsubscribe();
  }, [otherId, isGroup, currentUser.uid, currentUser.blockedUsers]);

  // Messages Polling
  useEffect(() => {
    const sync = async () => {
      const msgs = await getMessages(chat.id);
      setMessages(prev => {
        if (JSON.stringify(msgs) !== JSON.stringify(prev)) return msgs;
        return prev;
      });
    };
    sync();
    const itv = setInterval(sync, 1500); 
    return () => clearInterval(itv);
  }, [chat.id]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [messages.length, isTyping, replyingTo, editingMessage]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setInputText(e.target.value);
    if (!isTyping) {
      setIsTyping(true);
      setTypingStatus(chat.id, currentUser.uid, true);
    }
    if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
    typingTimeoutRef.current = setTimeout(() => {
      setIsTyping(false);
      setTypingStatus(chat.id, currentUser.uid, false);
    }, 2000);
  };

  // --- Voice Recording Logic ---
  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      let mimeType = 'audio/webm';
      if (MediaRecorder.isTypeSupported('audio/webm;codecs=opus')) mimeType = 'audio/webm;codecs=opus';
      else if (MediaRecorder.isTypeSupported('audio/mp4')) mimeType = 'audio/mp4';

      const recorder = new MediaRecorder(stream, { mimeType });
      setMediaRecorder(recorder);
      audioChunksRef.current = [];

      recorder.ondataavailable = (e) => {
        if (e.data.size > 0) audioChunksRef.current.push(e.data);
      };

      recorder.start();
      setIsRecording(true);
      setRecordingDuration(0);
      timerRef.current = setInterval(() => setRecordingDuration(p => p + 1), 1000);
    } catch (err) { alert("Microphone access denied."); }
  };

  const stopRecording = async (shouldSend: boolean) => {
    if (mediaRecorder && isRecording) {
      const mimeType = mediaRecorder.mimeType || 'audio/webm';
      mediaRecorder.onstop = async () => {
        if (shouldSend && audioChunksRef.current.length > 0) {
            const blob = new Blob(audioChunksRef.current, { type: mimeType });
            const reader = new FileReader();
            reader.readAsDataURL(blob);
            reader.onloadend = async () => {
                const base64Audio = reader.result as string;
                const msg: Message = {
                    id: 'v_' + Math.random().toString(36).substring(2, 11),
                    senderId: currentUser.uid,
                    recipientId: isGroup ? chat.id : otherId!,
                    text: 'Voice Message',
                    type: 'voice',
                    timestamp: Date.now(),
                    status: 'sent',
                    audioUrl: base64Audio,
                    duration: recordingDuration
                };
                setMessages(prev => [...prev, msg]);
                await addMessage(msg);
            };
        }
        mediaRecorder.stream.getTracks().forEach(track => track.stop());
        setMediaRecorder(null);
        audioChunksRef.current = [];
      };
      mediaRecorder.stop();
      clearInterval(timerRef.current);
      setIsRecording(false);
    }
  };

  const formatDuration = (sec: number) => {
    const m = Math.floor(sec / 60);
    const s = sec % 60;
    return `${m}:${s.toString().padStart(2, '0')}`;
  };

  // --- Deletion UX Logic ---
  const triggerDeleteFlow = (msg: Message) => {
      setMessageToDelete(msg);
      setShowDeleteOptions(true);
  };

  const confirmDelete = async (type: 'me' | 'everyone') => {
      if (!messageToDelete) return;
      if (window.confirm(type === 'everyone' ? "Delete for everyone?" : "Delete for me?")) {
          if (type === 'everyone') {
              setMessages(prev => prev.map(m => m.id === messageToDelete.id ? { ...m, type: 'deleted', text: '🚫 This message was deleted' } : m));
              await deleteMessageForEveryone(messageToDelete.id);
          } else {
              setMessages(prev => prev.filter(m => m.id !== messageToDelete.id));
              await deleteMessageForMe(messageToDelete.id, currentUser.uid);
          }
      }
      setShowDeleteOptions(false);
      setMessageToDelete(null);
  };

  const handlePinMessage = async (msg: Message) => {
      await togglePinMessage(chat.id, msg.id);
  };

  const handleEditMessage = (msg: Message) => {
      setEditingMessage(msg);
      setInputText(msg.text);
      inputRef.current?.focus();
  };

  const handleMediaClick = (msg: Message) => {
      setViewingMedia(msg);
  };

  const handleSend = async (e?: React.FormEvent) => {
    e?.preventDefault();
    const text = inputText.trim();
    if (!text) return;

    if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
    setIsTyping(false);
    setTypingStatus(chat.id, currentUser.uid, false);

    if (editingMessage) {
        setMessages(prev => prev.map(m => m.id === editingMessage.id ? { ...m, text: text, isEdited: true } : m));
        await editMessage(editingMessage.id, text);
        setEditingMessage(null);
        setInputText('');
        return;
    }

    const recipient = isGroup ? chat.id : otherId;
    if (!recipient) return;

    if (!isGroup && (isBlockedByMe || isBlockedByThem)) {
        if (isBlockedByMe) {
            if(!window.confirm("You blocked this user. Unblock to send message?")) return;
        }
    }

    let replyContext = undefined;
    if (replyingTo) {
      const sender = await getUserById(replyingTo.senderId);
      replyContext = {
        messageId: replyingTo.id,
        text: replyingTo.text || 'Media',
        senderName: sender?.name || 'User'
      };
    }

    const msg: Message = {
      id: 'm_' + Math.random().toString(36).substring(2, 11),
      senderId: currentUser.uid, 
      recipientId: recipient,
      text, 
      type: 'text', 
      timestamp: Date.now(), 
      status: 'sent',
      replyContext
    };

    setMessages(prev => [...prev, msg]);
    setInputText('');
    setReplyingTo(null);

    await addMessage(msg);

    if (text.toLowerCase().startsWith('/ai')) {
      setTypingUsers(prev => [...prev, 'gemini_ai']);
      try {
        const promptText = text.slice(3).trim(); 
        const res = await getAIResponse(promptText);
        const aiMsg: Message = {
          id: 'ai_' + Date.now(), 
          senderId: 'gemini_ai', 
          recipientId: isGroup ? chat.id : currentUser.uid,
          text: res || "I'm thinking...", 
          type: 'text', 
          timestamp: Date.now(), 
          status: 'seen'
        };
        await addMessage(aiMsg);
      } catch (err) { }
      finally { setTypingUsers(prev => prev.filter(id => id !== 'gemini_ai')); }
    }
  };

  const handleCreatePoll = async () => {
    if (!pollQuestion.trim() || pollOptions.filter(o => o.trim()).length < 2) return;

    const poll: PollData = {
        question: pollQuestion,
        options: pollOptions.filter(o => o.trim()).map((text, i) => ({
            id: `opt_${i}`,
            text,
            votes: []
        })),
        allowMultiple: false
    };

    const recipient = isGroup ? chat.id : otherId!;
    const msg: Message = {
        id: 'poll_' + Math.random().toString(36).substring(2, 11),
        senderId: currentUser.uid,
        recipientId: recipient,
        text: '📊 Poll',
        type: 'poll',
        timestamp: Date.now(),
        status: 'sent',
        poll
    };

    await addMessage(msg);
    setMessages(prev => [...prev, msg]);
    setShowPollModal(false);
    setPollQuestion('');
    setPollOptions(['', '']);
  };

  const handleSendSticker = async (url: string) => {
    const recipient = isGroup ? chat.id : otherId!;
    const msg: Message = {
        id: 'sticker_' + Math.random().toString(36).substring(2, 11),
        senderId: currentUser.uid,
        recipientId: recipient,
        text: '👾 Sticker',
        type: 'sticker',
        timestamp: Date.now(),
        status: 'sent',
        stickerUrl: url
    };
    await addMessage(msg);
    setMessages(prev => [...prev, msg]);
    setShowStickerPicker(false);
  };

  const handleForward = async (targetChat: Chat) => {
    if (!forwardingMessage) return;
    const targetId = targetChat.type === 'group' ? targetChat.id : targetChat.participants.find(p => p !== currentUser.uid)!;
    const { replyContext, ...msgContent } = forwardingMessage;
    const forwardMsg: Message = {
      ...msgContent,
      id: 'fwd_' + Math.random().toString(36).substring(2, 11),
      senderId: currentUser.uid,
      recipientId: targetId,
      timestamp: Date.now(),
      status: 'sent',
      isForwarded: true
    };
    await addMessage(forwardMsg);
    setForwardingMessage(null);
    alert(`Forwarded to ${targetChat.name || 'Contact'}`);
  };

  const openForwardModal = async (msg: Message) => {
    setForwardingMessage(msg);
    const chats = await getMyChats(currentUser.uid);
    const users = await getAllUsers();
    setAvailableChats(chats);
    setAllUsers(users);
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const recipient = isGroup ? chat.id : otherId;
    if (!recipient) return;

    setIsUploading(true);
    const reader = new FileReader();
    reader.onload = async (event) => {
      const fileUrl = event.target?.result as string;
      let messageType: any = 'file';
      if (file.type.startsWith('image/')) messageType = 'image';
      else if (file.type.startsWith('video/')) messageType = 'video';
      const msg: Message = {
        id: 'f_' + Math.random().toString(36).substring(2, 11), 
        senderId: currentUser.uid,
        recipientId: recipient, 
        text: file.name, 
        type: messageType,
        timestamp: Date.now(), 
        status: 'sent', 
        fileUrl, 
        fileName: file.name
      };
      setMessages(prev => [...prev, msg]);
      await addMessage(msg);
      setIsUploading(false);
    };
    reader.readAsDataURL(file);
    e.target.value = '';
    setShowAttachMenu(false);
  };

  const handleHeaderClick = () => {
    if (isGroup) {
      setShowGroupInfo(true);
    } else {
      onUserClick(otherUser || {} as User);
    }
  };

  const renderDateSeparator = (timestamp: number, prevTimestamp?: number) => {
    if (!timestamp) return null;
    const date = new Date(timestamp);
    if (isNaN(date.getTime())) return null;

    const dateStr = date.toDateString();
    const prevDateStr = prevTimestamp ? new Date(prevTimestamp).toDateString() : null;

    if (dateStr !== prevDateStr) {
      return (
        <div className="flex justify-center my-6 sticky top-2 z-10">
          <div className="px-4 py-1.5 bg-slate-900/10 dark:bg-white/10 backdrop-blur-md border border-white/20 rounded-full shadow-sm">
            <span className="text-[10px] font-black uppercase tracking-widest text-slate-500 dark:text-slate-300">
              {date.toLocaleDateString(undefined, { weekday: 'long', month: 'short', day: 'numeric' })}
            </span>
          </div>
        </div>
      );
    }
    return null;
  };

  const isOnline = otherUser?.status === 'online' && (Date.now() - (otherUser.lastSeen || 0) < 3 * 60 * 1000);
  const canSeeStatus = isGroup || (!isBlockedByThem && otherUser?.privacySettings?.lastSeen !== 'nobody');

  const statusColor = !isGroup && isOnline && canSeeStatus ? 'text-green-500' : 'text-slate-500 dark:text-slate-400';
  const statusText = !isGroup && canSeeStatus ? (isOnline ? 'Online Now' : 'Offline') : '';

  const displayPhoto = (!isGroup && isBlockedByThem) 
    ? 'https://ui-avatars.com/api/?name=User&background=random' 
    : (isGroup ? (chat.groupIcon || `https://picsum.photos/seed/${chat.id}/200`) : otherUser?.photoURL);

  const latestPinnedId = pinnedMessageIds[pinnedMessageIds.length - 1];
  const pinnedMessage = messages.find(m => m.id === latestPinnedId);

  return (
    <div className={`flex-1 flex flex-col h-full bg-white dark:bg-slate-900 animate-in fade-in duration-300 relative overflow-hidden ${FONT_SIZE_CLASSES[fontSize]}`}>
      {/* Background with optimized transparency to reduce lag */}
      <div className={`absolute inset-0 z-0 transition-all duration-700 ${wallpaper !== 'custom' ? WALLPAPER_CLASSES[wallpaper] || '' : ''}`}>
        {wallpaper === 'custom' && customUrl && <img src={customUrl} className="absolute inset-0 w-full h-full object-cover" alt="" /> }
        <div className="absolute inset-0 opacity-[0.03] pointer-events-none" style={{ backgroundImage: `url('${CHAT_BG_PATTERN}')` }}></div>
      </div>

      {/* Header */}
      <div className="p-3 md:p-4 flex items-center justify-between bg-white/90 dark:bg-slate-900/90 backdrop-blur-sm z-10 border-b border-slate-200 dark:border-slate-800 shadow-sm relative">
        <div className="flex items-center gap-3">
          <button onClick={onClose} className="lg:hidden p-2 rounded-xl hover:bg-slate-200 dark:hover:bg-slate-800"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 19l-7-7 7-7" /></svg></button>
          <div className="relative cursor-pointer group" onClick={handleHeaderClick}>
            <img src={displayPhoto} className="w-10 h-10 rounded-full object-cover border border-slate-200 dark:border-slate-700 group-hover:scale-105 transition-transform" alt="" />
            {!isGroup && isOnline && canSeeStatus && <div className="absolute -bottom-0.5 -right-0.5 w-3.5 h-3.5 bg-green-500 rounded-full border-2 border-white dark:border-slate-900 animate-pulse"></div>}
          </div>
          <div className="min-w-0 cursor-pointer" onClick={handleHeaderClick}>
            <h3 className="font-bold text-sm leading-none flex items-center gap-1.5 truncate text-slate-900 dark:text-white">
              {isGroup ? chat.name : (otherUser?.name || 'Loading...')}
              {isLocked && <svg className="w-3.5 h-3.5 text-indigo-500" fill="currentColor" viewBox="0 0 24 24"><path d="M12 17c1.1 0 2-.9 2-2s-.9-2-2-2-2 .9-2 2 .9 2 2 2zm6-9h-1V6c0-2.76-2.24-5-5-5S7 3.24 7 6v2H6c-1.1 0-2 .9-2 2v10c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V10c0-1.1-.9-2-2-2zm-6-5c1.66 0 3 1.34 3 3v2H9V6c0-1.66 1.34-3 3-3z"/></svg>}
            </h3>
            {typingUsers.length > 0 ? (
               <span className="text-[10px] text-indigo-500 font-bold uppercase tracking-widest mt-0.5 animate-pulse flex items-center gap-1">
                  <div className="flex gap-0.5">
                    <span className="w-1 h-1 bg-indigo-500 rounded-full animate-bounce"></span>
                    <span className="w-1 h-1 bg-indigo-500 rounded-full animate-bounce [animation-delay:0.1s]"></span>
                    <span className="w-1 h-1 bg-indigo-500 rounded-full animate-bounce [animation-delay:0.2s]"></span>
                  </div>
                  {isGroup ? `${typingUsers.length} typing...` : typingUsers.includes('gemini_ai') ? 'AI thinking...' : 'Typing...'}
               </span>
            ) : (
               <span className={`text-[10px] font-bold uppercase tracking-widest mt-0.5 ${statusColor}`}>
                  {isGroup ? `${chat.participants?.length || 0} members` : statusText}
               </span>
            )}
          </div>
        </div>
        <div className="flex items-center gap-2">
          {!isGroup && otherUser && !isBlockedByThem && !isBlockedByMe && (
            <>
