import React, { useState, useEffect, ReactNode } from 'react';
import { AuthView } from './components/Auth/AuthView';
import { ChatDashboard } from './components/Chat/ChatDashboard';
import { AdminDashboard } from './components/Admin/AdminDashboard';
import { useAuth } from './hooks/useAuth';

type AppView = 'auth' | 'role_select' | 'user' | 'admin';

interface ErrorBoundaryProps {
  children?: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
}

// Error Boundary to catch crashes and prevent white screen
class ErrorBoundary extends React.Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = { hasError: false };
  }

  static getDerivedStateFromError(error: any): ErrorBoundaryState {
    return { hasError: true };
  }

  componentDidCatch(error: any, errorInfo: any) {
    console.error("App Crash:", error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="h-screen w-full flex items-center justify-center bg-slate-50 dark:bg-slate-900 text-slate-900 dark:text-white p-4 text-center">
           <div className="max-w-md">
             <div className="w-20 h-20 bg-red-100 dark:bg-red-900/20 text-red-500 rounded-full flex items-center justify-center mx-auto mb-6">
                <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
             </div>
             <h1 className="text-2xl font-bold mb-2">Something went wrong</h1>
             <p className="opacity-70 mb-8 leading-relaxed">The application encountered an unexpected error. This can happen due to connection issues or corrupted local data.</p>
             <button 
                onClick={() => { 
                    localStorage.removeItem('roxx_settings'); 
                    window.location.reload(); 
                }} 
                className="px-8 py-4 bg-indigo-500 hover:bg-indigo-600 text-white rounded-2xl font-bold shadow-xl shadow-indigo-500/20 transition-all active:scale-95"
             >
                Reset & Reload App
             </button>
           </div>
        </div>
      );
    }

    return this.props.children;
  }
}

const App: React.FC = () => {
  const { user, loading } = useAuth();
  const [view, setView] = useState<AppView>('auth');
  const [darkMode, setDarkMode] = useState(() => {
    return localStorage.getItem('theme') === 'dark' || 
           (!localStorage.getItem('theme') && window.matchMedia('(prefers-color-scheme: dark)').matches);
  });

  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [darkMode]);

  // Handle initial view routing and transitions
  useEffect(() => {
    if (!user) {
      setView('auth');
    } else if (user.isAdmin) {
      // For admins, default to role selection unless they've already chosen a path
      if (view === 'auth') {
        setView('role_select');
      }
    } else {
      setView('user');
    }
  }, [user, view]);

  if (loading) {
    return (
      <div className="h-[100dvh] w-screen flex items-center justify-center bg-slate-50 dark:bg-slate-950">
        <div className="flex flex-col items-center gap-4">
          <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
          <p className="text-slate-500 animate-pulse font-medium text-sm">Initializing Secure Session...</p>
        </div>
      </div>
    );
  }

  // Guard: If no user, always show Auth
  if (!user) {
    return <AuthView />;
  }

  // Role Selection Screen for Admins
  if (view === 'role_select') {
    return (
      <div className="h-[100dvh] w-full flex items-center justify-center bg-gradient-to-br from-indigo-900 via-slate-900 to-black p-4">
        <div className="glass w-full max-w-lg p-10 rounded-[3rem] shadow-2xl flex flex-col items-center text-center animate-in zoom-in-95 duration-500">
           <div className="w-20 h-20 bg-indigo-500/20 rounded-[2rem] flex items-center justify-center mb-8 border border-white/20">
              <svg className="w-10 h-10 text-indigo-400" fill="currentColor" viewBox="0 0 24 24"><path d="M12 1L3 5v6c0 5.55 3.84 10.74 9 12 5.16-1.26 9-6.45 9-12V5l-9-4zm0 10.99h7c-.53 4.12-3.28 7.79-7 8.94V12H5V6.3l7-3.11v8.8z"/></svg>
           </div>
           <h1 className="text-3xl font-black text-white mb-2 tracking-tight">Access Control</h1>
           <p className="text-slate-400 text-sm font-medium mb-10">Welcome back, {user.name}. Choose your workspace.</p>

           <div className="grid grid-cols-1 md:grid-cols-2 gap-4 w-full">
              <button 
                onClick={() => setView('user')}
                className="group relative p-8 bg-white/5 border border-white/10 rounded-[2.5rem] hover:bg-white/10 transition-all text-left overflow-hidden"
              >
                 <div className="p-3 bg-white/10 rounded-2xl w-fit mb-4 group-hover:bg-indigo-500 transition-colors">
                    <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" /></svg>
                 </div>
                 <h3 className="text-lg font-bold text-white mb-1">Normal User</h3>
                 <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Go to Chat Dashboard</p>
                 <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-500/5 blur-3xl -mr-16 -mt-16 pointer-events-none"></div>
              </button>

              <button 
                onClick={() => setView('admin')}
                className="group relative p-8 bg-indigo-500/10 border border-indigo-500/30 rounded-[2.5rem] hover:bg-indigo-500/20 transition-all text-left overflow-hidden"
              >
                 <div className="p-3 bg-indigo-500 text-white rounded-2xl w-fit mb-4 shadow-lg shadow-indigo-500/40">
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                 </div>
                 <h3 className="text-lg font-bold text-white mb-1">Admin Panel</h3>
                 <p className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest">System Management</p>
                 <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-500/20 blur-3xl -mr-16 -mt-16 pointer-events-none"></div>
              </button>
           </div>
        </div>
      </div>
    );
  }

  // Main Dashboard or Admin Panel - Wrapped in ErrorBoundary
  return (
    <ErrorBoundary>
      <div className="h-[100dvh] w-full overflow-hidden text-slate-900 dark:text-slate-100">
        {view === 'admin' ? (
          <AdminDashboard 
            currentUser={user} 
            onExit={() => setView('user')}
          />
        ) : (
          <div className="relative h-full w-full">
            {user.isAdmin && (
              <button 
                onClick={() => setView('role_select')}
                className="fixed bottom-24 right-4 z-[200] bg-indigo-600 text-white px-4 py-2 rounded-full shadow-2xl font-bold text-[10px] uppercase tracking-widest hover:bg-indigo-700 transition-all flex items-center gap-2 border border-white/20"
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7h12m0 0l-4-4m4 4l-4 4m0 6H4m0 0l4 4m-4-4l4-4" /></svg>
                Switch Workspace
              </button>
            )}
            <ChatDashboard 
              currentUser={user} 
              toggleDarkMode={() => setDarkMode(!darkMode)} 
              isDarkMode={darkMode}
            />
          </div>
        )}
      </div>
    </ErrorBoundary>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { User, Chat, Message, PollData } from '../../types';
import { MessageBubble } from './MessageBubble';
import { GroupInfoModal } from './GroupInfoModal';
import { MediaViewer } from './MediaViewer';
import { getAIResponse } from '../../gemini';
import { 
  getUserById, 
  addMessage, 
  getMessages, 
  toggleChatLock, 
  editMessage, 
  subscribeToChat, 
  deleteMessageForEveryone, 
  deleteMessageForMe, 
  subscribeToUser, 
  togglePinMessage, 
  setTypingStatus,
  getMyChats,
  getAllUsers
} from '../../firebase';

interface ChatWindowProps {
  chat: Chat;
  currentUser: User;
  onClose: () => void;
  onUserClick: (user: User) => void;
  onCallStart?: (user: User, type: 'voice' | 'video') => void;
}

const STICKERS = [
    'https://cdn-icons-png.flaticon.com/512/742/742751.png',
    'https://cdn-icons-png.flaticon.com/512/742/742752.png',
    'https://cdn-icons-png.flaticon.com/512/742/742923.png',
    'https://cdn-icons-png.flaticon.com/512/742/742823.png',
    'https://cdn-icons-png.flaticon.com/512/742/742760.png',
    'https://cdn-icons-png.flaticon.com/512/742/742940.png',
    'https://cdn-icons-png.flaticon.com/512/4712/4712109.png',
    'https://cdn-icons-png.flaticon.com/512/4712/4712139.png',
];

const WALLPAPER_CLASSES: Record<string, string> = {
  default: 'bg-slate-50 dark:bg-slate-950',
  indigo: 'bg-indigo-600',
  emerald: 'bg-emerald-700',
  rose: 'bg-rose-500',
  amber: 'bg-amber-500',
  dark: 'bg-black',
  gradient: 'bg-gradient-to-br from-purple-900 via-indigo-900 to-black',
};

const FONT_SIZE_CLASSES: Record<string, string> = {
  small: 'text-[12px]',
  medium: 'text-[14px]',
  large: 'text-[16px]',
};

// Safe constants to prevent regex parsing errors
const ACCEPTED_MEDIA_TYPES = "image/png,image/jpeg,image/gif,video/mp4,video/webm";
const CHAT_BG_PATTERN = "https://www.transparenttextures.com/patterns/asfalt-dark.png";
const AI_TRIGGER = "/ai";
const AI_SENDER_ID = "gemini_ai";

export const ChatWindow: React.FC<ChatWindowProps> = ({ chat, currentUser, onClose, onUserClick, onCallStart }) => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [otherUser, setOtherUser] = useState<User | null>(null);
  const [isLocked, setIsLocked] = useState(chat.lockedBy?.includes(currentUser.uid) || false);
  const [inputText, setInputText] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [typingUsers, setTypingUsers] = useState<string[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [recordingDuration, setRecordingDuration] = useState(0);
  const [mediaRecorder, setMediaRecorder] = useState<MediaRecorder | null>(null);
  const [editingMessage, setEditingMessage] = useState<Message | null>(null);
  const [pinnedMessageIds, setPinnedMessageIds] = useState<string[]>([]);
  const [showGroupInfo, setShowGroupInfo] = useState(false);

  const [isBlockedByMe, setIsBlockedByMe] = useState(false);
  const [isBlockedByThem, setIsBlockedByThem] = useState(false);

  const [messageToDelete, setMessageToDelete] = useState<Message | null>(null);
  const [showDeleteOptions, setShowDeleteOptions] = useState(false);

  const [viewingMedia, setViewingMedia] = useState<Message | null>(null);

  const [showAttachMenu, setShowAttachMenu] = useState(false);
  const [showPollModal, setShowPollModal] = useState(false);
  const [showStickerPicker, setShowStickerPicker] = useState(false);

  const [pollQuestion, setPollQuestion] = useState('');
  const [pollOptions, setPollOptions] = useState(['', '']);

  const [wallpaper, setWallpaper] = useState('default');
  const [customUrl, setCustomUrl] = useState<string | null>(null);
  const [fontSize, setFontSize] = useState('medium');
  const [replyingTo, setReplyingTo] = useState<Message | null>(null);
  const [forwardingMessage, setForwardingMessage] = useState<Message | null>(null);
  const [availableChats, setAvailableChats] = useState<Chat[]>([]);
  const [allUsers, setAllUsers] = useState<User[]>([]);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const typingTimeoutRef = useRef<any>(null);
  const timerRef = useRef<any>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const inputRef = useRef<HTMLInputElement>(null);
  const attachMenuRef = useRef<HTMLDivElement>(null);

  const isGroup = chat.type === 'group';
  const participants = chat.participants || [];
  const otherId = !isGroup && participants.length > 0
    ? (participants.find(p => p !== currentUser.uid) || (participants.includes(currentUser.uid) ? currentUser.uid : '')) 
    : chat.id;

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (attachMenuRef.current && !attachMenuRef.current.contains(event.target as Node)) {
        setShowAttachMenu(false);
      }
    };
    if (showAttachMenu) document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [showAttachMenu]);

  const loadSettings = () => {
    try {
      const saved = localStorage.getItem('roxx_settings');
      if (saved) {
        const parsed = JSON.parse(saved);
        setWallpaper(parsed.wallpaper || 'default');
        setCustomUrl(parsed.customWallpaperUrl || null);
        setFontSize(parsed.fontSize || 'medium');
      }
    } catch (e) {
      console.warn("Settings corrupted, resetting");
      localStorage.removeItem('roxx_settings');
      setWallpaper('default');
    }
  };

  useEffect(() => {
    loadSettings();
    window.addEventListener('roxx_settings_updated', loadSettings);
    return () => window.removeEventListener('roxx_settings_updated', loadSettings);
  }, []);

  useEffect(() => {
    const unsubscribe = subscribeToChat(chat.id, (data) => {
      if (data.typing) {
        const activeTypers = Object.entries(data.typing)
          .filter(([uid, isTyping]) => uid !== currentUser.uid && isTyping)
          .map(([uid]) => uid);
        setTypingUsers(activeTypers);
      } else {
        setTypingUsers([]);
      }
      if (data.pinnedMessages) {
        setPinnedMessageIds(data.pinnedMessages);
      } else {
        setPinnedMessageIds([]);
      }
    });
    return () => unsubscribe();
  }, [chat.id, currentUser.uid]);

  useEffect(() => {
    if (isGroup || !otherId) return;

    getUserById(otherId).then(u => { 
        if(u) {
            setOtherUser(u); 
            setIsBlockedByThem(u.blockedUsers?.includes(currentUser.uid) || false);
        }
    });

    setIsBlockedByMe(currentUser.blockedUsers?.includes(otherId) || false);

    const unsubscribe = subscribeToUser(otherId, (userData) => {
        setOtherUser(userData);
        setIsBlockedByThem(userData.blockedUsers?.includes(currentUser.uid) || false);
    });
    return () => unsubscribe();
  }, [otherId, isGroup, currentUser.uid, currentUser.blockedUsers]);

  useEffect(() => {
    const sync = async () => {
      const msgs = await getMessages(chat.id);
      setMessages(prev => {
        if (JSON.stringify(msgs) !== JSON.stringify(prev)) return msgs;
        return prev;
      });
    };
    sync();
    const itv = setInterval(sync, 1500); 
    return () => clearInterval(itv);
  }, [chat.id]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [messages.length, isTyping, replyingTo, editingMessage]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setInputText(e.target.value);
    if (!isTyping) {
      setIsTyping(true);
      setTypingStatus(chat.id, currentUser.uid, true);
    }
    if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
    typingTimeoutRef.current = setTimeout(() => {
      setIsTyping(false);
      setTypingStatus(chat.id, currentUser.uid, false);
    }, 2000);
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      let mimeType = 'audio/webm';
      if (MediaRecorder.isTypeSupported('audio/webm;codecs=opus')) mimeType = 'audio/webm;codecs=opus';
      else if (MediaRecorder.isTypeSupported('audio/mp4')) mimeType = 'audio/mp4';

      const recorder = new MediaRecorder(stream, { mimeType });
      setMediaRecorder(recorder);
      audioChunksRef.current = [];

      recorder.ondataavailable = (e) => {
        if (e.data.size > 0) audioChunksRef.current.push(e.data);
      };

      recorder.start();
      setIsRecording(true);
      setRecordingDuration(0);
      timerRef.current = setInterval(() => setRecordingDuration(p => p + 1), 1000);
    } catch (err) { alert("Microphone access denied."); }
  };

  const stopRecording = async (shouldSend: boolean) => {
    if (mediaRecorder && isRecording) {
      const mimeType = mediaRecorder.mimeType || 'audio/webm';
      mediaRecorder.onstop = async () => {
        if (shouldSend && audioChunksRef.current.length > 0) {
            const blob = new Blob(audioChunksRef.current, { type: mimeType });
            const reader = new FileReader();
            reader.readAsDataURL(blob);
            reader.onloadend = async () => {
                const base64Audio = reader.result as string;
                const msg: Message = {
                    id: 'v_' + Math.random().toString(36).substring(2, 11),
                    senderId: currentUser.uid,
                    recipientId: isGroup ? chat.id : otherId!,
                    text: 'Voice Message',
                    type: 'voice',
                    timestamp: Date.now(),
                    status: 'sent',
                    audioUrl: base64Audio,
                    duration: recordingDuration
                };
                setMessages(prev => [...prev, msg]);
                await addMessage(msg);
            };
        }
        mediaRecorder.stream.getTracks().forEach(track => track.stop());
        setMediaRecorder(null);
        audioChunksRef.current = [];
      };
      mediaRecorder.stop();
      clearInterval(timerRef.current);
      setIsRecording(false);
    }
  };

  const formatDuration = (sec: number) => {
    const m = Math.floor(sec / 60);
    const s = sec % 60;
    return `${m}:${s.toString().padStart(2, '0')}`;
  };

  const triggerDeleteFlow = (msg: Message) => {
      setMessageToDelete(msg);
      setShowDeleteOptions(true);
  };

  const confirmDelete = async (type: 'me' | 'everyone') => {
      if (!messageToDelete) return;
      if (window.confirm(type === 'everyone' ? "Delete for everyone?" : "Delete for me?")) {
          if (type === 'everyone') {
              setMessages(prev => prev.map(m => m.id === messageToDelete.id ? { ...m, type: 'deleted', text: '🚫 This message was deleted' } : m));
              await deleteMessageForEveryone(messageToDelete.id);
          } else {
              setMessages(prev => prev.filter(m => m.id !== messageToDelete.id));
              await deleteMessageForMe(messageToDelete.id, currentUser.uid);
          }
      }
      setShowDeleteOptions(false);
      setMessageToDelete(null);
  };

  const handlePinMessage = async (msg: Message) => {
      await togglePinMessage(chat.id, msg.id);
  };

  const handleEditMessage = (msg: Message) => {
      setEditingMessage(msg);
      setInputText(msg.text);
      inputRef.current?.focus();
  };

  const handleMediaClick = (msg: Message) => {
      setViewingMedia(msg);
  };

  const handleSend = async (e?: React.FormEvent) => {
    e?.preventDefault();
    const text = inputText.trim();
    if (!text) return;

    if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
    setIsTyping(false);
    setTypingStatus(chat.id, currentUser.uid, false);

    if (editingMessage) {
        setMessages(prev => prev.map(m => m.id === editingMessage.id ? { ...m, text: text, isEdited: true } : m));
        await editMessage(editingMessage.id, text);
        setEditingMessage(null);
        setInputText('');
        return;
    }

    const recipient = isGroup ? chat.id : otherId;
    if (!recipient) return;

    if (!isGroup && (isBlockedByMe || isBlockedByThem)) {
        if (isBlockedByMe) {
            if(!window.confirm("You blocked this user. Unblock to send message?")) return;
        }
    }

    let replyContext = undefined;
    if (replyingTo) {
      const sender = await getUserById(replyingTo.senderId);
      replyContext = {
        messageId: replyingTo.id,
        text: replyingTo.text || 'Media',
        senderName: sender?.name || 'User'
      };
    }

    const msg: Message = {
      id: 'm_' + Math.random().toString(36).substring(2, 11),
      senderId: currentUser.uid, 
      recipientId: recipient,
      text, 
      type: 'text', 
      timestamp: Date.now(), 
      status: 'sent',
      replyContext
    };

    setMessages(prev => [...prev, msg]);
    setInputText('');
    setReplyingTo(null);

    await addMessage(msg);

    if (text.toLowerCase().startsWith(AI_TRIGGER)) {
      setTypingUsers(prev => [...prev, AI_SENDER_ID]);
      try {
        const promptText = text.slice(AI_TRIGGER.length).trim(); 
        const res = await getAIResponse(promptText);
        const aiMsg: Message = {
          id: 'ai_' + Date.now(), 
          senderId: AI_SENDER_ID, 
          recipientId: isGroup ? chat.id : currentUser.uid,
          text: res || "I'm thinking...", 
          type: 'text', 
          timestamp: Date.now(), 
          status: 'seen'
        };
        await addMessage(aiMsg);
      } catch (err) { }
      finally { setTypingUsers(prev => prev.filter(id => id !== AI_SENDER_ID)); }
    }
  };

  const handleCreatePoll = async () => {
    if (!pollQuestion.trim() || pollOptions.filter(o => o.trim()).length < 2) return;

    const poll: PollData = {
        question: pollQuestion,
        options: pollOptions.filter(o => o.trim()).map((text, i) => ({
            id: `opt_${i}`,
            text,
            votes: []
        })),
        allowMultiple: false
    };

    const recipient = isGroup ? chat.id : otherId!;
    const msg: Message = {
        id: 'poll_' + Math.random().toString(36).substring(2, 11),
        senderId: currentUser.uid,
        recipientId: recipient,
        text: '📊 Poll',
        type: 'poll',
        timestamp: Date.now(),
        status: 'sent',
        poll
    };

    await addMessage(msg);
    setMessages(prev => [...prev, msg]);
    setShowPollModal(false);
    setPollQuestion('');
    setPollOptions(['', '']);
  };

  const handleSendSticker = async (url: string) => {
    const recipient = isGroup ? chat.id : otherId!;
    const msg: Message = {
        id: 'sticker_' + Math.random().toString(36).substring(2, 11),
        senderId: currentUser.uid,
        recipientId: recipient,
        text: '👾 Sticker',
        type: 'sticker',
        timestamp: Date.now(),
        status: 'sent',
        stickerUrl: url
    };
    await addMessage(msg);
    setMessages(prev => [...prev, msg]);
    setShowStickerPicker(false);
  };

  const handleForward = async (targetChat: Chat) => {
    if (!forwardingMessage) return;
    const targetParticipants = targetChat.participants || [];
    const targetId = targetChat.type === 'group' ? targetChat.id : targetParticipants.find(p => p !== currentUser.uid)!;
    const { replyContext, ...msgContent } = forwardingMessage;
    const forwardMsg: Message = {
      ...msgContent,
      id: 'fwd_' + Math.random().toString(36).substring(2, 11),
      senderId: currentUser.uid,
      recipientId: targetId,
      timestamp: Date.now(),
      status: 'sent',
      isForwarded: true
    };
    await addMessage(forwardMsg);
    setForwardingMessage(null);
    alert(`Forwarded to ${targetChat.name || 'Contact'}`);
  };

  const openForwardModal = async (msg: Message) => {
    setForwardingMessage(msg);
    const chats = await getMyChats(currentUser.uid);
    const users = await getAllUsers();
    setAvailableChats(chats);
    setAllUsers(users);
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const recipient = isGroup ? chat.id : otherId;
    if (!recipient) return;

    setIsUploading(true);
    const reader = new FileReader();
    reader.onload = async (event) => {
      const fileUrl = event.target?.result as string;
      let messageType: any = 'file';
      if (file.type.startsWith('image/')) messageType = 'image';
      else if (file.type.startsWith('video/')) messageType = 'video';
      const msg: Message = {
        id: 'f_' + Math.random().toString(36).substring(2, 11), 
        senderId: currentUser.uid,
        recipientId: recipient, 
        text: file.name, 
        type: messageType,
        timestamp: Date.now(), 
        status: 'sent', 
        fileUrl, 
        fileName: file.name
      };
      setMessages(prev => [...prev, msg]);
      await addMessage(msg);
      setIsUploading(false);
    };
    reader.readAsDataURL(file);
    e.target.value = '';
    setShowAttachMenu(false);
  };

  const handleHeaderClick = () => {
    if (isGroup) {
      setShowGroupInfo(true);
    } else {
      onUserClick(otherUser || {} as User);
    }
  };

  const renderDateSeparator = (timestamp: number, prevTimestamp?: number) => {
    if (!timestamp) return null;
    const date = new Date(timestamp);
    if (isNaN(date.getTime())) return null;

    const dateStr = date.toDateString();
    const prevDateStr = prevTimestamp ? new Date(prevTimestamp).toDateString() : null;

    if (dateStr !== prevDateStr) {
      return (
        <div className="flex justify-center my-6 sticky top-2 z-10">
          <div className="px-4 py-1.5 bg-slate-900/10 dark:bg-white/10 backdrop-blur-md border border-white/20 rounded-full shadow-sm">
            <span className="text-[10px] font-black uppercase tracking-widest text-slate-500 dark:text-slate-300">
              {date.toLocaleDateString(undefined, { weekday: 'long', month: 'short', day: 'numeric' })}
            </span>
          </div>
        </div>
      );
    }
    return null;
  };

  const isOnline = otherUser?.status === 'online' && (Date.now() - (otherUser.lastSeen || 0) < 3 * 60 * 1000);
  const canSeeStatus = isGroup || (!isBlockedByThem && otherUser?.privacySettings?.lastSeen !== 'nobody');

  const statusColor = !isGroup && isOnline && canSeeStatus ? 'text-green-500' : 'text-slate-500 dark:text-slate-400';
  const statusText = !isGroup && canSeeStatus ? (isOnline ? 'Online Now' : 'Offline') : '';

  const displayPhoto = (!isGroup && isBlockedByThem) 
    ? 'https://ui-avatars.com/api/?name=User&background=random' 
    : (isGroup ? (chat.groupIcon || `https://picsum.photos/seed/${chat.id}/200`) : otherUser?.photoURL);

  const latestPinnedId = pinnedMessageIds[pinnedMessageIds.length - 1];
  const pinnedMessage = messages.find(m => m.id === latestPinnedId);

  return (
    <div className={`flex-1 flex flex-col h-full bg-white dark:bg-slate-900 animate-in fade-in duration-300 relative overflow-hidden ${FONT_SIZE_CLASSES[fontSize]}`}>
      <div className={`absolute inset-0 z-0 transition-all duration-700 ${wallpaper !== 'custom' ? WALLPAPER_CLASSES[wallpaper] || '' : ''}`}>
        {wallpaper === 'custom' && customUrl && <img src={customUrl} className="absolute inset-0 w-full h-full object-cover" alt="" /> }
        <div className="absolute inset-0 opacity-[0.03] pointer-events-none" style={{ backgroundImage: `url('${CHAT_BG_PATTERN}')` }}></div>
      </div>

      <div className="p-3 md:p-4 flex items-center justify-between bg-white/90 dark:bg-slate-900/90 backdrop-blur-sm z-10 border-b border-slate-200 dark:border-slate-800 shadow-sm relative">
        <div className="flex items-center gap-3">
          <button onClick={onClose} className="lg:hidden p-2 rounded-xl hover:bg-slate-200 dark:hover:bg-slate-800"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 19l-7-7 7-7" /></svg></button>
          <div className="relative cursor-pointer group" onClick={handleHeaderClick}>
            <img src={displayPhoto} className="w-10 h-10 rounded-full object-cover border border-slate-200 dark:border-slate-700 group-hover:scale-105 transition-transform" alt="" />
            {!isGroup && isOnline && canSeeStatus && <div className="absolute -bottom-0.5 -right-0.5 w-3.5 h-3.5 bg-green-500 rounded-full border-2 border-white dark:border-slate-900 animate-pulse"></div>}
          </div>
          <div className="min-w-0 cursor-pointer" onClick={handleHeaderClick}>
            <h3 className="font-bold text-sm leading-none flex items-center gap-1.5 truncate text-slate-900 dark:text-white">
              {isGroup ? chat.name : (otherUser?.name || 'Loading...')}
              {isLocked && <svg className="w-3.5 h-3.5 text-indigo-500" fill="currentColor" viewBox="0 0 24 24"><path d="M12 17c1.1 0 2-.9 2-2s-.9-2-2-2-2 .9-2 2 .9 2 2 2zm6-9h-1V6c0-2.76-2.24-5-5-5S7 3.24 7 6v2H6c-1.1 0-2 .9-2 2v10c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V10c0-1.1-.9-2-2-2zm-6-5c1.66 0 3 1.34 3 3v2H9V6c0-1.66 1.34-3 3-3z"/></svg>}
            </h3>
            {typingUsers.length > 0 ? (
               <span className="text-[10px] text-indigo-500 font-bold uppercase tracking-widest mt-0.5 animate-pulse flex items-center gap-1">
                  <div className="flex gap-0.5">
                    <span className="w-1 h-1 bg-indigo-500 rounded-full animate-bounce"></span>
                    <span className="w-1 h-1 bg-indigo-500 rounded-full animate-bounce [animation-delay:0.1s]"></span>
                    <span className="w-1 h-1 bg-indigo-500 rounded-full animate-bounce [animation-delay:0.2s]"></span>
                  </div>
                  {isGroup ? `${typingUsers.length} typing...` : typingUsers.includes(AI_SENDER_ID) ? 'AI thinking...' : 'Typing...'}
               </span>
            ) : (
               <span className={`text-[10px] font-bold uppercase tracking-widest mt-0.5 ${statusColor}`}>
                  {isGroup ? `${chat.participants?.length || 0} members` : statusText}
               </span>
            )}
          </div>
        </div>
        <div className="flex items-center gap-2">
          {!isGroup && otherUser && !isBlockedByThem && !isBlockedByMe && (
            <>
              <button onClick={() => onCallStart?.(otherUser, 'voice')} className="p-2.5 hover:bg-slate-200 dark:hover:bg-slate-800 text-slate-600 dark:text-slate-300 rounded-xl transition-colors"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z" /></svg></button>
              <button onClick={() => onCallStart?.(otherUser, 'video')} className="p-2.5 hover:bg-slate-200 dark:hover:bg-slate-800 text-slate-600 dark:text-slate-300 rounded-xl transition-colors"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg></button>
            </>
          )}
          <button onClick={async () => { await toggleChatLock(chat.id, currentUser.uid); setIsLocked(!isLocked); }} className={`p-2.5 rounded-xl transition-all ${isLocked ? 'bg-indigo-500 text-white shadow-lg' : 'hover:bg-slate-200 dark:hover:bg-slate-800 text-slate-400'}`}><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg></button>
        </div>
      </div>

      {pinnedMessage && (
        <div 
            onClick={() => {
                const el = document.getElementById(`msg-${pinnedMessage.id}`);
                el?.scrollIntoView({ behavior: 'smooth', block: 'center' });
                el?.classList.add('bg-indigo-100', 'dark:bg-indigo-900');
                setTimeout(() => el?.classList.remove('bg-indigo-100', 'dark:bg-indigo-900'), 1000);
            }}
            className="absolute top-[4.5rem] left-4 right-4 z-20 bg-white/95 dark:bg-slate-800/95 backdrop-blur-md rounded-xl p-3 border-l-4 border-indigo-500 shadow-lg flex items-center justify-between cursor-pointer animate-in slide-in-from-top-2"
        >
            <div className="min-w-0">
                <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest mb-0.5">Pinned Message</p>
                <p className="text-xs text-slate-600 dark:text-slate-300 truncate font-medium">{pinnedMessage.text || 'Media File'}</p>
            </div>
            <button 
                onClick={(e) => { e.stopPropagation(); togglePinMessage(chat.id, pinnedMessage.id); }}
                className="p-2 text-slate-400 hover:text-indigo-500 transition-colors"
            >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
            </button>
        </div>
      )}

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-1 scroll-smooth z-[5] no-scrollbar">
        {messages.map((msg, index) => (
          <React.Fragment key={msg.id || index}>
            {renderDateSeparator(msg.timestamp, messages[index-1]?.timestamp)}
            <MessageBubble 
              message={msg} 
              isOwn={msg.senderId === currentUser.uid} 
              isAI={msg.senderId === AI_SENDER_ID} 
              onReply={setReplyingTo} 
              onForward={openForwardModal}
              onDelete={triggerDeleteFlow}
              onEdit={handleEditMessage}
              onPin={handlePinMessage}
              isPinned={pinnedMessageIds.includes(msg.id)}
              onMediaClick={handleMediaClick}
            />
          </React.Fragment>
        ))}
        {typingUsers.length > 0 && (
          <div className="flex items-end gap-2 px-2 py-2 animate-in slide-in-from-left-4 fade-in duration-300">
             {!isGroup && <img src={displayPhoto} className="w-8 h-8 rounded-full border border-white dark:border-slate-800" alt="" />}
             <div className="bg-white dark:bg-slate-800 rounded-2xl rounded-bl-none px-4 py-3 flex items-center gap-1.5 shadow-sm border border-slate-100 dark:border-slate-700">
                <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce"></div>
             </div>
          </div>
        )}
      </div>

      <div className="bg-white/95 dark:bg-slate-900/95 backdrop-blur-sm border-t border-slate-200 dark:border-slate-800 z-10 flex flex-col">
        {editingMessage && (
             <div className="px-4 py-2 bg-indigo-50 dark:bg-indigo-900/20 border-l-4 border-indigo-500 flex items-center justify-between">
                <div>
                    <span className="text-xs font-bold text-indigo-500 uppercase tracking-widest">Editing Message</span>
                    <p className="text-xs text-slate-500 dark:text-slate-400 line-clamp-1">{editingMessage.text}</p>
                </div>
                <button onClick={() => { setEditingMessage(null); setInputText(''); }} className="p-1 text-indigo-500 hover:bg-indigo-100 rounded-full">
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
             </div>
        )}
        {replyingTo && (
          <div className="px-4 py-2 bg-slate-50 dark:bg-slate-800/80 border-l-4 border-indigo-500 flex items-center justify-between">
             <div className="min-w-0">
                <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest mb-0.5">Replying to {replyingTo.senderId === currentUser.uid ? 'Yourself' : 'Contact'}</p>
                <p className="text-xs text-slate-500 truncate">{replyingTo.text || 'Media Message'}</p>
             </div>
             <button onClick={() => setReplyingTo(null)} className="p-1.5 text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-full">
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
             </button>
          </div>
        )}

        {(!isGroup && (isBlockedByMe || isBlockedByThem)) ? (
            <div className="p-4 bg-slate-50 dark:bg-slate-800 text-center">
                <p className="text-sm font-medium text-slate-500">
                    {isBlockedByMe ? "You have blocked this contact." : "You cannot message this contact."}
                </p>
            </div>
        ) : (
            <div className="p-3 md:p-4 flex gap-2.5 items-center relative">
            {isRecording ? (
                <div className="flex-1 flex items-center justify-between bg-red-500 text-white rounded-[1.5rem] px-6 py-4 animate-pulse">
                    <div className="flex items-center gap-3">
                    <div className="w-3 h-3 bg-white rounded-full animate-bounce"></div>
                    <span className="font-bold text-sm tracking-widest">{formatDuration(recordingDuration)}</span>
                    </div>
                    <div className="flex items-center gap-3">
                        <button onClick={() => stopRecording(false)} className="text-white/80 hover:text-white text-xs font-bold uppercase">Cancel</button>
                        <button onClick={() => stopRecording(true)} className="p-2 bg-white text-red-500 rounded-full shadow-lg">
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M5 13l4 4L19 7" /></svg>
                        </button>
                    </div>
                </div>
            ) : (
                <>
                <div className="relative" ref={attachMenuRef}>
                    <button onClick={() => setShowAttachMenu(!showAttachMenu)} className="p-3.5 text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-2xl shrink-0 transition-colors active:scale-90 bg-slate-50 dark:bg-slate-800/50">
                        <svg className={`w-6 h-6 transition-transform ${showAttachMenu ? 'rotate-45' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 4v16m8-8H4" /></svg>
                    </button>
                    {showAttachMenu && (
                        <div className="absolute bottom-full left-0 mb-3 bg-white dark:bg-slate-900 rounded-2xl shadow-xl border border-slate-100 dark:border-slate-800 p-2 flex flex-col gap-1 min-w-[160px] animate-in slide-in-from-bottom-2 fade-in duration-200 z-50">
                            <button onClick={() => fileInputRef.current?.click()} className="flex items-center gap-3 px-4 py-3 hover:bg-slate-50 dark:hover:bg-slate-800 rounded-xl text-sm font-bold text-slate-600 dark:text-slate-300">
                                <svg className="w-5 h-5 text-green-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                                Photos & Video
                            </button>
                            <button onClick={() => { setShowPollModal(true); setShowAttachMenu(false); }} className="flex items-center gap-3 px-4 py-3 hover:bg-slate-50 dark:hover:bg-slate-800 rounded-xl text-sm font-bold text-slate-600 dark:text-slate-300">
                                <svg className="w-5 h-5 text-orange-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" /></svg>
                                Create Poll
                            </button>
                            <button onClick={() => { setShowStickerPicker(true); setShowAttachMenu(false); }} className="flex items-center gap-3 px-4 py-3 hover:bg-slate-50 dark:hover:bg-slate-800 rounded-xl text-sm font-bold text-slate-600 dark:text-slate-300">
                                <svg className="w-5 h-5 text-pink-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M14.828 14.828a4 4 0 01-5.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                                Stickers
                            </button>
                        </div>
                    )}
                </div>
                <input type="file" ref={fileInputRef} onChange={handleFileChange} accept={ACCEPTED_MEDIA_TYPES} className="hidden" />

                <form onSubmit={handleSend} className="flex-1 flex gap-2">
                    <input 
                        ref={inputRef}
                        type="text" 
                        value={inputText} 
                        onChange={handleInputChange} 
                        placeholder="Type a message..." 
                        className="flex-1 bg-slate-50 dark:bg-slate-800/80 rounded-[1.5rem] px-6 py-4 text-sm font-medium outline-none border border-slate-200 dark:border-slate-700 focus:ring-2 focus:ring-indigo-500/20 transition-all shadow-inner text-slate-900 dark:text-white" 
                    />
                    {inputText.trim() ? (
                        <button type="submit" className="p-4 bg-indigo-500 text-white rounded-2xl shadow-xl shadow-indigo-500/20 transition-all shrink-0 active:scale-95">
                            {editingMessage ? (
                                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M5 13l4 4L19 7" /></svg>
                            ) : (
                                <svg className="w-6 h-6 rotate-90" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
                            )}
                        </button>
                    ) : (
                        <button type="button" onClick={startRecording} className="p-4 bg-slate-100 dark:bg-slate-800 text-slate-500 hover:bg-red-500 hover:text-white rounded-2xl transition-all shrink-0 active:scale-95 group">
                            <svg className="w-6 h-6 group-hover:scale-110 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
                        </button>
                    )}
                </form>
                </>
            )}
        </div>
      </div>

      {showGroupInfo && (
        <GroupInfoModal 
          chat={chat}
          currentUser={currentUser}
          onClose={() => setShowGroupInfo(false)}
        />
      )}

      {viewingMedia && (
        <MediaViewer 
           message={viewingMedia}
           currentUser={currentUser}
           onClose={() => setViewingMedia(null)}
           onForward={openForwardModal}
           onReply={(msg) => setReplyingTo(msg)}
        />
      )}

      {showPollModal && (
        <div className="fixed inset-0 z-[250] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in">
            <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] w-full max-w-md p-6 shadow-2xl">
                <h3 className="text-xl font-black mb-6 dark:text-white">Create Poll</h3>
                <input 
                    type="text" 
                    placeholder="Ask a question..." 
                    value={pollQuestion}
                    onChange={(e) => setPollQuestion(e.target.value)}
                    className="w-full bg-slate-100 dark:bg-slate-800 rounded-xl px-4 py-3 font-bold mb-4 outline-none focus:ring-2 focus:ring-indigo-500/50 dark:text-white"
                />
                <div className="space-y-2 mb-6 max-h-60 overflow-y-auto no-scrollbar">
                    {pollOptions.map((opt, i) => (
                        <input 
                            key={i}
                            type="text"
                            placeholder={`Option ${i + 1}`}
                            value={opt}
                            onChange={(e) => {
                                const newOpts = [...pollOptions];
                                newOpts[i] = e.target.value;
                                setPollOptions(newOpts);
                            }}
                            className="w-full bg-slate-50 dark:bg-slate-800/50 rounded-xl px-4 py-3 text-sm outline-none border border-transparent focus:border-indigo-500 dark:text-white"
                        />
                    ))}
                    <button 
                        onClick={() => setPollOptions([...pollOptions, ''])}
                        className="text-xs font-bold text-indigo-500 hover:text-indigo-600 uppercase tracking-widest px-2"
                    >
                        + Add Option
                    </button>
                </div>
                <div className="flex gap-3">
                    <button onClick={() => setShowPollModal(false)} className="flex-1 py-3 rounded-xl font-bold text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800">Cancel</button>
                    <button onClick={handleCreatePoll} className="flex-1 py-3 bg-indigo-500 text-white rounded-xl font-bold shadow-lg shadow-indigo-500/30">Create Poll</button>
                </div>
            </div>
        </div>
      )}

      {showStickerPicker && (
        <div className="fixed inset-0 z-[250] flex flex-col justify-end">
            <div className="absolute inset-0 bg-black/20" onClick={() => setShowStickerPicker(false)}></div>
            <div className="bg-white dark:bg-slate-900 rounded-t-[2.5rem] p-6 shadow-2xl animate-in slide-in-from-bottom h-1/2 flex flex-col relative z-10">
                <div className="w-12 h-1.5 bg-slate-200 dark:bg-slate-700 rounded-full mx-auto mb-6"></div>
                <h3 className="text-lg font-black mb-4 dark:text-white">Stickers</h3>
                <div className="flex-1 overflow-y-auto grid grid-cols-4 gap-4 p-2">
                    {STICKERS.map((url, i) => (
                        <button key={i} onClick={() => handleSendSticker(url)} className="aspect-square hover:scale-110 transition-transform p-2 bg-slate-50 dark:bg-slate-800/50 rounded-2xl">
                            <img src={url} alt="Sticker" className="w-full h-full object-contain" />
                        </button>
                    ))}
                </div>
            </div>
        </div>
      )}

      {showDeleteOptions && messageToDelete && (
        <div className="fixed inset-0 z-[200] flex items-end justify-center sm:items-center">
            <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setShowDeleteOptions(false)}></div>
            <div className="relative w-full max-w-sm bg-white dark:bg-slate-900 rounded-t-[2rem] sm:rounded-[2rem] p-6 shadow-2xl animate-in slide-in-from-bottom duration-300">
                <div className="w-12 h-1.5 bg-slate-200 dark:bg-slate-700 rounded-full mx-auto mb-6"></div>
                <h3 className="text-lg font-bold mb-4 text-center dark:text-white">Delete Message?</h3>

                <div className="flex flex-col gap-3">
                    {messageToDelete.senderId === currentUser.uid && (
                        <button 
                            onClick={() => confirmDelete('everyone')}
                            className="w-full p-4 rounded-2xl bg-slate-100 dark:bg-slate-800 text-red-500 font-bold hover:bg-red-50 dark:hover:bg-red-900/10 transition-colors flex items-center justify-between group"
                        >
                            <span>Delete for everyone</span>
                            <svg className="w-5 h-5 opacity-0 group-hover:opacity-100 transition-opacity" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                        </button>
                    )}
                    <button 
                        onClick={() => confirmDelete('me')}
                        className="w-full p-4 rounded-2xl bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-200 font-bold hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors flex items-center justify-between"
                    >
                        <span>Delete for me</span>
                        <svg className="w-5 h-5 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" /></svg>
                    </button>
                    <button 
                        onClick={() => setShowDeleteOptions(false)}
