import React, { useState, useEffect } from 'react';

interface LockScreenProps {
  storedPin: string;
  onUnlock: () => void;
}

export const LockScreen: React.FC<LockScreenProps> = ({ storedPin, onUnlock }) => {
  const [pin, setPin] = useState('');
  const [error, setError] = useState(false);

  useEffect(() => {
    if (pin.length === storedPin.length) {
      if (pin === storedPin) {
        onUnlock();
      } else {
        setError(true);
        setTimeout(() => {
          setPin('');
          setError(false);
        }, 500);
      }
    }
  }, [pin, storedPin, onUnlock]);

  const handlePress = (num: string) => {
    if (pin.length < storedPin.length) {
      setPin(prev => prev + num);
    }
  };

  const handleDelete = () => {
    setPin(prev => prev.slice(0, -1));
  };

  return (
    <div className="fixed inset-0 z-[9999] bg-slate-900 flex flex-col items-center justify-center text-white">
      <div className="mb-10 text-center">
        <div className="w-20 h-20 bg-indigo-500 rounded-3xl mx-auto mb-6 flex items-center justify-center shadow-lg shadow-indigo-500/20">
          <svg className="w-10 h-10 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg>
        </div>
        <h2 className="text-2xl font-bold">App Locked</h2>
        <p className="text-slate-400 text-sm mt-2">Enter your PIN to continue</p>
      </div>

      <div className="flex gap-4 mb-10">
        {Array.from({ length: storedPin.length }).map((_, i) => (
          <div 
            key={i} 
            className={`w-4 h-4 rounded-full transition-all duration-200 ${i < pin.length ? 'bg-indigo-500 scale-110' : 'bg-slate-700'} ${error ? 'bg-red-500 animate-pulse' : ''}`}
          />
        ))}
      </div>

      <div className="grid grid-cols-3 gap-6">
        {[1, 2, 3, 4, 5, 6, 7, 8, 9].map(num => (
          <button 
            key={num} 
            onClick={() => handlePress(num.toString())}
            className="w-20 h-20 rounded-full bg-slate-800 hover:bg-slate-700 text-2xl font-bold transition-all active:scale-95"
          >
            {num}
          </button>
        ))}
        <div className="w-20 h-20"></div>
        <button 
          onClick={() => handlePress('0')}
          className="w-20 h-20 rounded-full bg-slate-800 hover:bg-slate-700 text-2xl font-bold transition-all active:scale-95"
        >
          0
        </button>
        <button 
          onClick={handleDelete}
          className="w-20 h-20 rounded-full flex items-center justify-center hover:bg-slate-800/50 text-slate-400 transition-all active:scale-95"
        >
          <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 14l9-5-9-5-9 5 9 5zm0 0l6.16-3.422a12.083 12.083 0 01.665 6.479A11.952 11.952 0 0012 20.055a11.952 11.952 0 00-6.824-2.998 12.078 12.078 0 01.665-6.479L12 14zm-4 6v-7.5l4-2.222" /></svg>
          <span className="sr-only">Delete</span>
        </button>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User, Chat, Story, CallSession } from '../../types';
import { Sidebar } from './Sidebar';
import { ChatWindow } from './ChatWindow';
import { ProfilePanel } from './ProfilePanel';
import { StoryUpload } from './StoryUpload';
import { StoryViewer } from './StoryViewer';
import { PublicProfile } from './PublicProfile';
import { CallModal } from './CallModal';
import { StatusView } from './StatusView';
import { BottomNav } from './BottomNav';
import { initiateCall, getIncomingCall, getUserById, updateCallStatus, cleanOldCalls, subscribeToNicknames } from '../../firebase';

interface ChatDashboardProps {
  currentUser: User;
  toggleDarkMode: () => void;
  isDarkMode: boolean;
}

export type NavTab = 'chats' | 'status' | 'profile';

export const ChatDashboard: React.FC<ChatDashboardProps> = ({ currentUser, toggleDarkMode, isDarkMode }) => {
  const [activeTab, setActiveTab] = useState<NavTab>('chats');
  const [selectedChat, setSelectedChat] = useState<Chat | null>(null);
  const [showStoryUpload, setShowStoryUpload] = useState(false);
  const [viewingStories, setViewingStories] = useState<Story[] | null>(null);
  const [viewingUser, setViewingUser] = useState<User | null>(null);
  const [activeCall, setActiveCall] = useState<CallSession | null>(null);

  // Feature 3: Nicknames
  const [nicknames, setNicknames] = useState<Record<string, string>>({});

  useEffect(() => {
    const unsub = subscribeToNicknames(currentUser.uid, (data) => {
      setNicknames(data);
    });
    return () => unsub();
  }, [currentUser.uid]);

  // Poll for incoming calls
  useEffect(() => {
    const poll = async () => {
      cleanOldCalls();
      if (activeCall) return; 

      const incoming = await getIncomingCall(currentUser.uid);
      if (incoming) {
        const caller = await getUserById(incoming.callerId);
        if (caller) {
          setActiveCall({
            id: incoming.id,
            partner: caller,
            type: incoming.type,
            callerId: incoming.callerId,
            receiverId: incoming.receiverId,
            status: incoming.status,
            isIncoming: true,
            timestamp: incoming.timestamp
          });
        }
      }
    };

    const itv = setInterval(poll, 3000);
    return () => clearInterval(itv);
  }, [currentUser.uid, activeCall]);

  const startCall = async (user: User, type: 'voice' | 'video') => {
    const call = await initiateCall(currentUser.uid, user.uid, type);
    setActiveCall({ 
      id: call.id,
      partner: user, 
      type, 
      callerId: currentUser.uid,
      receiverId: user.uid,
      status: 'ringing',
      isIncoming: false,
      timestamp: call.timestamp
    });
  };

  const handleCallEnd = async () => {
    if (activeCall) {
      await updateCallStatus(activeCall.id, 'ended');
      setActiveCall(null);
    }
  };

  const renderActiveView = () => {
    switch (activeTab) {
      case 'status':
        return (
          <StatusView 
            currentUser={currentUser}
            onStoryUpload={() => setShowStoryUpload(true)}
            onStoryView={setViewingStories}
            onChatSelect={(chat) => {
              setSelectedChat(chat);
              setActiveTab('chats');
            }}
          />
        );
      case 'profile':
        return (
          <ProfilePanel 
            user={currentUser} 
            onClose={() => setActiveTab('chats')} 
            toggleDarkMode={toggleDarkMode}
            isDarkMode={isDarkMode}
            isTabMode={true}
          />
        );
      case 'chats':
      default:
        return (
          <Sidebar 
            currentUser={currentUser} 
            onChatSelect={setSelectedChat} 
            activeChatId={selectedChat?.id}
            nicknames={nicknames}
          />
        );
    }
  };

  return (
    <div className="flex h-[100dvh] w-full bg-slate-50 dark:bg-slate-950 transition-colors duration-300 overflow-hidden">
      {/* Sidebar/Main Navigation Area */}
      <div className={`${selectedChat ? 'hidden lg:flex' : 'flex'} w-full lg:w-96 h-full shrink-0 border-r border-slate-200 dark:border-slate-800 shadow-xl z-20 flex-col bg-white dark:bg-slate-900`}>
        <div className="flex-1 overflow-hidden flex flex-col relative">
          {renderActiveView()}
        </div>
        <BottomNav activeTab={activeTab} onTabChange={setActiveTab} />
      </div>

      {/* Main Chat Area */}
      <div className={`${!selectedChat ? 'hidden lg:flex' : 'flex'} flex-1 h-full relative overflow-hidden bg-slate-100/30 dark:bg-slate-900/40`}>
        {selectedChat ? (
          <ChatWindow 
            chat={selectedChat} 
            currentUser={currentUser} 
            onClose={() => setSelectedChat(null)}
            onUserClick={setViewingUser}
            onCallStart={startCall}
            nicknames={nicknames}
          />
        ) : (
          <div className="hidden lg:flex flex-1 flex-col items-center justify-center p-8 text-center h-full relative">
            <div className="absolute inset-0 opacity-5 dark:opacity-[0.02] pointer-events-none overflow-hidden">
                <svg className="w-full h-full" viewBox="0 0 100 100" preserveAspectRatio="none">
                    <path d="M0,0 L100,100 M100,0 L0,100" stroke="currentColor" strokeWidth="0.1" fill="none" />
                </svg>
            </div>
            <div className="w-32 h-32 bg-indigo-500/10 dark:bg-indigo-500/5 rounded-full flex items-center justify-center mb-8 animate-float">
              <svg className="w-16 h-16 text-indigo-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.2" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z" />
              </svg>
            </div>
            <h2 className="text-3xl font-extrabold mb-3 bg-clip-text text-transparent bg-gradient-to-r from-indigo-500 to-purple-600">Connect instantly.</h2>
            <p className="text-slate-500 dark:text-slate-400 max-w-sm text-lg font-medium leading-relaxed">
              Select a conversation to start chatting, or explore recent stories from your contacts.
            </p>
          </div>
        )}
      </div>

      {/* Overlays */}
      {showStoryUpload && (
        <StoryUpload 
          currentUser={currentUser} 
          onClose={() => setShowStoryUpload(false)} 
        />
      )}

      {viewingStories && (
        <StoryViewer 
          stories={viewingStories} 
          currentUser={currentUser}
          onClose={() => setViewingStories(null)} 
        />
      )}

      {viewingUser && (
        <PublicProfile 
          user={viewingUser} 
          onClose={() => setViewingUser(null)} 
          onCallStart={startCall}
          nickname={nicknames[viewingUser.uid]}
        />
      )}

      {activeCall && (
        <CallModal 
          session={activeCall}
          onHangUp={handleCallEnd} 
        />
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { User, Chat } from '../../types';
import { getAllUsers, getMyChats, togglePinChat, subscribeToUser } from '../../firebase';
import { CreateGroupModal } from './CreateGroupModal';
import { AppGallery } from './AppGallery';
import { AccountSwitchModal } from './AccountSwitchModal';

interface SidebarProps {
  currentUser: User;
  onChatSelect: (chat: Chat) => void;
  activeChatId?: string;
  nicknames: Record<string, string>; // Feature 3
}

export const Sidebar: React.FC<SidebarProps> = ({ 
  currentUser, onChatSelect, activeChatId, nicknames
}) => {
  const [search, setSearch] = useState('');
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [chats, setChats] = useState<Chat[]>([]);
  const [showGroupModal, setShowGroupModal] = useState(false);
  const [pinnedChats, setPinnedChats] = useState<string[]>([]);

  // Menu States
  const [showMenu, setShowMenu] = useState(false);
  const [showGallery, setShowGallery] = useState(false);
  const [showAccountSwitch, setShowAccountSwitch] = useState(false);

  const searchInputRef = useRef<HTMLInputElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setShowMenu(false);
      }
    };
    if (showMenu) document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [showMenu]);

  useEffect(() => {
    const unsub = subscribeToUser(currentUser.uid, (data) => {
        setPinnedChats(data.pinnedChats || []);
    });

    const sync = async () => {
      const users = await getAllUsers();
      const myBlocked = currentUser.blockedUsers || [];
      setAllUsers(users.filter(u => u.uid !== currentUser.uid && !myBlocked.includes(u.uid)));
      const myChats = await getMyChats(currentUser.uid);
      setChats(myChats);
    };
    sync();
    const itv = setInterval(sync, 2000);
    return () => {
        clearInterval(itv);
        unsub();
    };
  }, [currentUser]);

  useEffect(() => {
    if (isSearchOpen && searchInputRef.current) {
        searchInputRef.current.focus();
    }
    if (!isSearchOpen) {
        setSearch('');
    }
  }, [isSearchOpen]);

  const isRevealingLocked = currentUser.chatLockPassword && search === currentUser.chatLockPassword;

  const isUserOnline = (u: User | undefined) => {
    if (!u) return false;
    if (u.privacySettings?.lastSeen === 'nobody') return false;
    if (u.status !== 'online') return false;
    const timeDiff = Date.now() - (u.lastSeen || 0);
    return timeDiff < 3 * 60 * 1000;
  };

  const handlePinChat = async (e: React.MouseEvent, chatId: string) => {
    e.stopPropagation();
    await togglePinChat(currentUser.uid, chatId);
  };

  const handleSwitchAccountClick = () => {
    setShowMenu(false);
    setShowAccountSwitch(true);
  };

  // Feature 3: Helper to get display name
  const getDisplayName = (user: User | undefined) => {
    if (!user) return 'Unknown';
    return nicknames[user.uid] || user.name;
  };

  const searchResults = useMemo(() => {
    const term = search.toLowerCase().trim();

    let visibleChats = chats.filter(c => {
      const isLocked = c.lockedBy?.includes(currentUser.uid);
      if (isRevealingLocked) return isLocked; 
      return !isLocked;
    });

    visibleChats.sort((a, b) => {
        const isAPinned = pinnedChats.includes(a.id);
        const isBPinned = pinnedChats.includes(b.id);
        if (isAPinned && !isBPinned) return -1;
        if (!isAPinned && isBPinned) return 1;
        return (b.updatedAt || 0) - (a.updatedAt || 0);
    });

    if (!term || isRevealingLocked) return { chats: visibleChats, users: [] };

    // Update search to look through nicknames too
    const matchedUsers = allUsers.filter(u => {
      const display = nicknames[u.uid] || u.name;
      return display.toLowerCase().includes(term);
    });

    const matchedChats = visibleChats.filter(c => {
      if (c.type === 'group') return c.name?.toLowerCase().includes(term);
      const otherId = c.participants.find(p => p !== currentUser.uid);
      const user = allUsers.find(u => u.uid === otherId);
      const display = user ? (nicknames[user.uid] || user.name) : '';
      return display.toLowerCase().includes(term);
    });

    return { chats: matchedChats, users: matchedUsers.filter(u => !chats.some(c => c.type === 'private' && c.participants.includes(u.uid))) };
  }, [search, allUsers, chats, currentUser.uid, isRevealingLocked, pinnedChats, nicknames]);

  const handleStartNewChat = (user: User) => {
    const existing = chats.find(c => c.type === 'private' && c.participants.includes(user.uid));
    if (existing) onChatSelect(existing);
    else onChatSelect({
      id: [currentUser.uid, user.uid].sort().join('_'),
      type: 'private', participants: [currentUser.uid, user.uid],
      updatedAt: Date.now(), lockedBy: []
    });
    setSearch('');
    setIsSearchOpen(false);
  };

  const getChatInfo = (chat: Chat) => {
    if (chat.type === 'group') return { name: chat.name || 'Group', photo: chat.groupIcon || `https://picsum.photos/seed/${chat.id}/200` };
    const otherId = chat.participants.find(p => p !== currentUser.uid);
    const user = allUsers.find(u => u.uid === otherId);

    return { 
        name: getDisplayName(user), 
        photo: user?.photoURL || `https://picsum.photos/seed/${otherId}/200`, 
        status: user?.status, 
        userObj: user 
    };
  };

  return (
    <div className="w-full h-full flex flex-col bg-white dark:bg-slate-900 animate-in slide-in-from-left duration-300 relative border-r border-slate-100 dark:border-slate-800">

      <div className="h-20 px-5 flex items-center justify-between shrink-0 bg-white/80 dark:bg-slate-900/80 backdrop-blur-sm z-10 sticky top-0">
        {isSearchOpen ? (
            <div className="flex-1 flex items-center gap-3 bg-slate-100 dark:bg-slate-800 px-4 py-2 rounded-2xl animate-in fade-in zoom-in-95">
                <svg className="w-5 h-5 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
