import React, { useState, useEffect } from 'react';
import { User, Message } from '../../types';
import { blockUser, unblockUser, auth, getMessages, setNickname } from '../../firebase';

interface PublicProfileProps {
  user: User;
  onClose: () => void;
  onCallStart?: (user: User, type: 'voice' | 'video') => void;
  nickname?: string; // Feature 3
}

export const PublicProfile: React.FC<PublicProfileProps> = ({ user, onClose, onCallStart, nickname: initialNickname }) => {
  const currentUser = auth.currentUser;
  const [isBlocked, setIsBlocked] = useState(currentUser?.blockedUsers?.includes(user.uid) || false);
  const [loading, setLoading] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const [mediaCount, setMediaCount] = useState(0);

  // Nickname State
  const [isEditingNickname, setIsEditingNickname] = useState(false);
  const [nicknameInput, setNicknameInput] = useState(initialNickname || '');

  useEffect(() => {
    const fetchMediaCount = async () => {
      const chatId = [currentUser.uid, user.uid].sort().join('_');
      const msgs = await getMessages(chatId);
      const media = msgs.filter((m: Message) => m.type === 'image' || m.type === 'video');
      setMediaCount(media.length);
    };
    fetchMediaCount();
  }, [user.uid, currentUser.uid]);

  const handleToggleBlock = async () => {
    if (!currentUser) return;
    setLoading(true);
    try {
      if (isBlocked) {
        await unblockUser(currentUser.uid, user.uid);
        setIsBlocked(false);
      } else {
        if (window.confirm(`Are you sure you want to block ${user.name}?`)) {
          await blockUser(currentUser.uid, user.uid);
          setIsBlocked(true);
        }
      }
    } catch (err) {
      alert("Failed to update block status.");
    } finally {
      setLoading(false);
    }
  };

  const handleSaveNickname = async () => {
    if(!currentUser) return;
    await setNickname(currentUser.uid, user.uid, nicknameInput);
    setIsEditingNickname(false);
  };

  return (
    <div className="fixed inset-0 z-[200] flex justify-end">
      <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm lg:backdrop-blur-0 lg:bg-transparent" onClick={onClose}></div>

      <div className="relative w-full lg:max-w-md h-full bg-slate-50 dark:bg-slate-950 shadow-2xl flex flex-col animate-in slide-in-from-right duration-300">

        <div className="h-16 flex items-center px-6 gap-6 bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 shrink-0">
          <button onClick={onClose} className="p-2 -ml-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-all text-slate-600 dark:text-slate-400">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
          <h2 className="text-lg font-bold">Contact Info</h2>
        </div>

        <div className="flex-1 overflow-y-auto no-scrollbar">
          <div className="bg-white dark:bg-slate-900 px-6 py-10 flex flex-col items-center border-b border-slate-200 dark:border-slate-800 shadow-sm">
            <div className="relative group mb-6">
              <img 
                src={user.photoURL} 
                className="w-48 h-48 rounded-full object-cover shadow-xl ring-4 ring-indigo-500/10 cursor-zoom-in transition-transform hover:scale-105" 
                alt={user.name} 
              />
              <div className={`absolute bottom-3 right-3 w-6 h-6 rounded-full border-4 border-white dark:border-slate-900 ${user.status === 'online' ? 'bg-green-500' : 'bg-slate-400'}`}></div>
            </div>

            {/* Nickname / Name Logic */}
            {isEditingNickname ? (
                <div className="flex flex-col items-center gap-2 mb-4 w-full px-8">
                    <input 
                        value={nicknameInput}
                        onChange={(e) => setNicknameInput(e.target.value)}
                        placeholder="Set Nickname"
                        className="w-full text-center bg-slate-100 dark:bg-slate-800 p-2 rounded-xl font-bold"
                        autoFocus
                    />
                    <div className="flex gap-2">
                        <button onClick={() => setIsEditingNickname(false)} className="text-xs font-bold text-slate-400 uppercase">Cancel</button>
                        <button onClick={handleSaveNickname} className="text-xs font-bold text-indigo-500 uppercase">Save</button>
                    </div>
                </div>
            ) : (
                <div className="text-center mb-1 relative group cursor-pointer" onClick={() => setIsEditingNickname(true)}>
                    <h3 className="text-2xl font-black text-slate-900 dark:text-white flex items-center justify-center gap-2">
                        {nicknameInput || user.name}
                        <svg className="w-4 h-4 text-slate-400 opacity-0 group-hover:opacity-100 transition-opacity" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg>
                    </h3>
                    {nicknameInput && <p className="text-xs text-slate-400 font-medium">Original: {user.name}</p>}
                </div>
            )}

            {/* Feature 2: Privacy - Hiding Email, replacing with status */}
            <p className="text-slate-500 dark:text-slate-400 text-sm font-medium mb-8 bg-slate-100 dark:bg-slate-800 px-3 py-1 rounded-full">
                {user.bio || 'App User'}
            </p>

            <div className="flex items-center gap-6">
               <button 
                  onClick={() => onCallStart?.(user, 'voice')}
                  className="flex flex-col items-center gap-2 group"
                >
                  <div className="w-12 h-12 rounded-2xl bg-indigo-50 dark:bg-indigo-900/20 flex items-center justify-center text-indigo-500 group-hover:bg-indigo-500 group-hover:text-white transition-all shadow-sm">
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z" /></svg>
                  </div>
                  <span className="text-[10px] font-black uppercase text-slate-400 dark:text-slate-500">Audio</span>
               </button>
               <button 
                  onClick={() => onCallStart?.(user, 'video')}
                  className="flex flex-col items-center gap-2 group"
                >
                  <div className="w-12 h-12 rounded-2xl bg-indigo-50 dark:bg-indigo-900/20 flex items-center justify-center text-indigo-500 group-hover:bg-indigo-500 group-hover:text-white transition-all shadow-sm">
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
                  </div>
                  <span className="text-[10px] font-black uppercase text-slate-400 dark:text-slate-500">Video</span>
               </button>
            </div>
          </div>

          <div className="mt-3 bg-white dark:bg-slate-900 px-6 py-5 border-y border-slate-200 dark:border-slate-800 shadow-sm">
             <h4 className="text-xs font-bold text-indigo-500 uppercase tracking-widest mb-2">About</h4>
             <p className="text-slate-800 dark:text-slate-100 font-medium leading-relaxed">{user.bio || "No status available"}</p>
             <p className="text-[10px] text-slate-400 font-bold mt-2 uppercase tracking-widest">{new Date(user.lastSeen).toLocaleDateString()}</p>
          </div>

          {/* ... Rest of settings (notifications, etc) ... */}

          <div className="mt-3 bg-white dark:bg-slate-900 border-y border-slate-200 dark:border-slate-800 shadow-sm mb-20">
             <button 
              onClick={handleToggleBlock}
              disabled={loading}
              className="w-full px-6 py-4 flex items-center gap-4 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/10 transition-colors border-b border-slate-100 dark:border-slate-800"
            >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M18.364 18.364A9 9 0 005.636 5.636m12.728 12.728L5.636 5.636" /></svg>
                <span className="font-black text-sm uppercase tracking-widest">{isBlocked ? 'Unblock Contact' : 'Block Contact'}</span>
             </button>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { User, Chat } from '../../types';
import { getUserById, leaveGroup, makeGroupAdmin, removeGroupMember, updateGroupInfo, addMembersToGroup, getAllUsers } from '../../firebase';

interface GroupInfoModalProps {
  chat: Chat;
  currentUser: User;
  onClose: () => void;
}

export const GroupInfoModal: React.FC<GroupInfoModalProps> = ({ chat, currentUser, onClose }) => {
  const [participants, setParticipants] = useState<User[]>([]);
  const [isEditing, setIsEditing] = useState(false);
  const [groupName, setGroupName] = useState(chat.name || '');
  const [groupDescription, setGroupDescription] = useState(chat.description || '');
  const [groupPhoto, setGroupPhoto] = useState(chat.groupIcon || '');
  const [isAdmin, setIsAdmin] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Feature 1: Add Member State
  const [showAddMember, setShowAddMember] = useState(false);
  const [availableUsers, setAvailableUsers] = useState<User[]>([]);
  const [selectedToAdd, setSelectedToAdd] = useState<string[]>([]);

  useEffect(() => {
    const loadParticipants = async () => {
      const users = await Promise.all(chat.participants.map(uid => getUserById(uid)));
      setParticipants(users.filter(u => u !== null) as User[]);
    };
    loadParticipants();
    setIsAdmin(chat.adminIds?.includes(currentUser.uid) || false);
  }, [chat, currentUser.uid]);

  // Load users for adding (Feature 1)
  useEffect(() => {
    if (showAddMember) {
        getAllUsers().then(users => {
            const nonMembers = users.filter(u => !chat.participants.includes(u.uid));
            setAvailableUsers(nonMembers);
        });
    }
  }, [showAddMember, chat.participants]);

  const handlePhotoSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        setGroupPhoto(ev.target?.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSave = async () => {
    if (!groupName.trim()) return;
    await updateGroupInfo(chat.id, groupName, groupPhoto, groupDescription);
    setIsEditing(false);
  };

  const handleLeaveGroup = async () => {
    if (window.confirm("Are you sure you want to leave this group?")) {
      await leaveGroup(chat.id, currentUser.uid);
      onClose();
    }
  };

  const handleRemoveMember = async (uid: string) => {
    if (window.confirm("Remove this user from the group?")) {
      await removeGroupMember(chat.id, uid);
      setParticipants(prev => prev.filter(p => p.uid !== uid));
    }
  };

  const handleMakeAdmin = async (uid: string) => {
    if (window.confirm("Promote this user to Admin?")) {
      await makeGroupAdmin(chat.id, uid);
    }
  };

  const handleAddSelected = async () => {
    if(selectedToAdd.length === 0) return;
    await addMembersToGroup(chat.id, selectedToAdd, currentUser.name);
    setShowAddMember(false);
    // Reload participants
    const users = await Promise.all([...chat.participants, ...selectedToAdd].map(uid => getUserById(uid)));
    setParticipants(users.filter(u => u !== null) as User[]);
  };

  return (
    <div className="fixed inset-0 z-[150] flex justify-end">
      <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={onClose}></div>
      <div className="relative w-full max-w-md bg-white dark:bg-slate-950 h-full shadow-2xl flex flex-col animate-in slide-in-from-right duration-300">

        <div className="h-16 flex items-center px-4 bg-white dark:bg-slate-900 border-b border-slate-100 dark:border-slate-800 shrink-0 gap-4">
          <button onClick={onClose} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-all">
            <svg className="w-6 h-6 text-slate-600 dark:text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
          <h2 className="text-lg font-bold text-slate-900 dark:text-white">Group Info</h2>
        </div>

        <div className="flex-1 overflow-y-auto no-scrollbar">
          {/* Group Profile */}
          <div className="flex flex-col items-center p-8 border-b border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900">
            <div className="relative group mb-6">
              <img src={groupPhoto || `https://picsum.photos/seed/${chat.id}/200`} className="w-32 h-32 rounded-[2.5rem] object-cover shadow-2xl ring-4 ring-slate-50 dark:ring-slate-800" alt="" />
              {isEditing && (
                <div 
                  onClick={() => fileInputRef.current?.click()}
                  className="absolute inset-0 bg-black/50 rounded-[2.5rem] flex items-center justify-center cursor-pointer opacity-0 group-hover:opacity-100 transition-opacity"
                >
                  <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                </div>
              )}
              <input type="file" ref={fileInputRef} onChange={handlePhotoSelect} className="hidden" accept="image/*" />
            </div>

            {isEditing ? (
              <div className="flex flex-col gap-4 w-full">
                <input 
                  value={groupName} 
                  onChange={e => setGroupName(e.target.value)} 
                  className="w-full bg-slate-100 dark:bg-slate-800 px-4 py-3 rounded-xl outline-none font-bold text-center text-lg"
                  placeholder="Group Name"
                />
                <textarea 
                  value={groupDescription} 
                  onChange={e => setGroupDescription(e.target.value)} 
                  className="w-full bg-slate-100 dark:bg-slate-800 px-4 py-3 rounded-xl outline-none text-sm font-medium resize-none min-h-[80px]"
                  placeholder="Group Description"
                />
                <div className="flex gap-2">
                    <button onClick={() => setIsEditing(false)} className="flex-1 py-3 bg-slate-200 dark:bg-slate-800 rounded-xl font-bold text-xs text-slate-500">Cancel</button>
                    <button onClick={handleSave} className="flex-1 py-3 bg-indigo-500 text-white rounded-xl font-bold text-xs shadow-lg shadow-indigo-500/20">Save Changes</button>
                </div>
              </div>
            ) : (
              <div className="text-center w-full">
                <h3 className="text-2xl font-black text-slate-900 dark:text-white">{chat.name}</h3>
                <p className="text-slate-500 text-sm font-medium mt-1 mb-4">{participants.length} participants</p>
                <div className="bg-slate-50 dark:bg-slate-800/50 p-4 rounded-2xl text-left border border-slate-100 dark:border-slate-800">
                    <p className="text-[10px] font-black uppercase text-indigo-500 tracking-widest mb-1">Description</p>
                    <p className="text-sm text-slate-700 dark:text-slate-300 leading-relaxed whitespace-pre-wrap">{chat.description || "No description provided."}</p>
                </div>
              </div>
            )}

            {isAdmin && !isEditing && (
               <button onClick={() => setIsEditing(true)} className="mt-6 px-6 py-3 bg-indigo-50 dark:bg-indigo-900/10 text-indigo-600 dark:text-indigo-400 rounded-xl text-xs font-bold uppercase tracking-widest hover:bg-indigo-100 dark:hover:bg-indigo-900/30 transition-all border border-indigo-100 dark:border-indigo-900/20">
                 Edit Settings
               </button>
            )}
          </div>

          {/* Feature 1: Add Member Logic */}
          {showAddMember ? (
              <div className="p-6 bg-indigo-50 dark:bg-indigo-900/20 border-b border-indigo-100 dark:border-indigo-800">
                  <h4 className="text-sm font-bold mb-3 flex items-center justify-between">
                      <span>Add Members</span>
                      <button onClick={() => setShowAddMember(false)} className="text-xs text-slate-400 uppercase font-bold">Cancel</button>
                  </h4>
                  <div className="max-h-48 overflow-y-auto space-y-2 mb-4">
                      {availableUsers.map(u => (
                          <div 
                            key={u.uid} 
                            onClick={() => setSelectedToAdd(prev => prev.includes(u.uid) ? prev.filter(id => id !== u.uid) : [...prev, u.uid])}
                            className={`flex items-center gap-3 p-2 rounded-xl cursor-pointer ${selectedToAdd.includes(u.uid) ? 'bg-indigo-500 text-white' : 'hover:bg-white dark:hover:bg-slate-800'}`}
                          >
                              <img src={u.photoURL} className="w-8 h-8 rounded-full" alt="" />
                              <span className="text-sm font-bold truncate">{u.name}</span>
                          </div>
                      ))}
                      {availableUsers.length === 0 && <p className="text-xs text-slate-400 italic">No other users available to add.</p>}
                  </div>
                  <button 
                    onClick={handleAddSelected}
                    disabled={selectedToAdd.length === 0}
                    className="w-full py-2 bg-indigo-500 text-white rounded-xl font-bold text-xs shadow-md disabled:opacity-50"
                  >
                      Confirm Add ({selectedToAdd.length})
                  </button>
              </div>
          ) : (
            isAdmin && (
                <div className="px-6 pt-6">
                    <button onClick={() => setShowAddMember(true)} className="w-full py-3 border-2 border-dashed border-slate-200 dark:border-slate-700 rounded-xl text-slate-400 font-bold text-xs uppercase tracking-widest hover:border-indigo-500 hover:text-indigo-500 transition-colors flex items-center justify-center gap-2">
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 4v16m8-8H4"/></svg>
                        Add Participants
                    </button>
                </div>
            )
          )}

          {/* Participants */}
          <div className="p-6">
            <div className="flex items-center justify-between px-2 mb-4">
                <h4 className="text-xs font-black text-slate-400 uppercase tracking-[0.2em]">Members</h4>
                <div className="px-2 py-1 bg-slate-100 dark:bg-slate-800 rounded-lg text-[10px] font-bold text-slate-500">{participants.length}</div>
            </div>

            <div className="space-y-2">
              {participants.map(user => {
                const isUserAdmin = chat.adminIds?.includes(user.uid);
                const isMe = user.uid === currentUser.uid;

                return (
                  <div key={user.uid} className="flex items-center justify-between p-3 rounded-2xl hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors group">
                    <div className="flex items-center gap-3">
                      <img src={user.photoURL} className="w-10 h-10 rounded-full object-cover border border-slate-100 dark:border-slate-800" alt="" />
                      <div>
                        <p className="text-sm font-bold flex items-center gap-2 text-slate-900 dark:text-white">
                          {isMe ? 'You' : user.name}
                          {isUserAdmin && <span className="text-[9px] bg-green-100 text-green-600 px-1.5 py-0.5 rounded border border-green-200 font-bold uppercase">Admin</span>}
                        </p>
                        {/* Feature 2: Hide Email */}
                        <p className="text-[10px] text-slate-400 font-medium">@{user.uid.slice(0,8)}</p>
                      </div>
                    </div>

                    {isAdmin && !isMe && (
                      <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                        {!isUserAdmin && (
                          <button onClick={() => handleMakeAdmin(user.uid)} title="Make Admin" className="p-2 bg-indigo-50 text-indigo-500 rounded-xl hover:bg-indigo-100 transition-colors">
                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" /></svg>
                          </button>
                        )}
                        <button onClick={() => handleRemoveMember(user.uid)} title="Remove" className="p-2 bg-red-50 text-red-500 rounded-xl hover:bg-red-100 transition-colors">
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
                        </button>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>

          <div className="p-6 pt-0">
            <button 
              onClick={handleLeaveGroup}
              className="w-full py-4 flex items-center justify-center gap-2 text-red-500 bg-red-50 dark:bg-red-900/10 rounded-2xl font-bold hover:bg-red-100 dark:hover:bg-red-900/20 transition-all border border-red-100 dark:border-red-900/20"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
              Exit Group
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { User } from '../../types';
import { useAuth } from '../../hooks/useAuth';
import { updateProfile, setAppLockPin, disableAppLock } from '../../firebase';

interface ProfilePanelProps {
  user: User;
  onClose: () => void;
  toggleDarkMode: () => void;
  isDarkMode: boolean;
  isTabMode?: boolean;
}

type ProfileViewMode = 'main' | 'edit' | 'settings' | 'privacy' | 'chats' | 'notifications' | 'language' | 'blocked' | 'wallpaper' | 'applock';

const WALLPAPER_OPTIONS = [
  { id: 'default', name: 'Default', class: 'bg-slate-100 dark:bg-slate-900' },
  { id: 'indigo', name: 'Indigo Night', class: 'bg-indigo-600' },
  { id: 'emerald', name: 'Emerald Forest', class: 'bg-emerald-700' },
  { id: 'rose', name: 'Rose Petal', class: 'bg-rose-500' },
  { id: 'amber', name: 'Amber Sunset', class: 'bg-amber-500' },
  { id: 'dark', name: 'Pure Dark', class: 'bg-black' },
  { id: 'gradient', name: 'Cosmic', class: 'bg-gradient-to-br from-purple-900 via-indigo-900 to-black' },
];

export const ProfilePanel: React.FC<ProfilePanelProps> = ({ user, onClose, toggleDarkMode, isDarkMode, isTabMode }) => {
  const { logout } = useAuth();
  const [viewMode, setViewMode] = useState<ProfileViewMode>('main');

  const [name, setName] = useState(user.name);
  const [bio, setBio] = useState(user.bio || 'Available');
  const [lockPass, setLockPass] = useState(user.chatLockPassword || '');
  const [newPhoto, setNewPhoto] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const wallpaperInputRef = useRef<HTMLInputElement>(null);

  const [lastSeenPrivacy, setLastSeenPrivacy] = useState(user.privacySettings?.lastSeen || 'everyone');

  // Feature 4: App Lock State
  const [appLockPinInput, setAppLockPinInput] = useState('');

  const [settings, setSettings] = useState(() => {
    try {
      const saved = localStorage.getItem('roxx_settings');
      return saved ? JSON.parse(saved) : {
        fontSize: 'medium',
        notificationsEnabled: true,
        notificationSound: true,
        language: 'English (US)',
        wallpaper: 'default',
        customWallpaperUrl: null
      };
    } catch (e) {
      return {
        fontSize: 'medium',
        notificationsEnabled: true,
        notificationSound: true,
        language: 'English (US)',
        wallpaper: 'default',
        customWallpaperUrl: null
      };
    }
  });

  useEffect(() => {
    localStorage.setItem('roxx_settings', JSON.stringify(settings));
    window.dispatchEvent(new Event('roxx_settings_updated'));
  }, [settings]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const compressWallpaper = (file: File): Promise<string> => {
    return new Promise((resolve) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = (e) => {
        const img = new Image();
        img.src = e.target?.result as string;
        img.onload = () => {
          const canvas = document.createElement('canvas');
          const MAX_WIDTH = 1280;
          let width = img.width;
          let height = img.height;
          if (width > MAX_WIDTH) {
            height *= MAX_WIDTH / width;
            width = MAX_WIDTH;
          }
          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          ctx?.drawImage(img, 0, 0, width, height);
          resolve(canvas.toDataURL('image/jpeg', 0.6));
        };
      };
    });
  };

  const handleCustomWallpaper = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const compressed = await compressWallpaper(file);
    setSettings({
      ...settings,
      wallpaper: 'custom',
      customWallpaperUrl: compressed
    });
  };

  const handlePhotoSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      const img = new Image();
      img.src = event.target?.result as string;
      img.onload = () => {
        const canvas = document.createElement('canvas');
        canvas.width = 300;
        canvas.height = 300;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, 300, 300);
        setNewPhoto(canvas.toDataURL('image/jpeg', 0.7));
      };
    };
    reader.readAsDataURL(file);
  };

  const handleSave = async () => {
    if (!name.trim()) return;
    setIsSaving(true);
    try {
      await updateProfile(user, {
        name: name.trim(),
        bio: bio.trim(),
        chatLockPassword: lockPass.trim(),
        photoURL: newPhoto || user.photoURL
      });
      setViewMode('main');
    } catch (err) { alert("Error saving profile"); }
    finally { setIsSaving(false); }
  };

  const handlePrivacyUpdate = async (type: 'lastSeen', value: string) => {
      if (type === 'lastSeen') setLastSeenPrivacy(value as any);

      const newSettings = { 
          ...user.privacySettings,
          [type]: value
      };

      await updateProfile(user, { privacySettings: newSettings });
  };

  // Feature 4: Set/Disable Lock
  const handleSetLock = async () => {
    if (appLockPinInput.length < 4) {
        alert("PIN must be 4-6 digits");
        return;
    }
    // Using localStorage for this implementation as requested for simple offline lock
    // For cloud sync, we'd use setAppLockPin from firebase.ts
    localStorage.setItem('roxx_app_lock', appLockPinInput);
    setAppLockPinInput('');
    alert("App Lock Enabled");
    setViewMode('privacy');
  };

  const handleDisableLock = () => {
      localStorage.removeItem('roxx_app_lock');
      alert("App Lock Disabled");
      setViewMode('privacy');
  };

  const renderHeader = () => {
    const titles: Record<string, string> = {
      main: "Settings", edit: "Edit Profile", settings: "ROXX Settings",
      privacy: "Privacy", chats: "Chats", notifications: "Notifications",
      language: "App Language", blocked: "Blocked Contacts", wallpaper: "Chat Wallpaper",
      applock: "App Lock"
    };

    const backTarget: Record<string, ProfileViewMode> = {
      edit: 'main', settings: 'main', privacy: 'settings',
      chats: 'settings', notifications: 'settings', language: 'settings',
      blocked: 'privacy', wallpaper: 'chats', applock: 'privacy'
    };

    return (
      <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between sticky top-0 bg-white/80 dark:bg-slate-900/80 backdrop-blur-md z-10">
        <div className="flex items-center gap-4">
          {viewMode !== 'main' && (
            <button onClick={() => setViewMode(backTarget[viewMode] || 'main')} className="p-2 -ml-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-all">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 19l-7-7 7-7" /></svg>
            </button>
          )}
          <h2 className="text-xl font-black tracking-tight">{titles[viewMode]}</h2>
        </div>
        {!isTabMode && viewMode === 'main' && (
          <button onClick={onClose} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-all">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        )}
      </div>
    );
  };

  const SettingsItem = ({ icon, title, subtitle, onClick, color = "indigo", toggle }: any) => (
    <button onClick={onClick} className="w-full flex items-center gap-4 p-4 hover:bg-slate-50 dark:hover:bg-slate-800/40 transition-all group border-b border-slate-50 dark:border-slate-800/50 last:border-0">
      <div className={`p-2.5 rounded-xl bg-${color}-500/10 text-${color}-500 group-hover:scale-110 transition-transform`}>
        {icon}
      </div>
      <div className="flex-1 text-left min-w-0">
        <p className="font-bold text-[13px] text-slate-900 dark:text-slate-100 leading-tight">{title}</p>
        {subtitle && <p className="text-[11px] font-medium text-slate-500 truncate mt-0.5">{subtitle}</p>}
      </div>
      {toggle !== undefined ? (
        <div className={`w-9 h-5 rounded-full transition-all relative ${toggle ? 'bg-indigo-500' : 'bg-slate-200 dark:bg-slate-700'}`}>
          <div className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all ${toggle ? 'left-5' : 'left-1'}`}></div>
        </div>
      ) : (
        <svg className="w-3.5 h-3.5 text-slate-300 group-hover:translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 5l7 7-7 7" />
        </svg>
      )}
    </button>
  );

  const renderContent = () => {
    switch (viewMode) {
      case 'edit':
        return (
          <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500">
            <div className="flex flex-col items-center gap-6">
              <div className="relative group cursor-pointer" onClick={() => fileInputRef.current?.click()}>
                <div className="w-32 h-32 rounded-[2.5rem] overflow-hidden border-4 border-indigo-500/20 shadow-2xl">
                  <img src={newPhoto || user.photoURL} className="w-full h-full object-cover transition-all group-hover:brightness-75" alt="" />
                </div>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handlePhotoSelect} />
              </div>
            </div>
            <div className="space-y-6">
              <input type="text" value={name} onChange={e => setName(e.target.value)} placeholder="Display Name" className="w-full bg-slate-100 dark:bg-slate-800 rounded-2xl px-6 py-4 font-bold outline-none border border-transparent focus:border-indigo-500/50" />
              <textarea value={bio} onChange={e => setBio(e.target.value)} placeholder="Bio" className="w-full bg-slate-100 dark:bg-slate-800 rounded-2xl px-6 py-4 text-sm font-medium outline-none resize-none" rows={3} />
            </div>
            <div className="flex gap-4">
              <button onClick={() => setViewMode('main')} className="flex-1 py-4 bg-slate-100 dark:bg-slate-800 rounded-2xl text-xs font-bold">Cancel</button>
              <button onClick={handleSave} className="flex-[2] py-4 bg-indigo-500 text-white rounded-2xl text-xs font-bold shadow-xl">Save Changes</button>
            </div>
          </div>
        );

      case 'settings':
        return (
          <div className="space-y-1 animate-in slide-in-from-right-4 duration-500">
            <SettingsItem title="Privacy" subtitle="Blocked, read receipts, app lock" icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg>} onClick={() => setViewMode('privacy')} />
            <SettingsItem title="Chats" subtitle="Wallpaper, font size, clear history" icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>} onClick={() => setViewMode('chats')} />
            <SettingsItem title="Notifications" subtitle="Tones, vibration, alerts" icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 17h5l-1.405-1.405A2.032 2.032 0 0118 14.158V11a6.002 6.002 0 00-4-5.659V5a2 2 0 10-4 0v.341C7.67 6.165 6 8.388 6 11v3.159c0 .538-.214 1.055-.595 1.436L4 17h5m6 0v1a3 3 0 11-6 0v-1m6 0H9" /></svg>} onClick={() => setViewMode('notifications')} />
            <SettingsItem title="Language" subtitle={settings.language} icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3.055 11H5a2 2 0 012 2v1a2 2 0 002 2 2 2 0 012 2v2.945M8 3.935V5.5A2.5 2.5 0 0010.5 8h.5a2 2 0 012 2 2 2 0 104 0 2 2 0 012-2h1.064M15 20.488V18a2 2 0 012-2h3.064M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>} onClick={() => setViewMode('language')} />
            <div className="pt-8 px-4">
              <button onClick={logout} className="w-full p-5 bg-red-50 dark:bg-red-900/10 text-red-500 rounded-3xl text-sm font-bold flex items-center gap-4 border border-red-100/50 hover:bg-red-100 transition-colors">
                <div className="p-2 bg-red-500 text-white rounded-lg">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
                </div>
                Logout Account
              </button>
            </div>
          </div>
        );

      case 'chats':
        return (
          <div className="space-y-1 animate-in slide-in-from-right-4 duration-500">
            <SettingsItem title="Wallpaper" subtitle="Customize your chat background" icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>} onClick={() => setViewMode('wallpaper')} />
            <SettingsItem title="Font Size" subtitle={settings.fontSize.charAt(0).toUpperCase() + settings.fontSize.slice(1)} onClick={() => {
              const sizes = ['small', 'medium', 'large'];
              setSettings({...settings, fontSize: sizes[(sizes.indexOf(settings.fontSize) + 1) % sizes.length]});
