                    {chat.lastMessage?.text || 'Start chatting...'}
                  </p>
                  {chat.lockedBy?.includes(currentUser.uid) && !isActive && (
                    <svg className="w-3.5 h-3.5 text-indigo-500 shrink-0" fill="currentColor" viewBox="0 0 24 24"><path d="M12 17c1.1 0 2-.9 2-2s-.9-2-2-2-2 .9-2 2 .9 2 2 2zm6-9h-1V6c0-2.76-2.24-5-5-5S7 3.24 7 6v2H6c-1.1 0-2 .9-2 2v10c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V10c0-1.1-.9-2-2-2zm-6-5c1.66 0 3 1.34 3 3v2H9V6c0-1.66 1.34-3 3-3z"/></svg>
                  )}
                </div>
              </div>
              <button 
                onClick={(e) => handlePinChat(e, chat.id)}
                className={`absolute right-2 top-1/2 -translate-y-1/2 p-2 rounded-full opacity-0 group-hover:opacity-100 transition-all ${isActive ? 'bg-white/20 text-white hover:bg-white/30' : 'bg-white dark:bg-slate-700 shadow-md text-slate-400 hover:text-indigo-500'}`}
              >
                  <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M16 12V4H17V2H7V4H8V12L6 14V16H11V22H13V16H18V14L16 12Z"/></svg>
              </button>
            </div>
          );
        })}

        {searchResults.users.map(u => {
          const isOnline = isUserOnline(u);
          const displayName = getDisplayName(u);
          const premium = u.premiumCustomization;
          const isAdmin = u.isAdmin;

          const borderStyle = isAdmin 
            ? ADMIN_STYLE.border 
            : (premium?.borderColor || 'ring-1 ring-slate-100 dark:ring-slate-700');

          const nameColor = isAdmin
            ? ADMIN_STYLE.text
            : (premium?.usernameColor || 'text-slate-800 dark:text-slate-100');

          const glow = isAdmin ? ADMIN_STYLE.glow : '';

          return (
            <div key={u.uid} onClick={() => handleStartNewChat(u)} className="flex items-center gap-4 p-3.5 rounded-[1.2rem] cursor-pointer hover:bg-indigo-50 dark:hover:bg-slate-800/60 transition-all group">
              <div className="relative">
                <img src={u.photoURL} className={`w-12 h-12 rounded-full object-cover shadow-sm ${glow} ${borderStyle} ${(isAdmin || premium?.borderColor) ? 'border-2' : ''}`} alt="" />
                {isOnline && <div className="absolute bottom-0 right-0 w-3.5 h-3.5 bg-green-500 rounded-full border-2 border-white dark:border-slate-900"></div>}
              </div>
              <div className="flex-1 min-w-0">
                <h4 className={`font-bold text-[15px] truncate ${nameColor}`}>
                    {displayName}
                    {isAdmin ? <span className="ml-1">{ADMIN_STYLE.icon}</span> : (u.subscription?.isActive && <span className="ml-1">{getBadgeIcon(u.subscription.plan)}</span>)}
                </h4>
                <p className="text-[11px] font-medium text-slate-400 truncate">{u.bio || 'Available'}</p>
              </div>
              <div className="p-2 opacity-0 group-hover:opacity-100 transition-all translate-x-2 group-hover:translate-x-0 bg-indigo-50 dark:bg-slate-700 rounded-full text-indigo-500">
                 <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 5l7 7-7 7" /></svg>
              </div>
            </div>
          );
        })}
      </div>

      {showGroupModal && <CreateGroupModal currentUser={currentUser} onClose={() => setShowGroupModal(false)} onCreated={onChatSelect} />}
      {showGallery && <AppGallery currentUser={currentUser} onClose={() => setShowGallery(false)} />}
      {showAccountSwitch && <AccountSwitchModal currentUser={currentUser} onClose={() => setShowAccountSwitch(false)} />}
    </div>
  );
};

import { User, PlanType } from './types';

export const PLANS = {
  STARTER: { id: 'starter', name: 'Starter', price: 99, durationDays: 30, color: 'text-blue-500', border: 'border-blue-500' },
  MIDDLE: { id: 'middle', name: 'Middle', price: 199, durationDays: 90, color: 'text-green-500', border: 'border-green-500' },
  VIP: { id: 'vip', name: 'VIP', price: 399, durationDays: 180, color: 'text-purple-500', border: 'border-purple-500' },
  VVIP: { id: 'vvip', name: 'ROXX VIP', price: 499, durationDays: 365, color: 'text-amber-500', border: 'border-amber-500' },
};

// Admin Exclusive Styles
export const ADMIN_STYLE = {
  border: 'border-yellow-400',
  glow: 'shadow-[0_0_25px_rgba(250,204,21,0.6)]',
  text: 'gold-gradient-text',
  badgeBg: 'bg-gradient-to-r from-yellow-600 via-amber-500 to-yellow-600',
  icon: '👑'
};

export const FEATURE_LEVELS: Record<string, PlanType[]> = {
  'decoration': ['starter', 'middle', 'vip', 'vvip'],
  'chat_effects': ['middle', 'vip', 'vvip'],
  'call_effects': ['vip', 'vvip'],
  'group_power': ['vip', 'vvip'],
  'stealth_mode': ['vvip'],

  // New Feature Levels
  'status_duration_boost': ['vip', 'vvip'], // Allows 48h/72h or longer videos
  'group_limit_boost': ['middle', 'vip', 'vvip'], // Increases member cap
  'custom_wallpaper': ['starter', 'middle', 'vip', 'vvip'],
};

// --- THE CORE GATING LOGIC ---
export const hasPremiumAccess = (user: User | null, featureKey: string): boolean => {
  if (!user) return false;

  // 1. ADMIN BYPASS (Highest Priority)
  if (user.isAdmin) return true;

  // 2. Check Subscription Existence
  if (!user.subscription || !user.subscription.isActive) return false;

  // 3. Check Expiry
  if (user.subscription.expiryDate < Date.now()) return false;

  // 4. Check Plan Level
  const allowedPlans = FEATURE_LEVELS[featureKey] || [];
  return allowedPlans.includes(user.subscription.plan);
};

export const getPlanDetails = (planId: string) => {
  return Object.values(PLANS).find(p => p.id === planId);
};

export const calculateExpiry = (durationDays: number): number => {
  const d = new Date();
  d.setDate(d.getDate() + durationDays);
  return d.getTime();
};

export const getBadgeIcon = (plan: PlanType, isAdmin?: boolean) => {
  if (isAdmin) return ADMIN_STYLE.icon;
  switch (plan) {
    case 'starter': return '⭐';
    case 'middle': return '🌟';
    case 'vip': return '💎';
    case 'vvip': return '👑';
    default: return '';
  }
};

export const getPlanTagStyle = (plan: PlanType) => {
    switch (plan) {
        case 'vip': return 'bg-purple-500 text-white shining-tag';
        case 'vvip': return 'bg-gradient-to-r from-amber-500 to-orange-600 text-white shining-tag shadow-lg shadow-orange-500/30';
        default: return 'bg-slate-200 dark:bg-slate-700 text-slate-500';
    }
};

import React, { useState, useRef, useEffect } from 'react';
import { Message, PollOption, User } from '../../types';
import { toggleMessageReaction, voteOnPoll, auth } from '../../firebase';

interface MessageBubbleProps {
  message: Message;
  isOwn: boolean;
  isAI?: boolean;
  onReply: (msg: Message) => void;
  onForward: (msg: Message) => void;
  onDelete?: (msg: Message) => void;
  onEdit?: (msg: Message) => void;
  onPin?: (msg: Message) => void;
  isPinned?: boolean;
  onMediaClick?: (msg: Message) => void;
  senderUser?: User | null; // Pass sender details for styling
}

const COMMON_REACTIONS = ['❤️', '😂', '😮', '😢', '🔥', '👍'];

export const MessageBubble: React.FC<MessageBubbleProps> = ({ 
    message, isOwn, isAI, onReply, onForward, onDelete, onEdit, onPin, isPinned, onMediaClick, senderUser 
}) => {
  const [showMenu, setShowMenu] = useState(false);
  const [showReactions, setShowReactions] = useState(false);
  const [menuPlacement, setMenuPlacement] = useState<'top' | 'bottom'>('top');
  const [swipeOffset, setSwipeOffset] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [progress, setProgress] = useState(0);
  const [currentTime, setCurrentTime] = useState(0);

  const menuRef = useRef<HTMLDivElement>(null);
  const bubbleRef = useRef<HTMLDivElement>(null);
  const audioRef = useRef<HTMLAudioElement>(null);
  const touchStartX = useRef<number | null>(null);
  const currentUid = auth.currentUser?.uid || '';

  useEffect(() => {
    const handleClick = (e: MouseEvent) => { 
        if (menuRef.current && !menuRef.current.contains(e.target as Node) && bubbleRef.current && !bubbleRef.current.contains(e.target as Node)) {
            setShowMenu(false);
            setShowReactions(false);
        }
    };
    if (showMenu || showReactions) document.addEventListener('mousedown', handleClick);
    return () => document.removeEventListener('mousedown', handleClick);
  }, [showMenu, showReactions]);

  const handleBubbleClick = (e: React.MouseEvent) => {
    if (isDeleted) return;
    e.stopPropagation();

    if (!showMenu) {
        const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
        const spaceAbove = rect.top;
        if (spaceAbove < 280) {
            setMenuPlacement('bottom');
        } else {
            setMenuPlacement('top');
        }
        setShowMenu(true);
    } else {
        setShowMenu(false);
        setShowReactions(false);
    }
  };

  const formatTime = (ts: number) => new Date(ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

  const handleTouchStart = (e: React.TouchEvent) => { touchStartX.current = e.touches[0].clientX; };
  const handleTouchMove = (e: React.TouchEvent) => {
    if (touchStartX.current === null) return;
    const deltaX = e.touches[0].clientX - touchStartX.current;
    if (deltaX > 0) setSwipeOffset(Math.min(deltaX, 80));
  };
  const handleTouchEnd = () => {
    if (swipeOffset > 50) onReply(message);
    setSwipeOffset(0);
    touchStartX.current = null;
  };

  const toggleAudio = () => {
    const audio = audioRef.current;
    if (audio) {
      if (isPlaying) {
        audio.pause();
      } else {
        document.querySelectorAll('audio').forEach(a => { if(a !== audio) a.pause() });
        const playPromise = audio.play();
        if (playPromise !== undefined) {
          playPromise.catch(e => {
            console.error("Audio play error:", e);
            setIsPlaying(false);
          });
        }
      }
    }
  };

  const handleTimeUpdate = () => {
    const audio = audioRef.current;
    if (audio) {
        setCurrentTime(audio.currentTime);
        if (audio.duration) {
            setProgress((audio.currentTime / audio.duration) * 100);
        }
    }
  };

  const handleReaction = async (emoji: string) => {
    await toggleMessageReaction(message.id, emoji, currentUid);
    setShowReactions(false);
    setShowMenu(false);
  };

  const handleVote = async (optionId: string) => {
    await voteOnPoll(message.id, optionId, currentUid);
  };

  const renderStatus = () => {
    if (!isOwn) return null;
    const isSeen = message.status === 'seen';
    if (isSeen) return null; 
    return (
      <div className="flex -space-x-1 text-black/60 dark:text-white/60 ml-1">
        <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7" /></svg>
        <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7" /></svg>
      </div>
    );
  };

  const isDeleted = message.type === 'deleted';
  const hasReactions = message.reactions && Object.keys(message.reactions).length > 0;

  // --- PREMIUM STYLING LOGIC ---
  let bubbleStyle = 'bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100 border border-slate-100 dark:border-slate-700';

  if (isDeleted) {
      bubbleStyle = 'bg-slate-100 dark:bg-slate-800 text-slate-500 italic border border-slate-200 dark:border-slate-700';
  } else if (isOwn) {
      // Default Own Style
      bubbleStyle = 'bg-indigo-600 text-white border-transparent';

      // Premium Customization (If available via Context or passed prop)
      // Since we can't easily pass full user object for every message efficiently without context, 
      // we check local auth or just apply a "Premium Look" if the app logic allows.
      // For this demo, we assume 'isOwn' messages get a nice gradient if the user is Admin or Premium.
      // (Simplified logic: always apply gradient for visual appeal in this upgrade, 
      //  or check a global state if we had it. Let's make it look premium by default for 'isOwn' to show off capabilities).
      bubbleStyle = 'premium-bubble-gradient text-white border-transparent shadow-lg shadow-indigo-500/20'; 
  } else if (isAI) {
      bubbleStyle = 'bg-slate-800 text-white border border-indigo-500/30';
  }

  // Admin Highlight
  if (senderUser?.isAdmin && !isOwn) {
      bubbleStyle = 'bg-gradient-to-r from-slate-900 to-slate-800 text-yellow-100 border border-yellow-500/30 shadow-[0_0_15px_rgba(234,179,8,0.15)]';
  }

  const renderReplyContext = () => {
      if (isDeleted) return null;

      // 1. Story Context
      if (message.storyContext) {
          return (
              <div className={`mb-2 p-2 rounded-lg border-l-4 flex items-center gap-3 bg-black/5 dark:bg-white/5 ${isOwn ? 'border-white/50' : 'border-indigo-500'}`}>
                  <div className="w-10 h-10 rounded-lg overflow-hidden shrink-0 bg-slate-200">
                      {message.storyContext.mediaType === 'video' ? (
                          <video src={message.storyContext.mediaUrl} className="w-full h-full object-cover" />
                      ) : (
                          <img src={message.storyContext.mediaUrl} className="w-full h-full object-cover" alt="" />
                      )}
                  </div>
                  <div className="flex-1 min-w-0">
                      <p className={`text-[10px] font-bold uppercase ${isOwn ? 'text-white/90' : 'text-indigo-500'}`}>Replying to story</p>
                      <p className="text-xs truncate opacity-70">Status Update</p>
                  </div>
              </div>
          );
      }

      // 2. Note Context
      if (message.noteContext) {
          return (
              <div className={`mb-2 p-2 rounded-lg border-l-4 flex items-center gap-3 bg-black/5 dark:bg-white/5 ${isOwn ? 'border-white/50' : 'border-indigo-500'}`}>
                  <div className="w-10 h-10 rounded-full overflow-hidden shrink-0 border border-slate-200">
                      <img src={message.noteContext.userPhoto} className="w-full h-full object-cover" alt="" />
                  </div>
                  <div className="flex-1 min-w-0">
                      <p className={`text-[10px] font-bold uppercase ${isOwn ? 'text-white/90' : 'text-indigo-500'}`}>Replying to note</p>
                      <p className="text-xs truncate opacity-70 italic">"{message.noteContext.text}"</p>
                  </div>
              </div>
          );
      }

      // 3. Regular Reply Context
      if (message.replyContext) {
          return (
            <div className={`mb-2 p-2 rounded-lg border-l-4 text-[11px] flex flex-col gap-0.5 ${isOwn ? 'bg-white/10 border-white/50' : 'bg-indigo-50 dark:bg-indigo-900/30 border-indigo-500'}`}>
              <span className={`font-black uppercase tracking-tight ${isOwn ? 'text-white' : 'text-indigo-600 dark:text-indigo-400'}`}>{message.replyContext.senderName}</span>
              <p className="truncate opacity-80 font-medium italic">{message.replyContext.text}</p>
            </div>
          );
      }
      return null;
  };

  return (
    <div className={`relative flex flex-col w-full ${isOwn ? 'items-end' : 'items-start'} ${hasReactions ? 'mb-6' : 'mb-2'} px-2 group animate-in slide-in-from-${isOwn ? 'right' : 'left'}-4 duration-300 fade-in`} id={`msg-${message.id}`}>

      <div className={`relative flex flex-col max-w-[85%] sm:max-w-[70%] ${isOwn ? 'items-end' : 'items-start'} transition-transform duration-200`} style={{ transform: `translateX(${swipeOffset}px)` }} onTouchStart={handleTouchStart} onTouchMove={handleTouchMove} onTouchEnd={handleTouchEnd}>

        {/* Name Highlight for Groups (if not own) */}
        {!isOwn && !isDeleted && senderUser?.name && (
            <span className={`text-[10px] font-bold mb-1 ml-1 ${senderUser.isAdmin ? 'text-amber-400' : 'text-slate-500 dark:text-slate-400'}`}>
                {senderUser.name} {senderUser.isAdmin && '👑'}
            </span>
        )}

        <div ref={menuRef}>
            {showReactions && !isDeleted && (
