                </div>
                <div className="mt-2 text-[10px] opacity-70 font-bold uppercase tracking-wider text-center">
                    {message.poll.options.reduce((acc: number, o: PollOption) => {
                        const votes = (o.votes || []) as string[];
                        return acc + votes.length;
                    }, 0)} votes
                </div>
             </div>
          ) : (
            <p className="text-[14px] leading-[1.5] font-medium whitespace-pre-wrap">{message.text}</p>
          )}

          {message.type !== 'sticker' && (
            <div className={`flex items-center gap-1 justify-end mt-1 ${isOwn ? 'text-white/70' : 'text-slate-400 dark:text-slate-500'}`}>
                {message.isEdited && !isDeleted && <span className="text-[9px] italic mr-1">(edited)</span>}
                <span className="text-[9px] font-bold uppercase tracking-tight">{formatTime(message.timestamp)}</span>
                {renderStatus()}
            </div>
          )}
        </div>

        {isOwn && message.status === 'seen' && (
            <span className="text-[9px] font-bold text-slate-400 mt-1 self-end mr-1 animate-in fade-in">
                Seen just now
            </span>
        )}

        {hasReactions && !isDeleted && (
            <div className={`absolute -bottom-5 ${isOwn ? 'right-2' : 'left-2'} flex gap-1 z-10`}>
                <div className="flex items-center gap-1 bg-white dark:bg-slate-800 rounded-full px-1.5 py-0.5 shadow-md border border-slate-100 dark:border-slate-700">
                    {Object.entries(message.reactions || {}).slice(0, 3).map(([emoji, users]) => (
                        <span key={emoji} className="text-[10px] leading-none" title={`${(users as string[]).length} reaction(s)`}>{emoji}</span>
                    ))}
                    <span className="text-[9px] font-bold text-slate-500 px-1">
                        {Object.values(message.reactions || {}).reduce((acc: number, u: any) => acc + (u?.length || 0), 0)}
                    </span>
                </div>
            </div>
        )}

      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User } from '../../types';
import { getAllUsers, createGroup } from '../../firebase';
import { hasPremiumAccess, getBadgeIcon } from '../../premiumUtils';

interface CreateGroupModalProps {
  currentUser: User;
  onClose: () => void;
  onCreated: (chat: any) => void;
}

export const CreateGroupModal: React.FC<CreateGroupModalProps> = ({ currentUser, onClose, onCreated }) => {
  const [mode, setMode] = useState<'single' | 'group'>('single');
  const [name, setName] = useState('');
  const [users, setUsers] = useState<User[]>([]);
  const [selected, setSelected] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);

  // Premium Limit Logic
  const hasLimitBoost = hasPremiumAccess(currentUser, 'group_limit_boost');
  const MEMBER_LIMIT = hasLimitBoost ? 250 : 20;

  useEffect(() => {
    getAllUsers().then(all => setUsers(all.filter(u => u.uid !== currentUser.uid)));
  }, [currentUser.uid]);

  const handleToggle = (uid: string) => {
    if (mode === 'single') return; 

    if (selected.includes(uid)) {
        setSelected(prev => prev.filter(id => id !== uid));
    } else {
        if (selected.length >= MEMBER_LIMIT) {
            alert(hasLimitBoost ? "Maximum group size reached." : "Upgrade to Premium to add more members!");
            return;
        }
        setSelected(prev => [...prev, uid]);
    }
  };

  const handleCreateGroup = async () => {
    if (!name.trim() || selected.length === 0) return;
    setLoading(true);
    const group = await createGroup(name.trim(), selected, currentUser.uid);
    onCreated(group);
    onClose();
  };

  const handleStartSingleChat = (user: User) => {
    // Determine chat ID deterministically
    const chatId = [currentUser.uid, user.uid].sort().join('_');
    const chat = {
      id: chatId,
      type: 'private',
      participants: [currentUser.uid, user.uid],
      updatedAt: Date.now(),
      lockedBy: []
    };
    onCreated(chat);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={onClose}></div>
      <div className="relative w-full max-w-md bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl flex flex-col max-h-[80vh] animate-in zoom-in-95">

        <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between">
          <h2 className="text-xl font-bold">{mode === 'group' ? 'New Group' : 'New Message'}</h2>
          <button onClick={onClose} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-all">
             <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <div className="p-6 space-y-4 flex-1 overflow-hidden flex flex-col">
          {mode === 'single' ? (
             <button 
               onClick={() => setMode('group')}
               className="w-full flex items-center gap-4 p-4 rounded-2xl bg-indigo-50 dark:bg-indigo-900/10 text-indigo-600 dark:text-indigo-400 hover:bg-indigo-100 dark:hover:bg-indigo-900/20 transition-all font-bold group"
             >
                <div className="p-2 bg-indigo-500 rounded-full text-white group-hover:scale-110 transition-transform">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 4v16m8-8H4" /></svg>
                </div>
                <div className="text-left">
                    <span className="block">Create New Group</span>
                    {!hasLimitBoost && <span className="text-[10px] text-slate-400 font-normal">Limit: 20 Members</span>}
                    {hasLimitBoost && <span className="text-[10px] text-amber-500 font-bold">Premium Limit: 250 Members 👑</span>}
                </div>
             </button>
          ) : (
            <div className="animate-in slide-in-from-right">
              <input 
                type="text" 
                placeholder="Group Name"
                value={name}
                onChange={(e) => setName(e.target.value)}
                className="w-full bg-slate-100 dark:bg-slate-800 rounded-2xl px-5 py-3 outline-none ring-2 ring-transparent focus:ring-indigo-500/30 transition-all font-semibold mb-2"
              />
              <div className="flex justify-between items-center mb-2">
                  <button onClick={() => setMode('single')} className="text-xs font-bold text-slate-400 hover:text-slate-600 dark:hover:text-slate-200">
                    &larr; Back to users
                  </button>
                  <span className={`text-xs font-bold ${selected.length >= MEMBER_LIMIT ? 'text-red-500' : 'text-slate-400'}`}>
                      {selected.length} / {MEMBER_LIMIT}
                  </span>
              </div>
            </div>
          )}

          <h4 className="text-[10px] font-bold uppercase tracking-widest text-slate-400 mt-2">
            {mode === 'group' ? 'Select Participants' : 'All Contacts'}
          </h4>

          <div className="overflow-y-auto space-y-2 flex-1 pr-2 no-scrollbar">
            {users.length === 0 ? (
                <div className="text-center py-8 text-slate-400 text-sm">
                    No other users found. Invite your friends!
                </div>
            ) : (
                users.map(u => (
                <div 
                    key={u.uid} 
                    onClick={() => mode === 'group' ? handleToggle(u.uid) : handleStartSingleChat(u)}
                    className={`flex items-center gap-3 p-3 rounded-2xl cursor-pointer transition-all ${selected.includes(u.uid) && mode === 'group' ? 'bg-indigo-500 text-white' : 'bg-slate-50 dark:bg-slate-800 hover:bg-slate-100 dark:hover:bg-slate-700'}`}
                >
                    <img src={u.photoURL} className="w-10 h-10 rounded-full object-cover" alt="" />
                    <div className="flex-1 min-w-0">
                        <span className="flex items-center gap-1 font-medium truncate">
                            {u.name}
                            {u.subscription?.isActive && <span className="text-[10px]">{getBadgeIcon(u.subscription.plan)}</span>}
                            {u.isAdmin && <span>🛡️</span>}
                        </span>
                        {mode === 'single' && <span className="text-[10px] opacity-60 uppercase tracking-wider">{u.status}</span>}
                    </div>
                    {mode === 'group' && selected.includes(u.uid) && (
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7" /></svg>
                    )}
                </div>
                ))
            )}
          </div>
        </div>

        {mode === 'group' && (
            <div className="p-6 bg-slate-50 dark:bg-slate-800/50 rounded-b-[2.5rem]">
            <button 
                onClick={handleCreateGroup}
                disabled={!name.trim() || selected.length === 0 || loading}
                className="w-full py-4 bg-indigo-500 text-white rounded-2xl font-bold shadow-lg shadow-indigo-500/20 active:scale-95 transition-all disabled:opacity-50"
            >
                {loading ? 'Creating...' : `Create Group (${selected.length})`}
            </button>
            </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { CallSession, CallStatus } from '../../types';
import { updateCallStatus, getCallById, updateCallSignal, addIceCandidate, subscribeToCall } from '../../firebase';
import { hasPremiumAccess, ADMIN_STYLE } from '../../premiumUtils';

interface CallModalProps {
  session: CallSession;
  onHangUp: () => void;
}

const SERVERS = {
  iceServers: [
    { urls: ['stun:stun1.l.google.com:19302', 'stun:stun2.l.google.com:19302'] }
  ]
};

export const CallModal: React.FC<CallModalProps> = ({ session, onHangUp }) => {
  const [status, setStatus] = useState<CallStatus | 'calling' | 'denied'>(session.isIncoming ? 'ringing' : 'calling');
  const [isMuted, setIsMuted] = useState(false);
  const [isVideoOff, setIsVideoOff] = useState(session.type === 'voice');
  const [duration, setDuration] = useState(0);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  const localVideoRef = useRef<HTMLVideoElement>(null);
  const remoteVideoRef = useRef<HTMLVideoElement>(null);
  const remoteAudioRef = useRef<HTMLAudioElement>(null);
  const ringtoneRef = useRef<HTMLAudioElement | null>(null);

  const pc = useRef<RTCPeerConnection | null>(null);
  const localStream = useRef<MediaStream | null>(null);

  // Premium Checks
  // Check if Caller (partner) is Admin or Premium to show THEIR custom styling to ME
  const isPartnerPremium = hasPremiumAccess(session.partner, 'call_effects');
  const isPartnerAdmin = session.partner.isAdmin;

  // Initialize Ringtone
  useEffect(() => {
    if (session.isIncoming && status === 'ringing') {
      try {
        // Use custom ringtone if partner is Premium/Admin
        const ringtoneUrl = (isPartnerPremium || isPartnerAdmin) 
            ? "https://cdn.pixabay.com/download/audio/2021/08/09/audio_88447e769f.mp3?filename=orchestral-logo-opener-11532.mp3" // Premium Tone
            : "https://cdn.pixabay.com/download/audio/2022/03/24/audio_c8c8a73467.mp3?filename=smartphone-ringtone-6260.mp3"; // Standard Tone

        const audio = new Audio(ringtoneUrl);
        audio.loop = true;
        audio.play().catch(e => console.warn("Autoplay blocked for ringtone", e));
        ringtoneRef.current = audio;
      } catch (e) {}
    } else {
      if (ringtoneRef.current) {
        ringtoneRef.current.pause();
        ringtoneRef.current = null;
      }
    }
    return () => {
      if (ringtoneRef.current) {
        ringtoneRef.current.pause();
      }
    };
  }, [session.isIncoming, status, isPartnerPremium, isPartnerAdmin]);

  const handleMediaError = (err: any) => {
    console.error("Media/WebRTC Error:", err);
    setStatus('denied');

    if (err.name === 'NotAllowedError' || err.name === 'PermissionDeniedError') {
        setErrorMsg("Permission denied. Please allow camera/microphone access.");
    } else if (err.name === 'NotFoundError') {
        setErrorMsg("No camera or microphone found.");
    } else if (err.name === 'NotReadableError') {
        setErrorMsg("Hardware is being used by another app.");
    } else if (!navigator.mediaDevices && window.location.protocol === 'http:' && window.location.hostname !== 'localhost') {
        setErrorMsg("Calls require HTTPS secure connection.");
    } else {
        setErrorMsg("Failed to access media devices.");
    }
  };

  // 1. Initialize Peer Connection & Local Stream (For Caller)
  useEffect(() => {
    const init = async () => {
      try {
        // Check for secure context support
        if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
            throw new Error("MediaDevices API not supported (requires HTTPS)");
        }

        const stream = await navigator.mediaDevices.getUserMedia({ 
            audio: true, 
            video: session.type === 'video' ? { facingMode: 'user' } : false 
        });
        localStream.current = stream;

        if (localVideoRef.current) {
            localVideoRef.current.srcObject = stream;
            localVideoRef.current.muted = true;
        }

        pc.current = new RTCPeerConnection(SERVERS);

        stream.getTracks().forEach(track => {
            if (pc.current && localStream.current) pc.current.addTrack(track, localStream.current);
        });

        pc.current.ontrack = (event) => {
            const track = event.track;
            const remoteStream = new MediaStream([track]);

            if (track.kind === 'video') {
                if (remoteVideoRef.current) remoteVideoRef.current.srcObject = remoteStream;
            } else if (track.kind === 'audio') {
                if (remoteAudioRef.current) {
                    remoteAudioRef.current.srcObject = remoteStream;
                    remoteAudioRef.current.play().catch(e => console.error("Remote audio play error", e));
                }
            }
        };

        pc.current.onicecandidate = (event) => {
            if (event.candidate) {
                addIceCandidate(session.id, event.candidate, session.isIncoming ? 'callee' : 'caller');
            }
        };

        if (!session.isIncoming) {
            const offer = await pc.current.createOffer();
            await pc.current.setLocalDescription(offer);
            await updateCallSignal(session.id, { offer });
        }

      } catch (err) {
        handleMediaError(err);
      }
    };

    if (!session.isIncoming) {
        init();
    }

    return () => {
       if(localStream.current) localStream.current.getTracks().forEach(t => t.stop());
       if(pc.current) pc.current.close();
    };
  }, []);

  // 2. Listen for Signaling Changes
  useEffect(() => {
    const unsubscribe = subscribeToCall(session.id, async (data) => {
        if (!data) return;

        if (data.status === 'ended' || data.status === 'rejected') {
            onHangUp();
        } else if (data.status === 'accepted') {
            setStatus('accepted');
        }

        if (!pc.current) return;

        if (!session.isIncoming && data.answer && !pc.current.currentRemoteDescription) {
            try {
                const answer = new RTCSessionDescription(data.answer);
                await pc.current.setRemoteDescription(answer);
            } catch (e) { console.error("Set Remote Desc Error", e); }
        }

        const newCandidates = session.isIncoming ? data.callerCandidates : data.calleeCandidates;
        if (newCandidates && newCandidates.length > 0) {
           newCandidates.forEach(async (c: any) => {
               try { await pc.current?.addIceCandidate(new RTCIceCandidate(c)); } catch(e) {}
           });
        }
    });
    return () => unsubscribe();
  }, [session.id, session.isIncoming]);

  const handleAccept = async () => {
    try {
        if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
            throw new Error("MediaDevices API not supported");
        }

        const stream = await navigator.mediaDevices.getUserMedia({ 
            audio: true, 
            video: session.type === 'video' 
        });
        localStream.current = stream;
        if (localVideoRef.current) {
            localVideoRef.current.srcObject = stream;
            localVideoRef.current.muted = true;
        }

        pc.current = new RTCPeerConnection(SERVERS);

        stream.getTracks().forEach(track => pc.current?.addTrack(track, stream));

        pc.current.ontrack = (event) => {
            const track = event.track;
            const remoteStream = new MediaStream([track]);
            if (track.kind === 'video' && remoteVideoRef.current) {
                remoteVideoRef.current.srcObject = remoteStream;
            } else if (track.kind === 'audio' && remoteAudioRef.current) {
                remoteAudioRef.current.srcObject = remoteStream;
                remoteAudioRef.current.play().catch(console.error);
            }
        };

        pc.current.onicecandidate = (event) => {
            if (event.candidate) addIceCandidate(session.id, event.candidate, 'callee');
        };

        const callData = await getCallById(session.id);
        if (callData?.offer) {
            await pc.current.setRemoteDescription(new RTCSessionDescription(callData.offer));
            const answer = await pc.current.createAnswer();
            await pc.current.setLocalDescription(answer);

            await updateCallSignal(session.id, { answer });
            await updateCallStatus(session.id, 'accepted');
            setStatus('accepted');
        }
    } catch(err) {
        handleMediaError(err);
    }
  };

  const handleDecline = async () => {
    await updateCallStatus(session.id, 'rejected');
    onHangUp();
  };

  const toggleMute = () => {
    if (localStream.current) {
        const track = localStream.current.getAudioTracks()[0];
        if (track) {
            track.enabled = !track.enabled;
            setIsMuted(!track.enabled);
        }
    }
  };

  const toggleVideo = () => {
    if (localStream.current) {
        const track = localStream.current.getVideoTracks()[0];
        if (track) {
            track.enabled = !track.enabled;
            setIsVideoOff(!track.enabled);
        }
    }
  };

  useEffect(() => {
    let t: any;
    if (status === 'accepted') t = setInterval(() => setDuration(s => s + 1), 1000);
    return () => clearInterval(t);
  }, [status]);

  const formatDuration = (s: number) => {
    const mins = Math.floor(s / 60);
    const secs = s % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  // Determine Background Style based on Premium Status
  const getBackgroundClass = () => {
      if (isPartnerAdmin) return "bg-gradient-to-br from-slate-900 via-yellow-900/40 to-black";
      if (isPartnerPremium) return "bg-gradient-to-br from-indigo-900 via-purple-900 to-black";
      return "bg-slate-950";
  };

  return (
    <div className={`fixed inset-0 z-[1000] flex flex-col items-center justify-center text-white overflow-hidden animate-in fade-in duration-500 ${getBackgroundClass()}`}>

      {/* Remote Video (Full Screen) */}
      <video 
        ref={remoteVideoRef} 
        autoPlay 
        playsInline 
        className={`absolute inset-0 w-full h-full object-cover z-0 ${session.type === 'voice' ? 'hidden' : ''}`}
      />

      {/* Dedicated Audio Element for Voice */}
      <audio ref={remoteAudioRef} autoPlay />

      {/* Background Partner Blur with Premium Pulse */}
      <div className={`absolute inset-0 opacity-40 blur-[50px] pointer-events-none bg-slate-900 z-0 ${status === 'accepted' && session.type === 'video' ? 'opacity-0' : 'opacity-100'}`}>
        <img src={session.partner.photoURL} className="w-full h-full object-cover" alt="" />
      </div>

      {/* Error UI Overlay */}
      {status === 'denied' && (
          <div className="absolute inset-0 z-50 bg-slate-950/90 flex flex-col items-center justify-center p-6 text-center animate-in zoom-in-95">
              <div className="w-20 h-20 bg-red-500/10 text-red-500 rounded-full flex items-center justify-center mb-6 border border-red-500/20">
                  <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M18.364 18.364A9 9 0 005.636 5.636m12.728 12.728L5.636 5.636" /></svg>
              </div>
              <h3 className="text-2xl font-bold text-white mb-2">Call Failed</h3>
              <p className="text-slate-400 mb-8 max-w-xs leading-relaxed">{errorMsg || "Unable to access media devices."}</p>
              <button 
                onClick={onHangUp} 
                className="px-8 py-3 bg-white text-slate-900 rounded-2xl font-bold hover:bg-slate-200 transition-all shadow-lg active:scale-95"
              >
                Close
              </button>
          </div>
      )}

      {/* Main UI Overlay */}
      {status !== 'denied' && (
        <div className="relative z-10 flex flex-col items-center w-full max-w-lg px-6 h-full py-12 justify-between">
            {/* Header / Info */}
            <div className="text-center mt-10">
                {status !== 'accepted' && (
                    <div className="relative w-32 h-32 mx-auto mb-6">
                        <div className={`w-full h-full rounded-full overflow-hidden border-4 shadow-2xl ${isPartnerAdmin ? ADMIN_STYLE.border : (isPartnerPremium ? 'border-purple-500' : 'border-white/10')}`}>
                            <img src={session.partner.photoURL} className="w-full h-full object-cover" alt="" />
                        </div>
                        {(isPartnerAdmin || isPartnerPremium) && (
                            <div className="absolute -bottom-2 -right-2 bg-black/50 backdrop-blur-md p-2 rounded-full border border-white/20">
                                <span className="text-2xl">{isPartnerAdmin ? '👑' : '💎'}</span>
                            </div>
                        )}
                        {/* Premium Glow Ring */}
                        {(isPartnerAdmin || isPartnerPremium) && (
                            <div className={`absolute -inset-4 rounded-full -z-10 animate-pulse-slow ${isPartnerAdmin ? 'bg-yellow-500/20' : 'bg-purple-500/20'}`}></div>
                        )}
                    </div>
                )}

                <h2 className={`text-3xl font-black tracking-tight drop-shadow-md ${isPartnerAdmin ? ADMIN_STYLE.text : ''}`}>
                    {session.partner.name}
                </h2>

                <p className="text-white/80 font-bold tracking-[0.2em] uppercase text-xs mt-2 bg-black/20 inline-block px-4 py-1 rounded-full backdrop-blur-md">
                    {status === 'accepted' ? formatDuration(duration) : status === 'calling' ? 'Calling...' : 'Incoming Call...'}
                </p>
            </div>

            {/* Local Video Preview */}
            {status === 'accepted' && session.type === 'video' && (
                <div className="w-32 h-48 bg-black rounded-2xl overflow-hidden shadow-2xl border border-white/20 absolute top-6 right-6 z-20">
                    <video ref={localVideoRef} autoPlay muted playsInline className={`w-full h-full object-cover mirror ${isVideoOff ? 'hidden' : ''}`} />
                    {isVideoOff && <div className="w-full h-full flex items-center justify-center text-xs text-white/50 uppercase font-bold">Cam Off</div>}
                </div>
            )}

            {/* Controls */}
            <div className="flex items-center gap-6 mb-8">
                {/* INCOMING CALL UI */}
                {status === 'ringing' && session.isIncoming ? (
                    <>
                        <button onClick={handleDecline} className="flex flex-col items-center gap-2 group">
                            <div className="p-6 bg-red-600 rounded-full shadow-lg group-hover:scale-110 transition-transform">
                                <svg className="w-8 h-8 rotate-[135deg]" fill="currentColor" viewBox="0 0 24 24"><path d="M6.62 10.79c1.44 2.83 3.76 5.14 6.59 6.59l2.2-2.2c.27-.27.67-.36 1.02-.24 1.12.37 2.33.57 3.57.57.55 0 1 .45 1 1V20c0 .55-.45 1-1 1-9.39 0-17-7.61-17-17 0-.55.45-1 1-1h3.5c.55 0 1 .45 1 1 0 1.25.2 2.45.57 3.57.11.35.03.74-.25 1.02l-2.2 2.2z" /></svg>
                            </div>
                            <span className="text-xs font-bold uppercase tracking-widest">Decline</span>
                        </button>
                        <button onClick={handleAccept} className="flex flex-col items-center gap-2 group">
                            <div className="p-6 bg-green-500 rounded-full shadow-lg group-hover:scale-110 transition-transform animate-pulse">
                                <svg className="w-8 h-8" fill="currentColor" viewBox="0 0 24 24"><path d="M6.62 10.79c1.44 2.83 3.76 5.14 6.59 6.59l2.2-2.2c.27-.27.67-.36 1.02-.24 1.12.37 2.33.57 3.57.57.55 0 1 .45 1 1V20c0 .55-.45 1-1 1-9.39 0-17-7.61-17-17 0-.55.45-1 1-1h3.5c.55 0 1 .45 1 1 0 1.25.2 2.45.57 3.57.11.35.03.74-.25 1.02l-2.2 2.2z" /></svg>
                            </div>
                            <span className="text-xs font-bold uppercase tracking-widest">Accept</span>
                        </button>
                    </>
                ) : (
                    /* ONGOING / OUTGOING UI */
                    <>
                        <button onClick={toggleMute} className={`p-4 rounded-full transition-all ${isMuted ? 'bg-white text-slate-900' : 'bg-white/20 hover:bg-white/30 backdrop-blur-md'}`}>
                            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d={isMuted ? "M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3zM5.5 5.5l13 13" : "M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z"} /></svg>
                        </button>
                        <button onClick={handleDecline} className="p-6 bg-red-600 rounded-full shadow-lg hover:scale-110 transition-transform">
                            <svg className="w-8 h-8 rotate-[135deg]" fill="currentColor" viewBox="0 0 24 24"><path d="M6.62 10.79c1.44 2.83 3.76 5.14 6.59 6.59l2.2-2.2c.27-.27.67-.36 1.02-.24 1.12.37 2.33.57 3.57.57.55 0 1 .45 1 1V20c0 .55-.45 1-1 1-9.39 0-17-7.61-17-17 0-.55.45-1 1-1h3.5c.55 0 1 .45 1 1 0 1.25.2 2.45.57 3.57.11.35.03.74-.25 1.02l-2.2 2.2z" /></svg>
                        </button>
                        {session.type === 'video' && (
                            <button onClick={toggleVideo} className={`p-4 rounded-full transition-all ${isVideoOff ? 'bg-white text-slate-900' : 'bg-white/20 hover:bg-white/30 backdrop-blur-md'}`}>
                                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
                            </button>
                        )}
                    </>
                )}
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { User, Story } from '../../types';
import { addStory } from '../../firebase';
import { hasPremiumAccess } from '../../premiumUtils';

interface StoryUploadProps {
  currentUser: User;
  onClose: () => void;
}

export const StoryUpload: React.FC<StoryUploadProps> = ({ currentUser, onClose }) => {
  const [file, setFile] = useState<File | null>(null);
  const [preview, setPreview] = useState<string | null>(null);
  const [mediaType, setMediaType] = useState<'image' | 'video' | null>(null);
  const [caption, setCaption] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Premium Check
  const hasLongStatus = hasPremiumAccess(currentUser, 'status_duration_boost');

  useEffect(() => {
    return () => {
      if (preview && preview.startsWith('blob:')) {
        URL.revokeObjectURL(preview);
      }
    };
  }, [preview]);

  // Helper to compress images using Canvas
  const compressImage = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = (event) => {
        const img = new Image();
        img.src = event.target?.result as string;
        img.onload = () => {
          const canvas = document.createElement('canvas');
          const MAX_WIDTH = 1080;
          const MAX_HEIGHT = 1920;
          let width = img.width;
          let height = img.height;

          if (width > height) {
            if (width > MAX_WIDTH) {
              height *= MAX_WIDTH / width;
              width = MAX_WIDTH;
            }
          } else {
            if (height > MAX_HEIGHT) {
              width *= MAX_HEIGHT / height;
              height = MAX_HEIGHT;
            }
          }

          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          ctx?.drawImage(img, 0, 0, width, height);

          // Compress to JPEG with 0.6 quality (High enough for mobile, small enough for storage)
          const dataUrl = canvas.toDataURL('image/jpeg', 0.6);
          resolve(dataUrl);
        };
        img.onerror = reject;
      };
      reader.onerror = reject;
    });
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selected = e.target.files?.[0];
    if (!selected) return;

    // Limit videos to 5MB (free) or 15MB (premium) for browser memory limits
    // In a real app with cloud storage, we'd allow much larger.
    const limit = hasLongStatus ? 15 : 5;
    if (selected.size > limit * 1024 * 1024) {
      alert(`File is too large. Limit is ${limit}MB.`);
      e.target.value = '';
      return;
    }

    const isVideo = selected.type.startsWith('video/');
    setMediaType(isVideo ? 'video' : 'image');
    setFile(selected);

    if (preview && preview.startsWith('blob:')) {
      URL.revokeObjectURL(preview);
    }

    const objectUrl = URL.createObjectURL(selected);
    setPreview(objectUrl);
    e.target.value = '';
  };

  const handleUpload = async () => {
    if (!file || !mediaType) return;
    setIsUploading(true);

    try {
      let mediaData: string;

      if (mediaType === 'image') {
        mediaData = await compressImage(file);
      } else {
        // For videos, we use standard Base64
        mediaData = await new Promise<string>((resolve, reject) => {
          const reader = new FileReader();
          reader.onload = () => resolve(reader.result as string);
          reader.onerror = () => reject(new Error("Failed to read video"));
          reader.readAsDataURL(file);
        });
      }

      const newStory: Story = {
        id: crypto.randomUUID(),
        userId: currentUser.uid,
        userName: currentUser.name,
        userPhoto: currentUser.photoURL,
        mediaUrl: mediaData,
        mediaType: mediaType,
        caption: caption,
        timestamp: Date.now()
      };

      await addStory(newStory);
      onClose();
    } catch (e) {
      console.error("Upload error:", e);
      alert("Storage full or file too large for browser.");
    } finally {
      setIsUploading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] bg-slate-950 flex flex-col items-center justify-center p-4 overflow-hidden">
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleFileChange} 
        accept="image/*,video/*" 
        className="hidden" 
      />

      <button 
        onClick={onClose} 
        className="absolute top-6 left-6 p-3 text-white hover:bg-white/10 rounded-full transition-all z-[110]"
      >
        <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
        </svg>
      </button>

      {!preview ? (
        <div className="text-center space-y-6 animate-in zoom-in-95 duration-300">
          <div className="w-24 h-24 bg-indigo-500/20 rounded-full flex items-center justify-center mx-auto mb-6">
            <svg className="w-12 h-12 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" />
            </svg>
          </div>
          <h2 className="text-2xl font-bold text-white">Share a Moment</h2>
          <p className="text-white/40 max-w-xs mx-auto text-sm">
            {hasLongStatus ? "You can upload longer high-quality videos." : "Basic upload limit enabled. Upgrade for 3x boost."}
          </p>
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="px-8 py-4 bg-indigo-500 hover:bg-indigo-600 text-white rounded-2xl font-bold shadow-xl shadow-indigo-500/20 active:scale-95 transition-all"
          >
            Choose Media
          </button>
        </div>
      ) : (
        <div className="w-full max-w-md flex flex-col gap-4 animate-in slide-in-from-bottom-10 duration-500">
          <div className="relative aspect-[9/16] bg-black rounded-3xl overflow-hidden shadow-2xl ring-1 ring-white/10">
            {mediaType === 'video' ? (
              <video 
                key={preview}
                src={preview} 
                className="w-full h-full object-contain" 
                autoPlay 
                muted 
                loop 
                playsInline 
              />
            ) : (
              <img src={preview} alt="Preview" className="w-full h-full object-contain" />
            )}

            <div className="absolute bottom-0 inset-x-0 p-6 bg-gradient-to-t from-black/90 via-black/40 to-transparent">
               <textarea 
                value={caption}
                onChange={(e) => setCaption(e.target.value)}
                placeholder="Add a caption..."
                className="w-full bg-white/10 backdrop-blur-md border border-white/20 rounded-2xl p-4 text-white placeholder-white/40 focus:ring-2 focus:ring-indigo-500 outline-none resize-none transition-all text-sm"
                rows={2}
              />
            </div>
          </div>

          <div className="flex gap-4">
            <button 
              onClick={() => { setFile(null); setPreview(null); setMediaType(null); }}
              className="flex-1 py-4 bg-white/10 hover:bg-white/20 text-white rounded-2xl font-bold transition-all text-sm"
            >
              Cancel
            </button>
            <button 
              onClick={handleUpload}
              disabled={isUploading}
              className="flex-[2] py-4 bg-indigo-500 hover:bg-indigo-600 disabled:opacity-50 text-white rounded-2xl font-bold shadow-xl shadow-indigo-500/20 transition-all flex items-center justify-center gap-2 text-sm"
            >
              {isUploading ? (
                <>
                  <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                  <span>Processing...</span>
                </>
              ) : (
                'Post Story'
              )}
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
