import React, { useState } from 'react';
import { PLANS, getBadgeIcon, ADMIN_STYLE, hasPremiumAccess, getPlanTagStyle } from '../../premiumUtils';
import { User, PlanType, PremiumCustomization } from '../../types';
import { activateSubscription, updatePremiumCustomization } from '../../firebase';

interface PremiumStoreProps {
  currentUser: User;
  onClose: () => void;
}

export const PremiumStore: React.FC<PremiumStoreProps> = ({ currentUser, onClose }) => {
  const [activeTab, setActiveTab] = useState<'plans' | 'decorations'>('plans');
  const [loading, setLoading] = useState(false);
  const [previewPlan, setPreviewPlan] = useState<PlanType>('vvip');

  // Helper to handle purchase/activation
  const handlePurchase = async (planId: PlanType) => {
    setLoading(true);
    // Simulate API call
    setTimeout(async () => {
      await activateSubscription(currentUser.uid, planId);
      alert(`Successfully upgraded to ${PLANS[planId.toUpperCase() as keyof typeof PLANS].name}!`);
      setLoading(false);
      window.location.reload();
    }, 1500);
  };

  const handleApplyDecoration = async (type: keyof PremiumCustomization, value: any, requiredPlan: string) => {
    if (!hasPremiumAccess(currentUser, 'decoration') && !currentUser.isAdmin) {
       alert(`This item requires the ${requiredPlan} plan or higher.`);
       return;
    }
    await updatePremiumCustomization(currentUser.uid, { ...currentUser.premiumCustomization, [type]: value });
  };

  const PlanCard: React.FC<{ planKey: string }> = ({ planKey }) => {
    const plan = PLANS[planKey as keyof typeof PLANS];
    const isCurrent = currentUser.subscription?.plan === plan.id && currentUser.subscription.isActive;
    const isHigher = false; // Logic to check if this is an upgrade would go here

    return (
      <div className={`relative p-5 rounded-3xl border-2 transition-all duration-300 overflow-hidden ${isCurrent ? 'border-green-500 bg-green-500/5' : 'border-slate-100 dark:border-slate-800 hover:border-indigo-500 dark:hover:border-indigo-500'}`}>
        {isCurrent && (
            <div className="absolute top-0 right-0 bg-green-500 text-white text-[10px] font-bold px-3 py-1 rounded-bl-xl uppercase tracking-widest">
                Active
            </div>
        )}

        <div className="flex justify-between items-start mb-4">
            <div>
                <h3 className={`text-xl font-black ${plan.color} flex items-center gap-2`}>
                    {getBadgeIcon(plan.id as PlanType)} {plan.name}
                </h3>
                <p className="text-xs text-slate-500 font-bold uppercase tracking-wider">{plan.durationDays} Days Validity</p>
            </div>
            <div className="text-right">
                <span className="text-2xl font-black text-slate-900 dark:text-white">₹{plan.price}</span>
            </div>
        </div>

        {/* Feature Preview based on Plan */}
        <div className="bg-slate-100 dark:bg-slate-900/50 rounded-xl p-3 mb-4 space-y-2">
            <div className="flex items-center gap-3">
                <div className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase ${getPlanTagStyle(plan.id as PlanType)}`}>
                    {plan.name} Tag
                </div>
                <span className="text-xs text-slate-500">Profile Badge</span>
            </div>
            {plan.id === 'vvip' && (
                <div className="flex items-center gap-3">
                    <div className="w-4 h-4 rounded-full bg-gradient-to-r from-indigo-500 to-purple-500 shadow-[0_0_10px_rgba(168,85,247,0.6)]"></div>
                    <span className="text-xs text-slate-500">Neon Glow Effects</span>
                </div>
            )}
        </div>

        <button 
            onClick={() => handlePurchase(plan.id as PlanType)}
            disabled={loading || isCurrent}
            className={`w-full py-3 rounded-xl font-bold text-sm transition-all active:scale-95 ${isCurrent ? 'bg-slate-200 dark:bg-slate-800 text-slate-500' : 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-lg shadow-indigo-500/20'}`}
        >
            {loading ? 'Processing...' : isCurrent ? 'Current Plan' : 'Upgrade'}
        </button>
      </div>
    );
  };

  return (
    <div className="fixed inset-0 z-[300] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md animate-in zoom-in-95">
      <div className="bg-white dark:bg-slate-950 w-full max-w-4xl h-[85vh] rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden relative border border-white/10">

        {/* Header */}
        <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-white/50 dark:bg-slate-900/50 backdrop-blur-xl sticky top-0 z-10">
            <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-gradient-to-br from-indigo-500 via-purple-500 to-pink-500 rounded-2xl flex items-center justify-center shadow-lg text-white text-2xl">
                    🛍️
                </div>
                <div>
                    <h2 className="text-2xl font-black text-slate-900 dark:text-white tracking-tight">ROXX Store</h2>
                    <p className="text-xs text-slate-500 font-bold uppercase tracking-widest">Premium Upgrades & Cosmetics</p>
                </div>
            </div>
            <button onClick={onClose} className="p-3 bg-slate-100 dark:bg-slate-800 rounded-full hover:bg-slate-200 transition-colors">
                <svg className="w-6 h-6 text-slate-600 dark:text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
            </button>
        </div>

        <div className="flex flex-1 overflow-hidden">
            {/* Sidebar Navigation for Store */}
            <div className="w-64 bg-slate-50 dark:bg-slate-900 p-4 border-r border-slate-100 dark:border-slate-800 flex flex-col gap-2 hidden md:flex">
                <button 
                    onClick={() => setActiveTab('plans')}
                    className={`p-4 rounded-2xl text-left font-bold text-sm transition-all flex items-center gap-3 ${activeTab === 'plans' ? 'bg-indigo-500 text-white shadow-lg shadow-indigo-500/30' : 'text-slate-500 hover:bg-slate-200 dark:hover:bg-slate-800'}`}
                >
                    <span>💎</span> Plans & Subscriptions
                </button>
                <button 
                    onClick={() => setActiveTab('decorations')}
                    className={`p-4 rounded-2xl text-left font-bold text-sm transition-all flex items-center gap-3 ${activeTab === 'decorations' ? 'bg-pink-500 text-white shadow-lg shadow-pink-500/30' : 'text-slate-500 hover:bg-slate-200 dark:hover:bg-slate-800'}`}
                >
                    <span>🎨</span> Profile Decorations
                </button>

                <div className="mt-auto p-4 bg-gradient-to-br from-slate-800 to-black rounded-3xl text-white text-center relative overflow-hidden">
                    <div className="relative z-10">
                        <p className="text-[10px] font-bold text-yellow-400 uppercase tracking-widest mb-1">Admin Status</p>
                        {currentUser.isAdmin ? (
                            <div className="flex flex-col items-center">
                                <span className="text-3xl mb-2">👑</span>
                                <span className="font-black text-lg">UNLOCKED</span>
                                <p className="text-[10px] opacity-70">You own everything</p>
                            </div>
                        ) : (
                            <div className="flex flex-col items-center opacity-50">
                                <span className="text-2xl mb-2">🔒</span>
                                <span className="font-bold">LOCKED</span>
                            </div>
                        )}
                    </div>
                </div>
            </div>

            {/* Main Content Area */}
            <div className="flex-1 overflow-y-auto p-6 md:p-10 scroll-smooth">
                {/* Mobile Tabs */}
                <div className="flex md:hidden mb-6 bg-slate-100 dark:bg-slate-800 p-1 rounded-2xl">
                    <button onClick={() => setActiveTab('plans')} className={`flex-1 py-3 rounded-xl font-bold text-xs uppercase tracking-widest transition-all ${activeTab === 'plans' ? 'bg-white dark:bg-slate-700 shadow-sm' : 'text-slate-400'}`}>Plans</button>
                    <button onClick={() => setActiveTab('decorations')} className={`flex-1 py-3 rounded-xl font-bold text-xs uppercase tracking-widest transition-all ${activeTab === 'decorations' ? 'bg-white dark:bg-slate-700 shadow-sm' : 'text-slate-400'}`}>Decorations</button>
                </div>

                {activeTab === 'plans' ? (
                    <div className="space-y-8">
