const generateUUID = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    try {
      return crypto.randomUUID();
    } catch (e) { /* fallback */ }
  }
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

// Robust sanitization to handle circular references, DOM nodes, and complex objects
export const sanitizeData = (data: any, seen = new WeakSet()): any => {
  if (data === null || data === undefined) return null;
  if (typeof data !== 'object') return data;
  if (data instanceof Date) return data.getTime();

  // Detect DOM Nodes
  if (data.nodeType && typeof data.cloneNode === 'function') return '[DOM Node]';
  // Detect React Elements
  if (data.$$typeof) return '[React Element]';
  if (data._reactInternals) return '[React Internals]';

  // Detect Circular References
  if (seen.has(data)) return '[Circular]';
  seen.add(data);

  if (Array.isArray(data)) {
    return data.map(item => sanitizeData(item, seen));
  }

  const out: any = {};
  for (const k in data) {
    // Skip internal React/Firebase/System properties
    if (k.startsWith('__react') || k === '_owner' || k === 'stateNode' || k === 'source' || k === 'constructor') continue;

    if (Object.prototype.hasOwnProperty.call(data, k)) {
      const val = data[k];
      if (val !== undefined && typeof val !== 'function') {
        out[k] = sanitizeData(val, seen);
      }
    }
  }
  return out;
};

// Safe JSON Stringify helper to be used across the app
export const safeJsonStringify = (value: any) => {
  try {
    return JSON.stringify(sanitizeData(value));
  } catch (e) {
    console.error("JSON Stringify failed even after sanitization", e);
    return "{}";
  }
};

