export const addNote = async (userId: string, userName: string, userPhoto: string, text: string) => {
  const noteId = `note_${userId}`;
  const note = { id: noteId, userId, userName, userPhoto, text, timestamp: Date.now() };
  await setDoc(doc(db, "notes", noteId), note);
  return note;
};

export const getNotes = async () => {
  const yesterday = Date.now() - 86400000;
  const q = query(collection(db, "notes"), where("timestamp", ">", yesterday));
  const snapshot = await getDocs(q);
  return snapshot.docs.map(doc => doc.data());
};

export const saveMediaToGallery = async (userId: string, mediaUrl: string, mediaType: 'image' | 'video', senderName: string) => {
  const id = 'saved_' + generateUUID();
  const item = { id, userId, mediaUrl, mediaType, savedAt: Date.now(), originalSenderName: senderName };
  await setDoc(doc(db, "saved_media", id), item);
};

export const getSavedGallery = async (userId: string) => {
  const q = query(collection(db, "saved_media"), where("userId", "==", userId));
  const snapshot = await getDocs(q);
  return snapshot.docs.map(doc => doc.data()).sort((a: any, b: any) => b.savedAt - a.savedAt);
};

export const deleteSavedMedia = async (id: string) => {
  await deleteDoc(doc(db, "saved_media", id));
};

export const admin_getAllUsers = async () => getAllUsers();
export const admin_toggleAdminAccess = async (uid: string) => {
  const userRef = doc(db, "users", uid);
  const snap = await getDoc(userRef);
  if (snap.exists()) await updateDoc(userRef, { isAdmin: !snap.data().isAdmin });
};
export const admin_toggleGlobalBlock = async (uid: string) => {
  const userRef = doc(db, "users", uid);
  const snap = await getDoc(userRef);
  if (snap.exists()) await updateDoc(userRef, { isGloballyBlocked: !snap.data().isGloballyBlocked });
};
export const admin_deleteUser = async (uid: string) => {
  await deleteDoc(doc(db, "users", uid));
};
export const admin_getStats = async () => {
  const u = await getDocs(collection(db, "users"));
  const m = await getDocs(collection(db, "messages"));
  const c = await getDocs(collection(db, "chats"));
  const s = await getDocs(collection(db, "stories"));
  return { users: u.size, messages: m.size, chats: c.size, stories: s.size };
};
export const blockUser = async (myUid: string, targetUid: string) => {
  await updateDoc(doc(db, "users", myUid), { blockedUsers: arrayUnion(targetUid) });
};
export const unblockUser = async (myUid: string, targetUid: string) => {
  await updateDoc(doc(db, "users", myUid), { blockedUsers: arrayRemove(targetUid) });
};

import React, { useState, useEffect } from 'react';
import { useAuth } from '../../hooks/useAuth';
import { safeJsonStringify } from '../../firebase';

export const AuthView: React.FC = () => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  const { login, signup, googleSignIn } = useAuth();

  // Clear error when user starts typing again or switches modes
  useEffect(() => {
    if (error) setError(null);
  }, [email, password, name, isLogin]);

  const getFriendlyErrorMessage = (errCode: string) => {
    if (!errCode) return "An unexpected error occurred.";
    const code = errCode.toLowerCase();
    if (code.includes('wrong-password') || code.includes('incorrect-password')) return "Incorrect password. Please double-check your credentials.";
    if (code.includes('user-not-found')) return "No account found with this email. Please sign up or check for typos.";
    if (code.includes('email-already-in-use')) return "This email is already registered. Try signing in instead.";
    if (code.includes('invalid-email')) return "Please enter a valid email address.";
    if (code.includes('weak-password')) return "Password should be at least 6 characters.";
    if (code.includes('suspended') || code.includes('blocked')) return "This account has been suspended by an administrator.";
    return errCode.replace('Firebase: ', '').replace('auth/', '').split('-').join(' ');
  };

  const updateAccountsList = (user: any, pass: string) => {
    try {
        const stored = localStorage.getItem('roxx_accounts');
        let accounts = stored ? JSON.parse(stored) : [];

        // Remove existing entry for this UID to update it (e.g. name/photo change)
        accounts = accounts.filter((a: any) => a.uid !== user.uid);

        accounts.push({
            uid: user.uid,
            email: user.email,
            name: user.displayName || name || user.email?.split('@')[0] || 'User',
            photoURL: user.photoURL,
            pass: pass // Storing password locally as requested for fast switching simulation
        });

        localStorage.setItem('roxx_accounts', safeJsonStringify(accounts));
    } catch(e) { console.error("Failed to save account", e); }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setIsLoading(true);

    try {
      let userRes;
      if (isLogin) {
        userRes = await login(email, password);
      } else {
        if (name.trim().length < 2) throw new Error("Please enter your full name.");
        // Try signup
        try {
            const res = await signup(email, password, name);
            userRes = res.user;
        } catch (err: any) {
            if (err.message.includes('email-already-in-use')) {
                setIsLogin(true);
                const res = await login(email, password);
                userRes = res;
            } else throw err;
        }
      }

      if (userRes) {
          // Check if saved
          const stored = localStorage.getItem('roxx_accounts');
          const accounts = stored ? JSON.parse(stored) : [];

          if (!accounts.find((a: any) => a.uid === userRes.uid)) {
              if (window.confirm("Save this account for fast switching?")) {
                  updateAccountsList({ ...userRes, displayName: name || userRes.displayName }, password);
              }
          } else {
              // Update existing entry automatically to keep it fresh
              updateAccountsList({ ...userRes, displayName: name || userRes.displayName }, password);
          }
      }

    } catch (err: any) {
      const message = getFriendlyErrorMessage(err.message);
      setError(message.charAt(0).toUpperCase() + message.slice(1));
    } finally {
      setIsLoading(false);
    }
  };

  const handleGoogleSignIn = async () => {
    setError(null);
    setIsLoading(true);
    try {
      await googleSignIn();
    } catch (err: any) {
      setError(getFriendlyErrorMessage(err.message));
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="h-screen w-full flex items-center justify-center bg-gradient-to-br from-indigo-600 via-purple-600 to-pink-500 p-4">
      <div className="glass w-full max-w-md p-8 rounded-3xl shadow-2xl transition-all duration-500 hover:shadow-indigo-500/20">
        <div className="text-center mb-8">
          <div className="w-16 h-16 bg-white/20 rounded-2xl flex items-center justify-center mx-auto mb-4 border border-white/30">
            <svg className="w-10 h-10 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" />
            </svg>
          </div>
          <h1 className="text-3xl font-bold text-white mb-2 tracking-tight">ROXX CHATS</h1>
          <p className="text-white/70">Secure, Real-time messaging</p>
        </div>

        {error && (
          <div className="mb-6 p-4 bg-red-500/10 border border-red-500/30 rounded-2xl text-red-100 text-[13px] leading-relaxed flex items-start gap-3 animate-in slide-in-from-top-2">
            <svg className="w-5 h-5 shrink-0 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
            <span className="flex-1">{error}</span>
          </div>
        )}

        <form id="auth-form" onSubmit={handleSubmit} className="space-y-4">
          {!isLogin && (
            <div className="animate-in fade-in slide-in-from-top-2 duration-300">
              <label className="block text-white/80 text-[11px] font-black uppercase tracking-widest mb-1.5 ml-1">Full Name</label>
              <input 
                type="text" 
                required
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="John Doe"
                disabled={isLoading}
                className="w-full bg-white/10 border border-white/20 rounded-xl px-4 py-3 text-white placeholder-white/40 focus:outline-none focus:ring-2 focus:ring-white/30 transition-all disabled:opacity-50"
              />
            </div>
          )}
          <div>
            <label className="block text-white/80 text-[11px] font-black uppercase tracking-widest mb-1.5 ml-1">Email Address</label>
            <input 
              type="email" 
              required
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="you@example.com"
              disabled={isLoading}
              className="w-full bg-white/10 border border-white/20 rounded-xl px-4 py-3 text-white placeholder-white/40 focus:outline-none focus:ring-2 focus:ring-white/30 transition-all disabled:opacity-50"
            />
          </div>
          <div>
            <label className="block text-white/80 text-[11px] font-black uppercase tracking-widest mb-1.5 ml-1">Password</label>
            <input 
              type="password" 
              required
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="••••••••"
              disabled={isLoading}
              className="w-full bg-white/10 border border-white/20 rounded-xl px-4 py-3 text-white placeholder-white/40 focus:outline-none focus:ring-2 focus:ring-white/30 transition-all disabled:opacity-50"
            />
          </div>

          <button 
            type="submit" 
            disabled={isLoading}
            className="w-full bg-white text-indigo-600 font-bold py-4 rounded-xl hover:bg-slate-50 active:scale-95 transition-all shadow-xl flex items-center justify-center gap-2 disabled:opacity-70 disabled:active:scale-100"
          >
            {isLoading ? (
              <div className="w-5 h-5 border-2 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
            ) : (
              isLogin ? 'Sign In' : 'Create Account'
            )}
          </button>
        </form>

        <div className="mt-6 flex flex-col gap-3">
          <div className="flex items-center justify-center gap-4 py-2">
            <div className="h-px bg-white/10 flex-1"></div>
            <span className="text-white/30 text-[9px] font-black uppercase tracking-[0.2em]">Social Connect</span>
            <div className="h-px bg-white/10 flex-1"></div>
          </div>

          <button 
            onClick={handleGoogleSignIn}
            disabled={isLoading}
            className="w-full bg-white/10 border border-white/20 py-3 rounded-xl text-white text-sm font-medium hover:bg-white/20 transition-all flex items-center justify-center gap-3 disabled:opacity-50 shadow-inner"
          >
            <svg className="w-5 h-5" viewBox="0 0 24 24">
              <path fill="currentColor" d="M12.545,10.239v3.821h5.445c-0.712,2.315-2.647,3.972-5.445,3.972-3.332,0-6.033-2.701-6.033-6.032s2.701-6.032,6.033-6.032c1.498,0,2.866,0.549,3.921,1.453l2.814-2.814C17.503,2.988,15.139,2,12.545,2C7.021,2,2.543,6.477,2.543,12s4.478,10,10.002,10c8.396,0,10.249-7.85,9.426-11.748L12.545,10.239z"/>
            </svg>
            Continue with Google
          </button>
        </div>

        <button 
          onClick={() => {
            setIsLogin(!isLogin);
            setError(null);
          }}
          disabled={isLoading}
          className="w-full mt-8 text-white/50 hover:text-white text-sm font-bold transition-colors"
        >
          {isLogin ? "Need an account? Sign Up" : "Already registered? Sign In"}
        </button>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { User, PremiumCustomization } from '../../types';
import { useAuth } from '../../hooks/useAuth';
import { updateProfile, updatePremiumCustomization, safeJsonStringify } from '../../firebase';
import { hasPremiumAccess, getPlanDetails, ADMIN_STYLE } from '../../premiumUtils';
import { SubscriptionModal } from '../Premium/SubscriptionModal';

interface ProfilePanelProps {
  user: User;
  onClose: () => void;
  toggleDarkMode: () => void;
  isDarkMode: boolean;
  isTabMode?: boolean;
}

type ProfileViewMode = 'main' | 'edit' | 'settings' | 'privacy' | 'chats' | 'notifications' | 'language' | 'blocked' | 'wallpaper' | 'applock' | 'premium';

export const ProfilePanel: React.FC<ProfilePanelProps> = ({ user, onClose, toggleDarkMode, isDarkMode, isTabMode }) => {
  const { logout } = useAuth();
  const [viewMode, setViewMode] = useState<ProfileViewMode>('main');

  const [name, setName] = useState(user.name);
  const [username, setUsername] = useState(user.username || '');
  const [bio, setBio] = useState(user.bio || 'Available');
  const [lockPass, setLockPass] = useState(user.chatLockPassword || '');
  const [newPhoto, setNewPhoto] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [showSubModal, setShowSubModal] = useState(false);

  // Premium State
  const [customization, setCustomization] = useState<PremiumCustomization>(user.premiumCustomization || {});

  const [settings, setSettings] = useState(() => {
    try {
      const saved = localStorage.getItem('roxx_settings');
      return saved ? JSON.parse(saved) : {
        fontSize: 'medium',
        notificationsEnabled: true,
        notificationSound: true,
        language: 'English (US)',
        wallpaper: 'default',
        customWallpaperUrl: null
      };
    } catch (e) {
      return {
        fontSize: 'medium',
        notificationsEnabled: true,
        notificationSound: true,
        language: 'English (US)',
        wallpaper: 'default',
        customWallpaperUrl: null
      };
    }
  });

  useEffect(() => {
    localStorage.setItem('roxx_settings', safeJsonStringify(settings));
    window.dispatchEvent(new Event('roxx_settings_updated'));
  }, [settings]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handlePhotoSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      const img = new Image();
      img.src = event.target?.result as string;
      img.onload = () => {
        const canvas = document.createElement('canvas');
        canvas.width = 300;
        canvas.height = 300;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, 300, 300);
        setNewPhoto(canvas.toDataURL('image/jpeg', 0.7));
      };
    };
    reader.readAsDataURL(file);
  };

  const handleSave = async () => {
    if (!name.trim()) return;
    setIsSaving(true);
    try {
      await updateProfile(user, {
        name: name.trim(),
        username: username.trim(),
        bio: bio.trim(),
        chatLockPassword: lockPass.trim(),
        photoURL: newPhoto || user.photoURL
      });
      setViewMode('main');
    } catch (err) { alert("Error saving profile"); }
    finally { setIsSaving(false); }
  };

  const handleCustomizationUpdate = async (key: keyof PremiumCustomization, value: any) => {
      if (!hasPremiumAccess(user, 'decoration')) {
          if (!user.isAdmin) {
              setShowSubModal(true);
              return;
          }
      }

      const newCustom = { ...customization, [key]: value };
      setCustomization(newCustom);
      await updatePremiumCustomization(user.uid, newCustom);
  };

  const renderHeader = () => {
    const titles: Record<string, string> = {
      main: "Settings", edit: "Edit Profile", settings: "ROXX Settings",
      privacy: "Privacy", chats: "Chats", notifications: "Notifications",
      language: "App Language", blocked: "Blocked Contacts", wallpaper: "Chat Wallpaper",
      applock: "App Lock", premium: "Premium Store"
    };

    const backTarget: Record<string, ProfileViewMode> = {
      edit: 'main', settings: 'main', privacy: 'settings',
      chats: 'settings', notifications: 'settings', language: 'settings',
      blocked: 'privacy', wallpaper: 'chats', applock: 'privacy', premium: 'main'
    };

    return (
      <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between sticky top-0 bg-white/80 dark:bg-slate-900/80 backdrop-blur-md z-10">
        <div className="flex items-center gap-4">
          {viewMode !== 'main' && (
            <button onClick={() => setViewMode(backTarget[viewMode] || 'main')} className="p-2 -ml-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-all">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 19l-7-7 7-7" /></svg>
            </button>
          )}
          <h2 className="text-xl font-black tracking-tight">{titles[viewMode]}</h2>
        </div>
        {!isTabMode && viewMode === 'main' && (
          <button onClick={onClose} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-all">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        )}
      </div>
    );
  };

  const SettingsItem = ({ icon, title, subtitle, onClick, color = "indigo", toggle }: any) => (
    <button onClick={onClick} className="w-full flex items-center gap-4 p-4 hover:bg-slate-50 dark:hover:bg-slate-800/40 transition-all group border-b border-slate-50 dark:border-slate-800/50 last:border-0">
      <div className={`p-2.5 rounded-xl bg-${color}-500/10 text-${color}-500 group-hover:scale-110 transition-transform`}>
        {icon}
      </div>
      <div className="flex-1 text-left min-w-0">
        <p className="font-bold text-[13px] text-slate-900 dark:text-slate-100 leading-tight">{title}</p>
        {subtitle && <p className="text-[11px] font-medium text-slate-500 truncate mt-0.5">{subtitle}</p>}
      </div>
      {toggle !== undefined ? (
        <div className={`w-9 h-5 rounded-full transition-all relative ${toggle ? 'bg-indigo-500' : 'bg-slate-200 dark:bg-slate-700'}`}>
          <div className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all ${toggle ? 'left-5' : 'left-1'}`}></div>
        </div>
      ) : (
        <svg className="w-3.5 h-3.5 text-slate-300 group-hover:translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 5l7 7-7 7" />
        </svg>
      )}
    </button>
  );

  const renderContent = () => {
    switch (viewMode) {
      case 'premium':
          const BORDERS = ['border-indigo-500', 'border-pink-500', 'border-amber-400', 'border-green-500', 'border-white'];
          const NAME_COLORS = ['text-indigo-500', 'text-pink-500', 'text-amber-400', 'text-green-500', 'text-white'];

          return (
              <div className="space-y-8 animate-in slide-in-from-right-4">
                  <div className="p-6 bg-gradient-to-r from-indigo-600 to-purple-600 rounded-3xl text-white text-center shadow-lg relative overflow-hidden">
                      <div className="relative z-10">
                        <h3 className="text-2xl font-black mb-2">Premium Customization</h3>
                        <p className="text-xs font-bold opacity-80 mb-4">Make your profile shine across the app.</p>
                        {!user.isAdmin && !hasPremiumAccess(user, 'decoration') && (
                            <button onClick={() => setShowSubModal(true)} className="bg-white text-indigo-600 px-6 py-2 rounded-full font-bold text-xs uppercase tracking-widest shadow-lg">Upgrade Now</button>
                        )}
                        {user.isAdmin && <div className="inline-block bg-white/20 px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-widest">Admin Access Unlocked</div>}
                      </div>
                  </div>

                  {/* Border Selection */}
                  <div>
                      <h4 className="font-bold text-sm mb-3">Profile Border Glow</h4>
                      <div className="flex gap-4 overflow-x-auto pb-2 no-scrollbar">
                          {BORDERS.map(b => (
                              <button 
                                key={b}
                                onClick={() => handleCustomizationUpdate('borderColor', b)}
                                className={`w-12 h-12 rounded-full border-4 ${b} ${customization.borderColor === b ? 'ring-2 ring-offset-2 ring-indigo-500' : ''} shrink-0 bg-slate-800`}
                              />
                          ))}
                          <button onClick={() => handleCustomizationUpdate('borderColor', '')} className="w-12 h-12 rounded-full border border-slate-500 flex items-center justify-center shrink-0"><span className="text-xs">None</span></button>
                      </div>
                  </div>

                  {/* Username Color */}
                  <div>
                      <h4 className="font-bold text-sm mb-3">Username Color</h4>
                      <div className="flex gap-4 overflow-x-auto pb-2 no-scrollbar">
                          {NAME_COLORS.map(c => (
                              <button 
                                key={c}
                                onClick={() => handleCustomizationUpdate('usernameColor', c)}
                                className={`w-12 h-12 rounded-xl bg-slate-800 flex items-center justify-center ${customization.usernameColor === c ? 'ring-2 ring-indigo-500' : ''} shrink-0`}
                              >
                                  <span className={`font-black text-lg ${c}`}>Aa</span>
                              </button>
                          ))}
                          <button onClick={() => handleCustomizationUpdate('usernameColor', '')} className="w-12 h-12 rounded-xl border border-slate-500 flex items-center justify-center shrink-0"><span className="text-xs">Reset</span></button>
                      </div>
                  </div>

                  {/* Glow Toggle */}
                  <div className="flex items-center justify-between p-4 bg-slate-50 dark:bg-slate-800 rounded-2xl">
                      <div>
                          <h4 className="font-bold text-sm">Neon Glow Effect</h4>
                          <p className="text-[10px] text-slate-500">Add a soft light behind your avatar</p>
                      </div>
                      <button 
                        onClick={() => handleCustomizationUpdate('glowEffect', !customization.glowEffect)}
                        className={`w-12 h-6 rounded-full relative transition-colors ${customization.glowEffect ? 'bg-indigo-500' : 'bg-slate-300 dark:bg-slate-700'}`}
                      >
                          <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all shadow-sm ${customization.glowEffect ? 'left-7' : 'left-1'}`} />
                      </button>
                  </div>
              </div>
          );

      case 'edit':
        return (
          <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500">
            <div className="flex flex-col items-center gap-6">
              <div className="relative group cursor-pointer" onClick={() => fileInputRef.current?.click()}>
                <div className={`w-32 h-32 rounded-[2.5rem] overflow-hidden border-4 shadow-2xl transition-all ${user.isAdmin ? ADMIN_STYLE.border : (customization.borderColor || 'border-indigo-500/20')} ${customization.glowEffect ? 'shadow-[0_0_30px_rgba(99,102,241,0.5)]' : ''}`}>
                  <img src={newPhoto || user.photoURL} className="w-full h-full object-cover transition-all group-hover:brightness-75" alt="" />
                </div>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handlePhotoSelect} />
              </div>
            </div>
            <div className="space-y-6">
              <input type="text" value={name} onChange={e => setName(e.target.value)} placeholder="Display Name" className="w-full bg-slate-100 dark:bg-slate-800 rounded-2xl px-6 py-4 font-bold outline-none border border-transparent focus:border-indigo-500/50" />
              <div className="relative">
                  <span className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-400 font-bold">@</span>
