export const Sidebar: React.FC<SidebarProps> = ({ 
  currentUser, onChatSelect, activeChatId, nicknames
}) => {
  const [search, setSearch] = useState('');
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [chats, setChats] = useState<Chat[]>([]);
  const [loading, setLoading] = useState(true);
  const [showGroupModal, setShowGroupModal] = useState(false);
  const [showStore, setShowStore] = useState(false);
  const [pinnedChats, setPinnedChats] = useState<string[]>([]);

  const [showMenu, setShowMenu] = useState(false);
  const [showGallery, setShowGallery] = useState(false);
  const [showAccountSwitch, setShowAccountSwitch] = useState(false);

  const searchInputRef = useRef<HTMLInputElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // 1. Subscribe to User Profile (Pins)
    const unsubUser = subscribeToUser(currentUser.uid, (data) => {
        setPinnedChats(data.pinnedChats || []);
    });

    // 2. Fetch Data Once aggressively, then poll slower or use cache
    const fetchData = async () => {
      try {
        const [usersData, chatsData] = await Promise.all([
            getAllUsers(),
            getMyChats(currentUser.uid)
        ]);
        const myBlocked = currentUser.blockedUsers || [];
        setAllUsers(usersData.filter(u => u.uid !== currentUser.uid && !myBlocked.includes(u.uid)));
        setChats(chatsData);
        setLoading(false);
      } catch(e) {
        console.error(e);
      }
    };

    fetchData();

    // Polling every 5s is sufficient for chat list (messages update real-time in window)
    const itv = setInterval(async () => {
       const chatsData = await getMyChats(currentUser.uid);
       setChats(prev => {
         // Basic diff to avoid re-render if order/count same
         if (prev.length === chatsData.length && prev[0]?.lastMessage?.timestamp === chatsData[0]?.lastMessage?.timestamp) return prev;
         return chatsData;
       });
    }, 5000);

    return () => {
        unsubUser();
        clearInterval(itv);
    };
  }, [currentUser.uid]);

  // ... (Rest of logic: search, pin handling, etc.) ...
  // Keeping simplified rendering logic for brevity, focusing on the fix above

  const searchResults = useMemo(() => {
    const term = search.toLowerCase().trim();
    let visibleChats = chats.filter(c => !c.lockedBy?.includes(currentUser.uid));

    // Simple sort
    visibleChats.sort((a, b) => {
        const isAPinned = pinnedChats.includes(a.id);
        const isBPinned = pinnedChats.includes(b.id);
        if (isAPinned && !isBPinned) return -1;
        if (!isAPinned && isBPinned) return 1;
        return (b.updatedAt || 0) - (a.updatedAt || 0);
    });

    if (!term) return { chats: visibleChats, users: [] };

    const matchedUsers = allUsers.filter(u => (nicknames[u.uid] || u.name).toLowerCase().includes(term));
    const matchedChats = visibleChats.filter(c => {
      const name = c.type === 'group' ? c.name : (nicknames[c.participants.find(p=>p!==currentUser.uid)!] || 'User');
      return name?.toLowerCase().includes(term);
    });

    return { chats: matchedChats, users: matchedUsers };
  }, [search, allUsers, chats, currentUser.uid, pinnedChats, nicknames]);

  const getChatInfo = (chat: Chat) => {
    if (chat.type === 'group') return { name: chat.name || 'Group', photo: chat.groupIcon || `https://picsum.photos/seed/${chat.id}/200` };
    const otherId = chat.participants.find(p => p !== currentUser.uid);
    const user = allUsers.find(u => u.uid === otherId);
    return { 
        name: user ? (nicknames[user.uid] || user.name) : 'User', 
        photo: user?.photoURL || `https://picsum.photos/seed/${otherId}/200`, 
        userObj: user 
    };
  };

  return (
    <div className="w-full h-full flex flex-col bg-white dark:bg-slate-900 animate-in slide-in-from-left duration-300 relative border-r border-slate-100 dark:border-slate-800">
      {/* Header */}
      <div className="h-20 px-5 flex items-center justify-between shrink-0 bg-white/80 dark:bg-slate-900/80 backdrop-blur-sm z-10 sticky top-0">
         {isSearchOpen ? (
             <div className="flex-1 flex bg-slate-100 dark:bg-slate-800 rounded-2xl px-4 py-2">
                 <input autoFocus ref={searchInputRef} value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search..." className="bg-transparent flex-1 outline-none text-sm" />
                 <button onClick={()=>setIsSearchOpen(false)}>✕</button>
             </div>
         ) : (
             <>
                <div>
                    <h2 className="text-xl font-bold dark:text-white">Messages</h2>
                    <p className="text-[10px] font-bold text-slate-400 uppercase">{chats.length} chats</p>
                </div>
                <div className="flex gap-2">
                    <button onClick={()=>setShowStore(true)} className="p-2 text-indigo-500 hover:bg-indigo-50 rounded-xl transition-colors">🛍️</button>
                    <button onClick={()=>setIsSearchOpen(true)} className="p-2 text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl">🔍</button>
                    <button onClick={()=>setShowMenu(!showMenu)} className="p-2 text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl">⋮</button>
                </div>
             </>
         )}
         {showMenu && (
             <div className="absolute right-4 top-16 bg-white dark:bg-slate-800 shadow-xl rounded-xl p-2 z-50 flex flex-col w-48 border border-slate-100 dark:border-slate-700">
                 <button onClick={()=>{setShowGroupModal(true); setShowMenu(false)}} className="p-3 text-left hover:bg-slate-50 dark:hover:bg-slate-700 rounded-lg text-sm font-bold">Create Group</button>
                 <button onClick={()=>{setShowGallery(true); setShowMenu(false)}} className="p-3 text-left hover:bg-slate-50 dark:hover:bg-slate-700 rounded-lg text-sm font-bold">Gallery</button>
                 <button onClick={()=>{setShowAccountSwitch(true); setShowMenu(false)}} className="p-3 text-left hover:bg-slate-50 dark:hover:bg-slate-700 rounded-lg text-sm font-bold">Switch Account</button>
             </div>
         )}
      </div>

      <div className="flex-1 overflow-y-auto space-y-2 px-3 pb-24 no-scrollbar pt-2">
        {loading ? <SidebarSkeleton /> : (
            <>
                {searchResults.chats.length === 0 && searchResults.users.length === 0 && (
                    <div className="text-center py-10 text-slate-400 text-sm">No chats found.</div>
                )}
                {searchResults.chats.map(chat => {
                    const info = getChatInfo(chat);
                    const isActive = activeChatId === chat.id;
                    const isPinned = pinnedChats.includes(chat.id);
                    return (
                        <div key={chat.id} onClick={() => onChatSelect(chat)} className={`flex items-center gap-4 p-3.5 rounded-[1.2rem] cursor-pointer transition-all ${isActive ? 'bg-indigo-600 text-white shadow-lg' : 'hover:bg-slate-50 dark:hover:bg-slate-800/60'}`}>
                            <div className="relative">
                                <img src={info.photo} className="w-12 h-12 rounded-full object-cover border-2 border-transparent" alt="" />
                                {info.userObj?.status === 'online' && !isActive && <div className="absolute bottom-0 right-0 w-3.5 h-3.5 bg-green-500 rounded-full border-2 border-white"></div>}
                            </div>
                            <div className="flex-1 min-w-0">
                                <div className="flex justify-between">
                                    <h4 className="font-bold text-[15px] truncate">{info.name}</h4>
                                    <span className="text-[10px] opacity-70">{chat.lastMessage ? new Date(chat.lastMessage.timestamp).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'}) : ''}</span>
                                </div>
                                <div className="flex justify-between items-center">
                                    <p className="text-[13px] truncate opacity-70">{chat.lastMessage?.text || 'No messages'}</p>
                                    {isPinned && <span className="text-[10px]">📌</span>}
                                </div>
                            </div>
                        </div>
                    );
                })}
            </>
        )}
      </div>

      {showGroupModal && <CreateGroupModal currentUser={currentUser} onClose={() => setShowGroupModal(false)} onCreated={onChatSelect} />}
      {showGallery && <AppGallery currentUser={currentUser} onClose={() => setShowGallery(false)} />}
      {showAccountSwitch && <AccountSwitchModal currentUser={currentUser} onClose={() => setShowAccountSwitch(false)} />}
      {showStore && <PremiumStore currentUser={currentUser} onClose={() => setShowStore(false)} />}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { CallSession, CallStatus } from '../../types';
import { updateCallStatus, getCallById, updateCallSignal, addIceCandidate, subscribeToCall } from '../../firebase';
import { hasPremiumAccess, ADMIN_STYLE } from '../../premiumUtils';

interface CallModalProps {
  session: CallSession;
  onHangUp: () => void;
}

const SERVERS = {
  iceServers: [
    { urls: ['stun:stun1.l.google.com:19302', 'stun:stun2.l.google.com:19302'] }
  ]
};

export const CallModal: React.FC<CallModalProps> = ({ session, onHangUp }) => {
  const [status, setStatus] = useState<CallStatus | 'calling' | 'denied'>(session.isIncoming ? 'ringing' : 'calling');
  const [isMuted, setIsMuted] = useState(false);
  const [isVideoOff, setIsVideoOff] = useState(session.type === 'voice');
  const [duration, setDuration] = useState(0);

  const localVideoRef = useRef<HTMLVideoElement>(null);
  const remoteVideoRef = useRef<HTMLVideoElement>(null);
  const remoteAudioRef = useRef<HTMLAudioElement>(null); // Critical: Separate audio element
  const pc = useRef<RTCPeerConnection | null>(null);
  const localStream = useRef<MediaStream | null>(null);

  // 1. Initialize & Cleanup
  useEffect(() => {
    const init = async () => {
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ 
                audio: true, 
                video: session.type === 'video' ? { facingMode: 'user' } : false 
            });
            localStream.current = stream;

            // Fix: Immediately attach local stream to preview
            if (localVideoRef.current) {
                localVideoRef.current.srcObject = stream;
                localVideoRef.current.muted = true; // Mute self to prevent echo
            }

            pc.current = new RTCPeerConnection(SERVERS);

            stream.getTracks().forEach(track => pc.current?.addTrack(track, stream));

            pc.current.ontrack = (event) => {
                if (event.streams && event.streams[0]) {
                    if (session.type === 'video' && remoteVideoRef.current) {
                        remoteVideoRef.current.srcObject = event.streams[0];
                    }
                    if (remoteAudioRef.current) {
                        remoteAudioRef.current.srcObject = event.streams[0];
                        remoteAudioRef.current.play().catch(e => console.warn("Audio autoplay blocked", e));
                    }
                }
            };

            pc.current.onicecandidate = (event) => {
                if (event.candidate) addIceCandidate(session.id, event.candidate, session.isIncoming ? 'callee' : 'caller');
            };

            if (!session.isIncoming) {
                const offer = await pc.current.createOffer();
                await pc.current.setLocalDescription(offer);
                await updateCallSignal(session.id, { offer });
            }
        } catch (e) {
            console.error("Media Error:", e);
            setStatus('denied');
        }
    };

    if (!session.isIncoming || status === 'accepted') {
        init();
    }

    return () => {
        localStream.current?.getTracks().forEach(t => t.stop());
        pc.current?.close();
    };
  }, [session.isIncoming, status, session.type]);

  // 2. Signaling
  useEffect(() => {
    const unsub = subscribeToCall(session.id, async (data) => {
        if (!data) return;
        if (data.status === 'ended' || data.status === 'rejected') onHangUp();
        if (data.status === 'accepted' && status !== 'accepted') setStatus('accepted');

        if (!pc.current) return;

        if (!session.isIncoming && data.answer && !pc.current.currentRemoteDescription) {
            await pc.current.setRemoteDescription(new RTCSessionDescription(data.answer));
        }

        const candidates = session.isIncoming ? data.callerCandidates : data.calleeCandidates;
        candidates?.forEach(async (c: any) => {
            try { await pc.current?.addIceCandidate(new RTCIceCandidate(c)); } catch(e){}
        });
    });
    return () => unsub();
  }, [session.id]);

  const handleAccept = async () => {
      setStatus('accepted'); // Triggers init in useEffect
      await updateCallStatus(session.id, 'accepted');

      // We need to wait for init to create PC, checking in loop or relying on effect
      // For simplicity in this structure, we assume effect triggers. 
      // But we need to create Answer once offer is set. 
      // Simplification: Caller creates offer. Callee (here) waits for PC to be made by effect, then creates answer.
      // Better flow: Manual logic here.

      setTimeout(async () => {
          if(!pc.current) return; // Wait for effect
          const callData = await getCallById(session.id);
          if(callData?.offer) {
              await pc.current.setRemoteDescription(new RTCSessionDescription(callData.offer));
              const answer = await pc.current.createAnswer();
              await pc.current.setLocalDescription(answer);
              await updateCallSignal(session.id, { answer });
          }
      }, 1000);
  };

  const handleEnd = async () => {
      await updateCallStatus(session.id, 'ended');
      onHangUp();
  };

  return (
    <div className="fixed inset-0 z-[9999] bg-slate-900 flex flex-col items-center justify-between py-10 text-white animate-in fade-in">
        {/* Audio Element is Critical */}
        <audio ref={remoteAudioRef} autoPlay />

        {/* Video Areas */}
        {session.type === 'video' && (
            <>
                <video ref={remoteVideoRef} autoPlay playsInline className="absolute inset-0 w-full h-full object-cover z-0" />
                <div className="absolute top-4 right-4 w-32 h-48 bg-black rounded-xl overflow-hidden shadow-2xl z-20 border border-white/20">
                    <video ref={localVideoRef} autoPlay muted playsInline className="w-full h-full object-cover mirror" />
                </div>
            </>
        )}

        <div className="z-30 text-center mt-10">
            <img src={session.partner.photoURL} className="w-24 h-24 rounded-full border-4 border-white/20 shadow-xl mx-auto mb-4" />
            <h2 className="text-2xl font-bold">{session.partner.name}</h2>
            <p className="text-sm font-medium opacity-80 uppercase tracking-widest">
                {status === 'ringing' ? 'Incoming Call...' : status === 'calling' ? 'Calling...' : formatTime(duration)}
            </p>
        </div>

        <div className="z-30 flex items-center gap-8 mb-8">
            {status === 'ringing' && session.isIncoming ? (
                <>
                    <button onClick={handleEnd} className="p-6 bg-red-500 rounded-full shadow-lg hover:scale-110 transition-transform">
                        <svg className="w-8 h-8 rotate-[135deg]" fill="currentColor" viewBox="0 0 24 24"><path d="M6.62 10.79c1.44 2.83 3.76 5.14 6.59 6.59l2.2-2.2c.27-.27.67-.36 1.02-.24 1.12.37 2.33.57 3.57.57.55 0 1 .45 1 1V20c0 .55-.45 1-1 1-9.39 0-17-7.61-17-17 0-.55.45-1 1-1h3.5c.55 0 1 .45 1 1 0 1.25.2 2.45.57 3.57.11.35.03.74-.25 1.02l-2.2 2.2z" /></svg>
                    </button>
                    <button onClick={handleAccept} className="p-6 bg-green-500 rounded-full shadow-lg hover:scale-110 transition-transform animate-pulse">
                        <svg className="w-8 h-8" fill="currentColor" viewBox="0 0 24 24"><path d="M6.62 10.79c1.44 2.83 3.76 5.14 6.59 6.59l2.2-2.2c.27-.27.67-.36 1.02-.24 1.12.37 2.33.57 3.57.57.55 0 1 .45 1 1V20c0 .55-.45 1-1 1-9.39 0-17-7.61-17-17 0-.55.45-1 1-1h3.5c.55 0 1 .45 1 1 0 1.25.2 2.45.57 3.57.11.35.03.74-.25 1.02l-2.2 2.2z" /></svg>
                    </button>
                </>
            ) : (
                <button onClick={handleEnd} className="p-6 bg-red-500 rounded-full shadow-lg hover:scale-110 transition-transform">
                    <svg className="w-8 h-8 rotate-[135deg]" fill="currentColor" viewBox="0 0 24 24"><path d="M6.62 10.79c1.44 2.83 3.76 5.14 6.59 6.59l2.2-2.2c.27-.27.67-.36 1.02-.24 1.12.37 2.33.57 3.57.57.55 0 1 .45 1 1V20c0 .55-.45 1-1 1-9.39 0-17-7.61-17-17 0-.55.45-1 1-1h3.5c.55 0 1 .45 1 1 0 1.25.2 2.45.57 3.57.11.35.03.74-.25 1.02l-2.2 2.2z" /></svg>
                </button>
            )}
        </div>
    </div>
  );
};

const formatTime = (s: number) => {
    const m = Math.floor(s / 60);
    const sec = s % 60;
    return `${m}:${sec.toString().padStart(2, '0')}`;
};

import React, { useState, useRef, useEffect } from 'react';
import { User, PremiumCustomization } from '../../types';
import { useAuth } from '../../hooks/useAuth';
import { updateProfile, updatePremiumCustomization, safeJsonStringify } from '../../firebase';
