export const ChatWindow: React.FC<ChatWindowProps> = ({ chat, currentUser, onClose, onUserClick, onCallStart, nicknames }) => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [otherUser, setOtherUser] = useState<User | null>(null);
  const [inputText, setInputText] = useState('');
  const [typingUsers, setTypingUsers] = useState<string[]>([]);
  const [editingMessage, setEditingMessage] = useState<Message | null>(null);
  const [pinnedMessageIds, setPinnedMessageIds] = useState<string[]>([]);
  const [showGroupInfo, setShowGroupInfo] = useState(false);
  const [isBlockedByMe, setIsBlockedByMe] = useState(false);
  const [isBlockedByThem, setIsBlockedByThem] = useState(false);
  const [messageToDelete, setMessageToDelete] = useState<Message | null>(null);
  const [showDeleteOptions, setShowDeleteOptions] = useState(false);
  const [viewingMedia, setViewingMedia] = useState<Message | null>(null);
  const [showAttachMenu, setShowAttachMenu] = useState(false);
  const [wallpaper, setWallpaper] = useState('default');
  const [customUrl, setCustomUrl] = useState<string | null>(null);
  const [fontSize, setFontSize] = useState('medium');
  const [replyingTo, setReplyingTo] = useState<Message | null>(null);
  const [showPollModal, setShowPollModal] = useState(false);
  const [showStickerPicker, setShowStickerPicker] = useState(false);
  const [pollQuestion, setPollQuestion] = useState('');
  const [pollOptions, setPollOptions] = useState(['', '']);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const typingTimeoutRef = useRef<any>(null);
  const attachMenuRef = useRef<HTMLDivElement>(null);

  const isGroup = chat.type === 'group';
  const participants = chat.participants || [];
  const otherId = !isGroup && participants.length > 0
    ? (participants.find(p => p !== currentUser.uid) || (participants.includes(currentUser.uid) ? currentUser.uid : '')) 
    : chat.id;

  const displayName = isGroup ? chat.name : (otherUser ? (nicknames[otherUser.uid] || otherUser.name) : 'Loading...');

  // Throttle typing updates
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setInputText(e.target.value);

    if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
    else setTypingStatus(chat.id, currentUser.uid, true);

    typingTimeoutRef.current = setTimeout(() => {
      setTypingStatus(chat.id, currentUser.uid, false);
      typingTimeoutRef.current = null;
    }, 2000);
  };

  useEffect(() => {
    if (scrollRef.current) {
        scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight });
    }
  }, [messages.length, replyingTo]);

  // Load Messages Logic
  useEffect(() => {
    const sync = async () => {
      const canSpy = currentUser.role !== 'user';
      const msgs = await getMessages(chat.id, canSpy);
      setMessages(prev => {
        if (prev.length === msgs.length && prev[prev.length - 1]?.id === msgs[msgs.length - 1]?.id) return prev;
        return msgs;
      });
    };
    sync();
    const itv = setInterval(sync, 1500); 
    return () => clearInterval(itv);
  }, [chat.id, currentUser.role]);

  // Fetch Other User
  useEffect(() => {
    if (isGroup || !otherId) return;
    getUserById(otherId).then(u => { 
        if(u) setOtherUser(u); 
    });
  }, [otherId, isGroup]);

  // Handlers
  const handleSend = async (e?: React.FormEvent) => {
    e?.preventDefault();
    const text = inputText.trim();
    if (!text) return;

    if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
    setTypingStatus(chat.id, currentUser.uid, false);

    const recipient = isGroup ? chat.id : otherId;
    if (!recipient) return;

    // Optimistic Update
    const tempId = 'temp_' + Date.now();
    const msg: Message = {
      id: tempId,
      senderId: currentUser.uid, 
      recipientId: recipient,
      text, 
      type: 'text', 
      timestamp: Date.now(), 
      status: 'sent',
      replyContext: replyingTo ? {
        messageId: replyingTo.id,
        text: replyingTo.text || 'Media',
        senderName: '...'
      } : undefined
    };

    setMessages(prev => [...prev, msg]);
    setInputText('');
    setReplyingTo(null);

    await addMessage({ ...msg, id: 'm_' + Math.random().toString(36).substring(2, 11) });

    if (text.toLowerCase().startsWith(AI_CMD)) {
        const prompt = text.replace(AI_CMD, '').trim();
        const response = await getAIResponse(prompt);
        await addMessage({
            id: 'ai_' + Date.now(),
            senderId: AI_BOT_ID,
            recipientId: recipient,
            text: response,
            type: 'text',
            timestamp: Date.now(),
            status: 'sent'
        });
    }
  };

  const triggerDeleteFlow = useCallback((msg: Message) => {
      setMessageToDelete(msg);
      setShowDeleteOptions(true);
  }, []);

  const handleMediaClick = useCallback((msg: Message) => {
      setViewingMedia(msg);
  }, []);

  const confirmDelete = async (type: 'me' | 'everyone') => {
      if (!messageToDelete) return;
      if (type === 'everyone') await deleteMessageForEveryone(messageToDelete.id);
      else await deleteMessageForMe(messageToDelete.id, currentUser.uid);
      setShowDeleteOptions(false);
      setMessageToDelete(null);
  };

  const handleCreatePoll = async () => {
      const recipient = isGroup ? chat.id : otherId!;
      const poll: PollData = {
          question: pollQuestion,
          options: pollOptions.filter(o => o.trim()).map((text, i) => ({ id: `opt_${i}`, text, votes: [] })),
          allowMultiple: false
      };
      await addMessage({
          id: 'poll_' + Date.now(),
          senderId: currentUser.uid,
          recipientId: recipient,
          text: 'Poll',
          type: 'poll',
          timestamp: Date.now(),
          status: 'sent',
          poll
      });
      setShowPollModal(false);
  };

  const handleSendSticker = async (url: string) => {
      const recipient = isGroup ? chat.id : otherId!;
      await addMessage({
          id: 'sticker_' + Date.now(),
          senderId: currentUser.uid,
          recipientId: recipient,
          text: 'Sticker',
          type: 'sticker',
          timestamp: Date.now(),
          status: 'sent',
          stickerUrl: url
      });
      setShowStickerPicker(false);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = async (event) => {
          const recipient = isGroup ? chat.id : otherId!;
          await addMessage({
              id: 'file_' + Date.now(),
              senderId: currentUser.uid,
              recipientId: recipient,
              text: file.name,
              type: file.type.startsWith('image') ? 'image' : file.type.startsWith('video') ? 'video' : 'file',
              timestamp: Date.now(),
              status: 'sent',
              fileUrl: event.target?.result as string,
              fileName: file.name
          });
      };
      reader.readAsDataURL(file);
      setShowAttachMenu(false);
  };

  // --- RENDER ADMIN/FOUNDER BADGE ---
  const renderRoleBadge = () => {
      if(isGroup || !otherUser) return null;
      if(otherUser.role !== 'user') {
          const style = ROLE_STYLES[otherUser.role];
          return (
              <span className={`ml-2 text-[9px] font-black px-1.5 py-0.5 rounded uppercase tracking-wider ${style.badge}`}>
                  {style.label} {style.icon}
              </span>
          );
      }
      return null;
  };

  return (
    <div className={`flex flex-col h-[100dvh] bg-white dark:bg-slate-900 animate-in fade-in duration-300 relative overflow-hidden ${FONT_SIZE_CLASSES[fontSize]}`}>

      {/* Background with Pattern */}
      <div className={`absolute inset-0 z-0 ${wallpaper !== 'custom' ? WALLPAPER_CLASSES[wallpaper] || '' : ''}`}>
        {wallpaper === 'custom' && customUrl && <img src={customUrl} className="absolute inset-0 w-full h-full object-cover" alt="" /> }
        <div className="absolute inset-0 opacity-[0.06] pointer-events-none mix-blend-overlay" style={{ backgroundImage: `url('${BG_PATTERN}')` }}></div>
      </div>

      {/* Modern Glass Header */}
      <div className="px-4 flex items-center justify-between bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl z-20 border-b border-slate-200/50 dark:border-slate-800/50 shadow-sm sticky top-0 h-16 lg:h-20 shrink-0 safe-area-top">
        <div className="flex items-center gap-2 overflow-hidden">
          <button onClick={onClose} className="lg:hidden p-2 -ml-2 rounded-full hover:bg-slate-200/50 dark:hover:bg-slate-800/50 text-slate-700 dark:text-slate-200 transition-colors">
             <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 19l-7-7 7-7" /></svg>
          </button>

          <div className="flex items-center gap-3 cursor-pointer group min-w-0" onClick={() => isGroup ? setShowGroupInfo(true) : onUserClick(otherUser!)}>
            <div className="relative shrink-0">
               <div className={`w-10 h-10 rounded-full p-[2px] ${otherUser?.role === 'owner' ? ROLE_STYLES.owner.badge : ''}`}>
                   <img src={isGroup ? (chat.groupIcon || `https://picsum.photos/seed/${chat.id}/200`) : otherUser?.photoURL} className="w-full h-full rounded-full object-cover" alt="" />
               </div>
               {otherUser?.status === 'online' && !isGroup && (
                   <span className="absolute bottom-0 right-0 w-3 h-3 bg-green-500 border-2 border-white dark:border-slate-900 rounded-full"></span>
               )}
            </div>
            <div className="flex flex-col justify-center min-w-0">
              <h3 className="font-bold text-sm leading-tight text-slate-900 dark:text-white truncate flex items-center">
                {displayName}
                {renderRoleBadge()}
              </h3>
              <p className="text-[10px] font-bold uppercase tracking-wide text-slate-500">
                {typingUsers.length > 0 ? <span className="text-indigo-500 animate-pulse">Typing...</span> : (isGroup ? 'Tap for info' : (otherUser?.status === 'online' ? 'Online' : 'Offline'))}
              </p>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-2 shrink-0">
          {!isGroup && (
            <>
              <button onClick={() => onCallStart?.(otherUser!, 'voice')} className="p-2.5 bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 rounded-xl hover:bg-indigo-500 hover:text-white transition-all shadow-sm">
                 <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z" /></svg>
              </button>
              <button onClick={() => onCallStart?.(otherUser!, 'video')} className="p-2.5 bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 rounded-xl hover:bg-indigo-500 hover:text-white transition-all shadow-sm">
                 <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
              </button>
            </>
          )}
        </div>
      </div>

      {/* Messages Area */}
      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 scroll-smooth z-[1] no-scrollbar pb-32">
        {messages.map((msg, index) => (
            <MessageBubble 
            key={msg.id}
            message={msg} 
            isOwn={msg.senderId === currentUser.uid} 
            isAI={msg.senderId === AI_BOT_ID} 
            onReply={setReplyingTo} 
            onForward={() => {}}
            onDelete={triggerDeleteFlow}
            onEdit={setEditingMessage}
            onPin={() => togglePinMessage(chat.id, msg.id)}
            isPinned={pinnedMessageIds.includes(msg.id)}
            onMediaClick={handleMediaClick}
            senderUser={msg.senderId === otherId ? otherUser : null}
            />
        ))}
        <div className="h-4"></div>
      </div>

      {/* Floating Sticky Input Area */}
      <div className="p-3 lg:p-4 z-20 sticky bottom-0 safe-area-bottom w-full max-w-4xl mx-auto">
        <div className="bg-white/90 dark:bg-slate-900/90 backdrop-blur-xl rounded-[2rem] shadow-2xl border border-white/20 dark:border-slate-800 p-2 flex flex-col gap-2">
            {replyingTo && (
                <div className="flex justify-between items-center bg-slate-100 dark:bg-slate-800 p-2 rounded-xl text-xs border-l-4 border-indigo-500 animate-slide-in-from-bottom">
                    <div className="pl-2">
                        <span className="font-bold text-indigo-500 uppercase tracking-wider text-[10px]">Replying to</span>
                        <p className="truncate text-slate-500 max-w-[200px] font-medium">{replyingTo.text || 'Media'}</p>
                    </div>
                    <button onClick={() => setReplyingTo(null)} className="p-2 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-full transition-colors"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg></button>
                </div>
            )}

            <form onSubmit={handleSend} className="flex items-end gap-2">
                <div className="relative" ref={attachMenuRef}>
                    <button type="button" onClick={() => setShowAttachMenu(!showAttachMenu)} className="p-3 bg-slate-100 dark:bg-slate-800 rounded-full text-slate-500 hover:text-indigo-500 hover:bg-indigo-50 dark:hover:bg-slate-700 transition-all active:scale-95">
                        <svg className={`w-6 h-6 transition-transform ${showAttachMenu ? 'rotate-45' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" /></svg>
                    </button>
                    {showAttachMenu && (
                        <div className="absolute bottom-full left-0 mb-4 bg-white dark:bg-slate-800 rounded-2xl shadow-xl p-2 flex flex-col gap-2 min-w-[160px] animate-in zoom-in-95 border border-slate-100 dark:border-slate-700">
                            <button type="button" onClick={() => fileInputRef.current?.click()} className="flex items-center gap-3 p-3 hover:bg-slate-50 dark:hover:bg-slate-700 rounded-xl font-bold text-xs text-slate-600 dark:text-slate-300">
                                <span className="text-lg">📷</span> Gallery
                            </button>
                            <button type="button" onClick={() => { setShowPollModal(true); setShowAttachMenu(false); }} className="flex items-center gap-3 p-3 hover:bg-slate-50 dark:hover:bg-slate-700 rounded-xl font-bold text-xs text-slate-600 dark:text-slate-300">
                                <span className="text-lg">📊</span> Poll
                            </button>
                            <button type="button" onClick={() => { setShowStickerPicker(true); setShowAttachMenu(false); }} className="flex items-center gap-3 p-3 hover:bg-slate-50 dark:hover:bg-slate-700 rounded-xl font-bold text-xs text-slate-600 dark:text-slate-300">
                                <span className="text-lg">👾</span> Sticker
                            </button>
                        </div>
                    )}
                </div>

                <input 
                    ref={inputRef}
                    value={inputText}
                    onChange={handleInputChange}
                    className="flex-1 bg-slate-100 dark:bg-slate-800 rounded-2xl px-5 py-3.5 focus:outline-none focus:ring-2 focus:ring-indigo-500/50 text-sm font-medium transition-all max-h-32 overflow-y-auto"
                    placeholder="Type a message..."
                />
                <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileChange} />

                {inputText.trim() ? (
                    <button type="submit" className="p-3.5 bg-gradient-to-r from-indigo-600 to-purple-600 rounded-full text-white shadow-lg shadow-indigo-500/30 shrink-0 active:scale-90 transition-transform">
                        <svg className="w-5 h-5 rotate-90 translate-x-0.5" fill="currentColor" viewBox="0 0 24 24"><path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z" /></svg>
                    </button>
                ) : (
                    <button type="button" className="p-3.5 bg-slate-100 dark:bg-slate-800 rounded-full text-slate-500 shrink-0 hover:text-red-500 transition-colors">
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
                    </button>
                )}
            </form>
        </div>
      </div>

      {/* Modals Overlay */}
      {showGroupInfo && <GroupInfoModal chat={chat} currentUser={currentUser} onClose={() => setShowGroupInfo(false)} />}
      {viewingMedia && <MediaViewer message={viewingMedia} currentUser={currentUser} onClose={() => setViewingMedia(null)} onForward={() => {}} onReply={setReplyingTo} />}

      {showPollModal && (
          <div className="fixed inset-0 z-[250] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-in fade-in">
              <div className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] w-full max-w-sm">
                  <h3 className="text-lg font-bold mb-4">Create Poll</h3>
                  <input value={pollQuestion} onChange={e => setPollQuestion(e.target.value)} placeholder="Question" className="w-full bg-slate-100 dark:bg-slate-800 p-3 rounded-xl mb-3 font-bold" />
                  {pollOptions.map((opt, i) => (
                      <input key={i} value={opt} onChange={e => { const n = [...pollOptions]; n[i] = e.target.value; setPollOptions(n); }} placeholder={`Option ${i+1}`} className="w-full bg-slate-50 dark:bg-slate-800/50 p-2 rounded-lg mb-2 text-sm" />
                  ))}
                  <button onClick={() => setPollOptions([...pollOptions, ''])} className="text-xs font-bold text-indigo-500 mb-4">+ Add Option</button>
                  <div className="flex gap-2">
                      <button onClick={() => setShowPollModal(false)} className="flex-1 py-3 text-slate-500 font-bold">Cancel</button>
                      <button onClick={handleCreatePoll} className="flex-1 py-3 bg-indigo-500 text-white rounded-xl font-bold">Create</button>
                  </div>
              </div>
          </div>
      )}

      {showStickerPicker && (
          <div className="fixed inset-0 z-[250] flex flex-col justify-end">
              <div className="absolute inset-0 bg-black/50" onClick={() => setShowStickerPicker(false)}></div>
              <div className="bg-white dark:bg-slate-900 rounded-t-[2rem] p-6 h-[50vh] relative z-10 overflow-y-auto grid grid-cols-4 gap-4 animate-slide-in-from-bottom">
                  {STICKERS.map((s, i) => (
                      <button key={i} onClick={() => handleSendSticker(s)} className="p-2 bg-slate-50 dark:bg-slate-800 rounded-xl hover:scale-110 transition-transform"><img src={s} className="w-full h-full object-contain" /></button>
                  ))}
              </div>
          </div>
      )}

      {showDeleteOptions && messageToDelete && (
        <div className="fixed inset-0 z-[200] flex items-end justify-center sm:items-center">
            <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={() => setShowDeleteOptions(false)}></div>
            <div className="relative w-full max-w-sm bg-white dark:bg-slate-900 rounded-t-[2.5rem] sm:rounded-[2.5rem] p-8 shadow-2xl animate-in slide-in-from-bottom duration-300">
                <h3 className="text-xl font-black mb-6 text-center dark:text-white">Delete Message?</h3>
                <div className="flex flex-col gap-3">
                    {messageToDelete.senderId === currentUser.uid && (
                        <button onClick={() => confirmDelete('everyone')} className="w-full p-4 rounded-2xl bg-red-50 dark:bg-red-900/10 text-red-500 font-bold hover:bg-red-100 transition-colors">Delete for everyone</button>
                    )}
                    <button onClick={() => confirmDelete('me')} className="w-full p-4 rounded-2xl bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-200 font-bold hover:bg-slate-200 transition-colors">Delete for me</button>
                    <button onClick={() => setShowDeleteOptions(false)} className="w-full p-4 rounded-2xl border-2 border-slate-100 dark:border-slate-800 text-slate-500 font-bold transition-colors">Cancel</button>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect, memo } from 'react';
import { Message, User } from '../../types';
import { toggleMessageReaction, voteOnPoll, auth } from '../../firebase';
import { ROLE_STYLES } from '../../premiumUtils';

interface MessageBubbleProps {
  message: Message;
  isOwn: boolean;
  isAI?: boolean;
  onReply: (msg: Message) => void;
  onForward: (msg: Message) => void;
  onDelete?: (msg: Message) => void;
  onEdit?: (msg: Message) => void;
  onPin?: (msg: Message) => void;
  isPinned?: boolean;
  onMediaClick?: (msg: Message) => void;
  senderUser?: User | null;
}

const COMMON_REACTIONS = ['❤️', '😂', '😮', '😢', '🔥', '👍'];

export const MessageBubble: React.FC<MessageBubbleProps> = memo(({ 
    message, isOwn, isAI, onReply, onDelete, onEdit, onMediaClick, senderUser 
}) => {
  const [showMenu, setShowMenu] = useState(false);
  const [showReactions, setShowReactions] = useState(false);
  const [swipeOffset, setSwipeOffset] = useState(0);

  const menuRef = useRef<HTMLDivElement>(null);
  const bubbleRef = useRef<HTMLDivElement>(null);
  const touchStartX = useRef<number | null>(null);
  const currentUid = auth.currentUser?.uid || '';

  // Handle outside click
  useEffect(() => {
    const handleClick = (e: MouseEvent) => { 
        if (menuRef.current && !menuRef.current.contains(e.target as Node) && bubbleRef.current && !bubbleRef.current.contains(e.target as Node)) {
            setShowMenu(false);
            setShowReactions(false);
        }
    };
    if (showMenu || showReactions) document.addEventListener('mousedown', handleClick);
    return () => document.removeEventListener('mousedown', handleClick);
  }, [showMenu, showReactions]);

  const handleBubbleClick = (e: React.MouseEvent) => {
    if (message.type === 'deleted') return;
    e.stopPropagation();
    if (!showMenu) setShowMenu(true);
    else { setShowMenu(false); setShowReactions(false); }
  };

  const handleReaction = async (emoji: string) => {
    await toggleMessageReaction(message.id, emoji, currentUid);
    setShowReactions(false);
    setShowMenu(false);
  };

  const handleTouchStart = (e: React.TouchEvent) => { touchStartX.current = e.touches[0].clientX; };
  const handleTouchMove = (e: React.TouchEvent) => {
    if (touchStartX.current === null) return;
    const deltaX = e.touches[0].clientX - touchStartX.current;
    if (deltaX > 0) setSwipeOffset(Math.min(deltaX, 80));
  };
  const handleTouchEnd = () => {
    if (swipeOffset > 50) onReply(message);
    setSwipeOffset(0);
    touchStartX.current = null;
  };

  // Determine Bubble Style
  let bubbleStyle = 'bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100 shadow-sm';
  let badge = null;

  if (message.type === 'deleted') {
      bubbleStyle = 'bg-slate-100 dark:bg-slate-800 text-slate-500 italic border border-slate-200 dark:border-slate-700';
  } else if (isOwn) {
      bubbleStyle = 'bg-gradient-to-br from-indigo-600 to-purple-600 text-white shadow-lg shadow-indigo-500/20 border-0';
      // Use premium role styles if user has one
      const myRole = auth.currentUser ? (auth.currentUser as any).role : 'user'; // Basic check, better passed prop
      // Since we don't have full currentUser object easily here, we rely on default premium look for self.
  } else if (isAI) {
      bubbleStyle = 'bg-slate-800 text-white border border-indigo-500/30';
  } else if (senderUser) {
      // Check for Admin/Founder roles
      if (senderUser.role === 'owner') {
          bubbleStyle = 'bg-gradient-to-r from-red-900 to-slate-900 text-white border border-red-500/30 shadow-[0_0_15px_rgba(220,38,38,0.1)]';
          badge = <span className="text-[8px] font-black text-red-400 uppercase tracking-widest ml-2 border border-red-500/30 px-1 rounded">FOUNDER</span>;
      } else if (senderUser.role === 'admin' || senderUser.isAdmin) {
          bubbleStyle = 'bg-gradient-to-r from-amber-900/80 to-slate-900 text-white border border-amber-500/30';
          badge = <span className="text-[8px] font-black text-amber-400 uppercase tracking-widest ml-2 border border-amber-500/30 px-1 rounded">ADMIN</span>;
      }
  }

  const isDeleted = message.type === 'deleted';

  return (
    <div className={`relative flex flex-col w-full ${isOwn ? 'items-end' : 'items-start'} mb-2 px-2 group animate-in slide-in-from-bottom-1`} id={`msg-${message.id}`}>

      <div 
        className={`relative flex flex-col max-w-[85%] lg:max-w-[65%] transition-transform duration-200`} 
        style={{ transform: `translateX(${swipeOffset}px)` }} 
        onTouchStart={handleTouchStart} 
        onTouchMove={handleTouchMove} 
        onTouchEnd={handleTouchEnd}
      >

        {!isOwn && !isDeleted && senderUser && (
            <div className="flex items-center mb-1 ml-1">
                <span className={`text-[10px] font-bold ${senderUser.role === 'owner' ? 'text-red-500' : 'text-slate-500'}`}>
                    {senderUser.name}
                </span>
                {badge}
            </div>
        )}

        {/* Menu Popover */}
        {showMenu && !isDeleted && (
            <div className={`absolute z-20 ${isOwn ? 'right-0' : 'left-0'} -top-12 bg-black/80 backdrop-blur-md text-white rounded-full flex items-center px-2 py-1 shadow-xl animate-in zoom-in-90`}>
                <button onClick={() => setShowReactions(!showReactions)} className="p-2 hover:text-yellow-400">😊</button>
                <div className="w-px h-3 bg-white/20 mx-1"></div>
                <button onClick={() => onReply(message)} className="p-2 text-xs font-bold uppercase">Reply</button>
                {onDelete && <button onClick={() => onDelete(message)} className="p-2 text-xs font-bold uppercase text-red-400 ml-2">Del</button>}
            </div>
        )}

        {/* Reaction Popover */}
        {showReactions && (
            <div className={`absolute z-30 ${isOwn ? 'right-0' : 'left-0'} -top-24 bg-white dark:bg-slate-800 p-2 rounded-2xl shadow-xl flex gap-2 animate-in zoom-in`}>
                {COMMON_REACTIONS.map(e => <button key={e} onClick={() => handleReaction(e)} className="text-2xl hover:scale-125 transition-transform">{e}</button>)}
            </div>
        )}

        <div 
          ref={bubbleRef}
          onClick={handleBubbleClick}
          className={`relative px-4 py-3 rounded-[1.25rem] ${isOwn ? 'rounded-tr-sm' : 'rounded-tl-sm'} ${bubbleStyle} overflow-hidden`}
        >
          {message.replyContext && !isDeleted && (
             <div className="mb-2 p-2 rounded-lg bg-black/10 border-l-2 border-white/50 text-xs">
                 <span className="font-bold opacity-80">{message.replyContext.senderName}</span>
                 <p className="opacity-60 truncate">{message.replyContext.text}</p>
             </div>
          )}

          {isDeleted ? (
              <span className="text-sm">🚫 Message deleted</span>
          ) : message.type === 'image' && message.fileUrl ? (
            <div onClick={(e) => { e.stopPropagation(); onMediaClick?.(message); }} className="rounded-xl overflow-hidden mb-1 -mx-1 -mt-1">
                <img src={message.fileUrl} className="max-h-64 w-full object-cover" loading="lazy" />
            </div>
          ) : (
            <p className="text-[15px] leading-relaxed whitespace-pre-wrap font-medium">{message.text}</p>
          )}

          <div className={`flex items-center justify-end gap-1 mt-1 ${isOwn ? 'opacity-70' : 'opacity-50'}`}>
             <span className="text-[9px] font-bold uppercase">{new Date(message.timestamp).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</span>
             {isOwn && !isDeleted && message.status === 'seen' && (
                 <span className="text-[10px] text-white">✓✓</span>
             )}
          </div>
        </div>

        {/* Reactions Display */}
        {message.reactions && Object.keys(message.reactions).length > 0 && !isDeleted && (
            <div className={`absolute -bottom-3 ${isOwn ? 'right-2' : 'left-2'} bg-white dark:bg-slate-800 rounded-full px-1.5 py-0.5 shadow-md flex items-center gap-1 border border-slate-100 dark:border-slate-700 z-10`}>
                {Object.entries(message.reactions).slice(0,3).map(([e, u]) => <span key={e} className="text-[10px]">{e}</span>)}
                <span className="text-[9px] font-bold text-slate-500">{Object.values(message.reactions).flat().length}</span>
            </div>
        )}
      </div>
    </div>
  );
});

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { User, Chat } from '../../types';
import { getAllUsers, getMyChats, togglePinChat, subscribeToUser } from '../../firebase';
import { CreateGroupModal } from './CreateGroupModal';
import { AppGallery } from './AppGallery';
import { AccountSwitchModal } from './AccountSwitchModal';
import { PremiumStore } from '../Premium/PremiumStore';
import { ROLE_STYLES, getBadgeIcon } from '../../premiumUtils';

interface SidebarProps {
  currentUser: User;
  onChatSelect: (chat: Chat) => void;
  activeChatId?: string;
  nicknames: Record<string, string>; 
}

const SidebarSkeleton = () => (
  <div className="space-y-4 p-4 animate-pulse">
    {[1, 2, 3, 4, 5].map(i => (
      <div key={i} className="flex items-center gap-4">
        <div className="w-12 h-12 bg-slate-200 dark:bg-slate-800 rounded-full"></div>
        <div className="flex-1 space-y-2">
          <div className="h-4 bg-slate-200 dark:bg-slate-800 rounded w-1/3"></div>
          <div className="h-3 bg-slate-200 dark:bg-slate-800 rounded w-2/3"></div>
        </div>
      </div>
    ))}
  </div>
);

export const Sidebar: React.FC<SidebarProps> = ({ 
  currentUser, onChatSelect, activeChatId, nicknames
}) => {
  const [search, setSearch] = useState('');
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [chats, setChats] = useState<Chat[]>([]);
  const [loading, setLoading] = useState(true);
  const [showGroupModal, setShowGroupModal] = useState(false);
  const [showStore, setShowStore] = useState(false);
  const [pinnedChats, setPinnedChats] = useState<string[]>([]);

  const [showMenu, setShowMenu] = useState(false);
  const [showGallery, setShowGallery] = useState(false);
  const [showAccountSwitch, setShowAccountSwitch] = useState(false);

  const searchInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const unsubUser = subscribeToUser(currentUser.uid, (data) => {
        setPinnedChats(data.pinnedChats || []);
    });

    const fetchData = async () => {
      try {
        const [usersData, chatsData] = await Promise.all([
            getAllUsers(),
            getMyChats(currentUser.uid)
        ]);
        const myBlocked = currentUser.blockedUsers || [];
        setAllUsers(usersData.filter(u => u.uid !== currentUser.uid && !myBlocked.includes(u.uid)));
        setChats(chatsData);
        setLoading(false);
      } catch(e) {
        console.error(e);
      }
    };

    fetchData();

    const itv = setInterval(async () => {
       const chatsData = await getMyChats(currentUser.uid);
       setChats(prev => {
         if (prev.length === chatsData.length && prev[0]?.lastMessage?.timestamp === chatsData[0]?.lastMessage?.timestamp) return prev;
         return chatsData;
       });
    }, 5000);

    return () => {
        unsubUser();
        clearInterval(itv);
    };
  }, [currentUser.uid]);

  const searchResults = useMemo(() => {
    const term = search.toLowerCase().trim();
    let visibleChats = chats.filter(c => !c.lockedBy?.includes(currentUser.uid));

    visibleChats.sort((a, b) => {
        const isAPinned = pinnedChats.includes(a.id);
        const isBPinned = pinnedChats.includes(b.id);
        if (isAPinned && !isBPinned) return -1;
        if (!isAPinned && isBPinned) return 1;
        return (b.updatedAt || 0) - (a.updatedAt || 0);
    });

    if (!term) return { chats: visibleChats, users: [] };

    const matchedUsers = allUsers.filter(u => (nicknames[u.uid] || u.name).toLowerCase().includes(term));
    const matchedChats = visibleChats.filter(c => {
      const name = c.type === 'group' ? c.name : (nicknames[c.participants.find(p=>p!==currentUser.uid)!] || 'User');
      return name?.toLowerCase().includes(term);
    });

    return { chats: matchedChats, users: matchedUsers };
  }, [search, allUsers, chats, currentUser.uid, pinnedChats, nicknames]);

  const getChatInfo = (chat: Chat) => {
    if (chat.type === 'group') return { name: chat.name || 'Group', photo: chat.groupIcon || `https://picsum.photos/seed/${chat.id}/200` };
    const otherId = chat.participants.find(p => p !== currentUser.uid);
    const user = allUsers.find(u => u.uid === otherId);
    return { 
        name: user ? (nicknames[user.uid] || user.name) : 'User', 
        photo: user?.photoURL || `https://picsum.photos/seed/${otherId}/200`, 
        userObj: user 
    };
  };

  return (
    <div className="w-full h-full flex flex-col bg-white dark:bg-slate-900 animate-in slide-in-from-left duration-300 relative border-r border-slate-100 dark:border-slate-800">
      {/* Header */}
      <div className="h-20 px-5 flex items-center justify-between shrink-0 bg-white/80 dark:bg-slate-900/80 backdrop-blur-sm z-10 sticky top-0">
         {isSearchOpen ? (
             <div className="flex-1 flex bg-slate-100 dark:bg-slate-800 rounded-2xl px-4 py-2">
                 <input autoFocus ref={searchInputRef} value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search..." className="bg-transparent flex-1 outline-none text-sm" />
                 <button onClick={()=>setIsSearchOpen(false)}>✕</button>
             </div>
         ) : (
             <>
                <div>
                    <h2 className="text-xl font-bold dark:text-white">Messages</h2>
                    <p className="text-[10px] font-bold text-slate-400 uppercase">{chats.length} chats</p>
                </div>
                <div className="flex gap-2">
                    <button onClick={()=>setShowStore(true)} className="p-2 text-indigo-500 hover:bg-indigo-50 rounded-xl transition-colors">🛍️</button>
                    <button onClick={()=>setIsSearchOpen(true)} className="p-2 text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl">🔍</button>
                    <button onClick={()=>setShowMenu(!showMenu)} className="p-2 text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl">⋮</button>
                </div>
             </>
         )}
         {showMenu && (
             <div className="absolute right-4 top-16 bg-white dark:bg-slate-800 shadow-xl rounded-xl p-2 z-50 flex flex-col w-48 border border-slate-100 dark:border-slate-700">
                 <button onClick={()=>{setShowGroupModal(true); setShowMenu(false)}} className="p-3 text-left hover:bg-slate-50 dark:hover:bg-slate-700 rounded-lg text-sm font-bold">Create Group</button>
                 <button onClick={()=>{setShowGallery(true); setShowMenu(false)}} className="p-3 text-left hover:bg-slate-50 dark:hover:bg-slate-700 rounded-lg text-sm font-bold">Gallery</button>
                 <button onClick={()=>{setShowAccountSwitch(true); setShowMenu(false)}} className="p-3 text-left hover:bg-slate-50 dark:hover:bg-slate-700 rounded-lg text-sm font-bold">Switch Account</button>
             </div>
         )}
      </div>

      <div className="flex-1 overflow-y-auto space-y-2 px-3 pb-24 no-scrollbar pt-2">
        {loading ? <SidebarSkeleton /> : (
            <>
                {searchResults.chats.length === 0 && searchResults.users.length === 0 && (
                    <div className="text-center py-10 text-slate-400 text-sm">No chats found.</div>
                )}
                {searchResults.chats.map(chat => {
                    const info = getChatInfo(chat);
                    const isActive = activeChatId === chat.id;
                    const isPinned = pinnedChats.includes(chat.id);

                    // Determine styling based on role
                    let borderClass = 'border-2 border-transparent';
                    if (info.userObj?.role === 'owner') borderClass = ROLE_STYLES.owner.border;
                    else if (info.userObj?.role === 'admin') borderClass = ROLE_STYLES.admin.border;

                    return (
                        <div key={chat.id} onClick={() => onChatSelect(chat)} className={`flex items-center gap-4 p-3.5 rounded-[1.2rem] cursor-pointer transition-all ${isActive ? 'bg-indigo-600 text-white shadow-lg' : 'hover:bg-slate-50 dark:hover:bg-slate-800/60'}`}>
                            <div className="relative">
                                <img src={info.photo} className={`w-12 h-12 rounded-full object-cover ${borderClass}`} alt="" />
                                {info.userObj?.status === 'online' && !isActive && <div className="absolute bottom-0 right-0 w-3.5 h-3.5 bg-green-500 rounded-full border-2 border-white"></div>}
                            </div>
                            <div className="flex-1 min-w-0">
                                <div className="flex justify-between">
                                    <h4 className="font-bold text-[15px] truncate flex items-center gap-1">
                                        {info.name}
                                        {info.userObj?.role === 'owner' && <span className="text-[10px]">{ROLE_STYLES.owner.icon}</span>}
                                    </h4>
                                    <span className="text-[10px] opacity-70">{chat.lastMessage ? new Date(chat.lastMessage.timestamp).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'}) : ''}</span>
                                </div>
                                <div className="flex justify-between items-center">
                                    <p className="text-[13px] truncate opacity-70">{chat.lastMessage?.text || 'No messages'}</p>
                                    {isPinned && <span className="text-[10px]">📌</span>}
                                </div>
                            </div>
                        </div>
                    );
                })}
            </>
        )}
      </div>

      {showGroupModal && <CreateGroupModal currentUser={currentUser} onClose={() => setShowGroupModal(false)} onCreated={onChatSelect} />}
      {showGallery && <AppGallery currentUser={currentUser} onClose={() => setShowGallery(false)} />}
      {showAccountSwitch && <AccountSwitchModal currentUser={currentUser} onClose={() => setShowAccountSwitch(false)} />}
      {showStore && <PremiumStore currentUser={currentUser} onClose={() => setShowStore(false)} />}
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { User, PremiumCustomization } from '../../types';
import { useAuth } from '../../hooks/useAuth';
import { updateProfile, updatePremiumCustomization } from '../../firebase';
import { hasPremiumAccess, ADMIN_STYLE } from '../../premiumUtils';
import { SubscriptionModal } from '../Premium/SubscriptionModal';

interface ProfilePanelProps {
  user: User;
  onClose: () => void;
  toggleDarkMode: () => void;
  isDarkMode: boolean;
  isTabMode?: boolean;
}

type ProfileViewMode = 'main' | 'edit' | 'premium' | 'privacy';

export const ProfilePanel: React.FC<ProfilePanelProps> = ({ user, onClose, toggleDarkMode, isDarkMode, isTabMode }) => {
  const { logout } = useAuth();
  const [viewMode, setViewMode] = useState<ProfileViewMode>('main');
  const [name, setName] = useState(user.name);
  const [bio, setBio] = useState(user.bio || '');
  const [showSubModal, setShowSubModal] = useState(false);
  const [customization, setCustomization] = useState<PremiumCustomization>(user.premiumCustomization || {});
  const [isSaving, setIsSaving] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handlePhotoSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = async (ev) => {
        if(ev.target?.result) {
            await updateProfile(user, { photoURL: ev.target.result as string });
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveProfile = async () => {
      setIsSaving(true);
      await updateProfile(user, { name, bio });
      setIsSaving(false);
      setViewMode('main');
  };

  const handleCustomizationUpdate = async (key: keyof PremiumCustomization, value: any) => {
      const canEquip = user.isAdmin || hasPremiumAccess(user, 'decoration');
      if (!canEquip) { setShowSubModal(true); return; }

      const newCustom = { ...customization, [key]: value };
      setCustomization(newCustom);
      await updatePremiumCustomization(user.uid, newCustom);
  };

  const renderHeader = (title: string, onBack?: () => void) => (
    <div className="h-16 px-6 flex items-center gap-4 border-b border-slate-100 dark:border-slate-800 bg-white/80 dark:bg-slate-900/80 backdrop-blur-md sticky top-0 z-20">
      {onBack ? (
        <button onClick={onBack} className="p-2 -ml-2 rounded-full hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors">
          <svg className="w-6 h-6 text-slate-600 dark:text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 19l-7-7 7-7" /></svg>
        </button>
      ) : !isTabMode && (
        <button onClick={onClose} className="p-2 -ml-2 rounded-full hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors">
           <svg className="w-6 h-6 text-slate-600 dark:text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
        </button>
      )}
      <h2 className="text-lg font-bold text-slate-900 dark:text-white">{title}</h2>
    </div>
  );

  const ListItem = ({ icon, label, subLabel, onClick, color = "slate", value }: any) => (
    <button onClick={onClick} className="w-full flex items-center justify-between p-4 hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors group">
        <div className="flex items-center gap-4">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center bg-${color}-100 dark:bg-${color}-900/20 text-${color}-600 dark:text-${color}-400 group-hover:scale-110 transition-transform`}>
                {icon}
            </div>
            <div className="text-left">
                <p className="font-bold text-sm text-slate-900 dark:text-white">{label}</p>
                {subLabel && <p className="text-[11px] font-medium text-slate-500">{subLabel}</p>}
            </div>
        </div>
        <div className="flex items-center gap-2">
            {value && <span className="text-xs font-bold text-slate-400">{value}</span>}
            <svg className="w-4 h-4 text-slate-300 group-hover:text-indigo-500 transition-colors" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 5l7 7-7 7" /></svg>
        </div>
    </button>
  );

  if (viewMode === 'edit') {
      return (
          <div className="flex flex-col h-full bg-white dark:bg-slate-900 animate-in slide-in-from-right">
              {renderHeader("Edit Profile", () => setViewMode('main'))}
              <div className="p-6 space-y-6">
                  <div className="flex justify-center">
                      <div className="relative group cursor-pointer" onClick={() => fileInputRef.current?.click()}>
                          <img src={user.photoURL} className="w-32 h-32 rounded-full object-cover border-4 border-slate-100 dark:border-slate-800" alt="" />
                          <div className="absolute inset-0 bg-black/40 rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                              <span className="text-white text-xs font-bold uppercase">Change</span>
                          </div>
                          <input type="file" ref={fileInputRef} onChange={handlePhotoSelect} className="hidden" accept="image/*" />
                      </div>
                  </div>
                  <div className="space-y-4">
                      <div>
                          <label className="text-xs font-bold text-slate-500 uppercase ml-1">Display Name</label>
                          <input value={name} onChange={e => setName(e.target.value)} className="w-full mt-1 bg-slate-100 dark:bg-slate-800 p-4 rounded-2xl outline-none font-bold text-slate-900 dark:text-white focus:ring-2 focus:ring-indigo-500/50 transition-all" />
                      </div>
                      <div>
                          <label className="text-xs font-bold text-slate-500 uppercase ml-1">About</label>
                          <textarea value={bio} onChange={e => setBio(e.target.value)} className="w-full mt-1 bg-slate-100 dark:bg-slate-800 p-4 rounded-2xl outline-none font-medium text-slate-900 dark:text-white focus:ring-2 focus:ring-indigo-500/50 transition-all resize-none h-24" />
                      </div>
                  </div>
                  <button onClick={handleSaveProfile} disabled={isSaving} className="w-full py-4 bg-indigo-500 text-white rounded-2xl font-bold shadow-lg shadow-indigo-500/20 active:scale-95 transition-all">
                      {isSaving ? 'Saving...' : 'Save Changes'}
                  </button>
              </div>
          </div>
      );
  }

  if (viewMode === 'premium') {
      return (
          <div className="flex flex-col h-full bg-white dark:bg-slate-900 animate-in slide-in-from-right">
              {renderHeader("Decorations", () => setViewMode('main'))}
              <div className="p-6 space-y-8 overflow-y-auto no-scrollbar">
                  <div className="p-6 bg-gradient-to-r from-indigo-600 to-purple-600 rounded-[2rem] text-white text-center shadow-lg relative overflow-hidden">
                      <div className="relative z-10">
                        <span className="text-4xl mb-2 block">🎨</span>
                        <h3 className="text-xl font-bold mb-1">Customize Your Look</h3>
                        <p className="text-xs opacity-80 mb-4">Stand out with glowing borders & colors.</p>
                      </div>
                  </div>

                  <div>
                      <h4 className="font-bold text-sm mb-4 px-2">Avatar Border</h4>
                      <div className="flex gap-4 overflow-x-auto pb-4 no-scrollbar px-2">
                          <button onClick={() => handleCustomizationUpdate('borderColor', '')} className="flex flex-col items-center gap-2 min-w-[60px]">
                              <div className="w-14 h-14 rounded-full border-2 border-dashed border-slate-300 dark:border-slate-700 flex items-center justify-center bg-slate-50 dark:bg-slate-800 text-slate-400">Off</div>
                              <span className="text-[10px] font-bold">None</span>
                          </button>
                          {['border-indigo-500', 'border-pink-500', 'border-amber-400', 'border-green-500', 'border-cyan-400'].map(b => (
                              <button key={b} onClick={() => handleCustomizationUpdate('borderColor', b)} className="flex flex-col items-center gap-2 min-w-[60px]">
                                  <div className={`w-14 h-14 rounded-full border-[3px] ${b} bg-slate-900 ${customization.borderColor === b ? 'ring-2 ring-indigo-500 ring-offset-2 dark:ring-offset-slate-900' : ''}`}></div>
                                  <span className="text-[10px] font-bold capitalize">{b.split('-')[1]}</span>
                              </button>
                          ))}
                      </div>
                  </div>

                  <div className="px-4 py-4 bg-slate-50 dark:bg-slate-800 rounded-2xl flex items-center justify-between">
                      <div>
                          <h4 className="font-bold text-sm">Neon Glow Effect</h4>
                          <p className="text-[10px] text-slate-500">Add a soft light behind your avatar</p>
                      </div>
                      <button onClick={() => handleCustomizationUpdate('glowEffect', !customization.glowEffect)} className={`w-12 h-7 rounded-full transition-colors relative ${customization.glowEffect ? 'bg-indigo-500' : 'bg-slate-300 dark:bg-slate-700'}`}>
                          <div className={`w-5 h-5 bg-white rounded-full absolute top-1 transition-all shadow-sm ${customization.glowEffect ? 'left-6' : 'left-1'}`}></div>
                      </button>
