import React, { useState, useRef, useEffect } from 'react';
import { User, Story, MusicMetadata } from '../../types';
import { addStory } from '../../firebase';
import { hasPremiumAccess } from '../../premiumUtils';
import { MusicPicker } from './MusicPicker';

interface StoryUploadProps {
  currentUser: User;
  onClose: () => void;
}

const BG_COLORS = [
    '#1e293b', // Slate 800
    '#be185d', // Pink 700
    '#4338ca', // Indigo 700
    '#0f766e', // Teal 700
    '#b45309', // Amber 700
    '#7f1d1d', // Red 900
    'linear-gradient(45deg, #ee7752, #e73c7e, #23a6d5, #23d5ab)',
    'linear-gradient(to top, #30cfd0 0%, #330867 100%)'
];

export const StoryUpload: React.FC<StoryUploadProps> = ({ currentUser, onClose }) => {
  const [mode, setMode] = useState<'media' | 'text'>('media');
  const [file, setFile] = useState<File | null>(null);
  const [preview, setPreview] = useState<string | null>(null);
  const [mediaType, setMediaType] = useState<'image' | 'video' | null>(null);
  const [caption, setCaption] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [showMusicPicker, setShowMusicPicker] = useState(false);
  const [selectedMusic, setSelectedMusic] = useState<MusicMetadata | null>(null);

  // Text Mode State
  const [textStatus, setTextStatus] = useState('');
  const [bgColor, setBgColor] = useState(BG_COLORS[0]);
  const [textStyle, setTextStyle] = useState<'normal' | 'bold' | 'italic'>('bold');

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Premium Check
  const hasLongStatus = hasPremiumAccess(currentUser, 'status_duration_boost');

  useEffect(() => {
    return () => {
      if (preview && preview.startsWith('blob:')) {
        URL.revokeObjectURL(preview);
      }
    };
  }, [preview]);

  const compressImage = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = (event) => {
        const img = new Image();
        img.src = event.target?.result as string;
        img.onload = () => {
          const canvas = document.createElement('canvas');
          const MAX_WIDTH = 1080;
          const MAX_HEIGHT = 1920;
          let width = img.width;
          let height = img.height;

          if (width > height) {
            if (width > MAX_WIDTH) {
              height *= MAX_WIDTH / width;
              width = MAX_WIDTH;
            }
          } else {
            if (height > MAX_HEIGHT) {
              width *= MAX_HEIGHT / height;
              height = MAX_HEIGHT;
            }
          }

          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          ctx?.drawImage(img, 0, 0, width, height);

          const dataUrl = canvas.toDataURL('image/jpeg', 0.6);
          resolve(dataUrl);
        };
        img.onerror = reject;
      };
      reader.onerror = reject;
    });
  };

  const generateTextImage = (): string => {
      const canvas = document.createElement('canvas');
      canvas.width = 1080;
      canvas.height = 1920;
      const ctx = canvas.getContext('2d');
      if(!ctx) return '';

      // Background
      if(bgColor.includes('gradient')) {
          const grad = ctx.createLinearGradient(0, 0, 0, 1920);
          ctx.fillStyle = '#1e293b'; 
          if(bgColor.includes('#ee7752')) {
              const g = ctx.createLinearGradient(0,0,1080,1920);
              g.addColorStop(0, '#ee7752'); g.addColorStop(1, '#23d5ab');
              ctx.fillStyle = g;
          } else if(bgColor.includes('#30cfd0')) {
              const g = ctx.createLinearGradient(0,1920,0,0);
              g.addColorStop(0, '#30cfd0'); g.addColorStop(1, '#330867');
              ctx.fillStyle = g;
          }
      } else {
          ctx.fillStyle = bgColor;
      }
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // Text
      ctx.fillStyle = 'white';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      const fontSize = textStatus.length < 50 ? 80 : 50;
      ctx.font = `${textStyle === 'bold' ? 'bold' : textStyle === 'italic' ? 'italic' : ''} ${fontSize}px sans-serif`;

      const words = textStatus.split(' ');
      let line = '';
      const lines = [];
      const maxWidth = 900;

      for(let n = 0; n < words.length; n++) {
          const testLine = line + words[n] + ' ';
          const metrics = ctx.measureText(testLine);
          if (metrics.width > maxWidth && n > 0) {
              lines.push(line);
              line = words[n] + ' ';
          } else {
              line = testLine;
          }
      }
      lines.push(line);

      const lineHeight = fontSize * 1.4;
      const startY = 960 - ((lines.length - 1) * lineHeight) / 2;

      lines.forEach((l, i) => {
          ctx.fillText(l, 540, startY + (i * lineHeight));
      });

      return canvas.toDataURL('image/jpeg', 0.8);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selected = e.target.files?.[0];
    if (!selected) return;

    const limit = hasLongStatus ? 15 : 5;
    if (selected.size > limit * 1024 * 1024) {
      alert(`File is too large. Limit is ${limit}MB.`);
      e.target.value = '';
      return;
    }

    const isVideo = selected.type.startsWith('video/');
    setMediaType(isVideo ? 'video' : 'image');
    setFile(selected);

    if (preview && preview.startsWith('blob:')) URL.revokeObjectURL(preview);
    setPreview(URL.createObjectURL(selected));
    e.target.value = '';
  };

  const handleUpload = async () => {
    setIsUploading(true);
    try {
      let mediaData: string;
      let type: 'image' | 'video' = 'image';

      if (mode === 'text') {
          if(!textStatus.trim()) return;
          mediaData = generateTextImage();
      } else {
          if (!file || !mediaType) return;
          type = mediaType;
          if (mediaType === 'image') {
            mediaData = await compressImage(file);
          } else {
            mediaData = await new Promise<string>((resolve, reject) => {
              const reader = new FileReader();
              reader.onload = () => resolve(reader.result as string);
              reader.onerror = () => reject(new Error("Failed to read video"));
              reader.readAsDataURL(file);
            });
          }
      }

      const newStory: Story = {
        id: crypto.randomUUID(),
        userId: currentUser.uid,
        userName: currentUser.name,
        userPhoto: currentUser.photoURL,
        mediaUrl: mediaData,
        mediaType: type,
        caption: mode === 'media' ? caption : '',
        timestamp: Date.now(),
        music: selectedMusic || undefined
      };

      await addStory(newStory);
      onClose();
    } catch (e) {
      console.error("Upload error:", e);
      alert("Storage full or file too large for browser.");
    } finally {
      setIsUploading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] bg-slate-950 flex flex-col items-center justify-center overflow-hidden">
      <input type="file" ref={fileInputRef} onChange={handleFileChange} accept="image/*,video/*" className="hidden" />

      {/* Top Controls */}
      <div className="absolute top-0 inset-x-0 p-4 flex justify-between items-center z-[110]">
          <button onClick={onClose} className="p-3 text-white hover:bg-white/10 rounded-full transition-all">
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
          {!preview && mode === 'media' && (
              <div className="flex bg-slate-800 rounded-full p-1 border border-slate-700">
                  <button onClick={() => setMode('media')} className={`px-4 py-1.5 rounded-full text-xs font-bold transition-all ${mode === 'media' ? 'bg-indigo-500 text-white' : 'text-slate-400'}`}>Media</button>
                  <button onClick={() => setMode('text')} className={`px-4 py-1.5 rounded-full text-xs font-bold transition-all ${mode === 'text' ? 'bg-indigo-500 text-white' : 'text-slate-400'}`}>Text</button>
              </div>
          )}
      </div>

      {mode === 'text' ? (
          <div className="w-full h-full flex flex-col animate-in fade-in">
              <div 
                className="flex-1 flex items-center justify-center p-8 transition-colors duration-500 relative"
                style={{ background: bgColor }}
              >
                  <textarea 
                    value={textStatus} 
                    onChange={e => setTextStatus(e.target.value)} 
                    placeholder="Type a status..." 
                    className={`w-full max-w-lg bg-transparent text-white text-center text-3xl outline-none resize-none placeholder-white/50 ${textStyle === 'bold' ? 'font-bold' : textStyle === 'italic' ? 'italic' : ''}`}
                    rows={5}
                    autoFocus
                  />

                  <button 
                    onClick={() => setTextStyle(prev => prev === 'normal' ? 'bold' : prev === 'bold' ? 'italic' : 'normal')}
                    className="absolute top-20 right-6 w-10 h-10 bg-black/20 rounded-full text-white font-serif flex items-center justify-center backdrop-blur-md"
                  >
                      {textStyle === 'normal' ? 'Aa' : textStyle === 'bold' ? 'B' : 'I'}
                  </button>

                  {/* Music Sticker (Preview) */}
                  {selectedMusic && (
                      <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 translate-y-32 bg-white/20 backdrop-blur-md p-2 rounded-xl flex items-center gap-3 pr-4">
                          <div className="w-10 h-10 bg-white/30 rounded-lg flex items-center justify-center text-white">🎵</div>
                          <div className="text-left">
                              <p className="text-white text-xs font-bold">{selectedMusic.title}</p>
                              <p className="text-white/70 text-[10px]">{selectedMusic.artist}</p>
                          </div>
                          <button onClick={() => setSelectedMusic(null)} className="text-white opacity-60 hover:opacity-100">✕</button>
                      </div>
                  )}
              </div>

              <div className="bg-black/80 p-6 pb-10 flex flex-col gap-6">
                  <div className="flex gap-3 overflow-x-auto no-scrollbar justify-center px-4">
                      {BG_COLORS.map(c => (
                          <button 
                            key={c} 
                            onClick={() => setBgColor(c)} 
                            className={`w-8 h-8 rounded-full border-2 ${bgColor === c ? 'border-white scale-110' : 'border-transparent opacity-70'} transition-all`}
                            style={{ background: c }}
                          />
                      ))}
                  </div>
                  <div className="flex items-center gap-4 px-4">
                      <button onClick={() => setShowMusicPicker(true)} className="p-3 bg-slate-800 rounded-full text-white"><span className="text-lg">🎵</span></button>
                      <button 
                        onClick={handleUpload}
                        disabled={!textStatus.trim() || isUploading}
                        className="flex-1 py-4 bg-indigo-500 rounded-2xl font-bold text-white shadow-lg active:scale-95 transition-all disabled:opacity-50"
                      >
                          {isUploading ? 'Posting...' : 'Share Status'}
                      </button>
                  </div>
              </div>
          </div>
      ) : (
          !preview ? (
            <div className="text-center space-y-6 animate-in zoom-in-95 duration-300">
              <div className="w-24 h-24 bg-indigo-500/20 rounded-full flex items-center justify-center mx-auto mb-6">
                <svg className="w-12 h-12 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" />
                </svg>
              </div>
              <h2 className="text-2xl font-bold text-white">Share a Moment</h2>

              <div className="flex gap-4">
                  <button onClick={() => fileInputRef.current?.click()} className="px-8 py-4 bg-indigo-500 hover:bg-indigo-600 text-white rounded-2xl font-bold shadow-xl active:scale-95 transition-all">
                    Choose Media
                  </button>
                  <button onClick={() => setMode('text')} className="px-8 py-4 bg-slate-800 hover:bg-slate-700 text-white rounded-2xl font-bold shadow-xl active:scale-95 transition-all">
                    Type Text
                  </button>
              </div>
            </div>
          ) : (
            <div className="w-full h-full flex flex-col bg-black">
              <div className="flex-1 relative flex items-center justify-center bg-black">
                {mediaType === 'video' ? (
                  <video key={preview} src={preview} className="max-h-full w-full object-contain" autoPlay muted loop playsInline />
                ) : (
                  <img src={preview} alt="Preview" className="max-h-full w-full object-contain" />
                )}

                {/* Music Sticker */}
                {selectedMusic && (
                    <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 bg-black/40 backdrop-blur-md p-3 rounded-xl flex items-center gap-3 pr-4 border border-white/20 animate-in zoom-in">
                        <div className="w-12 h-12 bg-white/20 rounded-lg flex items-center justify-center text-white text-2xl">🎵</div>
                        <div className="text-left">
                            <p className="text-white text-sm font-bold">{selectedMusic.title}</p>
                            <p className="text-white/70 text-xs">{selectedMusic.artist}</p>
                        </div>
                        <button onClick={() => setSelectedMusic(null)} className="text-white ml-2 opacity-60 hover:opacity-100">✕</button>
                    </div>
                )}

                <div className="absolute bottom-4 inset-x-4">
                   <input 
                    value={caption}
                    onChange={(e) => setCaption(e.target.value)}
                    placeholder="Add a caption..."
                    className="w-full bg-black/60 backdrop-blur-md border border-white/20 rounded-full px-6 py-3 text-white placeholder-white/50 focus:ring-2 focus:ring-indigo-500 outline-none transition-all text-sm text-center"
                  />
                </div>
              </div>

              <div className="p-4 flex gap-4 bg-black">
                <button 
                  onClick={() => setShowMusicPicker(true)}
                  className="p-4 bg-slate-800 rounded-2xl text-white hover:bg-slate-700"
                >
                    <span className="text-xl">🎵</span>
                </button>
                <button 
                  onClick={handleUpload}
                  disabled={isUploading}
                  className="flex-[2] py-4 bg-indigo-500 hover:bg-indigo-600 disabled:opacity-50 text-white rounded-2xl font-bold shadow-xl transition-all flex items-center justify-center gap-2 text-sm"
                >
                  {isUploading ? 'Posting...' : 'Share Story'}
                </button>
              </div>
            </div>
          )
      )}

      {showMusicPicker && (
          <MusicPicker 
            onClose={() => setShowMusicPicker(false)}
            onSelect={setSelectedMusic}
          />
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Story, User } from '../../types';
import { likeStory, sendStoryReply, viewStory, deleteStory } from '../../firebase';

interface StoryViewerProps {
  stories: Story[];
  currentUser: User;
  onClose: () => void;
}

const QUICK_REACTIONS = ['😂', '❤️', '🔥', '😮', '😢', '🙌'];

export const StoryViewer: React.FC<StoryViewerProps> = ({ stories: initialStories, currentUser, onClose }) => {
  const [stories, setStories] = useState(initialStories);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [progress, setProgress] = useState(0);
  const [replyText, setReplyText] = useState('');
  const [isLiked, setIsLiked] = useState(false);
  const [showHeartAnim, setShowHeartAnim] = useState(false);
  const [showSentAnim, setShowSentAnim] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [showMenu, setShowMenu] = useState(false);

  const menuRef = useRef<HTMLDivElement>(null);
  const audioRef = useRef<HTMLAudioElement>(null);

  const story = stories[currentIndex];
  const isOwner = story && currentUser && String(story.userId) === String(currentUser.uid);

  // Audio Playback Logic
  useEffect(() => {
      if (audioRef.current) {
          audioRef.current.pause();
          audioRef.current.currentTime = 0;

          if (story && story.music) {
              audioRef.current.src = story.music.url;
              audioRef.current.currentTime = story.music.startAt;
              // Browsers require interaction. If story is opened via click, this should work.
              // If failed (e.g. rapid switching), catch error.
              if (!isPaused) {
                  audioRef.current.play().catch(e => console.warn("Audio autoplay blocked", e));
              }
          }
      }
  }, [currentIndex, story]);

  useEffect(() => {
      if(audioRef.current) {
          if(isPaused) audioRef.current.pause();
          else if(story && story.music && audioRef.current.src) audioRef.current.play().catch(()=>{});
      }
  }, [isPaused]);

  useEffect(() => {
    if (!story) return;

    setIsLiked(story.likes?.includes(currentUser.uid) || false);
    setProgress(0);

    if (!isOwner) viewStory(story.id, currentUser.uid, currentUser.name);

    if (isPaused) return;

    const duration = story.mediaType === 'video' ? 10000 : 5000;
    const intervalTime = 50;
    const step = (intervalTime / duration) * 100;

    const timer = setInterval(() => {
      setProgress(prev => {
        if (prev >= 100) {
          clearInterval(timer);
          handleNext();
          return 100;
        }
        return prev + step;
      });
    }, intervalTime);

    return () => clearInterval(timer);
  }, [currentIndex, isPaused, story?.id, stories.length]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setShowMenu(false);
        setIsPaused(false);
      }
    };
    if (showMenu) document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [showMenu]);

  const handleNext = () => {
    if (currentIndex < stories.length - 1) {
      setCurrentIndex(prev => prev + 1);
    } else {
      onClose();
    }
  };

  const handlePrev = () => {
    if (currentIndex > 0) {
      setCurrentIndex(prev => prev - 1);
    }
  };

  const handleDelete = async () => {
    if (!story) return;
    if (window.confirm("Delete this story permanently?")) {
      await deleteStory(story.id);
      const newStories = stories.filter(s => s.id !== story.id);
      if (newStories.length === 0) {
        onClose();
      } else {
        setStories(newStories);
        if (currentIndex >= newStories.length) {
          setCurrentIndex(newStories.length - 1);
        }
      }
      setShowMenu(false);
      setIsPaused(false);
    }
  };

  const handleLike = async () => {
    if (!isLiked) {
      setShowHeartAnim(true);
      setTimeout(() => setShowHeartAnim(false), 800);
    }
    setIsLiked(!isLiked);
    await likeStory(story.id, currentUser.uid);
  };

  const triggerSentAnim = () => {
    setShowSentAnim(true);
    setTimeout(() => setShowSentAnim(false), 1500);
  };

  const handleReply = async (e?: React.FormEvent, customText?: string) => {
    e?.preventDefault();
    const text = customText || replyText.trim();
    if (!text) return;

    setReplyText('');
    setIsPaused(false);

    await sendStoryReply(story.userId, currentUser.uid, text, story);
    triggerSentAnim();

    if (customText) setTimeout(handleNext, 800);
  };

  if (!story) return null;

  return (
    <div className="fixed inset-0 z-[110] bg-black flex flex-col h-full transition-all overflow-hidden touch-none">

      {/* Hidden Audio Player */}
      <audio ref={audioRef} loop={false} />

      {/* Header with Progress Bars */}
      <div className="absolute top-0 inset-x-0 z-[130] pt-4 safe-area-top bg-gradient-to-b from-black/60 to-transparent pb-8">
        <div className="flex gap-1.5 px-3 mb-3">
          {stories.map((_, idx) => {
            const barWidth = idx < currentIndex ? '100%' : idx === currentIndex ? progress + '%' : '0%';
            return (
              <div key={idx} className="h-0.5 flex-1 bg-white/30 rounded-full overflow-hidden">
                <div className="h-full bg-white transition-all duration-100 ease-linear" style={{ width: barWidth }} />
              </div>
            );
          })}
        </div>

        <div className="px-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <img src={story.userPhoto} className="w-10 h-10 rounded-full border border-white/20 object-cover shadow-sm" alt="" />
            <div>
              <h4 className="text-white font-bold text-sm leading-none mb-0.5 shadow-black drop-shadow-md">{story.userName}</h4>
              <div className="flex items-center gap-2">
                  <span className="text-white/80 text-[10px] font-medium drop-shadow-md">
                    {new Date(story.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </span>
                  {story.music && (
                      <div className="flex items-center gap-1 bg-white/20 backdrop-blur-sm px-2 py-0.5 rounded-md">
                          <span className="text-[10px]">🎵</span>
                          <span className="text-[9px] text-white font-bold animate-pulse">{story.music.title}</span>
                      </div>
                  )}
              </div>
            </div>
          </div>
          <div className="flex items-center gap-4">
            {isOwner && (
              <div className="relative" ref={menuRef}>
                <button onClick={() => { setShowMenu(!showMenu); setIsPaused(!showMenu); }} className="text-white drop-shadow-md">
                  <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24"><path d="M12 8c1.1 0 2-.9 2-2s-.9-2-2-2-2 .9-2 2 .9 2 2 2zm0 2c-1.1 0-2 .9-2 2s.9 2 2 2 2-.9 2-2-.9-2-2-2zm0 6c-1.1 0-2 .9-2 2s.9 2 2 2 2-.9 2-2-.9-2-2-2z" /></svg>
                </button>
                {showMenu && (
                  <div className="absolute right-0 top-full mt-2 w-32 bg-white rounded-xl shadow-xl overflow-hidden animate-in zoom-in-95">
                    <button onClick={handleDelete} className="w-full px-4 py-3 flex items-center gap-2 text-red-500 font-bold text-xs hover:bg-red-50">
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                      Delete
                    </button>
                  </div>
                )}
              </div>
            )}
            <button onClick={onClose} className="text-white drop-shadow-md">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
            </button>
          </div>
        </div>
      </div>

      {/* Main Media Content */}
      <div className="flex-1 flex items-center justify-center relative bg-black">
        <div className="absolute inset-y-0 left-0 w-1/3 z-30 cursor-pointer" onClick={handlePrev} />
        <div className="absolute inset-y-0 right-0 w-1/3 z-30 cursor-pointer" onClick={handleNext} />

        {showHeartAnim && (
          <div className="absolute z-[140] animate-ping pointer-events-none">
            <svg className="w-32 h-32 text-red-500 drop-shadow-[0_0_20px_rgba(239,68,68,0.5)]" fill="currentColor" viewBox="0 0 24 24">
              <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" />
            </svg>
          </div>
        )}

        {showSentAnim && (
          <div className="absolute z-[150] bg-black/60 backdrop-blur-md px-6 py-3 rounded-full text-white font-bold border border-white/20 animate-in zoom-in">
            Sent! ✨
          </div>
        )}

        {story.mediaType === 'video' ? (
            story.mediaUrl ? (
                <video key={story.id} src={story.mediaUrl} className="max-h-full w-full object-contain" autoPlay playsInline muted={false} onPlay={() => !isPaused && setIsPaused(false)} />
            ) : <div className="text-white text-sm font-bold opacity-70">Unavailable</div>
        ) : (
            <img key={story.id} src={story.mediaUrl} className="max-h-full w-full object-contain select-none" alt="" onDoubleClick={handleLike} />
        )}

        {/* Music Sticker Visual (if playing) */}
        {story.music && (
            <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 bg-black/40 backdrop-blur-md p-3 rounded-xl flex items-center gap-3 border border-white/20 pointer-events-none z-30 animate-float">
                <div className="w-10 h-10 bg-white/20 rounded-lg flex items-center justify-center text-white text-xl animate-spin-slow">💿</div>
                <div className="text-left">
                    <p className="text-white text-sm font-bold">{story.music.title}</p>
                    <p className="text-white/70 text-xs">{story.music.artist}</p>
                </div>
            </div>
        )}

        {/* Caption Area */}
        {story.caption && (
          <div className="absolute bottom-28 inset-x-0 flex justify-center z-40 pointer-events-none">
            <div className="bg-black/50 backdrop-blur-sm px-4 py-2 rounded-xl max-w-[80%] text-center">
                <p className="text-white text-sm font-medium drop-shadow-md">{story.caption}</p>
            </div>
          </div>
        )}
      </div>

      {/* Footer Area - Reply & Like */}
      <div className="absolute bottom-0 inset-x-0 z-[120] pb-6 pt-4 px-4 bg-gradient-to-t from-black/90 via-black/50 to-transparent safe-area-bottom">
        {!isOwner ? (
            <div className="flex items-end gap-3 max-w-lg mx-auto">
                <form onSubmit={handleReply} className="flex-1 relative">
                    <input 
                      type="text"
                      placeholder="Send a reply..."
                      value={replyText}
                      onFocus={() => setIsPaused(true)}
                      onBlur={() => !replyText && setIsPaused(false)}
                      onChange={(e) => setReplyText(e.target.value)}
                      className="w-full bg-white/10 backdrop-blur-md border border-white/20 rounded-full pl-5 pr-12 py-3 text-white placeholder-white/60 focus:outline-none focus:ring-1 focus:ring-white/50 text-sm font-medium"
                    />
                    {replyText && (
                        <button type="submit" className="absolute right-2 top-1/2 -translate-y-1/2 p-1.5 bg-indigo-500 rounded-full text-white">
                            <svg className="w-4 h-4 rotate-90 translate-x-0.5" fill="currentColor" viewBox="0 0 24 24"><path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z" /></svg>
                        </button>
                    )}
                </form>
                <button 
                  onClick={handleLike}
                  className={`p-3 rounded-full bg-white/10 backdrop-blur-md border border-white/20 active:scale-90 transition-transform ${isLiked ? 'text-red-500' : 'text-white'}`}
                >
                    <svg className={`w-6 h-6 ${isLiked ? 'fill-current' : 'fill-none stroke-current'}`} strokeWidth="2" viewBox="0 0 24 24">
                      <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" />
                    </svg>
                </button>
            </div>
        ) : (
            <div className="flex items-center justify-center gap-2 text-white/70 py-2">
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg>
                <span className="text-xs font-bold uppercase tracking-widest">{story.views?.length || 0} Views</span>
            </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { User, Story, Chat, Note, MusicMetadata } from '../../types';
import { getStories, getMyChats, addNote, getNotes, sendNoteReply } from '../../firebase';
import { MusicPicker } from './MusicPicker';

interface StatusViewProps {
  currentUser: User;
  onStoryUpload: () => void;
  onStoryView: (stories: Story[]) => void;
  onChatSelect: (chat: Chat) => void;
}

export const StatusView: React.FC<StatusViewProps> = ({ currentUser, onStoryUpload, onStoryView, onChatSelect }) => {
  const [stories, setStories] = useState<Story[]>([]);
  const [notes, setNotes] = useState<Note[]>([]);
  const [groups, setGroups] = useState<Chat[]>([]);
  const [selectedViewersStory, setSelectedViewersStory] = useState<Story | null>(null);

  // Note Creation
  const [showNoteInput, setShowNoteInput] = useState(false);
  const [noteText, setNoteText] = useState('');
  const [showMusicPicker, setShowMusicPicker] = useState(false);
  const [noteMusic, setNoteMusic] = useState<MusicMetadata | null>(null);

  // Full Note Viewing
  const [viewingNote, setViewingNote] = useState<Note | null>(null);
  const [noteReplyText, setNoteReplyText] = useState('');

  // Audio for Notes
  const audioRef = useRef<HTMLAudioElement>(null);

  useEffect(() => {
    const fetchData = async () => {
      const [storyData, chatData, noteData] = await Promise.all([
        getStories(),
        getMyChats(currentUser.uid),
        getNotes()
      ]);
      setStories(storyData);
      setGroups(chatData.filter(c => c.type === 'group'));
      setNotes(noteData as Note[]);
    };
    fetchData();
    const itv = setInterval(fetchData, 5000); 
    return () => clearInterval(itv);
  }, [currentUser.uid]);

  const handlePostNote = async () => {
    if (!noteText.trim()) return;
    await addNote(currentUser.uid, currentUser.name, currentUser.photoURL, noteText.trim().substring(0, 60), noteMusic || undefined);
    setNoteText('');
    setNoteMusic(null);
    setShowNoteInput(false);
    // Optimistic Update
    const newNote: Note = { 
        id: `note_${currentUser.uid}`, 
        userId: currentUser.uid, 
        userName: currentUser.name, 
        userPhoto: currentUser.photoURL, 
        text: noteText.trim(), 
        timestamp: Date.now(),
        music: noteMusic || undefined
    };
    setNotes(prev => [newNote, ...prev.filter(n => n.userId !== currentUser.uid)]);
  };

  const handleSendNoteReply = async () => {
      if(!viewingNote || !noteReplyText.trim()) return;
      await sendNoteReply(viewingNote.userId, currentUser.uid, noteReplyText, viewingNote);
      alert("Reply Sent!");
      setNoteReplyText('');
      setViewingNote(null);
  };

  // Play music when viewing full note
  useEffect(() => {
      if(audioRef.current) {
          audioRef.current.pause();
          if(viewingNote && viewingNote.music) {
              audioRef.current.src = viewingNote.music.url;
              audioRef.current.currentTime = viewingNote.music.startAt;
              audioRef.current.play().catch(()=>{});
          }
      }
  }, [viewingNote]);

  const userStoriesMap: Record<string, Story[]> = {};
  stories.forEach(story => {
    if (!userStoriesMap[story.userId]) userStoriesMap[story.userId] = [];
    userStoriesMap[story.userId].push(story);
  });

  const myStories = userStoriesMap[currentUser.uid] || [];
  const others = Object.keys(userStoriesMap).filter(id => id !== currentUser.uid);
  const totalViews = myStories.reduce((acc, s) => acc + (s.views?.length || 0), 0);

  const myNote = notes.find(n => n.userId === currentUser.uid);
  const otherNotes = notes.filter(n => n.userId !== currentUser.uid);

  return (
    <div className="flex-1 flex flex-col bg-white dark:bg-slate-900 animate-in fade-in duration-500">
      <audio ref={audioRef} />
      <div className="p-5 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between sticky top-0 bg-white/80 dark:bg-slate-900/80 backdrop-blur-md z-10">
        <h2 className="text-xl font-bold tracking-tight text-slate-900 dark:text-white">Updates & Status</h2>
        <button 
            onClick={onStoryUpload}
            className="p-2.5 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-500/20 active:scale-95"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 4v16m8-8H4" /></svg>
        </button>
      </div>

      <div className="flex-1 overflow-y-auto px-4 py-6 space-y-10 no-scrollbar">

        {/* NOTES SECTION */}
        <section>
            <h4 className="px-2 mb-4 text-[11px] font-black uppercase text-indigo-500 tracking-widest">Thought Bubbles</h4>
            <div className="flex gap-4 overflow-x-auto no-scrollbar pb-4 px-2 snap-x">
                {/* My Note */}
                <div className="flex flex-col items-center gap-3 relative shrink-0 snap-start">
                    <div className="relative cursor-pointer group" onClick={() => setShowNoteInput(true)}>
                        <img src={currentUser.photoURL} className="w-16 h-16 rounded-[1.5rem] object-cover border-2 border-slate-100 dark:border-slate-800 shadow-sm" alt="" />
                        <div className="absolute -top-3 -right-3 bg-white dark:bg-slate-800 rounded-2xl p-3 shadow-xl max-w-[90px] min-w-[40px] flex justify-center border border-slate-100 dark:border-slate-700 group-hover:-translate-y-1 transition-transform">
                            {myNote ? (
                                <p className="text-[10px] font-bold text-center leading-tight line-clamp-2 text-slate-700 dark:text-slate-200">
                                    {myNote.music && '🎵 '}{myNote.text}
                                </p>
                            ) : (
                                <span className="text-xl text-slate-400">+</span>
                            )}
                        </div>
                    </div>
                    <span className="text-[10px] font-bold text-slate-500">Your Note</span>
                </div>

                {/* Other Notes */}
                {otherNotes.map(note => (
                    <div key={note.id} className="flex flex-col items-center gap-3 relative shrink-0 snap-start">
                        <div className="relative group cursor-pointer" onClick={() => setViewingNote(note)}>
                            <img src={note.userPhoto} className="w-16 h-16 rounded-[1.5rem] object-cover ring-2 ring-indigo-500 ring-offset-2 ring-offset-white dark:ring-offset-slate-900" alt="" />
                            <div className="absolute -top-3 -right-3 bg-white dark:bg-slate-800 rounded-2xl p-3 shadow-xl max-w-[100px] border border-slate-100 dark:border-slate-700 z-10 group-hover:-translate-y-1 transition-transform">
                                <p className="text-[10px] font-bold text-center leading-tight line-clamp-2 text-slate-700 dark:text-slate-200">
                                    {note.music && '🎵 '}{note.text}
                                </p>
                            </div>
                        </div>
                        <span className="text-[10px] font-bold text-slate-500 w-16 truncate text-center">{note.userName.split(' ')[0]}</span>
                    </div>
                ))}
            </div>
        </section>

        {/* My Status Section */}
        <section>
          <h4 className="px-2 mb-3 text-[11px] font-black uppercase text-indigo-500 tracking-widest">My Story</h4>
          <div className="flex items-center justify-between p-4 rounded-[1.5rem] bg-slate-50 dark:bg-slate-800/40 border border-slate-100 dark:border-slate-800 transition-all hover:shadow-md">
            <div 
              onClick={myStories.length > 0 ? () => onStoryView(myStories) : onStoryUpload}
              className="flex items-center gap-4 cursor-pointer flex-1"
            >
              <div className={`relative w-14 h-14 rounded-full p-[3px] ${myStories.length > 0 ? 'bg-gradient-to-tr from-indigo-500 via-purple-500 to-pink-500' : 'bg-slate-200 dark:bg-slate-700'}`}>
                <img src={currentUser.photoURL} className="w-full h-full rounded-full object-cover border-[3px] border-white dark:border-slate-900" alt="" />
                {myStories.length === 0 && (
                  <div className="absolute -bottom-1 -right-1 bg-indigo-500 text-white rounded-full p-1 border-2 border-white dark:border-slate-900 shadow-md">
                    <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4" /></svg>
                  </div>
                )}
              </div>
              <div className="flex-1">
                <p className="font-bold text-sm text-slate-900 dark:text-white">My Status</p>
                <p className="text-xs text-slate-500 font-semibold">{myStories.length > 0 ? `${myStories.length} updates active` : 'Add to your story'}</p>
              </div>
            </div>

            {myStories.length > 0 && (
              <button 
                onClick={() => setSelectedViewersStory(myStories[myStories.length - 1])}
                className="flex items-center gap-2 px-3 py-2 bg-white dark:bg-slate-700 rounded-xl shadow-sm border border-slate-200 dark:border-slate-600 hover:text-indigo-500 transition-all group"
              >
                <svg className="w-4 h-4 text-slate-400 group-hover:text-indigo-500 transition-colors" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
                </svg>
                <span className="text-xs font-black">{totalViews}</span>
              </button>
            )}
          </div>
        </section>

        {/* Recent Updates Section */}
        <section>
          <h4 className="px-2 mb-3 text-[11px] font-black uppercase text-indigo-500 tracking-widest">Recent Updates</h4>
          {others.length === 0 ? (
            <div className="p-8 text-center text-slate-400 font-semibold text-xs border border-dashed border-slate-200 dark:border-slate-800 rounded-2xl">
              No recent updates from friends.
            </div>
          ) : (
            <div className="space-y-3">
              {others.map(uid => {
                const userStories = userStoriesMap[uid];
                const first = userStories[0];
                return (
                  <div 
                    key={uid}
                    onClick={() => onStoryView(userStories)}
                    className="flex items-center gap-4 p-3.5 rounded-[1.2rem] hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-all cursor-pointer border border-transparent hover:border-slate-100 dark:hover:border-slate-700/50 group"
                  >
                    <div className="w-14 h-14 rounded-full bg-gradient-to-tr from-green-400 to-blue-500 p-[3px]">
                      <img src={first.userPhoto} className="w-full h-full rounded-full object-cover border-[3px] border-white dark:border-slate-900" alt="" />
                    </div>
                    <div className="flex-1">
                      <p className="font-bold text-sm text-slate-900 dark:text-white group-hover:text-indigo-600 dark:group-hover:text-indigo-400 transition-colors">{first.userName}</p>
                      <p className="text-[10px] text-slate-500 font-bold uppercase tracking-wider">{new Date(first.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</p>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </section>

        {/* Groups Section */}
        <section className="pb-10">
          <div className="flex items-center justify-between px-2 mb-4">
            <h4 className="text-[11px] font-black uppercase text-indigo-500 tracking-widest">Groups</h4>
            <span className="text-[9px] bg-slate-100 dark:bg-slate-800 text-slate-500 px-2 py-0.5 rounded-full font-bold">{groups.length}</span>
          </div>
          {groups.length === 0 ? (
             <div className="p-8 text-center text-slate-400 font-semibold text-xs border border-dashed border-slate-200 dark:border-slate-800 rounded-2xl">
               You aren't in any groups yet.
             </div>
          ) : (
            <div className="grid grid-cols-1 gap-3">
              {groups.map(group => (
                <div 
                  key={group.id}
                  onClick={() => onChatSelect(group)}
                  className="flex items-center gap-4 p-3.5 rounded-[1.2rem] bg-white dark:bg-slate-800/20 border border-slate-100 dark:border-slate-700 hover:border-indigo-200 dark:hover:border-indigo-900 transition-all cursor-pointer group hover:shadow-sm"
                >
                  <img src={group.groupIcon || `https://picsum.photos/seed/${group.id}/200`} className="w-12 h-12 rounded-xl object-cover shadow-sm group-hover:scale-105 transition-transform" alt="" />
                  <div className="flex-1 min-w-0">
                    <p className="font-bold text-sm truncate text-slate-900 dark:text-white">{group.name}</p>
                    <p className="text-[10px] text-slate-500 font-medium truncate mt-0.5">
                      {group.description || 'No description'}
                    </p>
                  </div>
                  <div className="p-2 text-slate-300 group-hover:text-indigo-500 transition-colors">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 5l7 7-7 7" /></svg>
                  </div>
                </div>
              ))}
            </div>
          )}
        </section>
      </div>

      {/* Full Note Viewer with Reply */}
      {viewingNote && (
          <div className="fixed inset-0 z-[250] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md animate-in zoom-in-95">
              <div className="bg-white dark:bg-slate-900 rounded-[3rem] p-8 w-full max-w-md shadow-2xl relative border border-slate-200 dark:border-slate-700 flex flex-col items-center text-center">
                  <button onClick={() => { setViewingNote(null); if(audioRef.current) audioRef.current.pause(); }} className="absolute top-6 right-6 text-slate-400 hover:text-slate-600"><svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg></button>

                  <img src={viewingNote.userPhoto} className="w-24 h-24 rounded-full object-cover mb-4 ring-4 ring-indigo-500/20" alt="" />
                  <h3 className="text-xl font-bold mb-2">{viewingNote.userName}'s Note</h3>

                  {viewingNote.music && (
                      <div className="bg-indigo-50 dark:bg-indigo-900/30 px-4 py-2 rounded-full flex items-center gap-2 mb-4 animate-bounce">
                          <span>🎵</span>
                          <span className="text-xs font-bold text-indigo-600 dark:text-indigo-400">{viewingNote.music.title} - {viewingNote.music.artist}</span>
                      </div>
                  )}

                  <div className="bg-slate-100 dark:bg-slate-800 p-6 rounded-3xl w-full mb-6 relative">
                      <span className="absolute top-2 left-4 text-4xl text-slate-300 dark:text-slate-600 font-serif">"</span>
                      <p className="text-lg font-medium text-slate-800 dark:text-slate-200 leading-relaxed px-4">{viewingNote.text}</p>
                      <span className="absolute bottom-2 right-4 text-4xl text-slate-300 dark:text-slate-600 font-serif leading-none">"</span>
                  </div>

                  {viewingNote.userId !== currentUser.uid && (
                      <div className="w-full flex items-center gap-2">
                          <input 
                            value={noteReplyText} 
                            onChange={(e) => setNoteReplyText(e.target.value)}
                            placeholder="Reply to note..." 
                            className="flex-1 bg-slate-100 dark:bg-slate-800 px-4 py-3 rounded-xl outline-none border border-transparent focus:border-indigo-500 transition-all"
                          />
                          <button 
                            onClick={handleSendNoteReply}
                            disabled={!noteReplyText.trim()}
                            className="p-3 bg-indigo-500 text-white rounded-xl shadow-lg active:scale-90 transition-transform disabled:opacity-50"
                          >
                              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
                          </button>
                      </div>
                  )}
              </div>
          </div>
      )}

      {/* Note Input Modal */}
      {showNoteInput && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md animate-in fade-in">
            <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] p-8 w-full max-w-sm shadow-2xl relative border border-slate-200 dark:border-slate-800">
                <button onClick={() => setShowNoteInput(false)} className="absolute top-6 right-6 text-slate-400 hover:text-slate-600"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg></button>
