                                    className="w-full bg-slate-950 p-3 rounded-xl border border-slate-800 text-white outline-none focus:border-indigo-500 transition-colors"
                                >
                                    <option value="decoration">Decoration</option>
                                    <option value="animation">Effect</option>
                                    <option value="badge">Badge</option>
                                </select>
                              </div>
                              <input placeholder="Item Name" value={newItem.name || ''} onChange={e => setNewItem({...newItem, name: e.target.value})} className="w-full bg-slate-950 p-3 rounded-xl border border-slate-800 text-white outline-none focus:border-indigo-500" />
                              <input placeholder="Price (INR)" type="number" value={newItem.price || ''} onChange={e => setNewItem({...newItem, price: Number(e.target.value)})} className="w-full bg-slate-950 p-3 rounded-xl border border-slate-800 text-white outline-none focus:border-indigo-500" />
                              <input placeholder="Preview (Emoji/URL)" value={newItem.previewUrl || ''} onChange={e => setNewItem({...newItem, previewUrl: e.target.value})} className="w-full bg-slate-950 p-3 rounded-xl border border-slate-800 text-white outline-none focus:border-indigo-500" />
                              <input placeholder="Value (CSS Class/ID)" value={newItem.value || ''} onChange={e => setNewItem({...newItem, value: e.target.value})} className="w-full bg-slate-950 p-3 rounded-xl border border-slate-800 text-white outline-none focus:border-indigo-500" />
                              <input placeholder="Category" value={newItem.category || ''} onChange={e => setNewItem({...newItem, category: e.target.value})} className="w-full bg-slate-950 p-3 rounded-xl border border-slate-800 text-white outline-none focus:border-indigo-500" />
                              <button onClick={handleAddStoreItem} className="w-full py-4 bg-green-600 hover:bg-green-500 rounded-xl font-black uppercase tracking-widest text-white transition-all shadow-lg shadow-green-900/20 active:scale-95">Add to Store</button>
                          </div>
                      </div>

                      {/* Items List */}
                      <div className="xl:col-span-2 grid grid-cols-2 sm:grid-cols-3 gap-4">
                          {storeItems.map(item => (
                              <div key={item.id} className="bg-slate-900 p-4 rounded-2xl border border-slate-800 relative group hover:border-indigo-500 transition-all">
                                  <div className="aspect-square bg-slate-950 rounded-xl mb-3 flex items-center justify-center text-4xl shadow-inner relative overflow-hidden">
                                      {item.type === 'decoration' && <div className={`w-full h-full border-4 ${item.value}`}></div>}
                                      <span className="relative z-10">{item.previewUrl}</span>
                                  </div>
                                  <h4 className="font-bold text-white truncate">{item.name}</h4>
                                  <div className="flex justify-between items-center mt-1">
                                    <p className="text-[10px] text-slate-500 uppercase tracking-wider">{item.category}</p>
                                    <p className="font-mono text-green-400 text-xs font-bold">₹{item.price}</p>
                                  </div>
                                  <button onClick={() => handleDeleteItem(item.id)} className="absolute top-2 right-2 p-2 bg-red-500/10 text-red-500 rounded-lg opacity-0 group-hover:opacity-100 transition-opacity hover:bg-red-500 hover:text-white">
                                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                                  </button>
                              </div>
                          ))}
                      </div>
                  </div>
              </div>
          )}

          {/* MUSIC VIEW */}
          {activeView === 'music' && (
              <div className="flex-1 flex flex-col p-4 lg:p-8 no-scrollbar h-full">
                  {/* Top Bar: Search + Add Button */}
                  <div className="flex flex-col sm:flex-row items-center justify-between gap-4 mb-6">
                      <div className="relative w-full sm:max-w-md">
                          <input 
                            value={musicSearch}
                            onChange={(e) => setMusicSearch(e.target.value)}
                            placeholder="Search songs..."
                            className="w-full bg-slate-900 border border-slate-800 rounded-xl py-3 pl-12 pr-4 text-white focus:outline-none focus:border-indigo-500"
                          />
                          <svg className="absolute left-4 top-3.5 w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                      </div>
                      <button 
                        onClick={() => setIsMusicModalOpen(true)}
                        className="w-full sm:w-auto px-6 py-3 bg-pink-600 hover:bg-pink-500 text-white rounded-xl font-bold shadow-lg shadow-pink-900/20 active:scale-95 transition-all flex items-center justify-center gap-2"
                      >
                          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" /></svg>
                          Add Music
                      </button>
                  </div>

                  {/* List of Songs */}
                  <div className="flex-1 overflow-y-auto space-y-3 pb-20">
                      {filteredSongs.length === 0 ? (
                          <div className="text-center py-20 text-slate-500">No songs found.</div>
                      ) : (
                          filteredSongs.map(song => (
                              <div key={song.id} className="flex items-center justify-between p-4 bg-slate-900 rounded-2xl border border-slate-800 hover:border-slate-700 transition-colors group">
                                  <div className="flex items-center gap-4">
                                      <div className="w-12 h-12 bg-slate-800 rounded-full flex items-center justify-center text-slate-500 group-hover:bg-indigo-500 group-hover:text-white transition-colors">
                                          🎵
                                      </div>
                                      <div>
                                          <h4 className="font-bold text-white">{song.title}</h4>
                                          <p className="text-xs text-slate-500">{song.artist} • <span className="bg-slate-800 px-2 py-0.5 rounded text-[10px] uppercase">{song.category}</span></p>
                                      </div>
                                  </div>
                                  <div className="flex items-center gap-2">
                                      <button onClick={() => handleDeleteSong(song.id)} className="p-3 bg-red-500/10 text-red-500 rounded-xl hover:bg-red-500 hover:text-white transition-all">
                                          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                                      </button>
                                  </div>
                              </div>
                          ))
                      )}
                  </div>

                  {/* Upload Modal */}
                  {isMusicModalOpen && (
                      <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-sm">
                          <div className="bg-slate-900 p-6 rounded-[2rem] border border-slate-800 w-full max-w-md shadow-2xl animate-in zoom-in-95">
                              <div className="flex justify-between items-center mb-6">
                                  <h3 className="text-xl font-bold text-white">Upload New Song</h3>
                                  <button onClick={() => setIsMusicModalOpen(false)} className="text-slate-400 hover:text-white">✕</button>
                              </div>
                              <div className="space-y-4">
                                  <input placeholder="Song Title" value={newSong.title || ''} onChange={e => setNewSong({...newSong, title: e.target.value})} className="w-full bg-slate-950 p-3 rounded-xl border border-slate-800 text-white outline-none focus:border-indigo-500" />
                                  <input placeholder="Artist Name" value={newSong.artist || ''} onChange={e => setNewSong({...newSong, artist: e.target.value})} className="w-full bg-slate-950 p-3 rounded-xl border border-slate-800 text-white outline-none focus:border-indigo-500" />
                                  <select 
                                    value={newSong.category} 
                                    onChange={e => setNewSong({...newSong, category: e.target.value})}
                                    className="w-full bg-slate-950 p-3 rounded-xl border border-slate-800 text-white outline-none focus:border-indigo-500"
                                  >
                                      <option value="Trending">Trending</option>
                                      <option value="Love">Love</option>
                                      <option value="Sad">Sad</option>
                                      <option value="Party">Party</option>
                                      <option value="Chill">Chill</option>
                                  </select>
                                  <div className="border border-dashed border-slate-700 p-6 rounded-xl text-center cursor-pointer hover:bg-slate-800/50 transition-all relative">
                                      <input type="file" accept="audio/mpeg,audio/mp3" className="absolute inset-0 opacity-0 cursor-pointer z-10" onChange={e => setSongFile(e.target.files?.[0] || null)} />
                                      <div className="flex flex-col items-center gap-2">
                                          <span className="text-2xl">📂</span>
                                          <p className="text-sm font-bold text-slate-400">{songFile ? songFile.name : "Tap to select MP3"}</p>
                                      </div>
                                  </div>
                                  <button onClick={handleUploadSong} disabled={isUploadingSong} className="w-full py-4 bg-pink-600 hover:bg-pink-500 rounded-xl font-black uppercase tracking-widest text-white transition-all shadow-lg shadow-pink-900/20 active:scale-95 disabled:opacity-50 flex items-center justify-center gap-2">
                                      {isUploadingSong ? (
                                          <>
                                            <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                                            Uploading...
                                          </>
                                      ) : 'Upload Song'}
                                  </button>
                              </div>
                          </div>
                      </div>
                  )}
              </div>
          )}

          {/* SPY VIEW */}
          {activeView === 'spy' && spyTarget && (
              <div className="flex h-full flex-col lg:flex-row">
                  {/* Spy Sidebar - Desktop */}
                  <div className="hidden lg:flex w-72 bg-slate-900 border-r border-slate-800 flex-col">
                      <div className="p-4 border-b border-slate-800 bg-red-900/10">
                          <h3 className="font-bold text-red-400 flex items-center gap-2">
                              🕵️ Spying on: {spyTarget.name}
                          </h3>
                      </div>
                      <div className="flex-1 overflow-y-auto">
                          {spyChats.map(chat => (
                              <div 
                                key={chat.id} 
                                onClick={() => handleSelectSpyChat(chat)}
                                className={`p-4 border-b border-slate-800 cursor-pointer hover:bg-slate-800 ${spyActiveChat?.id === chat.id ? 'bg-slate-800' : ''}`}
                              >
                                  <p className="font-bold text-sm truncate text-white">{chat.type === 'group' ? chat.name : 'Private Chat'}</p>
                                  <p className="text-xs text-slate-500">{chat.id}</p>
                              </div>
                          ))}
                      </div>
                  </div>

                  {/* Spy Sidebar - Mobile (Dropdown) */}
                  <div className="lg:hidden p-4 bg-slate-900 border-b border-slate-800">
                      <select 
                        className="w-full bg-slate-950 text-white p-3 rounded-xl border border-slate-800"
                        onChange={(e) => {
                            const chat = spyChats.find(c => c.id === e.target.value);
                            if (chat) handleSelectSpyChat(chat);
                        }}
                      >
                          <option value="">Select a Chat to Spy</option>
                          {spyChats.map(chat => (
                              <option key={chat.id} value={chat.id}>{chat.type === 'group' ? chat.name : chat.id}</option>
                          ))}
                      </select>
                  </div>

                  {/* Spy Chat Area */}
                  <div className="flex-1 bg-slate-950 flex flex-col min-h-0">
                      {spyActiveChat ? (
                          <>
                              <div className="h-14 border-b border-slate-800 flex items-center px-6 bg-slate-900/50">
                                  <span className="font-bold text-sm text-slate-300">Monitoring: <span className="text-white">{spyActiveChat.type === 'group' ? spyActiveChat.name : 'Private'}</span></span>
                              </div>
                              <div className="flex-1 overflow-y-auto p-4 space-y-3">
                                  {spyMessages.map(msg => (
                                      <div key={msg.id} className={`flex ${msg.senderId === spyTarget.uid ? 'justify-end' : 'justify-start'}`}>
                                          <div className={`max-w-[85%] p-3 rounded-xl ${msg.senderId === spyTarget.uid ? 'bg-indigo-900/50 border border-indigo-500/30' : 'bg-slate-800 border border-slate-700'}`}>
                                              <p className="text-[10px] text-slate-400 mb-1 opacity-70">{msg.senderId}</p>
                                              <p className="text-sm text-white">{msg.text}</p>
                                              {msg.fileUrl && <span className="text-xs text-blue-400 mt-1 block">[Media Attachment]</span>}
                                          </div>
                                      </div>
                                  ))}
                              </div>
                          </>
                      ) : (
                          <div className="flex-1 flex items-center justify-center text-slate-600 flex-col gap-4">
                              <span className="text-4xl">👁️</span>
                              <p>Select a chat to inspect messages</p>
                          </div>
                      )}
                  </div>
              </div>
          )}

      </div>
    </div>
  );
};

const ActionButton = ({ onClick, icon, color }: any) => (
    <button 
        onClick={onClick} 
        className={`w-8 h-8 flex items-center justify-center rounded-lg bg-${color}-500/10 text-${color}-400 hover:bg-${color}-500 hover:text-white transition-all`}
    >
        {icon}
    </button>
);

const StatBox = ({ label, value, color }: any) => (
    <div className={`p-5 bg-slate-900 border border-slate-800 rounded-2xl relative overflow-hidden`}>
        <h4 className="text-slate-500 text-[10px] font-bold uppercase tracking-widest mb-1">{label}</h4>
        <p className="text-2xl font-black text-white">{value}</p>
        <div className={`absolute -right-4 -bottom-4 w-20 h-20 bg-${color}-500/20 blur-[30px] rounded-full`}></div>
    </div>
);

import React, { useState, useRef } from 'react';
import { User, PremiumCustomization } from '../../types';
import { useAuth } from '../../hooks/useAuth';
import { updateProfile, updatePremiumCustomization, saveWallpaper, updatePrivacySettings } from '../../firebase';
import { hasPremiumAccess, ADMIN_STYLE } from '../../premiumUtils';
import { SubscriptionModal } from '../Premium/SubscriptionModal';

interface ProfilePanelProps {
  user: User;
  onClose: () => void;
  toggleDarkMode: () => void;
  isDarkMode: boolean;
  isTabMode?: boolean;
}

type ProfileViewMode = 'main' | 'edit' | 'premium' | 'settings' | 'privacy' | 'chats_settings';

export const ProfilePanel: React.FC<ProfilePanelProps> = ({ user, onClose, toggleDarkMode, isDarkMode, isTabMode }) => {
  const { logout } = useAuth();
  const [viewMode, setViewMode] = useState<ProfileViewMode>('main');
  const [name, setName] = useState(user.name);
  const [bio, setBio] = useState(user.bio || '');
  const [showSubModal, setShowSubModal] = useState(false);
  const [customization, setCustomization] = useState<PremiumCustomization>(user.premiumCustomization || {});
  const [isSaving, setIsSaving] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handlePhotoSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = async (ev) => {
        if(ev.target?.result) {
            await updateProfile(user, { photoURL: ev.target.result as string });
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveProfile = async () => {
      setIsSaving(true);
      await updateProfile(user, { name, bio });
      setIsSaving(false);
      setViewMode('main');
  };

  const handleCustomizationUpdate = async (key: keyof PremiumCustomization, value: any) => {
      const canEquip = user.isAdmin || hasPremiumAccess(user, 'decoration');
      if (!canEquip) { setShowSubModal(true); return; }

      const newCustom = { ...customization, [key]: value };
      setCustomization(newCustom);
      await updatePremiumCustomization(user.uid, newCustom);
  };

  const handleWallpaperSelect = async (color: string) => {
      await saveWallpaper(user.uid, 'default', color);
      alert("Global Wallpaper Updated!");
  };

  const handlePrivacyToggle = async (key: string, current: any) => {
      let newVal = !current;
      if (key === 'lastSeen') newVal = current === 'nobody' ? 'everyone' : 'nobody';

      const updated = { ...user.privacySettings, [key]: newVal };
      await updatePrivacySettings(user.uid, updated);
  };

  const renderHeader = (title: string, onBack?: () => void, rightAction?: React.ReactNode) => (
    <div className="h-16 px-6 flex items-center justify-between border-b border-slate-100 dark:border-slate-800 bg-white/80 dark:bg-slate-900/80 backdrop-blur-md sticky top-0 z-20">
      <div className="flex items-center gap-4">
        {onBack ? (
            <button onClick={onBack} className="p-2 -ml-2 rounded-full hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors">
            <svg className="w-6 h-6 text-slate-600 dark:text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 19l-7-7 7-7" /></svg>
            </button>
        ) : !isTabMode && (
            <button onClick={onClose} className="p-2 -ml-2 rounded-full hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors">
            <svg className="w-6 h-6 text-slate-600 dark:text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
            </button>
        )}
        <h2 className="text-lg font-bold text-slate-900 dark:text-white">{title}</h2>
      </div>
      {rightAction}
    </div>
  );

  const ListItem = ({ icon, label, subLabel, onClick, color = "slate", value }: any) => (
    <button onClick={onClick} className="w-full flex items-center justify-between p-4 hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors group border-b border-slate-50 dark:border-slate-800/50 last:border-0">
        <div className="flex items-center gap-4">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center bg-${color}-100 dark:bg-${color}-900/20 text-${color}-600 dark:text-${color}-400 group-hover:scale-110 transition-transform`}>
                {icon}
            </div>
            <div className="text-left">
                <p className="font-bold text-sm text-slate-900 dark:text-white">{label}</p>
                {subLabel && <p className="text-[11px] font-medium text-slate-500">{subLabel}</p>}
            </div>
        </div>
        <div className="flex items-center gap-2">
            {value && <span className="text-xs font-bold text-slate-400">{value}</span>}
            <svg className="w-4 h-4 text-slate-300 group-hover:text-indigo-500 transition-colors" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 5l7 7-7 7" /></svg>
        </div>
    </button>
  );

  // VIEW: EDIT PROFILE
  if (viewMode === 'edit') {
      return (
          <div className="flex flex-col h-full bg-white dark:bg-slate-900 animate-in slide-in-from-right">
              {renderHeader("Edit Profile", () => setViewMode('main'))}
              <div className="p-6 space-y-6">
                  <div className="flex justify-center">
                      <div className="relative group cursor-pointer" onClick={() => fileInputRef.current?.click()}>
                          <img src={user.photoURL} className="w-32 h-32 rounded-full object-cover border-4 border-slate-100 dark:border-slate-800" alt="" />
                          <div className="absolute inset-0 bg-black/40 rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                              <span className="text-white text-xs font-bold uppercase">Change</span>
                          </div>
                          <input type="file" ref={fileInputRef} onChange={handlePhotoSelect} className="hidden" accept="image/*" />
                      </div>
                  </div>
                  <div className="space-y-4">
                      <div>
                          <label className="text-xs font-bold text-slate-500 uppercase ml-1">Display Name</label>
                          <input value={name} onChange={e => setName(e.target.value)} className="w-full mt-1 bg-slate-100 dark:bg-slate-800 p-4 rounded-2xl outline-none font-bold text-slate-900 dark:text-white focus:ring-2 focus:ring-indigo-500/50 transition-all" />
                      </div>
                      <div>
                          <label className="text-xs font-bold text-slate-500 uppercase ml-1">About</label>
                          <textarea value={bio} onChange={e => setBio(e.target.value)} className="w-full mt-1 bg-slate-100 dark:bg-slate-800 p-4 rounded-2xl outline-none font-medium text-slate-900 dark:text-white focus:ring-2 focus:ring-indigo-500/50 transition-all resize-none h-24" />
                      </div>
                  </div>
                  <button onClick={handleSaveProfile} disabled={isSaving} className="w-full py-4 bg-indigo-500 text-white rounded-2xl font-bold shadow-lg shadow-indigo-500/20 active:scale-95 transition-all">
                      {isSaving ? 'Saving...' : 'Save Changes'}
                  </button>
              </div>
          </div>
      );
  }

  // VIEW: PREMIUM
  if (viewMode === 'premium') {
      return (
          <div className="flex flex-col h-full bg-white dark:bg-slate-900 animate-in slide-in-from-right">
              {renderHeader("Decorations", () => setViewMode('main'))}
              <div className="p-6 space-y-8 overflow-y-auto no-scrollbar">
                  {/* ... Decoration content ... */}
                  <div className="p-6 bg-gradient-to-r from-indigo-600 to-purple-600 rounded-[2rem] text-white text-center shadow-lg relative overflow-hidden">
                      <div className="relative z-10">
                        <span className="text-4xl mb-2 block">🎨</span>
                        <h3 className="text-xl font-bold mb-1">Customize Your Look</h3>
                        <p className="text-xs opacity-80 mb-4">Stand out with glowing borders & colors.</p>
                      </div>
                  </div>
                  <div>
                      <h4 className="font-bold text-sm mb-4 px-2">Avatar Border</h4>
                      <div className="flex gap-4 overflow-x-auto pb-4 no-scrollbar px-2">
                          <button onClick={() => handleCustomizationUpdate('borderColor', '')} className="flex flex-col items-center gap-2 min-w-[60px]">
                              <div className="w-14 h-14 rounded-full border-2 border-dashed border-slate-300 dark:border-slate-700 flex items-center justify-center bg-slate-50 dark:bg-slate-800 text-slate-400">Off</div>
                              <span className="text-[10px] font-bold">None</span>
                          </button>
                          {['border-indigo-500', 'border-pink-500', 'border-amber-400', 'border-green-500', 'border-cyan-400'].map(b => (
                              <button key={b} onClick={() => handleCustomizationUpdate('borderColor', b)} className="flex flex-col items-center gap-2 min-w-[60px]">
                                  <div className={`w-14 h-14 rounded-full border-[3px] ${b} bg-slate-900 ${customization.borderColor === b ? 'ring-2 ring-indigo-500 ring-offset-2 dark:ring-offset-slate-900' : ''}`}></div>
                                  <span className="text-[10px] font-bold capitalize">{b.split('-')[1]}</span>
                              </button>
                          ))}
                      </div>
                  </div>
                  <div className="px-4 py-4 bg-slate-50 dark:bg-slate-800 rounded-2xl flex items-center justify-between">
                      <div>
                          <h4 className="font-bold text-sm">Neon Glow Effect</h4>
                          <p className="text-[10px] text-slate-500">Add a soft light behind your avatar</p>
                      </div>
                      <button onClick={() => handleCustomizationUpdate('glowEffect', !customization.glowEffect)} className={`w-12 h-7 rounded-full transition-colors relative ${customization.glowEffect ? 'bg-indigo-500' : 'bg-slate-300 dark:bg-slate-700'}`}>
                          <div className={`w-5 h-5 bg-white rounded-full absolute top-1 transition-all shadow-sm ${customization.glowEffect ? 'left-6' : 'left-1'}`}></div>
                      </button>
                  </div>
              </div>
              {showSubModal && <SubscriptionModal currentUser={user} onClose={() => setShowSubModal(false)} />}
          </div>
      );
  }

  // VIEW: SETTINGS MAIN
  if (viewMode === 'settings') {
      return (
          <div className="flex flex-col h-full bg-white dark:bg-slate-900 animate-in slide-in-from-right">
              {renderHeader("Settings", () => setViewMode('main'))}
              <div className="p-4 space-y-6">
                <div className="bg-white dark:bg-slate-900 rounded-3xl overflow-hidden border border-slate-100 dark:border-slate-800 shadow-sm">
                    <div className="divide-y divide-slate-100 dark:divide-slate-800">
                        <ListItem 
                            icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z" /></svg>}
                            label="Chats"
                            subLabel="Wallpaper, Font Size"
                            color="indigo"
                            onClick={() => setViewMode('chats_settings')}
                        />
                        <ListItem 
                            icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg>}
                            label="Privacy"
