import { HomeFeed } from './HomeFeed';
import { BottomNav } from './BottomNav';
import { initiateCall, getIncomingCall, getUserById, updateCallStatus, cleanOldCalls, subscribeToNicknames } from '../../firebase';

interface ChatDashboardProps {
  currentUser: User;
  toggleDarkMode: () => void;
  isDarkMode: boolean;
}

export type NavTab = 'home' | 'search' | 'add' | 'reels' | 'profile' | 'chats';

export const ChatDashboard: React.FC<ChatDashboardProps> = ({ currentUser, toggleDarkMode, isDarkMode }) => {
  const [activeTab, setActiveTab] = useState<NavTab>('home');
  const [selectedChat, setSelectedChat] = useState<Chat | null>(null);
  const [showStoryUpload, setShowStoryUpload] = useState(false);
  const [viewingStories, setViewingStories] = useState<Story[] | null>(null);
  const [viewingUser, setViewingUser] = useState<User | null>(null);
  const [activeCall, setActiveCall] = useState<CallSession | null>(null);
  const [nicknames, setNicknames] = useState<Record<string, string>>({});

  useEffect(() => {
    const unsub = subscribeToNicknames(currentUser.uid, (data) => setNicknames(data));
    return () => unsub();
  }, [currentUser.uid]);

  useEffect(() => {
    const poll = async () => {
      cleanOldCalls();
      if (activeCall) return; 
      const incoming = await getIncomingCall(currentUser.uid);
      if (incoming) {
        const caller = await getUserById(incoming.callerId);
        if (caller) {
          setActiveCall({
            id: incoming.id, partner: caller, type: incoming.type, callerId: incoming.callerId,
            receiverId: incoming.receiverId, status: incoming.status, isIncoming: true, timestamp: incoming.timestamp
          });
        }
      }
    };
    const itv = setInterval(poll, 3000);
    return () => clearInterval(itv);
  }, [currentUser.uid, activeCall]);

  const startCall = async (user: User, type: 'voice' | 'video') => {
    const call = await initiateCall(currentUser.uid, user.uid, type);
    setActiveCall({ 
      id: call.id, partner: user, type, callerId: currentUser.uid, receiverId: user.uid,
      status: 'ringing', isIncoming: false, timestamp: call.timestamp
    });
  };

  // Main view switcher based on activeTab
  const renderTabContent = () => {
    switch (activeTab) {
      case 'home':
        return (
          <HomeFeed 
            currentUser={currentUser}
            onOpenDMs={() => setActiveTab('chats')}
            onUploadPost={() => setShowStoryUpload(true)}
            onOpenStory={setViewingStories}
          />
        );
      case 'chats':
        return (
          <Sidebar 
            currentUser={currentUser} 
            onChatSelect={setSelectedChat} 
            activeChatId={selectedChat?.id}
            nicknames={nicknames}
          />
        );
      case 'profile':
        return (
          <ProfilePanel 
            user={currentUser} 
            onClose={() => setActiveTab('home')} 
            toggleDarkMode={toggleDarkMode}
            isDarkMode={isDarkMode}
            isTabMode={true}
          />
        );
      case 'search':
        return (
          <div className="flex-1 flex items-center justify-center p-8 text-center animate-in fade-in">
             <div className="max-w-xs">
                <span className="material-symbols-outlined text-6xl text-primary mb-4">explore</span>
                <h2 className="text-xl font-bold">Explore Content</h2>
                <p className="text-sm text-slate-500 mt-2">Search for creators and trending topics coming soon.</p>
             </div>
          </div>
        );
      case 'reels':
        return (
          <div className="flex-1 flex items-center justify-center p-8 text-center animate-in fade-in">
             <div className="max-w-xs">
                <span className="material-symbols-outlined text-6xl text-primary mb-4">movie</span>
                <h2 className="text-xl font-bold">Lumina Reels</h2>
                <p className="text-sm text-slate-500 mt-2">Short-form video experience is being polished.</p>
             </div>
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="flex flex-col h-[100dvh] w-full bg-background-light dark:bg-background-dark overflow-hidden font-display">

      {/* Top Main Content Area */}
      <div className="flex-1 relative flex flex-col overflow-hidden">
        {/* If a chat is selected, it covers the whole screen (Mobile) or stays relative */}
        {selectedChat ? (
          <ChatWindow 
            chat={selectedChat} 
            currentUser={currentUser} 
            onClose={() => setSelectedChat(null)}
            onUserClick={setViewingUser}
            onCallStart={startCall}
            nicknames={nicknames}
          />
        ) : (
          renderTabContent()
        )}
      </div>

      {/* Global Bottom Navigation */}
      {!selectedChat && (
        <BottomNav 
          activeTab={activeTab} 
          onTabChange={(tab) => {
            if (tab === 'add') setShowStoryUpload(true);
            else setActiveTab(tab);
          }} 
          currentUser={currentUser} 
        />
      )}

      {/* Modals & Overlays */}
      {showStoryUpload && <StoryUpload currentUser={currentUser} onClose={() => setShowStoryUpload(false)} />}
      {viewingStories && <StoryViewer stories={viewingStories} currentUser={currentUser} onClose={() => setViewingStories(null)} />}
      {viewingUser && <PublicProfile user={viewingUser} onClose={() => setViewingUser(null)} onCallStart={startCall} nickname={nicknames[viewingUser.uid]} />}
      {activeCall && <CallModal session={activeCall} onHangUp={() => setActiveCall(null)} />}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Post, User, Story } from '../../types';
import { getFeedPosts, toggleLikePost, toggleBookmarkPost, getStories } from '../../firebase';

interface HomeFeedProps {
  currentUser: User;
  onOpenDMs: () => void;
  onUploadPost: () => void;
  onOpenStory: (stories: Story[]) => void;
}

export const HomeFeed: React.FC<HomeFeedProps> = ({ currentUser, onOpenDMs, onUploadPost, onOpenStory }) => {
  const [posts, setPosts] = useState<Post[]>([]);
  const [stories, setStories] = useState<Story[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const load = async () => {
      const [feed, activeStories] = await Promise.all([
        getFeedPosts(),
        getStories()
      ]);
      setPosts(feed);
      setStories(activeStories);
      setLoading(false);
    };
    load();
  }, []);

  const handleLike = async (postId: string) => {
    await toggleLikePost(postId, currentUser.uid);
    setPosts(prev => prev.map(p => {
        if(p.id === postId) {
            const isLiked = p.likes.includes(currentUser.uid);
            return {
                ...p,
                likes: isLiked ? p.likes.filter(id => id !== currentUser.uid) : [...p.likes, currentUser.uid]
            };
        }
        return p;
    }));
  };

  const handleBookmark = async (postId: string) => {
    await toggleBookmarkPost(postId, currentUser.uid);
    setPosts(prev => prev.map(p => {
        if(p.id === postId) {
            const isBookmarked = p.bookmarks.includes(currentUser.uid);
            return {
                ...p,
                bookmarks: isBookmarked ? p.bookmarks.filter(id => id !== currentUser.uid) : [...p.bookmarks, currentUser.uid]
            };
        }
        return p;
    }));
  };

  // Group stories by user
  const userStoriesMap: Record<string, Story[]> = {};
  stories.forEach(s => {
    if(!userStoriesMap[s.userId]) userStoriesMap[s.userId] = [];
    userStoriesMap[s.userId].push(s);
  });
  const storyUserIds = Object.keys(userStoriesMap);

  return (
    <div className="flex-1 flex flex-col bg-background-light dark:bg-background-dark overflow-hidden animate-in fade-in">
        {/* Top Navigation Bar */}
        <nav className="sticky top-0 z-50 flex items-center justify-between px-4 py-4 bg-background-light/80 dark:bg-background-dark/80 backdrop-blur-md">
            <div className="flex items-center gap-2">
                <div className="bg-primary size-8 rounded-lg flex items-center justify-center shadow-lg shadow-primary/20">
                    <span className="material-symbols-outlined text-white text-xl">blur_on</span>
                </div>
                <h1 className="text-xl font-black tracking-tighter">LUMINA</h1>
            </div>
            <div className="flex items-center gap-4">
                <button 
                    onClick={onOpenDMs}
                    className="relative p-2 rounded-full hover:bg-black/5 dark:hover:bg-white/10 transition-colors"
                >
                    <span className="material-symbols-outlined text-2xl">send</span>
                    <span className="absolute top-2 right-2 flex h-2 w-2 rounded-full bg-primary animate-pulse"></span>
                </button>
            </div>
        </nav>

        <div className="flex-1 overflow-y-auto no-scrollbar pb-24">
            {/* Stories Carousel */}
            <section className="w-full overflow-x-auto py-4">
                <div className="flex px-4 gap-5 min-w-max">
                    {/* My Story Add */}
                    <div className="flex flex-col items-center gap-2 w-16 group cursor-pointer" onClick={onUploadPost}>
                        <div className="relative w-16 h-16 rounded-full p-[2px] bg-slate-200 dark:bg-slate-800">
                            <img src={currentUser.photoURL} className="w-full h-full rounded-full object-cover border-2 border-background-dark" alt="" />
                            <div className="absolute bottom-0 right-0 bg-primary rounded-full border-2 border-background-dark p-0.5 flex items-center justify-center">
                                <span className="material-symbols-outlined text-white text-[14px]">add</span>
                            </div>
                        </div>
                        <p className="text-[11px] font-medium opacity-70">Your Story</p>
                    </div>

                    {/* Active User Stories */}
                    {storyUserIds.map(uid => (
                        <div key={uid} className="flex flex-col items-center gap-2 w-16 cursor-pointer" onClick={() => onOpenStory(userStoriesMap[uid])}>
                            <div className="w-16 h-16 rounded-full p-[2px] bg-gradient-to-tr from-primary to-purple-500">
                                <img src={userStoriesMap[uid][0].userPhoto} className="w-full h-full rounded-full object-cover border-2 border-background-dark" alt="" />
                            </div>
                            <p className="text-[11px] font-medium truncate w-full text-center">{userStoriesMap[uid][0].userName.split(' ')[0]}</p>
                        </div>
                    ))}
                </div>
            </section>

            {/* Feed List */}
            <main className="flex flex-col gap-8 pb-24">
                {loading ? (
                    <div className="flex justify-center py-20">
                        <div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
                    </div>
                ) : posts.length === 0 ? (
                    <div className="text-center py-20 opacity-40">
                        <span className="material-symbols-outlined text-6xl">grid_off</span>
                        <p className="font-bold uppercase tracking-widest mt-4">Feed is quiet</p>
                    </div>
                ) : (
                    posts.map(post => (
                        <article key={post.id} className="relative w-full @container">
                            {/* Post Header Overlay */}
                            <div className="absolute top-0 left-0 right-0 z-10 p-4 flex items-center justify-between bg-gradient-to-b from-black/50 to-transparent">
                                <div className="flex items-center gap-3">
                                    <img src={post.userPhoto} className="w-10 h-10 rounded-full border border-white/20 object-cover" alt="" />
                                    <div className="flex flex-col">
                                        <span className="text-sm font-bold text-white leading-none">{post.userName}</span>
                                        <span className="text-[10px] text-white/70 flex items-center gap-1">
                                            <span className="material-symbols-outlined text-[10px]">location_on</span> {post.location || 'Unknown'}
                                        </span>
                                    </div>
                                </div>
                                <button className="text-white">
                                    <span className="material-symbols-outlined">more_vert</span>
                                </button>
                            </div>

                            {/* Main Media */}
                            <div className="w-full aspect-[4/5] bg-slate-900 overflow-hidden">
                                {post.mediaType === 'video' ? (
                                    <video src={post.mediaUrl} className="w-full h-full object-cover" autoPlay muted loop playsInline />
                                ) : (
                                    <img src={post.mediaUrl} className="w-full h-full object-cover" alt="" />
                                )}
                            </div>

                            {/* Glass Interaction Bar */}
                            <div className="absolute bottom-4 left-4 right-4 z-10">
                                <div className="bg-black/40 backdrop-blur-xl border border-white/10 rounded-xl p-3 flex flex-col gap-3">
                                    <div className="flex items-center justify-between w-full">
                                        <div className="flex items-center gap-4">
                                            <button 
                                                onClick={() => handleLike(post.id)}
                                                className={`flex items-center gap-1.5 transition-all active:scale-125 ${post.likes.includes(currentUser.uid) ? 'text-primary' : 'text-white'}`}
                                            >
                                                <span className="material-symbols-outlined" style={post.likes.includes(currentUser.uid) ? { fontVariationSettings: "'FILL' 1" } : {}}>favorite</span>
                                                <span className="text-xs font-semibold">{post.likes.length}</span>
                                            </button>
                                            <button className="flex items-center gap-1.5 text-white">
                                                <span className="material-symbols-outlined">chat_bubble</span>
                                                <span className="text-xs font-semibold">{post.commentCount}</span>
                                            </button>
                                            <button className="text-white hover:text-primary transition-colors">
                                                <span className="material-symbols-outlined">send</span>
                                            </button>
                                        </div>
                                        <button 
                                            onClick={() => handleBookmark(post.id)}
                                            className={`transition-all active:scale-125 ${post.bookmarks.includes(currentUser.uid) ? 'text-primary' : 'text-white'}`}
                                        >
                                            <span className="material-symbols-outlined" style={post.bookmarks.includes(currentUser.uid) ? { fontVariationSettings: "'FILL' 1" } : {}}>bookmark</span>
                                        </button>
                                    </div>
                                    <div className="text-white text-[13px] leading-relaxed">
                                        <span className="font-bold mr-1">{post.userName}</span> 
                                        {post.caption} <button className="opacity-60 font-medium">more</button>
                                    </div>
                                </div>
                            </div>
                        </article>
                    ))
                )}
            </main>
        </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { User, Chat } from '../../types';
import { getAllUsers, getMyChats, togglePinChat, subscribeToUser } from '../../firebase';
import { CreateGroupModal } from './CreateGroupModal';
import { AppGallery } from './AppGallery';
import { AccountSwitchModal } from './AccountSwitchModal';
import { PremiumStore } from '../Premium/PremiumStore';
import { ROLE_STYLES, getBadgeIcon } from '../../premiumUtils';

interface SidebarProps {
  currentUser: User;
  onChatSelect: (chat: Chat) => void;
  activeChatId?: string;
  nicknames: Record<string, string>; 
}

export const Sidebar: React.FC<SidebarProps> = ({ 
  currentUser, onChatSelect, activeChatId, nicknames
}) => {
  const [search, setSearch] = useState('');
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [chats, setChats] = useState<Chat[]>([]);
  const [loading, setLoading] = useState(true);
  const [showGroupModal, setShowGroupModal] = useState(false);
  const [showStore, setShowStore] = useState(false);
  const [pinnedChats, setPinnedChats] = useState<string[]>([]);

  const [showMenu, setShowMenu] = useState(false);
  const [showGallery, setShowGallery] = useState(false);
  const [showAccountSwitch, setShowAccountSwitch] = useState(false);

  useEffect(() => {
    const unsubUser = subscribeToUser(currentUser.uid, (data) => {
        setPinnedChats(data.pinnedChats || []);
    });

    const fetchData = async () => {
      try {
        const [usersData, chatsData] = await Promise.all([
            getAllUsers(),
            getMyChats(currentUser.uid)
        ]);
        const myBlocked = currentUser.blockedUsers || [];
        setAllUsers(usersData.filter(u => u.uid !== currentUser.uid && !myBlocked.includes(u.uid)));
        setChats(chatsData);
        setLoading(false);
      } catch(e) { }
    };

    fetchData();
    const itv = setInterval(fetchData, 5000);
    return () => { unsubUser(); clearInterval(itv); };
  }, [currentUser.uid]);

  const searchResults = useMemo(() => {
    const term = search.toLowerCase().trim();
    let visibleChats = chats.filter(c => !c.lockedBy?.includes(currentUser.uid));

    visibleChats.sort((a, b) => {
        const isAPinned = pinnedChats.includes(a.id);
        const isBPinned = pinnedChats.includes(b.id);
        if (isAPinned && !isBPinned) return -1;
        if (!isAPinned && isBPinned) return 1;
        return (b.updatedAt || 0) - (a.updatedAt || 0);
    });

    if (!term) return { chats: visibleChats, users: [] };
    const matchedUsers = allUsers.filter(u => (nicknames[u.uid] || u.name).toLowerCase().includes(term));
    const matchedChats = visibleChats.filter(c => {
      const name = c.type === 'group' ? c.name : (nicknames[c.participants.find(p=>p!==currentUser.uid)!] || 'User');
      return name?.toLowerCase().includes(term);
    });
    return { chats: matchedChats, users: matchedUsers };
  }, [search, allUsers, chats, currentUser.uid, pinnedChats, nicknames]);

  const getChatInfo = (chat: Chat) => {
    if (chat.type === 'group') return { name: chat.name || 'Group', photo: chat.groupIcon || `https://picsum.photos/seed/${chat.id}/200` };
    const otherId = chat.participants.find(p => p !== currentUser.uid);
    const user = allUsers.find(u => u.uid === otherId);
    return { name: user ? (nicknames[user.uid] || user.name) : 'User', photo: user?.photoURL || `https://picsum.photos/seed/${otherId}/200`, userObj: user };
  };

  return (
    <div className="w-full h-full flex flex-col bg-background-light dark:bg-background-dark animate-in slide-in-from-left duration-300">
      {/* Header */}
      <div className="h-20 px-6 flex items-center justify-between shrink-0 bg-background-light/80 dark:bg-background-dark/80 backdrop-blur-md border-b border-gray-100 dark:border-border-dark sticky top-0 z-10">
         <div>
            <h2 className="text-xl font-bold tracking-tight">Messages</h2>
            <p className="text-[10px] font-black uppercase text-primary tracking-[0.2em]">{chats.length} Active Conversations</p>
         </div>
         <div className="flex gap-2">
            <button onClick={()=>setShowGroupModal(true)} className="p-2 bg-slate-100 dark:bg-slate-800 rounded-full hover:bg-primary hover:text-white transition-all">
                <span className="material-symbols-outlined text-xl">add_comment</span>
            </button>
            <button onClick={()=>setShowMenu(!showMenu)} className="p-2 bg-slate-100 dark:bg-slate-800 rounded-full">
                <span className="material-symbols-outlined text-xl">more_vert</span>
            </button>
         </div>
      </div>

      {showMenu && (
          <div className="absolute right-6 top-16 bg-white dark:bg-slate-900 shadow-2xl rounded-2xl p-2 z-50 w-48 border border-gray-100 dark:border-border-dark animate-in zoom-in-95">
              <button onClick={()=>{setShowGallery(true); setShowMenu(false)}} className="w-full p-3 text-left hover:bg-slate-50 dark:hover:bg-slate-800 rounded-xl text-sm font-bold flex items-center gap-3">
                  <span className="material-symbols-outlined text-lg">photo_library</span> Gallery
              </button>
              <button onClick={()=>{setShowAccountSwitch(true); setShowMenu(false)}} className="w-full p-3 text-left hover:bg-slate-50 dark:hover:bg-slate-800 rounded-xl text-sm font-bold flex items-center gap-3">
                  <span className="material-symbols-outlined text-lg">sync_alt</span> Switch Account
              </button>
          </div>
      )}

      {/* List */}
      <div className="flex-1 overflow-y-auto px-4 py-2 space-y-2 no-scrollbar">
          {searchResults.chats.map(chat => {
              const info = getChatInfo(chat);
              const isActive = activeChatId === chat.id;
              const isPinned = pinnedChats.includes(chat.id);

              return (
                  <div 
                    key={chat.id} 
                    onClick={() => onChatSelect(chat)} 
                    className={`flex items-center gap-4 p-4 rounded-2xl cursor-pointer transition-all ${isActive ? 'bg-primary text-white shadow-lg shadow-primary/20' : 'hover:bg-white dark:hover:bg-card-dark border border-transparent hover:border-gray-100 dark:hover:border-border-dark'}`}
                  >
                      <div className="relative">
                          <img src={info.photo} className="w-14 h-14 rounded-full object-cover border-2 border-white dark:border-slate-800 shadow-sm" alt="" />
                          {info.userObj?.status === 'online' && <div className="absolute bottom-0 right-0 w-4 h-4 bg-green-500 rounded-full border-2 border-white dark:border-background-dark"></div>}
                      </div>
                      <div className="flex-1 min-w-0">
                          <div className="flex justify-between items-center mb-0.5">
                              <h4 className="font-bold text-[15px] truncate">{info.name}</h4>
                              <span className={`text-[10px] font-bold ${isActive ? 'text-white/80' : 'text-slate-400'}`}>
                                  {chat.lastMessage ? new Date(chat.lastMessage.timestamp).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'}) : ''}
                              </span>
                          </div>
                          <div className="flex items-center justify-between">
                            <p className={`text-[13px] truncate ${isActive ? 'text-white/70' : 'text-slate-500'}`}>{chat.lastMessage?.text || 'Start chatting...'}</p>
                            {isPinned && <span className="material-symbols-outlined text-sm rotate-45">push_pin</span>}
                          </div>
                      </div>
                  </div>
              );
          })}
      </div>

      {showGroupModal && <CreateGroupModal currentUser={currentUser} onClose={() => setShowGroupModal(false)} onCreated={onChatSelect} />}
      {showGallery && <AppGallery currentUser={currentUser} onClose={() => setShowGallery(false)} />}
      {showAccountSwitch && <AccountSwitchModal currentUser={currentUser} onClose={() => setShowAccountSwitch(false)} />}
      {showStore && <PremiumStore currentUser={currentUser} onClose={() => setShowStore(false)} />}
    </div>
  );
};

