  return (
    <div className="flex items-end gap-3 mb-4 group animate-in slide-in-from-left-4 duration-300">
        <div className="w-8 shrink-0 mb-1">
            {!hideAvatar && !isOwn && (
                <img 
                    src={senderUser?.photoURL || `https://picsum.photos/seed/${message.senderId}/100`} 
