    const bookmarks = snap.data().bookmarks || [];
    if (bookmarks.includes(userId)) await updateDoc(postRef, { bookmarks: arrayRemove(userId) });
    else await updateDoc(postRef, { bookmarks: arrayUnion(userId) });
  }
};

