            <div className="flex flex-1 flex-col gap-1 rounded-[1.5rem] bg-slate-100 dark:bg-white/5 py-4 items-center text-center backdrop-blur-sm border border-transparent dark:border-white/5">
              <p className="text-xl font-black leading-tight">1.2K</p>
              <p className="text-slate-500 dark:text-slate-400 text-[10px] font-black uppercase tracking-widest">Followers</p>
            </div>
            <div className="flex flex-1 flex-col gap-1 rounded-[1.5rem] bg-slate-100 dark:bg-white/5 py-4 items-center text-center backdrop-blur-sm border border-transparent dark:border-white/5">
              <p className="text-xl font-black leading-tight">482</p>
              <p className="text-slate-500 dark:text-slate-400 text-[10px] font-black uppercase tracking-widest">Following</p>
            </div>
          </div>
        </section>

        {/* Mutual Friends Section */}
        <section className="px-6 mb-8">
          <div className="flex flex-col gap-3">
            <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-500 dark:text-slate-400">Mutual Friends</h3>
            <div className="flex items-center gap-3">
              <div className="flex items-center">
                <div className="bg-center bg-no-repeat aspect-square bg-cover border-2 border-background-light dark:border-background-dark bg-slate-800 rounded-full h-9 w-9 relative z-30" style={{ backgroundImage: `url("https://picsum.photos/seed/a1/100")` }}></div>
                <div className="bg-center bg-no-repeat aspect-square bg-cover border-2 border-background-light dark:border-background-dark bg-slate-800 rounded-full h-9 w-9 -ml-3 relative z-20" style={{ backgroundImage: `url("https://picsum.photos/seed/a2/100")` }}></div>
                <div className="bg-center bg-no-repeat aspect-square bg-cover border-2 border-background-light dark:border-background-dark bg-slate-800 rounded-full h-9 w-9 -ml-3 relative z-10" style={{ backgroundImage: `url("https://picsum.photos/seed/a3/100")` }}></div>
              </div>
              <p className="text-xs text-slate-500 dark:text-slate-400 font-medium leading-tight">
                Followed by <span className="text-slate-900 dark:text-white font-bold">sarah_j</span>, <span className="text-slate-900 dark:text-white font-bold">m_ross</span> and 12 others
              </p>
            </div>
          </div>
        </section>

        {/* Posts Grid Tabs */}
        <div className="flex border-b border-slate-200 dark:border-white/5 mb-0.5">
          <button onClick={() => setActiveTab('grid')} className={`flex-1 py-4 flex items-center justify-center transition-all ${activeTab === 'grid' ? 'text-primary border-b-2 border-primary' : 'text-slate-400 opacity-50'}`}>
            <span className="material-symbols-outlined" style={activeTab === 'grid' ? { fontVariationSettings: "'FILL' 1" } : {}}>grid_view</span>
          </button>
          <button onClick={() => setActiveTab('reels')} className={`flex-1 py-4 flex items-center justify-center transition-all ${activeTab === 'reels' ? 'text-primary border-b-2 border-primary' : 'text-slate-400 opacity-50'}`}>
            <span className="material-symbols-outlined">video_library</span>
          </button>
          <button onClick={() => setActiveTab('tagged')} className={`flex-1 py-4 flex items-center justify-center transition-all ${activeTab === 'tagged' ? 'text-primary border-b-2 border-primary' : 'text-slate-400 opacity-50'}`}>
            <span className="material-symbols-outlined">person_pin</span>
          </button>
        </div>

        {/* Posts Grid */}
        <section className="grid grid-cols-3 gap-0.5">
            {activeTab === 'grid' && userPosts.length === 0 ? (
                <div className="col-span-3 py-20 text-center opacity-30">
                    <span className="material-symbols-outlined text-5xl">photo_library</span>
                    <p className="text-[10px] font-black uppercase tracking-widest mt-4">No posts found</p>
                </div>
            ) : (
                userPosts.map(p => (
                    <div key={p.id} onClick={() => onOpenPost?.(p)} className="aspect-square bg-slate-200 dark:bg-white/5 overflow-hidden relative group cursor-pointer active:opacity-70 transition-opacity">
                        {p.mediaType === 'video' ? (
                            <>
                                <video src={p.mediaUrl} className="w-full h-full object-cover" />
                                <div className="absolute top-2 right-2"><span className="material-symbols-outlined text-white text-sm">play_circle</span></div>
                            </>
                        ) : (
                            <img src={p.mediaUrl} className="w-full h-full object-cover" alt="" />
                        )}
                    </div>
                ))
            )}
        </section>
      </main>

      {/* PIN Setup Modal */}
      {showPinSetup && (
          <div className="fixed inset-0 z-[600] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-in fade-in">
              <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] p-8 w-full max-w-sm text-center shadow-2xl">
                  <h3 className="text-xl font-black mb-4">Secure this Chat</h3>
                  <p className="text-xs text-slate-500 mb-6 font-bold uppercase tracking-wider">Set a PIN to lock/unlock conversations</p>
                  <input 
                    type="password"
                    placeholder="Enter PIN"
                    value={newPin}
                    onChange={(e) => setNewPin(e.target.value)}
                    className="w-full bg-slate-100 dark:bg-white/5 p-5 rounded-2xl text-center font-black text-2xl outline-none mb-6 border border-transparent focus:border-primary transition-all"
                    autoFocus
                  />
                  <div className="flex gap-4">
                      <button onClick={() => setShowPinSetup(false)} className="flex-1 py-4 text-slate-500 font-black uppercase text-xs">Cancel</button>
                      <button onClick={confirmLock} className="flex-1 py-4 bg-primary text-white rounded-2xl font-black uppercase text-xs shadow-lg shadow-primary/20">Lock Chat</button>
                  </div>
              </div>
          </div>
      )}

      {/* Wallpaper Picker Modal */}
      {showWallpaperModal && (
          <div className="fixed inset-0 z-[600] flex items-end sm:items-center justify-center p-4 bg-black/60 backdrop-blur-md">
              <div className="relative w-full max-w-sm bg-white dark:bg-slate-900 rounded-t-[2.5rem] sm:rounded-[2.5rem] p-8 shadow-2xl animate-in slide-in-from-bottom">
                  <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-black">Chat Wallpaper</h3>
                    <button onClick={() => setShowWallpaperModal(false)}><span className="material-symbols-outlined">close</span></button>
                  </div>
                  <div className="grid grid-cols-3 gap-4 mb-8">
                      {WALLPAPERS.map(wp => (
                          <button 
                            key={wp.id} 
                            onClick={() => { setSelectedWallpaper(wp.id); setShowWallpaperModal(false); setShowWallpaperConfirm(true); }}
                            className={`aspect-[9/16] rounded-2xl ${wp.color} border-2 border-transparent hover:border-primary transition-all flex items-center justify-center relative overflow-hidden`}
                          >
                              <span className="text-[10px] font-black uppercase tracking-tighter bg-black/20 text-white px-2 py-1 rounded-md">{wp.label}</span>
                          </button>
                      ))}
                  </div>
                  <button onClick={() => setShowWallpaperModal(false)} className="w-full py-4 bg-slate-100 dark:bg-white/5 rounded-2xl font-black text-xs uppercase tracking-widest text-slate-500">Cancel</button>
              </div>
          </div>
      )}

      {/* Nickname Editor Modal */}
      {isEditingNickname && (
        <div className="fixed inset-0 z-[600] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-in fade-in">
            <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] p-8 w-full max-w-sm text-center shadow-2xl">
                <h3 className="text-xl font-black mb-2">Set Nickname</h3>
                <p className="text-xs text-slate-500 mb-6 font-bold uppercase tracking-widest">Original: {user.name}</p>
                <input 
                  value={nicknameInput}
                  onChange={(e) => setNicknameInput(e.target.value)}
                  placeholder="The legend..."
                  className="w-full bg-slate-100 dark:bg-white/5 p-5 rounded-2xl text-center font-bold text-lg outline-none mb-6 border border-transparent focus:border-primary transition-all"
                  autoFocus
                />
                <div className="flex gap-4">
                    <button onClick={() => setIsEditingNickname(false)} className="flex-1 py-4 text-slate-500 font-black uppercase text-xs">Cancel</button>
                    <button onClick={handleSaveNickname} className="flex-1 py-4 bg-primary text-white rounded-2xl font-black uppercase text-xs shadow-lg shadow-primary/20">Save</button>
                </div>
            </div>
        </div>
      )}

      {/* Wallpaper Context Confirm */}
      {showWallpaperConfirm && (
          <div className="fixed inset-0 z-[610] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-in fade-in">
              <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] p-8 w-full max-w-sm text-center">
                  <h3 className="text-xl font-black mb-2">Apply Background</h3>
                  <p className="text-xs text-slate-500 mb-8 font-bold uppercase tracking-widest">Where should this be visible?</p>
                  <div className="space-y-4">
                      <button onClick={() => confirmWallpaper('chat')} className="w-full py-5 bg-primary text-white rounded-2xl font-black uppercase tracking-widest shadow-lg shadow-primary/30 active:scale-95 transition-all">
                          This Chat Only
                      </button>
                      <button onClick={() => confirmWallpaper('global')} className="w-full py-5 bg-slate-100 dark:bg-white/5 text-slate-900 dark:text-white rounded-2xl font-black uppercase tracking-widest active:scale-95 transition-all">
                          All Chats
                      </button>
                      <button onClick={() => setShowWallpaperConfirm(false)} className="w-full py-2 text-slate-400 font-bold text-[10px] uppercase tracking-widest mt-2">
                          Cancel
                      </button>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { User, PremiumCustomization, SavedMedia, Post } from '../../types';
import { useAuth } from '../../hooks/useAuth';
import { updateProfile, updatePremiumCustomization, saveWallpaper, updatePrivacySettings, getSavedGallery, getPostsByUser } from '../../firebase';
import { hasPremiumAccess, ROLE_STYLES } from '../../premiumUtils';
import { SubscriptionModal } from '../Premium/SubscriptionModal';

interface ProfilePanelProps {
  user: User;
  onClose: () => void;
  toggleDarkMode: () => void;
  isDarkMode: boolean;
  isTabMode?: boolean;
  onOpenPost?: (post: Post) => void;
}

type ProfileViewMode = 'main' | 'edit' | 'settings' | 'privacy' | 'chats_settings';

export const ProfilePanel: React.FC<ProfilePanelProps> = ({ user, onClose, toggleDarkMode, isDarkMode, isTabMode, onOpenPost }) => {
  const { logout } = useAuth();
  const [viewMode, setViewMode] = useState<ProfileViewMode>('main');
  const [activeTab, setActiveTab] = useState<'grid' | 'reels' | 'tagged'>('grid');
  const [name, setName] = useState(user.name);
  const [bio, setBio] = useState(user.bio || '');
  const [showSubModal, setShowSubModal] = useState(false);
  const [galleryItems, setGalleryItems] = useState<SavedMedia[]>([]);
  const [userPosts, setUserPosts] = useState<Post[]>([]);
  const [isSaving, setIsSaving] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    getSavedGallery(user.uid).then(items => setGalleryItems(items as SavedMedia[]));
    getPostsByUser(user.uid).then(posts => setUserPosts(posts));
  }, [user.uid]);

  const handlePhotoSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = async (ev) => {
        if(ev.target?.result) {
            await updateProfile(user, { photoURL: ev.target.result as string });
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveProfile = async () => {
      setIsSaving(true);
      await updateProfile(user, { name, bio });
      setIsSaving(false);
      setViewMode('main');
  };

  const handlePrivacyToggle = async (key: string, current: any) => {
      let newVal: any = !current;
      if (key === 'lastSeen') newVal = current === 'nobody' ? 'everyone' : 'nobody';
      const updated = { ...user.privacySettings, [key]: newVal };
      await updatePrivacySettings(user.uid, updated);
  };

  const handleWallpaperSelect = async (color: string) => {
    await saveWallpaper(user.uid, 'default', color);
    alert("Wallpaper Updated!");
  };

  // SUB-VIEW: HEADER (for settings/edit)
  const renderSubHeader = (title: string, onBack: () => void) => (
    <nav className="sticky top-0 z-50 bg-background-light/80 dark:bg-background-dark/80 backdrop-blur-md px-4 py-3 flex items-center gap-4 border-b border-gray-200 dark:border-border-dark">
      <button onClick={onBack} className="p-1 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full">
        <span className="material-symbols-outlined text-2xl">arrow_back_ios</span>
      </button>
      <h2 className="text-sm font-bold tracking-tight uppercase">{title}</h2>
    </nav>
  );

  // VIEW: EDIT PROFILE
  if (viewMode === 'edit') {
      return (
          <div className="flex flex-col h-full bg-background-light dark:bg-background-dark animate-in slide-in-from-right">
              {renderSubHeader("Edit Profile", () => setViewMode('main'))}
              <div className="p-6 space-y-6">
                  <div className="flex justify-center">
                      <div className="relative group cursor-pointer" onClick={() => fileInputRef.current?.click()}>
                          <img src={user.photoURL} className="w-32 h-32 rounded-full object-cover border-4 border-primary/20" alt="" />
                          <div className="absolute inset-0 bg-black/40 rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                              <span className="text-white text-xs font-bold uppercase">Change</span>
                          </div>
                          <input type="file" ref={fileInputRef} onChange={handlePhotoSelect} className="hidden" accept="image/*" />
                      </div>
                  </div>
                  <div className="space-y-4">
                      <div>
                          <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest ml-1">Display Name</label>
                          <input value={name} onChange={e => setName(e.target.value)} className="w-full mt-1 bg-slate-100 dark:bg-card-dark p-4 rounded-2xl outline-none font-bold text-slate-900 dark:text-white border border-transparent focus:border-primary transition-all" />
                      </div>
                      <div>
                          <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest ml-1">Bio</label>
                          <textarea value={bio} onChange={e => setBio(e.target.value)} className="w-full mt-1 bg-slate-100 dark:bg-card-dark p-4 rounded-2xl outline-none font-medium text-slate-900 dark:text-white border border-transparent focus:border-primary transition-all resize-none h-24" />
                      </div>
                  </div>
                  <button onClick={handleSaveProfile} disabled={isSaving} className="w-full h-14 bg-primary text-white rounded-full font-bold shadow-lg shadow-primary/20 active:scale-95 transition-all">
                      {isSaving ? 'Updating...' : 'Save Changes'}
                  </button>
              </div>
          </div>
      );
  }

  // VIEW: SETTINGS
  if (viewMode === 'settings') {
      return (
          <div className="flex flex-col h-full bg-background-light dark:bg-background-dark animate-in slide-in-from-right">
              {renderSubHeader("Settings", () => setViewMode('main'))}
              <div className="p-4 space-y-4">
                  <button onClick={() => setViewMode('privacy')} className="w-full flex items-center justify-between p-5 bg-white dark:bg-card-dark rounded-2xl border border-gray-100 dark:border-border-dark">
                      <div className="flex items-center gap-4">
                          <span className="material-symbols-outlined text-primary">lock</span>
                          <span className="font-bold text-sm">Privacy Settings</span>
                      </div>
                      <span className="material-symbols-outlined text-gray-400">chevron_right</span>
                  </button>
                  <button onClick={() => setViewMode('chats_settings')} className="w-full flex items-center justify-between p-5 bg-white dark:bg-card-dark rounded-2xl border border-gray-100 dark:border-border-dark">
                      <div className="flex items-center gap-4">
                          <span className="material-symbols-outlined text-primary">palette</span>
                          <span className="font-bold text-sm">Appearance & Wallpaper</span>
                      </div>
                      <span className="material-symbols-outlined text-gray-400">chevron_right</span>
                  </button>
                  <button onClick={toggleDarkMode} className="w-full flex items-center justify-between p-5 bg-white dark:bg-card-dark rounded-2xl border border-gray-100 dark:border-border-dark">
                      <div className="flex items-center gap-4">
                          <span className="material-symbols-outlined text-primary">{isDarkMode ? 'light_mode' : 'dark_mode'}</span>
                          <span className="font-bold text-sm">Toggle {isDarkMode ? 'Light' : 'Dark'} Mode</span>
                      </div>
                  </button>
                  <div className="pt-6">
                      <button onClick={logout} className="w-full h-14 bg-red-500/10 text-red-500 rounded-full font-bold border border-red-500/20 hover:bg-red-500 hover:text-white transition-all">
                          Log Out
                      </button>
                  </div>
              </div>
          </div>
      );
  }

  // VIEW: PRIVACY
  if (viewMode === 'privacy') {
    return (
        <div className="flex flex-col h-full bg-background-light dark:bg-background-dark animate-in slide-in-from-right">
            {renderSubHeader("Privacy", () => setViewMode('settings'))}
            <div className="p-6 space-y-6">
                <div className="flex items-center justify-between p-4 bg-white dark:bg-card-dark rounded-2xl">
                    <div>
                        <p className="font-bold text-sm">Last Seen</p>
                        <p className="text-[10px] text-slate-500 uppercase tracking-widest">{user.privacySettings?.lastSeen || 'Everyone'}</p>
                    </div>
                    <button onClick={() => handlePrivacyToggle('lastSeen', user.privacySettings?.lastSeen)} className={`w-12 h-6 rounded-full transition-all relative ${user.privacySettings?.lastSeen !== 'nobody' ? 'bg-primary' : 'bg-gray-300 dark:bg-gray-700'}`}>
                        <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${user.privacySettings?.lastSeen !== 'nobody' ? 'left-7' : 'left-1'}`}></div>
                    </button>
                </div>
                <div className="flex items-center justify-between p-4 bg-white dark:bg-card-dark rounded-2xl">
                    <div>
                        <p className="font-bold text-sm">Read Receipts</p>
                        <p className="text-[10px] text-slate-500 uppercase tracking-widest">Double blue ticks</p>
                    </div>
                    <button onClick={() => handlePrivacyToggle('readReceipts', user.privacySettings?.readReceipts)} className={`w-12 h-6 rounded-full transition-all relative ${user.privacySettings?.readReceipts ? 'bg-primary' : 'bg-gray-300 dark:bg-gray-700'}`}>
                        <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${user.privacySettings?.readReceipts ? 'left-7' : 'left-1'}`}></div>
                    </button>
                </div>
            </div>
        </div>
    );
  }

  // VIEW: CHAT SETTINGS
  if (viewMode === 'chats_settings') {
    return (
        <div className="flex flex-col h-full bg-background-light dark:bg-background-dark animate-in slide-in-from-right">
            {renderSubHeader("Chat Appearance", () => setViewMode('settings'))}
            <div className="p-6 space-y-6">
                <h4 className="text-[10px] font-black uppercase text-primary tracking-widest">Global Wallpapers</h4>
                <div className="grid grid-cols-3 gap-3">
                    {['default', 'indigo', 'dark'].map(wp => (
                        <button key={wp} onClick={() => handleWallpaperSelect(wp)} className="aspect-[9/16] rounded-xl border-2 border-transparent hover:border-primary overflow-hidden relative bg-slate-800">
                            <span className="absolute inset-0 flex items-center justify-center text-[10px] font-bold uppercase">{wp}</span>
                        </button>
                    ))}
                </div>
            </div>
        </div>
    );
  }

  // MAIN VIEW (SOCIAL MEDIA STYLE)
  return (
    <div className="flex-1 flex flex-col bg-background-light dark:bg-background-dark text-slate-900 dark:text-white overflow-hidden animate-in fade-in transition-colors duration-300">

        {/* Top Navigation Bar */}
        <nav className="sticky top-0 z-50 bg-background-light/80 dark:bg-background-dark/80 backdrop-blur-md px-4 py-4 flex items-center justify-between border-b border-gray-200 dark:border-border-dark">
            <div className="flex items-center gap-1 cursor-pointer" onClick={onClose}>
                <span className="material-symbols-outlined text-2xl">arrow_back_ios</span>
            </div>
            <div className="flex flex-col items-center">
                <h2 className="text-sm font-black tracking-tighter uppercase leading-none">@{user.username || user.email.split('@')[0]}</h2>
            </div>
            <div className="flex items-center gap-4">
                <button className="flex items-center justify-center" onClick={() => setViewMode('settings')}>
                    <span className="material-symbols-outlined text-2xl">settings</span>
                </button>
            </div>
        </nav>

        <main className="flex-1 overflow-y-auto no-scrollbar pb-32">
            {/* Profile Header Section */}
            <section className="px-6 pt-6 pb-4">
                <div className="flex flex-col items-start gap-6">
                    <div className="relative">
                        <div className="absolute -inset-1.5 bg-gradient-to-tr from-primary to-purple-600 rounded-full blur-sm opacity-40 animate-pulse"></div>
                        <div 
                            className="relative bg-center bg-no-repeat aspect-square bg-cover rounded-full h-28 w-28 ring-4 ring-background-light dark:ring-background-dark shadow-2xl"
                            style={{ backgroundImage: `url("${user.photoURL}")` }}
                        ></div>
                    </div>
                    <div className="flex flex-col gap-1">
                        <div className="flex items-center gap-2">
                            <h1 className="text-[26px] font-black tracking-tighter">{user.name}</h1>
                            {(user.isAdmin || user.role === 'owner') && (
                                <span className="material-symbols-outlined text-primary text-xl" style={{ fontVariationSettings: "'FILL' 1" }}>verified</span>
                            )}
                        </div>
                        <p className="text-slate-500 dark:text-gray-400 text-sm font-medium leading-relaxed max-w-xs">
                            {user.bio || "Digital Architect & Visual Designer"}
                        </p>
                        <div className="flex items-center gap-1.5 mt-1 text-slate-400">
                            <span className="material-symbols-outlined text-xs">location_on</span>
                            <span className="text-[10px] font-black uppercase tracking-[0.2em]">New York City</span>
                        </div>
                    </div>
                    {/* Action Buttons */}
                    <div className="flex w-full gap-3 mt-2">
                        <button onClick={() => setViewMode('edit')} className="flex-1 h-12 bg-slate-200 dark:bg-white/10 text-slate-900 dark:text-white flex items-center justify-center rounded-full text-xs font-black uppercase tracking-widest border border-slate-300 dark:border-white/10 active:scale-95 transition-all">
                            Edit Profile
                        </button>
                        <button className="flex-1 h-12 bg-primary text-white flex items-center justify-center rounded-full text-xs font-black uppercase tracking-widest shadow-lg shadow-primary/20 active:scale-95 transition-all">
                            Share Profile
                        </button>
                    </div>
                </div>
            </section>

            {/* Stats Section */}
            <section className="px-4 py-4">
                <div className="flex gap-3">
                    <div className="flex-1 flex flex-col gap-1 rounded-[1.5rem] bg-slate-100 dark:bg-white/5 py-4 items-center border border-transparent dark:border-white/5">
                        <p className="text-xl font-black">{userPosts.length}</p>
                        <p className="text-slate-500 dark:text-gray-500 text-[10px] uppercase tracking-[0.2em] font-black">Posts</p>
                    </div>
                    <div className="flex-1 flex flex-col gap-1 rounded-[1.5rem] bg-slate-100 dark:bg-white/5 py-4 items-center border border-transparent dark:border-white/5">
                        <p className="text-xl font-black">4.2K</p>
                        <p className="text-slate-500 dark:text-gray-500 text-[10px] uppercase tracking-[0.2em] font-black">Followers</p>
                    </div>
                    <div className="flex-1 flex flex-col gap-1 rounded-[1.5rem] bg-slate-100 dark:bg-white/5 py-4 items-center border border-transparent dark:border-white/5">
                        <p className="text-xl font-black">298</p>
                        <p className="text-slate-500 dark:text-gray-500 text-[10px] uppercase tracking-[0.2em] font-black">Following</p>
                    </div>
                </div>
            </section>

