                                </>
                            ) : (
                                <img src={p.mediaUrl} className="w-full h-full object-cover" alt="" />
                            )}
                        </div>
                    ))
                )}
            </section>
        </main>

        {showSubModal && <SubscriptionModal currentUser={user} onClose={() => setShowSubModal(false)} />}
    </div>
  );
};

