                </p>
                <div className="flex items-center gap-1 mt-1 text-slate-400">
                  <span className="material-symbols-outlined text-xs">location_on</span>
                  <p className="text-[10px] font-black uppercase tracking-widest">New York, NY</p>
                </div>
