    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User, Chat, Story, CallSession, Post } from '../../types';
import { Sidebar } from './Sidebar';
import { ChatWindow } from './ChatWindow';
import { ProfilePanel } from './ProfilePanel';
import { StoryUpload } from './StoryUpload';
import { StoryViewer } from './StoryViewer';
import { PublicProfile } from './PublicProfile';
import { CallModal } from './CallModal';
import { HomeFeed } from './HomeFeed';
import { BottomNav } from './BottomNav';
import { ExploreView } from './ExploreView';
import { ActivityView } from './ActivityView';
import { PostDetailView } from './PostDetailView';
import { ConnectionsView } from './ConnectionsView';
import { initiateCall, getIncomingCall, getUserById, updateCallStatus, cleanOldCalls, subscribeToNicknames } from '../../firebase';

interface ChatDashboardProps {
  currentUser: User;
  toggleDarkMode: () => void;
  isDarkMode: boolean;
}

export type NavTab = 'home' | 'search' | 'add' | 'activity' | 'profile' | 'chats';

export const ChatDashboard: React.FC<ChatDashboardProps> = ({ currentUser, toggleDarkMode, isDarkMode }) => {
  const [activeTab, setActiveTab] = useState<NavTab>('home');
  const [selectedChat, setSelectedChat] = useState<Chat | null>(null);
  const [showStoryUpload, setShowStoryUpload] = useState(false);
  const [viewingStories, setViewingStories] = useState<Story[] | null>(null);
  const [viewingUser, setViewingUser] = useState<User | null>(null);
  const [activeCall, setActiveCall] = useState<CallSession | null>(null);
  const [selectedPost, setSelectedPost] = useState<Post | null>(null);
  const [connectionsState, setConnectionsState] = useState<{ user: User, type: 'followers' | 'following' } | null>(null);
  const [nicknames, setNicknames] = useState<Record<string, string>>({});

  useEffect(() => {
    const unsub = subscribeToNicknames(currentUser.uid, (data) => setNicknames(data));
    return () => unsub();
  }, [currentUser.uid]);

  useEffect(() => {
    const poll = async () => {
      cleanOldCalls();
      if (activeCall) return; 
      const incoming = await getIncomingCall(currentUser.uid);
      if (incoming) {
        const caller = await getUserById(incoming.callerId);
        if (caller) {
          setActiveCall({
            id: incoming.id, partner: caller, type: incoming.type, callerId: incoming.callerId,
            receiverId: incoming.receiverId, status: incoming.status, isIncoming: true, timestamp: incoming.timestamp
          });
        }
      }
    };
    const itv = setInterval(poll, 3000);
    return () => clearInterval(itv);
  }, [currentUser.uid, activeCall]);

  const startCall = async (user: User, type: 'voice' | 'video') => {
    const call = await initiateCall(currentUser.uid, user.uid, type);
    setActiveCall({ 
      id: call.id, partner: user, type, callerId: currentUser.uid, receiverId: user.uid,
      status: 'ringing', isIncoming: false, timestamp: call.timestamp
    });
  };

  const handleOpenProfileByUid = async (uid: string) => {
      const user = await getUserById(uid);
      if(user) setViewingUser(user);
      setConnectionsState(null); // Close connections if opening profile
  };

  const handleMessageUser = (user: User) => {
    const chatId = [currentUser.uid, user.uid].sort().join('_');
    const chat: Chat = {
      id: chatId,
      type: 'private',
      participants: [currentUser.uid, user.uid],
      updatedAt: Date.now()
    };
    setSelectedChat(chat);
    setViewingUser(null);
    setConnectionsState(null);
    setSelectedPost(null);
  };

  const renderTabContent = () => {
    switch (activeTab) {
      case 'home':
        return (
          <HomeFeed 
            currentUser={currentUser}
            onOpenDMs={() => setActiveTab('chats')}
            onUploadPost={() => setShowStoryUpload(true)}
            onOpenStory={setViewingStories}
            onOpenPost={setSelectedPost}
          />
        );
      case 'chats':
        return (
          <Sidebar 
            currentUser={currentUser} 
            onChatSelect={setSelectedChat} 
            activeChatId={selectedChat?.id}
            nicknames={nicknames}
            onBack={() => setActiveTab('home')}
          />
        );
      case 'profile':
        return (
          <ProfilePanel 
            user={currentUser} 
            onClose={() => setActiveTab('home')} 
            toggleDarkMode={toggleDarkMode}
            isDarkMode={isDarkMode}
            isTabMode={true}
            onOpenPost={setSelectedPost}
            onOpenConnections={(type) => setConnectionsState({ user: currentUser, type })}
          />
        );
      case 'search':
        return (
          <ExploreView 
            currentUser={currentUser}
            onOpenProfile={setViewingUser}
            onOpenPost={setSelectedPost}
          />
        );
      case 'activity':
        return (
          <ActivityView 
            onBack={() => setActiveTab('home')}
            onOpenProfile={setViewingUser}
          />
        );
      default:
        return null;
    }
  };

  return (
    <div className="flex flex-col h-[100dvh] w-full bg-background-light dark:bg-background-dark overflow-hidden font-display">

      {/* Top Main Content Area */}
      <div className="flex-1 relative flex flex-col overflow-hidden">
        {selectedChat ? (
          <ChatWindow 
            chat={selectedChat} 
            currentUser={currentUser} 
            onClose={() => setSelectedChat(null)}
            onUserClick={setViewingUser}
            onCallStart={startCall}
            nicknames={nicknames}
          />
        ) : (
          renderTabContent()
        )}
      </div>

      {/* Global Bottom Navigation */}
      {!selectedChat && !selectedPost && !connectionsState && (
        <BottomNav 
          activeTab={activeTab} 
          onTabChange={(tab) => {
            if (tab === 'add') setShowStoryUpload(true);
            else setActiveTab(tab);
          }} 
          currentUser={currentUser} 
        />
      )}

      {/* Modals & Overlays */}
      {showStoryUpload && <StoryUpload currentUser={currentUser} onClose={() => setShowStoryUpload(false)} />}
      {viewingStories && <StoryViewer stories={viewingStories} currentUser={currentUser} onClose={() => setViewingStories(null)} />}
      {viewingUser && (
        <PublicProfile 
          user={viewingUser} 
          currentUser={currentUser}
          onClose={() => setViewingUser(null)} 
          onCallStart={startCall} 
          onMessageClick={handleMessageUser}
          nickname={nicknames[viewingUser.uid]} 
          onOpenPost={setSelectedPost} 
          onOpenConnections={(type) => setConnectionsState({ user: viewingUser, type })}
        />
      )}
      {activeCall && <CallModal session={activeCall} onHangUp={() => setActiveCall(null)} />}
      {selectedPost && <PostDetailView post={selectedPost} currentUser={currentUser} onClose={() => setSelectedPost(null)} onOpenProfile={handleOpenProfileByUid} />}
      {connectionsState && (
        <ConnectionsView 
            targetUser={connectionsState.user} 
            currentUser={currentUser} 
            initialType={connectionsState.type} 
            onClose={() => setConnectionsState(null)}
            onOpenProfile={handleOpenProfileByUid}
        />
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { User, Post, Comment } from '../../types';
import { toggleLikePost, toggleBookmarkPost, addComment, subscribeToComments, subscribeToPost, toggleFollow, subscribeToUser } from '../../firebase';

interface PostDetailViewProps {
  post: Post;
  currentUser: User;
  onClose: () => void;
  onOpenProfile: (uid: string) => void;
}

export const PostDetailView: React.FC<PostDetailViewProps> = ({ post: initialPost, currentUser, onClose, onOpenProfile }) => {
  const [post, setPost] = useState<Post>(initialPost);
  const [author, setAuthor] = useState<User | null>(null);
  const [comments, setComments] = useState<Comment[]>([]);
  const [newComment, setNewComment] = useState('');
  const [showHeartAnim, setShowHeartAnim] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isFollowing, setIsFollowing] = useState(currentUser.following?.includes(initialPost.userId) || false);

  const commentInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    // Sync Post Data
    const unsubPost = subscribeToPost(initialPost.id, (updated) => setPost(updated));
    // Sync Comments
    const unsubComments = subscribeToComments(initialPost.id, (list) => setComments(list));
    // Sync Author Info
    const unsubAuthor = subscribeToUser(initialPost.userId, (u) => {
        if(u) {
            setAuthor(u as User);
            setIsFollowing(currentUser.following?.includes(u.uid) || false);
        }
    });

    return () => { unsubPost(); unsubComments(); unsubAuthor(); };
  }, [initialPost.id, initialPost.userId, currentUser.following]);

  const handleLike = async () => {
    if (!post.likes.includes(currentUser.uid)) {
        setShowHeartAnim(true);
        setTimeout(() => setShowHeartAnim(false), 1000);
    }
    await toggleLikePost(post.id, currentUser.uid);
  };

  const handleFollow = async (e: React.MouseEvent) => {
      e.stopPropagation();
      await toggleFollow(currentUser.uid, post.userId);
  };

  const handlePostComment = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newComment.trim() || isSubmitting) return;

    setIsSubmitting(true);
    try {
        await addComment(post.id, {
            userId: currentUser.uid,
            userName: currentUser.name,
            userPhoto: currentUser.photoURL,
            text: newComment.trim()
        });
        setNewComment('');
    } finally {
        setIsSubmitting(false);
    }
  };

  const formatTimestamp = (ts: number) => {
      const diff = Date.now() - ts;
      const hours = Math.floor(diff / (1000 * 60 * 60));
      if (hours < 1) return 'Just now';
      if (hours < 24) return `${hours} hours ago`;
      return new Date(ts).toLocaleDateString();
  };

  return (
    <div className="fixed inset-0 z-[600] bg-background-light dark:bg-background-dark font-display text-slate-900 dark:text-white flex flex-col animate-in slide-in-from-bottom duration-300 overflow-hidden h-[100dvh]">

        {/* Top Navigation Bar */}
        <header className="fixed top-0 z-50 w-full flex items-center justify-between p-4 bg-background-light/80 dark:bg-background-dark/80 backdrop-blur-md border-b border-slate-200 dark:border-white/5">
            <button onClick={onClose} className="flex size-10 items-center justify-center rounded-full bg-black/5 dark:bg-white/10 text-slate-900 dark:text-white hover:bg-black/10 dark:hover:bg-white/20 transition-all active:scale-90">
                <span className="material-symbols-outlined font-bold">arrow_back_ios_new</span>
            </button>
            <div className="flex flex-col items-center">
                <span className="text-[11px] font-black uppercase tracking-[0.2em] text-primary">Post</span>
                <span className="text-sm font-bold tracking-tight">Explore</span>
            </div>
            <button className="flex size-10 items-center justify-center rounded-full bg-black/5 dark:bg-white/10 text-slate-900 dark:text-white hover:bg-black/10 dark:hover:bg-white/20">
                <span className="material-symbols-outlined">more_horiz</span>
            </button>
        </header>

        {/* Scrollable Content */}
        <main className="flex-1 overflow-y-auto no-scrollbar pt-20 pb-24">

            {/* Main Media Section */}
            <div className="px-4">
                <div 
                    className="relative w-full aspect-[4/5] bg-center bg-no-repeat bg-cover rounded-[1.5rem] overflow-hidden shadow-2xl border border-black/5 dark:border-white/5 group"
                    onDoubleClick={handleLike}
                >
                    {post.mediaType === 'video' ? (
                        <video src={post.mediaUrl} className="w-full h-full object-cover" autoPlay muted loop playsInline />
                    ) : (
                        <img src={post.mediaUrl} className="w-full h-full object-cover" alt="" />
                    )}

                    {/* Location Tag Overlay */}
                    <div className="absolute top-4 left-4 flex items-center gap-1 px-3 py-1.5 rounded-full bg-black/40 backdrop-blur-lg border border-white/10 text-white">
                        <span className="material-symbols-outlined text-[14px]">location_on</span>
                        <span className="text-[12px] font-bold tracking-tight">{post.location || 'Cyber Space'}</span>
                    </div>

                    {/* Big Heart Animation */}
                    {showHeartAnim && (
                        <div className="absolute inset-0 flex items-center justify-center z-20 pointer-events-none">
                            <span className="material-symbols-outlined text-white text-[100px] animate-ping opacity-70" style={{ fontVariationSettings: "'FILL' 1" }}>favorite</span>
                        </div>
                    )}
                </div>
            </div>

            {/* Author Header Section */}
            <div className="flex p-4 mt-2 items-center justify-between">
                <div className="flex gap-3 cursor-pointer" onClick={() => onOpenProfile(post.userId)}>
                    <img src={post.userPhoto} className="size-12 rounded-full border-2 border-primary/40 object-cover" alt="" />
                    <div className="flex flex-col justify-center">
                        <div className="flex items-center gap-1">
                            <p className="text-slate-900 dark:text-white text-base font-black tracking-tight">{post.userName}</p>
                            {author?.isAdmin && <span className="material-symbols-outlined text-primary text-[16px]" style={{ fontVariationSettings: "'FILL' 1" }}>verified</span>}
                        </div>
                        <p className="text-slate-500 dark:text-[#a19cba] text-xs font-bold uppercase tracking-widest">{formatTimestamp(post.timestamp)}</p>
                    </div>
                </div>
                {post.userId !== currentUser.uid && (
                    <button 
                        onClick={handleFollow}
                        className={`flex min-w-[100px] items-center justify-center rounded-full h-9 px-4 text-xs font-black uppercase tracking-widest transition-all active:scale-95 shadow-lg ${isFollowing ? 'bg-slate-200 dark:bg-white/10 text-slate-500' : 'bg-primary text-white shadow-primary/30'}`}
                    >
                        {isFollowing ? 'Following' : 'Follow'}
                    </button>
                )}
