export const StoryUpload: React.FC<StoryUploadProps> = ({ currentUser, onClose }) => {
  const [mode, setMode] = useState<CameraMode>('Story');
  const [file, setFile] = useState<File | null>(null);
  const [preview, setPreview] = useState<string | null>(null);
  const [mediaType, setMediaType] = useState<'image' | 'video' | null>(null);
  const [selectedFilter, setSelectedFilter] = useState(FILTERS[0]);
  const [caption, setCaption] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [showMusicPicker, setShowMusicPicker] = useState(false);
  const [selectedMusic, setSelectedMusic] = useState<MusicMetadata | null>(null);

  // Camera State
  const [isCameraActive, setIsCameraActive] = useState(false);
  const [cameraFacing, setCameraFacing] = useState<'user' | 'environment'>('user');
  const [cameraStream, setCameraStream] = useState<MediaStream | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const generateUID = () => Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15);

  // Start Camera
  const startCamera = async () => {
    try {
      if (cameraStream) {
        cameraStream.getTracks().forEach(track => track.stop());
      }
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: cameraFacing, width: { ideal: 1280 }, height: { ideal: 1920 } },
        audio: false
      });
      setCameraStream(stream);
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
      setIsCameraActive(true);
      setPreview(null); 
    } catch (err) {
      console.error("Camera access error:", err);
      // Fallback: if camera fails, just rely on library
      setIsCameraActive(false);
    }
  };

  const stopCamera = () => {
    if (cameraStream) {
      cameraStream.getTracks().forEach(track => track.stop());
      setCameraStream(null);
    }
    setIsCameraActive(false);
  };

  useEffect(() => {
    startCamera();
    return () => stopCamera();
  }, [cameraFacing]);

  // Capture Photo
  const handleCapture = () => {
    if (!videoRef.current || !canvasRef.current || !isCameraActive) return;

    const video = videoRef.current;
    if (video.readyState < 2) return; // Ensure video is ready

    const canvas = canvasRef.current;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Draw current frame to canvas
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

    // Convert to dataURL with slightly reduced quality to avoid Firestore size limits
    const dataUrl = canvas.toDataURL('image/jpeg', 0.8);
    setPreview(dataUrl);
    setMediaType('image');
    stopCamera();
  };

  const handleSwitchCamera = (e: React.MouseEvent) => {
    e.stopPropagation();
    setCameraFacing(prev => prev === 'user' ? 'environment' : 'user');
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selected = e.target.files?.[0];
    if (!selected) return;

    stopCamera();
    const isVideo = selected.type.startsWith('video/');
    setMediaType(isVideo ? 'video' : 'image');
    setFile(selected);

    if (preview?.startsWith('blob:')) URL.revokeObjectURL(preview);
    setPreview(URL.createObjectURL(selected));
    e.target.value = '';
  };

  const handleUpload = async () => {
    if (!preview || isUploading) return;
    setIsUploading(true);
    try {
      let mediaData = preview;

      // If we have a File object (from gallery), read it as base64
      if (file) {
          mediaData = await new Promise((resolve, reject) => {
              const reader = new FileReader();
              reader.readAsDataURL(file);
              reader.onload = () => resolve(reader.result as string);
              reader.onerror = (err) => reject(err);
          });
      }

      if (mode === 'Story') {
        const newStory: Story = {
          id: 'story_' + generateUID(),
          userId: currentUser.uid,
          userName: currentUser.name,
          userPhoto: currentUser.photoURL,
          mediaUrl: mediaData,
          mediaType: mediaType!,
          caption,
          timestamp: Date.now(),
          music: selectedMusic || undefined
        };
        await addStory(newStory);
      } else if (mode === 'Post') {
        await addPost({
          userId: currentUser.uid,
          userName: currentUser.name,
          userPhoto: currentUser.photoURL,
          mediaUrl: mediaData,
          mediaType: mediaType!,
          caption,
          location: 'ROXX Universe',
          timestamp: Date.now()
        });
      }
      onClose();
    } catch (e) {
      console.error("Upload error:", e);
      alert("Failed to publish. The image might be too large or there was a network issue.");
    } finally {
      setIsUploading(false);
    }
  };

  return (
