}

const CATEGORIES = ['All', 'Architecture', 'Art', 'Tech', 'Travel', 'Fashion', 'Photography'];

export const ExploreView: React.FC<ExploreViewProps> = ({ currentUser, onOpenProfile, onOpenPost }) => {
