export const StoryUpload: React.FC<StoryUploadProps> = ({ currentUser, onClose }) => {
  const [mode, setMode] = useState<CameraMode>('Story');
  const [file, setFile] = useState<File | null>(null);
  const [preview, setPreview] = useState<string | null>(null);
  const [mediaType, setMediaType] = useState<'image' | 'video' | null>(null);
  const [selectedFilter, setSelectedFilter] = useState(FILTERS[0]);
  const [caption, setCaption] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [showMusicPicker, setShowMusicPicker] = useState(false);
  const [selectedMusic, setSelectedMusic] = useState<MusicMetadata | null>(null);

  const [cameraFacing, setCameraFacing] = useState<'user' | 'environment'>('user');
  const [isCameraReady, setIsCameraReady] = useState(false);
  const [hasError, setHasError] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const generateUID = () => Math.random().toString(36).substring(2, 15);

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => {
        track.stop();
        track.enabled = false;
      });
      streamRef.current = null;
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
    setIsCameraReady(false);
  };

  const startCamera = async () => {
    if (preview) return;
    setHasError(null);
    stopCamera();

    try {
      const constraints = {
        video: { facingMode: cameraFacing, width: { ideal: 1280 }, height: { ideal: 720 } },
        audio: false
      };

      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      streamRef.current = stream;

      if (videoRef.current) {
        const video = videoRef.current;
        video.srcObject = stream;
        video.onloadedmetadata = async () => {
          try {
            await video.play();
            setIsCameraReady(true);
          } catch (playErr) {
            setHasError("Tap screen to start camera");
          }
        };
      }
    } catch (err: any) {
      console.error("Camera Access Error:", err);
      setHasError("Camera unavailable. Try gallery.");
    }
  };

  const handleSwitchCamera = () => {
    setCameraFacing(prev => prev === 'user' ? 'environment' : 'user');
  };

  useEffect(() => {
    startCamera();
    return () => stopCamera();
  }, [cameraFacing, preview === null]);

  const compressImage = (img: HTMLImageElement | HTMLVideoElement): string => {
      const canvas = document.createElement('canvas');
      const MAX_DIM = 1080;
      let width = (img instanceof HTMLVideoElement) ? img.videoWidth : img.width;
      let height = (img instanceof HTMLVideoElement) ? img.videoHeight : img.height;

      if (width > height) {
          if (width > MAX_DIM) {
              height *= MAX_DIM / width;
              width = MAX_DIM;
          }
      } else {
          if (height > MAX_DIM) {
              width *= MAX_DIM / height;
              height = MAX_DIM;
          }
      }

      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext('2d');
      if (!ctx) return "";

      if (cameraFacing === 'user' && img instanceof HTMLVideoElement) {
          ctx.translate(canvas.width, 0);
          ctx.scale(-1, 1);
      }

      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
      return canvas.toDataURL('image/jpeg', 0.6);
  };

  const handleCapture = () => {
    if (!videoRef.current || !isCameraReady) return;
    const dataUrl = compressImage(videoRef.current);
    setPreview(dataUrl);
    setMediaType('image');
    stopCamera();
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const selected = e.target.files?.[0];
    if (!selected) return;

    setIsProcessing(true);
    if (selected.type.startsWith('image/')) {
        const reader = new FileReader();
        reader.onload = (event) => {
            const img = new Image();
            img.onload = () => {
                const compressed = compressImage(img);
                setPreview(compressed);
                setMediaType('image');
                setFile(null); 
                setIsProcessing(false);
            };
            img.src = event.target?.result as string;
        };
        reader.readAsDataURL(selected);
    } else if (selected.type.startsWith('video/')) {
        // Video size check - strict for database storage
        if (selected.size > 1024 * 1024 * 0.8) { // 800KB Limit for video to account for Base64 growth
            alert("Video must be very small (<800KB) for real-time storage. Try a shorter clip.");
            setIsProcessing(false);
            return;
        }
        setMediaType('video');
        setFile(selected);
        setPreview(URL.createObjectURL(selected));
        setIsProcessing(false);
    }
    stopCamera();
    e.target.value = '';
  };

  const convertFileToBase64 = (file: File): Promise<string> => {
      return new Promise((resolve, reject) => {
          const reader = new FileReader();
          reader.onload = () => resolve(reader.result as string);
          reader.onerror = reject;
          reader.readAsDataURL(file);
      });
  };

  const handleUpload = async () => {
    if (!preview || isUploading) return;
    setIsUploading(true);

    try {
      let finalMediaData = preview;

      if (file && mediaType === 'video') {
          finalMediaData = await convertFileToBase64(file);
      }

      if (finalMediaData.length > 1000000) {
          throw new Error("This file is too large for the database. Try a shorter video or different photo.");
      }

      const uploadId = generateUID();

      if (mode === 'Story') {
        await addStory({
          id: 'story_' + uploadId,
          userId: currentUser.uid,
          userName: currentUser.name,
          userPhoto: currentUser.photoURL,
          mediaUrl: finalMediaData,
          mediaType: mediaType!,
          caption,
          timestamp: Date.now(),
          music: selectedMusic || undefined
        });
      } else if (mode === 'Post') {
        await addPost({
          userId: currentUser.uid,
          userName: currentUser.name,
          userPhoto: currentUser.photoURL,
          mediaUrl: finalMediaData,
          mediaType: mediaType!,
          caption,
          location: 'ROXX Universe',
          timestamp: Date.now()
        });
      }
      onClose();
    } catch (e: any) {
      console.error("Upload error:", e);
      alert(e.message || "Upload failed. Image might be too large.");
    } finally {
      setIsUploading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[500] bg-black text-white font-display overflow-hidden animate-in fade-in flex flex-col h-[100dvh]">
      <input type="file" ref={fileInputRef} onChange={handleFileChange} accept="image/*,video/*" className="hidden" />
      <canvas ref={canvasRef} className="hidden" />

      <div className="absolute inset-0 z-0 bg-black flex items-center justify-center" onClick={() => !isCameraReady && !preview && startCamera()}>
        {preview ? (
            <div className={`w-full h-full relative transition-all duration-500 ${selectedFilter.class}`}>
                {mediaType === 'video' ? (
                    <video src={preview} className="w-full h-full object-cover" autoPlay muted loop playsInline />
                ) : (
                    <img src={preview} className="w-full h-full object-cover" alt="Preview" />
                )}
            </div>
        ) : (
            <div className={`w-full h-full relative ${selectedFilter.class}`}>
                <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-opacity duration-300 ${isCameraReady ? 'opacity-100' : 'opacity-0'} ${cameraFacing === 'user' ? 'scale-x-[-1]' : ''}`} />
                {!isCameraReady && (
                    <div className="absolute inset-0 flex flex-col items-center justify-center gap-4 bg-slate-900/40 backdrop-blur-sm">
                        {isProcessing ? (
                            <div className="text-center">
                                <div className="w-10 h-10 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4 mx-auto"></div>
                                <p className="text-[10px] font-black uppercase tracking-[0.2em]">Optimizing Media...</p>
                            </div>
                        ) : hasError ? (
                             <div className="text-center p-6">
                                <span className="material-symbols-outlined text-4xl text-rose-500 mb-2">videocam_off</span>
                                <p className="text-xs font-bold uppercase tracking-widest">{hasError}</p>
                                <button onClick={startCamera} className="mt-4 px-6 py-2 bg-white/10 rounded-full text-[10px] font-black uppercase">Retry</button>
                             </div>
                        ) : (
                            <div className="w-10 h-10 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
                        )}
                    </div>
                )}
            </div>
        )}
      </div>

      <div className="relative z-10 flex items-center justify-between p-6 pt-12 bg-gradient-to-b from-black/60 to-transparent">
        <button onClick={onClose} className="flex items-center justify-center size-12 rounded-full bg-black/40 backdrop-blur-xl border border-white/10 text-white active:scale-90"><span className="material-symbols-outlined">close</span></button>
        {!preview && <button onClick={handleSwitchCamera} className="flex items-center justify-center size-12 rounded-full bg-black/40 backdrop-blur-xl border border-white/10 text-white active:bg-white/20 transition-all"><span className="material-symbols-outlined">sync</span></button>}
      </div>

      <div className="mt-auto relative z-20 w-full flex flex-col items-center">
        {preview && (
            <div className="w-full px-6 mb-8 animate-in slide-in-from-bottom-10">
                <div className="bg-black/60 backdrop-blur-3xl p-6 rounded-[2.5rem] border border-white/10 flex flex-col gap-5 shadow-2xl">
                    <textarea value={caption} onChange={(e) => setCaption(e.target.value)} placeholder="Add a caption..." className="bg-transparent border-none focus:ring-0 text-white placeholder-white/30 text-sm font-bold resize-none h-20 w-full text-center" />
                    <div className="flex gap-3">
                        <button onClick={() => { setPreview(null); setFile(null); startCamera(); }} disabled={isUploading} className="flex-1 py-4 bg-white/10 text-white rounded-3xl font-bold uppercase tracking-widest text-[10px]">Retake</button>
                        <button onClick={handleUpload} disabled={isUploading} className="flex-[2] py-4 bg-primary text-white rounded-3xl font-black uppercase tracking-[0.2em] shadow-lg active:scale-95 transition-all disabled:opacity-50 flex items-center justify-center gap-3">{isUploading ? <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div> : `Post ${mode}`}</button>
                    </div>
                </div>
            </div>
        )}

        {!preview && (
            <>
                <div className="flex w-full overflow-x-auto no-scrollbar px-4 py-6 bg-gradient-to-t from-black/60 to-transparent">
                    <div className="flex flex-row items-end justify-center gap-6 mx-auto">
                        {FILTERS.map((f) => (
                            <button key={f.name} onClick={() => setSelectedFilter(f)} className="flex flex-col items-center gap-3 min-w-[70px]">
                                <div className={`size-14 rounded-full border-2 transition-all overflow-hidden ${selectedFilter.name === f.name ? 'size-20 border-primary ring-4 ring-black/50 scale-110' : 'border-white/20'}`}><img src={f.preview} className="w-full h-full object-cover" alt={f.name} /></div>
                                <p className={`text-[10px] font-black tracking-widest uppercase ${selectedFilter.name === f.name ? 'text-primary' : 'text-white/60'}`}>{f.name}</p>
                            </button>
                        ))}
                    </div>
                </div>
                <div className="flex items-center justify-center gap-10 p-4 pb-8 w-full max-sm:max-w-xs">
                    <button onClick={() => fileInputRef.current?.click()} className="flex shrink-0 items-center justify-center rounded-full size-12 bg-white/10 backdrop-blur-xl border border-white/10"><span className="material-symbols-outlined">photo_library</span></button>
                    <button onClick={handleCapture} disabled={!isCameraReady} className="relative flex items-center justify-center group active:scale-110 transition-transform">
                        <div className="absolute size-24 bg-primary/20 rounded-full animate-pulse"></div>
                        <div className="relative flex shrink-0 items-center justify-center rounded-full size-20 border-[6px] border-white/40 bg-white/5 p-1"><div className="size-full bg-white rounded-full transition-transform group-active:scale-90"></div></div>
                    </button>
                    <button onClick={() => setShowMusicPicker(true)} className="flex shrink-0 items-center justify-center rounded-full size-12 bg-white/10 backdrop-blur-xl border border-white/10"><span className={`material-symbols-outlined ${selectedMusic ? 'text-primary' : ''}`}>music_note</span></button>
                </div>
                <div className="flex px-8 pb-10 w-full max-w-sm">
                    <div className="flex h-12 flex-1 items-center justify-center rounded-full bg-black/40 backdrop-blur-xl p-1.5 border border-white/10">
                        {(['Post', 'Story', 'Live'] as CameraMode[]).map((m) => (
                            <label key={m} className={`flex cursor-pointer h-full grow items-center justify-center rounded-full px-4 text-[10px] font-black uppercase tracking-[0.2em] transition-all ${mode === m ? 'bg-white text-black' : 'text-white/40'}`}>
                                <span>{m}</span>
                                <input type="radio" className="invisible w-0" name="camera-mode" checked={mode === m} onChange={() => setMode(m)} />
                            </label>
                        ))}
                    </div>
                </div>
            </>
        )}
      </div>
      {showMusicPicker && <MusicPicker onClose={() => setShowMusicPicker(false)} onSelect={setSelectedMusic} />}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Story, User } from '../../types';
import { likeStory, sendStoryReply, viewStory, deleteStory } from '../../firebase';

interface StoryViewerProps {
  stories: Story[];
  currentUser: User;
  onClose: () => void;
  onSwitchToReels?: () => void;
}

const QUICK_REACTIONS = ['❤️', '😂', '😮', '😢', '🔥'];

export const StoryViewer: React.FC<StoryViewerProps> = ({ stories: initialStories, currentUser, onClose, onSwitchToReels }) => {
  const [stories, setStories] = useState(initialStories);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [progress, setProgress] = useState(0);
  const [replyText, setReplyText] = useState('');
  const [isLiked, setIsLiked] = useState(false);
  const [showHeartAnim, setShowHeartAnim] = useState(false);
  const [showSentAnim, setShowSentAnim] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [showMenu, setShowMenu] = useState(false);

  const menuRef = useRef<HTMLDivElement>(null);
  const audioRef = useRef<HTMLAudioElement>(null);

  const story = stories[currentIndex];
  const isOwner = story && currentUser && String(story.userId) === String(currentUser.uid);

  // Audio Playback Logic
  useEffect(() => {
      if (audioRef.current) {
          audioRef.current.pause();
          audioRef.current.currentTime = 0;

          if (story && story.music) {
              audioRef.current.src = story.music.url;
              audioRef.current.currentTime = story.music.startAt;
              if (!isPaused) {
                  audioRef.current.play().catch(e => console.warn("Audio autoplay blocked", e));
              }
          }
      }
  }, [currentIndex, story]);

  useEffect(() => {
      if(audioRef.current) {
          if(isPaused) audioRef.current.pause();
          else if(story && story.music && audioRef.current.src) audioRef.current.play().catch(()=>{});
      }
  }, [isPaused]);

  useEffect(() => {
    if (!story) return;

    setIsLiked(story.likes?.includes(currentUser.uid) || false);
    setProgress(0);

    if (!isOwner) viewStory(story.id, currentUser.uid, currentUser.name);

    if (isPaused) return;

    const duration = story.mediaType === 'video' ? 10000 : 5000;
    const intervalTime = 50;
    const step = (intervalTime / duration) * 100;

    const timer = setInterval(() => {
      setProgress(prev => {
        if (prev >= 100) {
          clearInterval(timer);
          handleNext();
          return 100;
        }
        return prev + step;
      });
    }, intervalTime);

    return () => clearInterval(timer);
  }, [currentIndex, isPaused, story?.id, stories.length]);

  const handleNext = () => {
    if (currentIndex < stories.length - 1) {
      setCurrentIndex(prev => prev + 1);
    } else {
      onClose();
    }
  };

  const handlePrev = () => {
    if (currentIndex > 0) {
      setCurrentIndex(prev => prev - 1);
    }
  };

  const handleDelete = async () => {
    if (!story) return;
    if (window.confirm("Delete this story permanently?")) {
      await deleteStory(story.id);
      const newStories = stories.filter(s => s.id !== story.id);
      if (newStories.length === 0) {
        onClose();
      } else {
        setStories(newStories);
        if (currentIndex >= newStories.length) {
          setCurrentIndex(newStories.length - 1);
        }
      }
      setShowMenu(false);
      setIsPaused(false);
    }
  };

  const handleLike = async () => {
    if (!isLiked) {
      setShowHeartAnim(true);
      setTimeout(() => setShowHeartAnim(false), 800);
    }
    setIsLiked(!isLiked);
    await likeStory(story.id, currentUser.uid);
  };

  const triggerSentAnim = () => {
    setShowSentAnim(true);
    setTimeout(() => setShowSentAnim(false), 1500);
  };

  const handleReply = async (e?: React.FormEvent, customText?: string) => {
    e?.preventDefault();
    const text = customText || replyText.trim();
    if (!text) return;

    setReplyText('');
    setIsPaused(false);

    await sendStoryReply(story.userId, currentUser.uid, text, story);
    triggerSentAnim();

    // Auto-advance if it was a quick reaction to keep it snappy
    if (customText) {
        setTimeout(handleNext, 800);
    }
  };

  if (!story) return null;

  return (
    <div className="fixed inset-0 z-[600] bg-[#131022] flex flex-col h-full transition-all overflow-hidden touch-none font-display">

      {/* Hidden Audio Player */}
      <audio ref={audioRef} loop={false} />

      {/* Main Background Media */}
      <div className="absolute inset-0 z-0">
        <div className="w-full h-full bg-center bg-no-repeat bg-cover flex items-center justify-center">
            {story.mediaType === 'video' ? (
                <video key={story.id} src={story.mediaUrl} className="w-full h-full object-cover" autoPlay playsInline muted={false} onPlay={() => !isPaused && setIsPaused(false)} />
            ) : (
                <img key={story.id} src={story.mediaUrl} className="w-full h-full object-cover" alt="" onDoubleClick={handleLike} />
            )}
        </div>
      </div>

      {/* Top Header Overlay */}
      <div className="relative z-10 pt-6 px-4 pb-20 bg-gradient-to-b from-black/60 to-transparent">
        {/* Progress Bars */}
        <div className="flex w-full flex-row items-center justify-center gap-1.5 py-2">
            {stories.map((_, idx) => {
                const barWidth = idx < currentIndex ? '100%' : idx === currentIndex ? progress + '%' : '0%';
                return (
                    <div key={idx} className="h-1 flex-1 rounded-full bg-white/40 overflow-hidden">
                        <div className="h-full bg-white transition-all duration-100 ease-linear" style={{ width: barWidth }}></div>
                    </div>
                );
            })}
        </div>

        {/* User Info Bar */}
        <div className="flex items-center mt-3 justify-between">
            <div className="flex items-center gap-3">
                <div className="border-2 border-primary p-0.5 rounded-full shadow-lg">
                    <img src={story.userPhoto} className="bg-center bg-no-repeat aspect-square bg-cover rounded-full size-10 object-cover" alt="" />
                </div>
                <div className="flex flex-col">
                    <div className="flex items-center gap-2">
                        <h2 className="text-white text-sm font-bold leading-tight tracking-tight shadow-sm">{story.userName}</h2>
                        <span className="text-white/60 text-xs font-medium drop-shadow-md">
                            {new Date(story.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                        </span>
                    </div>
                </div>
            </div>

            <div className="flex items-center gap-2">
                {onSwitchToReels && (
                    <button 
                        onClick={onSwitchToReels}
                        className="flex items-center justify-center rounded-full h-10 w-10 text-white bg-white/10 backdrop-blur-md border border-white/10 active:scale-95 transition-transform"
                        title="Switch to Reels"
                    >
                        <span className="material-symbols-outlined text-[20px]">video_library</span>
                    </button>
                )}
                {isOwner && (
                    <button onClick={() => { setShowMenu(!showMenu); setIsPaused(!showMenu); }} className="flex items-center justify-center rounded-full h-10 w-10 text-white">
                        <span className="material-symbols-outlined">more_horiz</span>
                    </button>
                )}
                <button onClick={onClose} className="flex items-center justify-center rounded-full h-10 w-10 text-white active:scale-90 transition-transform">
                    <span className="material-symbols-outlined">close</span>
                </button>
            </div>
        </div>
      </div>

      {/* Menu Modal (Owner Only) */}
      {showMenu && (
          <div className="absolute inset-0 z-[140] flex items-center justify-center bg-black/40 backdrop-blur-sm p-4">
              <div className="bg-white dark:bg-[#1a1826] rounded-3xl p-6 w-full max-w-xs shadow-2xl animate-in zoom-in-95">
                  <h3 className="text-slate-900 dark:text-white font-black text-lg mb-4 text-center">Story Options</h3>
                  <button onClick={handleDelete} className="w-full py-4 text-red-500 font-bold uppercase tracking-widest text-xs flex items-center justify-center gap-2 hover:bg-red-50 dark:hover:bg-red-500/10 rounded-2xl transition-all">
                      <span className="material-symbols-outlined">delete</span> Delete Story
                  </button>
                  <button onClick={() => { setShowMenu(false); setIsPaused(false); }} className="w-full py-4 text-slate-400 font-bold uppercase tracking-widest text-xs mt-2">Cancel</button>
              </div>
          </div>
      )}

      {/* Tap Zones for Navigation */}
      <div className="absolute inset-y-0 left-0 w-1/4 z-20 cursor-pointer" onClick={handlePrev}></div>
      <div className="absolute inset-y-0 right-0 w-1/4 z-20 cursor-pointer" onClick={handleNext}></div>

      {/* Animations Overlays */}
      {showHeartAnim && (
          <div className="absolute inset-0 flex items-center justify-center z-[150] pointer-events-none">
              <span className="material-symbols-outlined text-red-500 text-[120px] animate-ping opacity-80" style={{ fontVariationSettings: "'FILL' 1" }}>favorite</span>
          </div>
      )}

      {showSentAnim && (
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-[160] bg-white/10 backdrop-blur-xl border border-white/20 px-8 py-4 rounded-full text-white font-black uppercase tracking-[0.2em] animate-in zoom-in">
              Sent! ✨
          </div>
      )}

      {/* Bottom Interface Area */}
      <div className="mt-auto relative z-30 px-4 pb-10 pt-20 bg-gradient-to-t from-black/80 to-transparent flex flex-col">

        {/* Emoji Reactions Tray (Functional) */}
        {!isOwner && (
            <div className="flex items-center justify-between mb-6 px-1 animate-in slide-in-from-bottom-4">
                {QUICK_REACTIONS.map(emoji => (
                    <button 
                        key={emoji}
                        onClick={() => handleReply(undefined, emoji)}
                        className="flex items-center justify-center w-12 h-12 rounded-2xl text-2xl bg-white/10 backdrop-blur-md border border-white/10 shadow-[0_0_15px_rgba(255,255,255,0.05)] hover:bg-white/20 active:scale-[1.3] transition-all duration-300"
                    >
                        {emoji}
                    </button>
                ))}
            </div>
        )}

        {/* Caption Bar (Visual) */}
        {story.caption && (
            <div className="mb-4 text-center px-4 animate-in slide-in-from-bottom-2">
                <p className="text-white text-sm font-medium leading-relaxed drop-shadow-lg bg-black/20 backdrop-blur-sm py-2 px-4 rounded-xl inline-block max-w-full truncate">{story.caption}</p>
            </div>
        )}

        {/* Music Indicator */}
        {story.music && (
            <div className="mb-4 flex items-center justify-center gap-2">
                <div className="bg-white/10 backdrop-blur-md px-4 py-1.5 rounded-full border border-white/10 flex items-center gap-2 animate-pulse">
                    <span className="text-sm">🎵</span>
                    <span className="text-[10px] font-black text-white uppercase tracking-widest">{story.music.title}</span>
                </div>
            </div>
        )}

        {/* Input & Action Bar */}
        <div className="flex items-center gap-3">
            {!isOwner ? (
                <>
                    <div className="flex-1 h-12 bg-white/10 backdrop-blur-xl border border-white/10 rounded-full px-4 flex items-center focus-within:bg-white/20 transition-all">
                        <form onSubmit={handleReply} className="w-full">
                            <input 
                                value={replyText}
                                onChange={(e) => setReplyText(e.target.value)}
                                onFocus={() => setIsPaused(true)}
                                onBlur={() => !replyText && setIsPaused(false)}
                                className="bg-transparent border-none focus:ring-0 text-sm font-bold text-white placeholder:text-white/60 w-full" 
                                placeholder="Send message..." 
                                type="text"
                            />
                        </form>
                    </div>
                    <div className="flex items-center gap-4">
                        <button 
                            onClick={handleLike}
                            className={`flex items-center justify-center transition-all active:scale-[1.5] ${isLiked ? 'text-red-500' : 'text-white'}`}
                        >
                            <span className="material-symbols-outlined text-[32px]" style={isLiked ? { fontVariationSettings: "'FILL' 1" } : {}}>favorite</span>
                        </button>
                        <button 
                            onClick={() => handleReply()}
                            className="flex items-center justify-center transition-transform active:scale-90 text-white"
                        >
                            <span className="material-symbols-outlined text-[32px]">send</span>
                        </button>
                    </div>
                </>
            ) : (
                <div className="flex-1 py-4 flex items-center justify-center gap-2 text-white/70">
                    <span className="material-symbols-outlined text-sm">visibility</span>
                    <span className="text-[10px] font-black uppercase tracking-[0.2em]">{story.views?.length || 0} Story Views</span>
                </div>
            )}
        </div>
      </div>

      {/* Music Sticker Center Visual */}
      {story.music && !isPaused && (
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-20 pointer-events-none flex flex-col items-center gap-4 animate-float opacity-40">
              <div className="size-24 rounded-3xl bg-white/5 backdrop-blur-xl border border-white/10 flex items-center justify-center text-4xl animate-spin-slow">💿</div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User, Chat, Story, CallSession, Post } from '../../types';
import { Sidebar } from './Sidebar';
import { ChatWindow } from './ChatWindow';
import { ProfilePanel } from './ProfilePanel';
import { StoryUpload } from './StoryUpload';
import { StoryViewer } from './StoryViewer';
import { PublicProfile } from './PublicProfile';
import { CallModal } from './CallModal';
import { HomeFeed } from './HomeFeed';
import { BottomNav } from './BottomNav';
import { ExploreView } from './ExploreView';
import { ActivityView } from './ActivityView';
import { PostDetailView } from './PostDetailView';
import { ConnectionsView } from './ConnectionsView';
import { ReelsView } from './ReelsView';
import { initiateCall, getIncomingCall, getUserById, updateCallStatus, cleanOldCalls, subscribeToNicknames } from '../../firebase';

interface ChatDashboardProps {
  currentUser: User;
  toggleDarkMode: () => void;
  isDarkMode: boolean;
}

export type NavTab = 'home' | 'search' | 'reels' | 'add' | 'activity' | 'profile' | 'chats';

export const ChatDashboard: React.FC<ChatDashboardProps> = ({ currentUser, toggleDarkMode, isDarkMode }) => {
  const [activeTab, setActiveTab] = useState<NavTab>('home');
  const [selectedChat, setSelectedChat] = useState<Chat | null>(null);
  const [showStoryUpload, setShowStoryUpload] = useState(false);
  const [viewingStories, setViewingStories] = useState<Story[] | null>(null);
  const [viewingUser, setViewingUser] = useState<User | null>(null);
  const [activeCall, setActiveCall] = useState<CallSession | null>(null);
  const [selectedPost, setSelectedPost] = useState<Post | null>(null);
  const [connectionsState, setConnectionsState] = useState<{ user: User, type: 'followers' | 'following' } | null>(null);
  const [nicknames, setNicknames] = useState<Record<string, string>>({});

  useEffect(() => {
    const unsub = subscribeToNicknames(currentUser.uid, (data) => setNicknames(data));
    return () => unsub();
  }, [currentUser.uid]);

  useEffect(() => {
    const poll = async () => {
      cleanOldCalls();
      if (activeCall) return; 
      const incoming = await getIncomingCall(currentUser.uid);
      if (incoming) {
        const caller = await getUserById(incoming.callerId);
        if (caller) {
          setActiveCall({
            id: incoming.id, partner: caller, type: incoming.type, callerId: incoming.callerId,
            receiverId: incoming.receiverId, status: incoming.status, isIncoming: true, timestamp: incoming.timestamp
          });
        }
      }
    };
    const itv = setInterval(poll, 3000);
    return () => clearInterval(itv);
  }, [currentUser.uid, activeCall]);

  const startCall = async (user: User, type: 'voice' | 'video') => {
    const call = await initiateCall(currentUser.uid, user.uid, type);
    setActiveCall({ 
      id: call.id, partner: user, type, callerId: currentUser.uid, receiverId: user.uid,
      status: 'ringing', isIncoming: false, timestamp: call.timestamp
    });
  };

  const handleOpenProfileByUid = async (uid: string) => {
      const user = await getUserById(uid);
      if(user) setViewingUser(user);
      setConnectionsState(null); // Close connections if opening profile
  };

  const handleMessageUser = (user: User) => {
    const chatId = [currentUser.uid, user.uid].sort().join('_');
    const chat: Chat = {
      id: chatId,
      type: 'private',
      participants: [currentUser.uid, user.uid],
      updatedAt: Date.now()
    };
    setSelectedChat(chat);
    setViewingUser(null);
    setConnectionsState(null);
    setSelectedPost(null);
  };

  const renderTabContent = () => {
    switch (activeTab) {
      case 'home':
        return (
          <HomeFeed 
            currentUser={currentUser}
            onOpenDMs={() => setActiveTab('chats')}
            onUploadPost={() => setShowStoryUpload(true)}
            onOpenStory={setViewingStories}
            onOpenPost={setSelectedPost}
          />
        );
      case 'chats':
        return (
          <Sidebar 
            currentUser={currentUser} 
            onChatSelect={setSelectedChat} 
            activeChatId={selectedChat?.id}
            nicknames={nicknames}
            onBack={() => setActiveTab('home')}
          />
        );
      case 'reels':
        return (
          <ReelsView 
            currentUser={currentUser}
            onOpenProfile={setViewingUser}
            onOpenComments={setSelectedPost}
          />
        );
      case 'profile':
        return (
          <ProfilePanel 
            user={currentUser} 
            onClose={() => setActiveTab('home')} 
            toggleDarkMode={toggleDarkMode}
            isDarkMode={isDarkMode}
            isTabMode={true}
            onOpenPost={setSelectedPost}
            onOpenConnections={(type) => setConnectionsState({ user: currentUser, type })}
          />
        );
      case 'search':
        return (
          <ExploreView 
            currentUser={currentUser}
            onOpenProfile={setViewingUser}
            onOpenPost={setSelectedPost}
          />
        );
      case 'activity':
        return (
          <ActivityView 
            onBack={() => setActiveTab('home')}
            onOpenProfile={setViewingUser}
          />
        );
      default:
        return null;
    }
  };

  return (
    <div className="flex flex-col h-[100dvh] w-full bg-background-light dark:bg-background-dark overflow-hidden font-display">

      {/* Top Main Content Area */}
      <div className="flex-1 relative flex flex-col overflow-hidden">
        {selectedChat ? (
          <ChatWindow 
            chat={selectedChat} 
            currentUser={currentUser} 
            onClose={() => setSelectedChat(null)}
            onUserClick={setViewingUser}
            onCallStart={startCall}
            nicknames={nicknames}
          />
        ) : (
          renderTabContent()
        )}
      </div>

      {/* Global Bottom Navigation */}
      {!selectedChat && !selectedPost && !connectionsState && (
        <BottomNav 
          activeTab={activeTab} 
          onTabChange={(tab) => {
            if (tab === 'add') setShowStoryUpload(true);
            else setActiveTab(tab);
          }} 
          currentUser={currentUser} 
        />
      )}

      {/* Modals & Overlays */}
      {showStoryUpload && <StoryUpload currentUser={currentUser} onClose={() => setShowStoryUpload(false)} />}
      {viewingStories && (
        <StoryViewer 
          stories={viewingStories} 
          currentUser={currentUser} 
          onClose={() => setViewingStories(null)} 
          onSwitchToReels={() => {
            setViewingStories(null);
            setActiveTab('reels');
          }}
        />
      )}
      {viewingUser && (
        <PublicProfile 
          user={viewingUser} 
          currentUser={currentUser}
          onClose={() => setViewingUser(null)} 
          onCallStart={startCall} 
          onMessageClick={handleMessageUser}
          nickname={nicknames[viewingUser.uid]} 
          onOpenPost={setSelectedPost} 
          onOpenConnections={(type) => setConnectionsState({ user: viewingUser, type })}
        />
      )}
      {activeCall && <CallModal session={activeCall} onHangUp={() => setActiveCall(null)} />}
      {selectedPost && <PostDetailView post={selectedPost} currentUser={currentUser} onClose={() => setSelectedPost(null)} onOpenProfile={handleOpenProfileByUid} />}
      {connectionsState && (
        <ConnectionsView 
            targetUser={connectionsState.user} 
            currentUser={currentUser} 
            initialType={connectionsState.type} 
            onClose={() => setConnectionsState(null)}
            onOpenProfile={handleOpenProfileByUid}
        />
      )}
    </div>
  );
};

